ns.ZoneText:Register("koKR", {
	["s:1411:bladefist bay"] = "듀로타 동쪽의 바다는 산산조각난손 부족의 옛 족장 카르가스 블레이드피스트의 이름을 따서 불린다. 바다 건너 북쪽으로는 아즈샤라의 해안이 보이고, 이 해안을 따라 해골 바위굴이 솟아 있다.\n\n이 만을 아는 이들 사이에서는 더 거친 이름도 붙었다. 바로 대해의 쓰레기 더미이다. 파도가 바다의 잔해를 거듭 실어 와 해초와 난파선 조각이 해골 바위굴 근처로 밀려오기 때문에, 해안은 결코 오래 깨끗하게 남아 있지 못한다.",
	["s:1411:burning blade coven"] = "시험의 골짜기 북쪽 끝을 막고 선 산에는 한때 바위와 그림자보다 나쁜 것은 없었다. 이제는 동굴 입구에서 임프와 하급 악마들이 골짜기로 쏟아져 나오며, 그 너머 버려진 동굴 깊은 곳에는 불타는 칼날 단원들을 비롯해 더 강한 것들이 도사리고 있다고 한다. 흑마법사 야로그 베인섀도가 그 안에 사는 것들을 지휘한다고 전해진다.\n\n악마들이 오기 전, 타즈릴이라는 작업반장이 광물을 조사하러 그 동굴로 들어갔다. 그는 일을 마친 뒤 곡괭이를 두고 나왔고, 그 곡괭이는 지금도 그곳에 남아 있다.\n\n시험의 골짜기에서 스스로를 증명하는 오크와 트롤에게 이 소굴은 골짜기를 떠나기 전의 마지막 시험이 되었다.",
	["s:1411:darkspear strand"] = "검은창 트롤은 메아리 섬에서 달아났을 때 이곳 해안에 상륙했다. 이 해변에서 그들은 내륙의 센진 마을로 향했고, 살아남은 이들은 그곳에 모여 새 삶을 시작했다.",
	["s:1411:deadeye shore"] = "데드아이 해안은 한때 피눈물 부족을 이끌었던 오크 영웅 킬로그 데드아이의 이름에서 따왔다. 이곳 사막에서 뜯겨 나온 거대한 모래밭은 눈 하나가 없는 해골 모양을 하고 있어, 마치 그의 이름이 떠올리게 하는 상처를 땅이 지니고 있는 듯하다.\n\n이제 이 해안을 어지럽히는 것은 랩터와 전갈, 멧돼지 정도이다. 오크 어부 바이록이 한때 이 바다에서 일했지만, 이곳에서 불타는 칼날의 습격을 받았다.",
	["s:1411:den"] = "시험의 골짜기에서 젊은 오크들은 동굴 막사라 불리는 동굴에 첫 야영지를 차린다. 그 안에는 젊은이들에게 저마다의 소명을 가르치는 원로들이 있어, 무기를 드는 모든 오크의 첫걸음을 이끌어 준다.",
	["s:1411:drygulch ravine"] = "모래바람 협곡은 주변 땅보다 푹 꺼져 있어, 벽을 타고 떨어지거나 칼바람 협곡에서 이어지는 좁은 동굴을 통해서만 들어갈 수 있다. 협곡 사이로 강이 흐르며, 이곳의 이름이 유래한 메마르고 갈라진 땅을 적신다.\n\n이제 이 협곡은 먼지바람 하피의 차지이다. 그들은 도적질에 나서 짐마차 행렬을 덮치고, 약탈품을 높은 절벽 위 둥지로 끌어올린다. 그곳에서는 그들 가운데 가장 강한 자들이 알을 지킨다.",
	["s:1411:dustwind cave"] = "칼바위 언덕 북동쪽, 칼바람 협곡의 절벽 꼭대기에는 바위 속으로 좁은 동굴이 나 있다. 작고 눈에 잘 띄지 않는 곳이지만, 불타는 칼날은 이곳을 요긴하게 쓴다. 이곳에서 광신도들은 새로 맹세한 신도들을 훈련시켜, 듀로타의 다른 곳에서 신임을 얻기 전에 그들을 단련한다.",
	["s:1411:echo isles"] = "메아리 섬은 듀로타 앞바다에 솟은 열대의 땅으로, 랩터와 스라소니가 우글거리며 정글 트롤 검은창 부족의 보금자리이다. 구루바시 제국이 전성기를 누리던 시절, 정글 트롤은 가시덤불 골짜기까지 뻗어 있던 영토의 일부로서 이 바다를 다스렸다.\n\n대족장 스랄이 검은창 부족을 구해 호드로 받아들인 뒤, 부족은 이 섬들에 다시 자리를 잡았다. 그러나 평화는 오래가지 않았다. 부족의 부두술사 잘라제인이 죽음의 비밀을 익히고, 그를 믿었던 검은창 트롤들에게 좀비와 주술에 걸린 동족을 풀어놓았다. 그는 본섬의 오두막들 사이에 오염된 부적을 묻어 듀로타 전역의 마력의 흐름을 비틀었고, 이 땅의 야생 동물과 어두운 곳들을 타락시켰다.\n\n검은창 부족은 거듭 그를 끝장내려 했지만, 그는 매번 자신이 죽은 것처럼 그들을 속였고, 그사이 그의 언데드 트롤들은 본토로 기어들어 더 많은 부족원을 그의 지배 아래로 끌어들였다. 검은창 부족은 스랄이 내려 준 땅에서 여전히 추방된 채, 자신들의 보금자리였어야 할 섬에서 잘라제인의 힘이 곪아 가는 것을 지켜보고 있다.",
	["s:1411:hidden path"] = "시험의 골짜기를 둘러싼 산 사이로 숨겨진 길이 굽이굽이 이어지며, 그 길은 찾는 이에게만 알려져 있다. 주술사들은 이 길을 올라 더 쉬운 길로는 닿을 수 없는 힘의 장소인 정기 바위에 이르며, 그 높은 곳에서는 불모의 땅 전체가 발아래 펼쳐진다. 더 아래쪽에서 길은 톱니항과 오그리마로 열려 있어, 이 길을 아는 이들에게는 조용한 샛길이 되며 이방인들에게도 마찬가지이다.",
	["s:1411:jaggedswine farm"] = "톱니멧돼지 농장은 오그리마 성문 근처에 있으며, 저장고와 넓은 돼지우리, 연못이 듀로타의 호드를 먹여 살리는 돼지들을 기른다.",
	["s:1411:kolkar crag"] = "콜카르 바윗골은 듀로타 남부의 험준한 협곡으로, 이곳을 차지한 콜카르 켄타우로스에게서 이름을 얻었다.\n\n전쟁군주 콜카니스는 이곳에서 동족을 모아 야심 찬 계획 하나를 세웠다. 시험의 골짜기와 센진 마을에서 칼바위 언덕, 나아가 오그리마의 성문에 이르기까지 오크의 땅 듀로타의 심장부를 치는 것이었다.",
	["s:1411:orgrimmar"] = "오그리마는 하이잘 산 전투 이후, 대족장 스랄이 동족을 이끌고 칼림도어의 황량한 해안에 왔던 시절에 세워졌다. 그는 아버지를 기려 그 땅을 듀로타라 불렀고, 그곳에 세운 도시는 자신을 길러 준 벗이자 스승인 오그림 둠해머를 기려 오그리마라 이름 지었다. 도시는 빠르게 세워졌지만 허술하지 않았다. 튼튼한 성벽과 거대한 성문, 높은 탑을 갖추었고, 뒤편의 산을 깎아 요새의 일부로 삼아 대지가 도시를 지키도록 했다.\n\n도시를 세운 호드는 한때 세상을 불태우며 휩쓸었던 그 호드가 아니었다. 악마의 저주가 풀리자 스랄의 백성은 정복이 아닌 생존을 향해 돌아섰고, 오그리마는 오크만큼이나 다른 이들의 손으로 세워졌다. 고블린과 타우렌, 검은창 트롤이 그들과 함께 일했고, 모크나탈의 렉사르도 일손을 보탰다. 켄타우로스와 하피, 천둥도마뱀, 코볼트, 가시멧돼지가 모두 첫 몇 해 동안 이 젊은 도시를 시험했지만, 도시는 버텨 냈다. 그리고 오크뿐 아니라 트롤과 타우렌, 시간이 흘러서는 새로 호드에 받아들여진 포세이큰의 보금자리가 되었다.\n\n이곳에서는 바람조차 친구가 아니다. 칼날 같은 바람이 골짜기를 휩쓸며, 허술하게 지은 건물의 지붕쯤은 뜯어낼 만큼 거세게 분다.",
	["s:1411:razor hill"] = "칼바위 언덕은 듀로타의 길들이 만나는 곳에 서 있다. 남쪽으로는 센진 마을과 시험의 골짜기로 길이 이어지고, 북쪽에는 오그리마가 있으며, 서쪽으로는 길이 강을 건너 불모의 땅을 지나 크로스로드까지 뻗어 있다. 칼바람 언덕 병영이 마을에서 가장 눈에 띄는 건물로 솟아 있고, 마을에는 땅굴도 하나 있다.\n\n3차 대전쟁이 끝난 직후, 쿨 티라스 군이 스랄에게 평화를 제안하며 회담을 청한 곳이 바로 이곳이었다. 스랄은 다른 속셈이 있다고 의심했고, 그 의심은 옳았다. 회담은 그를 노린 매복이었다. 이 소식을 들은 렉사르는 스랄이 함정에 걸어 들어가게 둘 수 없다며 그를 대신해 회담에 나갔다. 칼바위 언덕에서 기다리던 암살자들이 마주한 것은 렉사르였고, 그는 그들을 베어 쓰러뜨렸다.\n\n오르그닐 소울스카는 지금도 이곳에서 감시를 서며 언덕 주변 땅에서 불타는 칼날의 움직임을 추적하고 있다.",
	["s:1411:razor hill barracks"] = "이 병영은 칼바위 언덕에서 가장 큰 건물로, 그 크기만으로도 이 마을이 오그리마 다음가는 듀로타의 진정한 요새 가운데 하나임을 보여 준다.",
	["s:1411:razormane grounds"] = "서슬갈기일족 영토에는 살점이 뜯겨 나간 짐승의 뼈가 널려 있고, 그 위 붉은 산에서는 가시덤불이 터져 나오듯 자라 있다. 이곳에서 서슬갈기 가시멧돼지는 불모의 땅에서 듀로타로 밀고 들어오고, 오크들은 고향의 경계를 지키기 위해 싸운다. 가시멧돼지 하나를 베어 넘기면 덤불 속에서 둘이 기어 나와 그 자리를 채운다. 부족의 야영지는 대지술사 모틀의 지휘를 받고, 오크에 맞서 전선을 지키는 전투 경비대는 플랫 터스크 대장이 이끈다.",
	["s:1411:razorwind canyon"] = "협곡은 칼바위 언덕과 오그리마 사이의 길 양옆으로 두 개의 골짜기로 갈라지며, 그 벽에는 오솔길과 숨겨진 굽이가 얽혀 있다. 이곳은 먼지바람 하피가 둥지로 삼은 곳으로, 길 양쪽의 바위마다 그들이 가득하다. 그들은 침입자를 가볍게 봐주지 않는다. 새 여인들은 길에서 너무 멀리 벗어난 모든 것을 빠르고 사납게 덮치며, 얼마나 많은 하피가 지켜보고 있었는지 깨닫기도 전에 끌려 내려간 여행자가 한둘이 아니다. 협곡 동쪽 끝의 동굴은 모래바람 협곡으로 이어지지만, 가는 길에 무엇이 둥지를 틀고 있는지 알기에 그 길을 택하려는 이는 드물다.",
	["s:1411:rocktusk farm"] = "바위어금니 농장은 오그리마 성문 밖 서쪽 길을 따라 조금 내려간 곳에 있다. 주인들은 이곳에서 별다른 두려움 없이 일하며, 호드를 먹여 살릴 고기를 내는 돼지를 기른다.",
	["s:1411:scuttle coast"] = "가라앉은 해안은 듀로타가 대해와 만나는 곳으로, 그 바위들에는 아직도 쿨 티라스 함선의 잔해가 걸려 있다. 이곳에서 대제독 데일린 프라우드무어의 함대는 오크에게 부딪혀 무너졌고, 가라앉지 않은 배들은 해안으로 떠밀려 산산이 부서졌다.\n\n그 부서진 선창에는 아직도 노움의 물자가 실려 있어, 오크들은 쓸 만한 것을 찾아 목재 사이를 뒤진다. 그러나 바다 정령들이 밀물을 타고 들어와 해안에 다가오는 모든 것을 공격하기에, 오크들은 해안을 지키기 위해 난파선만큼이나 바다와도 싸워야 한다.",
	["s:1411:senjin village"] = "센진 마을은 듀로타 남쪽 해안에 자리한 작은 오두막 무리로, 검은창 부족이 세운 곳이다. 소박한 마을이다. 아주 작은 오두막 셋, 작은 오두막 둘, 조금 큰 회관 하나, 그리고 트롤들이 바다에서 생계를 얻는 부두 하나가 바다로 뻗어 있을 뿐이다.\n\n마을은 옛 방식을 지킨다. 이곳 사람들은 치유사이자 약초 채집꾼이며, 해안의 식물과 대대로 전해 내려온 트롤의 약술을 아는 연금술사들이다. 뿌리와 약재에 관한 부족의 지식이 맡겨진 것도 바로 그들이다.",
	["s:1411:shrine of the dormant flame"] = "희미한 불꽃의 제단은 이 지역에서 가장 높은 산 꼭대기에 있으며, 시험의 골짜기 북서쪽 분노의 강 근처에서 나선을 그리며 올라가는 비밀 길로 닿을 수 있다. 이곳은 호드 주술사들에게 성스러운 땅이다. 그 오르막은 가벼이 오를 길이 아니며, 지역 전체를 굽어보는 꼭대기의 낭떠러지 또한 마찬가지이다.\n\n꼭대기에는 꺼진 화로가 기다리고 있다. 주술사를 꿈꾸는 이들은 불을 다스리는 힘을 증명하러 이곳에 온다. 그들은 불의 정령을 찾아내 쓰러뜨린 뒤, 불씨 하나를 가져와 화로에 불을 붙여 정령이 자신의 뜻에 굴복했음을 증명한다.\n\n텔프 줄람이 시련을 찾는 이들을 안내한다.",
	["s:1411:skull rock"] = "듀로타 북동쪽의 해골 바위굴은 불타는 칼날 교단의 마지막 거점이다. 그 깊은 곳에서 오크 흑마법사 가주즈가 교단의 잔당을 이끌고 있다.",
	["s:1411:southfury river"] = "분노의 강은 하이잘 산 높은 곳에서 발원해, 산정 호수에서 쏟아져 저지대로 우레처럼 떨어지는 폭포를 이룬다. 그곳에서부터 강은 넓고 빠르게 흐르며 땅을 둘로 가른다. 잿빛 골짜기가 아즈샤라로 바뀌는 곳을 표시하고, 더 남쪽에서는 불모의 땅이 끝나고 듀로타가 시작되는 곳을 가른다. 하구에서 강은 고블린 항구 톱니항의 바로 북동쪽에서 마지막 폭포를 넘어 대해로 뛰어든다.\n\n강을 따라 다리들이 놓여 있는데, 하나는 아즈샤라와 잿빛 골짜기를, 하나는 듀로타와 불모의 땅을 잇는다. 강줄기 어딘가에는 네 땅에 한꺼번에 닿는 물줄기가 한 곳 있다. 잿빛 골짜기와 아즈샤라, 듀로타, 불모의 땅이 만나는 유일한 곳이다.",
	["s:1411:spirit rock"] = "비밀의 길이 듀로타의 언덕으로 올라가는 곳, 시험의 골짜기 저 위에 호드 주술사들에게 신성한 정기 바위가 서 있다. 그곳에서 주술사를 꿈꾸는 이들은 바위 곁에서 삽타를 마시고 대지와 교감하려 한다.",
	["s:1411:thunder ridge"] = "천둥 골짜기는 오그리마 남서쪽, 듀로타 북서부의 협곡이다. 이곳에는 그 사이에 굴을 파고 사는 천둥도마뱀과 조화를 이루며 자라 온 고목들의 숲이 있다.\n\n그 조화는 인간의 벌목 작업이 골짜기의 나무를 베어 내기 시작하면서 깨졌고, 도마뱀들은 미쳐 버렸다. 드렉타르를 위해 어스름 풀을 모으러 왔던 렉사르가 짐승들의 변화를 알아채고 오그리마에 소식을 전했다. 그와 드렉타르는 함께 돌아와 벌목 현장을 찾아냈고, 재앙을 막기 위해 미쳐 버린 도마뱀들을 처치할 수밖에 없었다. 다만 렉사르는 그 뒤 드렉타르가 연구할 수 있도록 도마뱀의 알을 모아 갔다.\n\n스랄의 명으로 골짜기를 더욱 어지럽힌 것이 무엇인지 알아보러 온 제이나 프라우드무어는, 이곳의 나무들이 이 지역을 불안정하게 만들려는 불타는 칼날의 악마 마법에 베였다는 사실을 밝혀냈다. 피즐 다크클로가 이끄는 소수의 광신도 무리가 더 큰 혼란을 퍼뜨리려고 그곳에 야영지를 차렸고, 오르그닐 소울스카는 피즐을 처단하고 그 증거로 그의 발톱을 가져오라고 명했다.",
	["s:1411:tiragarde keep"] = "타이라가드 요새는 가라앉은 해안의 붉은 바위를 배경으로 하얗게 솟아 있다. 애초에 듀로타에 서 있어서는 안 되었던 요새이다.\n\n이 요새는 쿨 티라스의 대제독 데일린 프라우드무어의 명령으로 서둘러 세워졌다. 3차 대전쟁은 스랄과 대제독의 친딸인 제이나 프라우드무어 사이의 불안한 평화로 끝났지만, 데일린은 어떤 오크도 믿지 않았고 자신의 이름으로 맺어진 휴전도 존중하지 않았다. 그는 쿨 티라스에서 함대를 이끌고 듀로타 해안으로 와서 호드에 맞서 싸웠고, 끝을 보려던 전쟁의 거점으로 타이라가드 요새를 세웠다. 공세는 오크 앞에서 무너졌고, 요새도 함께 폐허가 되었다.\n\n데일린 자신은 요새가 재건되는 것을 보지 못했다. 그는 렉사르가 이끄는 호드가 테라모어를 급습했을 때 목숨을 잃었다. 그러나 쿨 티라스를 떠나기 전, 그는 자신의 함대가 소식이 끊길 날에 대비해 봉인된 명령을 남겨 두었다. 아무 소식도 돌아오지 않자 그 명령이 드러났고, 베네딕트 중위가 폐허를 되찾고 지휘관의 성전을 이어 가도록 파견되었다.\n\n그렇게 요새는 다시 서 있다. 상처투성이지만 굳건히 지켜지고 있는, 진홍빛 바위 위의 빛나는 이질적인 색의 흉터로서.",
	["s:1411:torkren farm"] = "톨크렌 농장은 천둥 골짜기와 분노의 강 유역 사이에 자리한 소박한 농장으로, 이웃 농장들만큼 수익을 낸 적이 한 번도 없다. 한때 이 농장은 미샤 톨크렌과 그녀의 아들 크론이 일구었지만, 크론은 악어를 사냥하러 분노의 강으로 내려갔다가 돌아오지 않았다. 이제 미샤는 홀로 농장을 지키며, 아들을 기억할 수 있도록 악어 이빨로 엮은 목걸이를 청한다.",
	["s:1411:valley of trials"] = "시험의 골짜기는 듀로타 남부에 벽처럼 둘러싸인 그을린 땅의 분지로, 모든 젊은 오크가 호드가 정해 준 삶을 이곳에서 시작한다. 실패한 자는 실려 나가지 않는다. 그들은 쓰러진 자리에 그대로 남겨져, 시험이 시작한 일을 사막이 마저 끝낼 때까지 햇볕에 구워진다.\n\n골짜기 한가운데에는 동굴 막사가 있다. 절벽을 파서 만든 이 동굴에는 봉사하는 삶에 걸맞은 소박한 편의가 갖추어져 있다. 원로들이 그곳을 지키며 젊은이들에게 저마다의 소명을 가르치고 시험을 맡긴다.\n\n북쪽 절벽에는 한때 비어 있던 자연 동굴 몇 개가 이어져 있었다. 그 후 무언가가 그 안으로 기어들었다. 이제 불타는 칼날의 악마들이 그곳에 둥지를 틀고 골짜기 안으로 흘러나오고 있으며, 그들의 존재는 어둠의 의회가 이 지역에 발판을 마련했다는 오래된 소문에 무게를 더했다. 악마들은 약하지만 동굴 안에 머물러 있지 않으며, 그들이 지닌 오염은 한때 그것을 가두었던 바위 너머로 퍼지기 시작했다.",
	["s:1412:baeldun digsite"] = "바엘던 원정대는 멀고어 서쪽 끝에 채석장을 파고, 곡괭이로 산허리를 찢어발겼다. 그들의 발굴은 대지 어머니에 대한 모독으로 여겨졌고, 말로 그들을 되돌리지 못하자 블러드후프 부족은 침입자들의 도구를 빼앗아 부숴 그들을 몰아냈다.\n\n드워프들은 받은 경고에 아랑곳하지 않고 계속 파 내려갔으며, 그 무모한 작업은 땅의 정령들의 분노를 일깨웠다. 채석장은 멀고어의 대지에 새겨진 흉터로 남아 있다.",
	["s:1412:bloodhoof village"] = "블러드후프 마을은 멀고어 평원의 황소바위 호숫가에 자리하며, 이곳을 고향으로 삼은 부족의 이름을 따서 불린다. 이곳에서는 평원의 야생 코도를 길들이고 훈련시켜 등에 기수를 태울 만큼 차분해지게 만드는데, 마을은 무엇보다도 이 일로 이름이 나 있다.\n\n베인 블러드후프는 마을을 지켜보며 그 안전을 책임진다. 자를만 투문은 블러드후프 부족의 영적인 삶을 돌보는 원로로, 이곳에 사는 이들과 지나가는 이들에게 조상과 대지 어머니의 뜻을 전한다.",
	["s:1412:brambleblade ravine"] = "칼날가시 협곡은 붉은구름 고원의 북동쪽 끝을 파고든 협곡으로, 뾰족등 가시멧돼지의 보금자리이다. 협곡 안쪽의 커다란 오두막에는 그들의 우두머리 샤프터스크 쏜맨틀이 산다. 그가 이끄는 가시멧돼지의 습격이 끊이지 않자, 타우렌은 그 근원을 끊어 내기 위해 공격에 나섰다.",
	["s:1412:camp narache"] = "나라체 야영지는 멀고어 남부, 붉은구름 고원의 북쪽 끝에 자리한 호크윈드 부족의 작은 천막촌이다. 부상당한 용사들은 중앙 천막에서 쉬고, 마을 한가운데 주위에서는 부족의 스승들이 조용히 둘러앉아 대모 호크윈드에게 경의를 표한다.",
	["s:1412:golden plains"] = "황금 초원은 썬더 블러프 남동쪽에 푸른 풀이 물결치는 분지로, 타우렌의 고향 땅에서도 귀하게 여겨지며 사냥터로 소중히 아껴진다. 거대한 코도 떼가 이곳에 모여 풀을 뜯으며, 풀밭 어딘가에 그 유명한 아라체아가 산다고 한다.",
	["s:1412:kodo rock"] = "코도 바위는 나라체 야영지와 칼날가시 협곡 사이에 조용히 솟아 있다. 가까이에서만 보이기 때문에 주의 깊게 살피지 않으면 모르고 지나치기 쉽다.",
	["s:1412:palemane rock"] = "회색갈기일족 바위굴은 멀고어 서부의 산허리 깊숙이 파인 동굴로, 회색갈기 부족 놀의 보금자리이다. 그들은 동굴과 그 바깥의 야영지를 함께 지키며, 걸핏하면 폭력을 휘둘러 자기 땅에 너무 가까이 다가온 자는 누구든 덮친다.",
	["s:1412:ravaged caravan"] = "황소바위 호수의 북동쪽 기슭에서는 투자개발회사 짐마차 행렬의 잔해가 아직도 연기를 피우며 멀고어의 하늘로 검은 연기를 뿜어내고 있다. 이 행렬은 감독관 피즈스프로켓의 채굴 작업장에 물자를 나르던 중이었는데, 자기 땅을 오가는 고블린들에 진저리가 난 타우렌이 그것을 덮쳤다.\n\n살아남은 자들은 결코 잔해를 버리지 않았다. 그들은 지금도 연기 나는 잔해 더미와 그을린 화물을 지키며 가까이 오는 자는 누구든 물리친다.",
	["s:1412:red cloud mesa"] = "붉은구름 고원은 멀고어 남부의 높은 절벽 위에 펼쳐진 구릉진 평원으로, 고요하고 탁 트인 아름다움으로 알려져 있다. 젊은 타우렌은 바로 이곳에서 스스로를 증명하며, 북동쪽의 칼날가시 협곡을 차지한 뾰족등 가시멧돼지에 맞서 무기를 든다.\n\n고원 북서쪽에 자리한 나라체 야영지는 고원에 남은 마지막 안전한 땅이다. 야영지 서쪽의 묘지에서부터 길이 올라가 먼눈 고원 꼭대기에 이른다.",
	["s:1412:red rocks"] = "붉은 바위 언덕의 붉은 사암은 멀고어 북동쪽에 솟아 있으며, 썬더 블러프의 세상이 멀어지고 더 고요한 무언가가 그 자리를 채우는 곳이다. 이곳에서 타우렌은 명예로운 망자를 정화의 불꽃으로 대지 어머니와 하늘 아버지에게 보낸다. 쓰러진 타우렌이 모두 이곳에 오는 것은 아니다. 가장 용맹한 이들, 곧 썬더 블러프를 세우고 지킨 전사들과 부족과 족장을 위해 목숨을 바친 이들만이 이곳에서 안식을 얻는다. 이곳은 또한 젊은 용사들이 성년이 되는 통과 의례를 마치러 오는 곳이기도 하다. 그들은 바위 사이에 서서 바람에 실려 오는 조상의 목소리에 귀를 기울인다.\n\n그 신성함도 이곳을 지켜 주지는 못했다. 뾰족등 가시멧돼지 무리가 붉은 바위 언덕으로 밀고 들어와 그 존재만으로 성지를 더럽혔고, 이 일은 이곳을 소중히 여기는 썬더 블러프의 타우렌 사이에 깊은 분노를 불러일으켰다.",
	["s:1412:rolling plains"] = "구릉 초원은 블러드후프 마을 남쪽으로 펼쳐져 불모의 땅 경계를 향해 뻗어 있다. 늑대와 퓨마가 코도, 타조와 나란히 풀밭을 누빈다.\n\n멀고어의 다른 곳과 달리 이 초원은 막혀 있지 않다. 켄타우로스 척후병들이 이곳으로 들어오는 길을 찾아내어, 다른 켄타우로스는 발을 들이지 않는 곳까지 누비고 있다. 동쪽 끝에는 성난바람 하피의 둥지가 자리를 잡았다.",
	["s:1412:stonebull lake"] = "황소바위 호수는 블러드후프 마을을 세 방향으로 감싸고 도는 길쭉한 말굽 모양의 시원한 호수이다. 물에는 물고기가 가득하여, 고요한 시간 내내 낚싯줄이 드리워진다. 호수가 좁아지는 곳에는 다리가 놓여 있어, 블러드후프 마을과 썬더 블러프를 잇는 길이 그 위를 지난다.",
	["s:1412:thunder bluff"] = "썬더 블러프는 멀고어의 초원 위, 바람이 휘몰아치는 네 개의 고원 위에 솟아 있으며, 타우렌이 만든 밧줄과 나무 승강기나 고원 사이에 걸린 긴 다리로만 오갈 수 있다. 봉우리마다 천막과 긴 집, 채색된 토템이 얹혀 있다. 여러 세대 동안 타우렌은 칼림도어 곳곳을 누비는 켄타우로스에게 쉼 없이 시달리며 떠도는 유목민으로 살았다. 그 유랑을 끝낸 이는 블러드후프 부족의 족장 케른 블러드후프였다. 3차 대전쟁 때 대족장 스랄과 그의 새로운 호드가 멀고어에 왔을 때, 그들의 힘은 케른의 힘과 하나가 되었고, 그들은 함께 켄타우로스를 무찔러 마침내 타우렌에게 초원을 안겨 주었다. 케른은 고원 위에 흩어진 모든 부족에게 열린 안식처를 세웠고, 시간이 흘러 그 부족들은 한 민족으로서 그의 통치를 따르게 되었다. 앞으로 나아갈 길에 대해서는 때때로 의견이 갈렸지만, 그들을 이끄는 그의 지혜에 대해서는 결코 이견이 없었다.\n\n고원들은 그 솟은 봉우리와 다리에, 그리고 한 족장의 지붕 아래 모인 부족들의 천막에 지금도 그 건국의 무게를 짊어지고 있다.",
	["s:1412:thunderhorn water well"] = "이 우물은 썬더 블러프와 블러드후프 마을 사이의 북쪽 길을 따라 멀고어의 탁 트인 풀밭에 자리하고 있다. 한때 투자개발회사가 타우렌의 물줄기를 끊으려고 이곳을 차지했지만, 타우렌은 그들을 몰아내고 우물을 되찾았다.",
	["s:1412:venture co mine"] = "이 광산은 멀고어 동쪽 절벽 깊숙이 파고들어 있으며, 들어가는 길은 셋이다. 걸어서 들어가는 정문, 절벽면, 그리고 그 너머의 작은 벌목지이다. 이 광산은 그곳에 있어서는 안 되는 것이다. 타우렌은 자기 고향에서의 채굴권을 투자개발회사에 내주지 않았지만, 회사는 아랑곳없이 파기 시작했다. 감독관 피즈스프로켓이 작업을 맡았고, 거물 라즈둔크의 자문단은 그에게 벌목까지 사업을 넓히라고 압박하며 새 벌목기와 멀고어의 목재를 먹어 치울 제재소의 원자재를 보내왔다.\n\n타우렌은 이 침입을 그냥 넘기지 않았다. 호위를 받으며 황소바위 호수 북쪽 기슭을 따라 이동하던 채굴 물자 짐마차 행렬을 초원달리미들이 발견했고, 그들은 행렬을 덮쳐 태울 수 있는 것은 모두 태웠다. 불길이 쓸 만한 것은 모두 망쳤으리라 여긴 그들은 잔해를 그대로 두고 떠났다. 그러나 그렇지 않았다. 훗날 투자개발회사의 회수꾼들이 잿더미를 뒤지며 불길이 남긴 것을 주워 모으는 모습이 목격되었다.\n\n그 발견으로 광산은 보복의 표적이 되었다. 타우렌의 땅에서 손을 떼지 않는 회사에 대한 경고로서 피즈스프로켓의 작업장이 공격을 받게 된 것이다.",
	["s:1412:wildmane water well"] = "와일드메인 우물은 썬더 블러프 북쪽에 있으며, 타우렌의 성스러운 우물 가운데 가장 북쪽에 있는 우물이다. 성난바람 하피들이 그 주변 땅을 차지했고, 우물은 더럽혀진 채 정화를 기다리고 있다.",
	["s:1412:windfury ridge"] = "성난바람 마루는 그 꼭대기에 둥지를 튼 하피들에게서 이름을 얻었다. 이 사나운 생물들은 너무 가까이 다가온 자에게 급강하해 덮쳐 방심한 이들을 죽이거나 채어 간다. 주변 언덕에는 퓨마와 늑대도 어슬렁거린다.\n\n그러나 썬더 블러프의 타우렌은 하피의 화려한 깃털을 귀하게 여겨, 혼례와 잔치에 쓰기 위해 그것을 구해 간다.",
	["s:1412:winterhoof water well"] = "윈터후프 우물은 멀고어 남부의 구릉 초원 끝자락에 있다. 3차 대전쟁이 끝나고 몇 년 뒤, 투자개발회사가 이 우물을 차지하고 물에 독을 풀어 타우렌의 물줄기를 끊으려 했다. 멀 썬더혼이 오염을 정화할 토템을 만들고 있지만, 우물은 아직 깨끗해지지 않았다.",
	["s:1413:agamagor"] = "아가마고르는 타우라조 야영지에서 서쪽으로 뻗은 길의 북쪽에 자리한, 뾰족등 가시멧돼지가 차지한 가시나무 소굴이다. 그들의 시체는 말라붙은 핏덩이 조각을 남기는데, 추방자 맹글투스는 이 징표를 귀하게 여겨 자신만의 기묘한 호의와 맞바꾼다.",
	["s:1413:bael modan"] = "바엘던 요새의 돌 요새는 한때 돌첨탑 부족 타우렌의 마을이 있던 자리에 솟아 있다. 그 아래에서 드워프 발굴꾼들은 고대 티탄 시설을 향해 파 내려가고 있다. 타우렌이 이 땅을 밟기도 전부터 묻혀 있던 연구 시설로, 그 유물은 아직 대부분 어둠 속에서 주인을 기다리고 있다.\n\n드워프들은 폭약을 들고 와 돌첨탑 부족이 신성하게 여기던 땅을 폭파했다. 발굴은 대지를 찢어 놓았고, 타우렌 또한 함께 찢어 놓았다. 부족 대부분은 죽거나 여러 세대 동안 지켜 온 땅에서 흩어졌다. 그들의 옛 마을은 이제 드워프의 굴착 기계에 파헤쳐져 있다. 지금도 근처 길을 걷는 간 스톤스파이어는 족장 대 족장으로서 싸움이 아닌 대화로 이 일을 해결하려 했다. 드워프들은 발굴을 포기하지 않았다. 그는 외교에서 전쟁으로 돌아섰고, 그들을 몰아낼 수 있는 힘이라면 무엇이든 찾고 있다.",
	["s:1413:baeldun keep"] = "바엘던 요새는 불모의 땅 남부, 바엘 모단의 발굴지 위에 서 있다. 트윈브레이드 장군이 요새를 지휘하며, 주변 평원의 타우렌과 오크에 맞서 요새와 드워프들을 지키고 있다.",
	["s:1413:blackthorn ridge"] = "가시덩굴 우리 북쪽의 골짜기에는 가시덤불이 빽빽하며, 서슬갈기 가시멧돼지가 이곳을 차지하고 있다. 마루 위에는 주술사 브라인이 산다. 그녀의 야영지 아래에는 가시덤불 한가운데서도 맑고 깨끗한 물웅덩이가 있다.",
	["s:1413:boulder lode mine"] = "돌무더기 광산은 불모의 땅에 있으며, 굴은 오크의 목재로 받쳐져 있고 호드의 깃발이 걸려 있다. 처음 이 바위에 갱도를 판 이가 누구였든 그들이 남긴 빛바랜 유물이다. 그 소유권은 이제 사라졌다. 투자개발회사가 광산을 차지했고, 한때 오크들이 일하던 갱도에는 고블린들이 우글거린다.\n\n부두 관리인 디지위그에게 그곳 광부 하나가 광맥을 뚫고 거대한 에메랄드를 캐냈다는 소식이 들어왔다. 부두 관리인은 그것이 너무나 탐이 나서, 광산에 들어가 투자개발회사의 손에서 그것을 빼앗아 올 사람에게는 누구든 이익의 한몫을 주겠다고 약속했다.",
	["s:1413:bramblescar"] = "가시덩굴 벌판은 서슬갈기 가시멧돼지의 차지이다. 길 건너 아가마고르에는 뾰족등 부족이 자리 잡고 있으며, 두 부족 사이에는 오직 전쟁만이 있을 뿐이다. 서슬갈기의 소굴에 너무 가까이 다가가면, 가시멧돼지들은 도발을 기다리지 않는다.",
	["s:1413:camp taurajo"] = "타우라조 야영지는 불모의 땅, 멀고어로 이어지는 산길 근처에 서 있다. 이곳은 블러드후프 마을에서 오는 여행자들이 타우렌의 고향으로 계속 나아가기 전에 쉬어 가고 보급품을 얻는 곳이다.",
	["s:1413:crossroads"] = "크로스로드는 길이 만나는 곳에 자리한다. 황금길에서 내려오는 남북 방향의 길과, 톱니항에서 돌발톱 산맥까지 뻗은 긴 동서 방향의 길이 이곳에서 교차한다. 이곳을 만든 것은 무언가를 지은 것이 아니라 길이 교차한다는 사실이다. 숙소는 몇 없고 거대한 성벽도 없으며, 천막과 좌판, 그리고 저마다 물건을 팔려고 서로의 목소리를 누르며 외치는 상인들뿐이다.\n\n마을 가장자리 너머에는 매장지가 있는데, 뒤편 교역 광장의 소란과는 달리 소박하고 고요하다. 얼라이언스에게 감시의 언덕이 그러하듯, 호드가 망자에게 경의를 표하러 오는 곳이 바로 이곳이다.",
	["s:1413:dreadmist den"] = "공포의 안개봉우리 위에는 짙붉은 안개가 영원히 드리워 봉우리를 황혼 속에 감싸고 있다. 그 안에서 불타는 칼날 광신도들은 공포의 안개굴을 차지하고, 무엇보다 귀하게 여기는 유물인 악마의 씨앗을 지킨다. 안개 자체가 그들의 악마 숭배를 바깥의 눈으로부터 가려 주는 듯하다.",
	["s:1413:dreadmist peak"] = "크로스로드 북서쪽, 불모의 땅에 솟은 공포의 안개봉우리는 그 꼭대기가 붉은 안개에 휩싸여 있다. 고대 악마의 저주가 남긴 잔재이다. 불타는 칼날 광신도들은 그 꼭대기에 보금자리를 틀고, 아래쪽 공포의 안개굴 안에 있는 악마의 씨앗을 지키고 있다.",
	["s:1413:dry hills"] = "메마른 언덕은 불모의 땅의 흙먼지를 배경으로 푸르게 솟아 있으며, 돌발톱 산맥을 향해 올라가는 구릉지이다. 마녀날개 하피가 이 땅을 차지하고 있는데, 이들은 점점 대담해져 황금길 북부를 따라 가는 짐마차 행렬을 덮친 뒤 다시 푸른 언덕 속으로 사라진다.",
	["s:1413:far watch post"] = "전초 기지는 듀로타와 불모의 땅을 잇는 다리 바로 서쪽에 있다. 감시탑 하나와 오크 땅굴 하나, 투석기 한 줄이 전부이고, 조금 남쪽에 늑대 우리와 일꾼 둘이 있을 뿐이다. 편안한 근무지는 아니지만 꼭 필요한 곳이다. 듀로타로 향하는 짐마차 행렬을 지키고, 얼라이언스와 가시멧돼지 모두에 맞서 전선을 지키기 때문이다.",
	["s:1413:field of giants"] = "거인의 들판은 불모의 땅 남부에 넓고 탁 트이게 펼쳐져 있으며, 천둥도마뱀과 코도 떼가 다른 땅에서는 보기 힘든 수로 함께 무리 지어 다닌다.\n\n황금길의 남쪽 구간이 이 평원을 지나는데, 이곳은 북쪽보다 덜 안전하다. 한때 지나가는 짐마차 행렬을 지키기 위해 길을 따라 감시탑들이 서 있었지만, 지금은 텅 빈 채 바람과 풀에 내맡겨져 있다.\n\n호드는 이 땅을 포기하지 않았지만, 그 장악력은 약하다. 들판 남쪽 끝의 마루 위에는 주술사 브라인이 어떤 야영지나 교차로와도 떨어져 산다. 멀지 않은 곳에는 간 스톤스파이어가 오랜 원한을 품고 걷고 있다. 드워프들이 그의 부족의 고향 옆 땅에서 티탄 유적을 찾아 땅을 파헤치러 왔을 때, 그의 부족은 마을에서 쫓겨났다. 그 발굴지가 바엘 모단이 되었고, 간은 그 일로 자기 부족이 치른 대가를 잊지 않았다.",
	["s:1413:forgotten pools"] = "잊혀진 웅덩이는 크로스로드에서 서쪽으로 뻗은 길의 북쪽에 있으며, 북부 불모의 땅에 흩어진 오아시스 가운데 가장 북쪽에 있다. 물가는 늘 푸르고, 다른 곳에서는 찾을 수 없는 무거운 버섯이 둘러 자라며, 물속에는 불모의 땅 다른 곳에서 잡히는 것과는 전혀 다른 돌연변이 물고기가 산다.\n\n콜카르 켄타우로스가 그곳에 몸을 숨긴 거북과 야생 동물들과 함께 물가를 누빈다.",
	["s:1413:fray island"] = "격투의 섬은 불모의 땅 동쪽 해안 앞에 있는 작고 메마른 섬이다.\n\n이 섬은 모든 종족과 신념의 전사들이 클라녹 맥클라우드 아래 모여 수련하는 훈련장이다.",
	["s:1413:gold road"] = "황금길은 몰샨의 망루와 대균열 사이를 잇는다. 경계를 이루는 다리 너머의 남쪽 구간은 따로 남부 황금길이라 불린다.",
	["s:1413:groldom farm"] = "그롤돔 농장은 오그리마가 세워진 뒤 몇 해 동안 자리를 잡은 돼지 농장 가운데 하나로, 그 우리는 서슬갈기 약탈자들의 습격에 끊임없이 시달리고 있다.",
	["s:1413:lushwater oasis"] = "대균열이 끝나는 곳에 물이 고이고, 야생 짐승들이 그 물을 마시러 나무 사이로 내려온다. 콜카르 켄타우로스는 뿌리 사이에 숨어 웅덩이로 이끌려 오는 짐승들을 사냥한다.\n\n오아시스 아래에는 저주받은 곳으로 일컬어지는 통곡의 동굴 입구가 있다. 그 아래에서 꿈틀대는 것은 수면으로 올라오지 않지만, 그 이름은 여전히 물 위에 드리워 있다.\n\n이곳의 물고기는 불모의 땅 다른 어디에서도 볼 수 없는 것들이다.",
	["s:1413:merchant coast"] = "무역 해안이라는 이름은 이곳을 오가는 알뜰하고 끊임없는 교역에서 왔으며, 그 교역은 톱니항 고블린들의 손에 쥐어져 있다.\n\n남쪽 해안은 남해 해적단의 차지이다. 그중에는 롱쇼어 남작도 있는데, 그는 한때 가즐로의 귀한 화물을 훔쳐 붙잡히기 전에 땅에 묻어 버렸고, 그 보물은 해안 어딘가에 잃어버린 채 남아 있다.",
	["s:1413:morshan base camp"] = "몰샨 주둔지는 잿빛 골짜기와의 경계 남쪽, 몰샨의 망루 근처에 서 있으며, 불모의 땅에서 규모가 큰 호드 거점 가운데 하나이다. 전쟁노래 정찰대가 이곳에 본거지를 두고, 그 너머 분쟁 중인 숲으로 향하는 북쪽 길을 감시한다.",
	["s:1413:morshan rampart"] = "몰샨의 망루는 황금길이 불모의 땅에서 북쪽으로 뻗어 나가는 곳에 서 있으며, 잿빛 골짜기에서 밀고 나오는 얼라이언스를 막는 방벽으로 세워졌다. 전쟁을 위해 지은 투박한 곳이다. 북쪽에서 밀려오는 적을 막아 전선을 지키기 위한 토루와 감시탑들이 서 있다.",
	["s:1413:raptor grounds"] = "이 작은 골짜기를 채운 태양비늘 랩터는 불모의 땅의 다른 어떤 랩터와도 다르다. 그들은 부자연스러운 영리함을 보이며, 기술이라고는 알 리 없는 발톱으로 투박한 오두막을 짓고 도구를 만든다.\n\n더욱 기이한 것은 반짝이거나 낯선 것이라면 무엇이든 탐내는 그들의 욕심이다. 그 때문에 그들은 근처의 호드 정착지를 습격해 눈에 띄는 것이라면 무엇이든 끌고 간다.",
	["s:1413:ratchet"] = "톱니항은 불모의 땅 동쪽 해안에 자리한 고블린 항구 마을로, 바다 건너 무법항과 레빌가즈 남작과 활발히 교역한다. 가즐로는 오그리마를 세워 준 대가로 스랄에게서 받은 돈으로 이곳을 세웠고, 마을은 밀수꾼들과 번듯한 곳에서 내쳐진 온갖 이들로 채워졌다.\n\n그 무관심이 하마터면 큰 대가를 치를 뻔했다. 불타는 칼날 교단은 오그리마와 테라모어를 서로 이간질하려고 은밀히 움직였고, 톱니항 부두 근처에서 해운 사고를 꾸며 양쪽 모두 그것을 도발로만 여기게 만들었다. 부두를 평화롭게 함께 쓰던 오크와 인간 선원들이 거리에서 주먹다짐을 벌이기 시작했고, 해결사 머즐크랭크가 선장 클라트와 조크를 체포하자 북부 전초기지는 그것을 오크들이 전쟁을 위해 결집하고 있다는 증거로 받아들였다. 톱니항은 그들에 맞서 진군할 준비를 하는 호드 군대의 집결지가 되었다. 불타는 칼날이 이 일에 손을 쓴 것이 드러나고서야 스랄은 싸움이 시작되기 전에 그것을 멈추었다.",
	["s:1413:shrine of the fallen warrior"] = "크로스로드 서쪽의 언덕으로 닳은 오솔길이 올라가며, 그 끝에는 전사한 용사를 기리는 제단이 있다. 그곳에는 새겨진 이름도, 걸린 깃발도 없다. 언덕은 침묵을 지키고, 그 위로 오르는 길만이 아직 누군가 기억하고 있다는 유일한 표시이다.",
	["s:1413:sludge fen"] = "진흙늪이 처음부터 땅의 상처였던 것은 아니다. 한때 이곳에는 수정처럼 푸른 물웅덩이가 있었다. 투자개발회사가 와서 그 위에 석유 굴착기를 세우기 전까지는. 이제 남은 것은 산업 폐기물의 수렁이며, 회사에 작업을 책임지는 고블린 감독관의 감시 아래 돌아가고 있다.\n\n굴착기는 물을 더럽힌 만큼이나 경쟁자들도 끌어들였다. 톱니항의 기술자 조합은 투자개발회사의 신형 벌목기에 필적하라는 이사 리들복스의 압박을 받자, 더 나은 것을 만들려는 노력을 포기하고 아예 설계를 훔치기로 했다. 고블린 스퍼터밸브는 위즐크랭크를 보내 늪에서 기계 한 대를 빼앗아 톱니항으로 끌고 오게 했다. 위즐크랭크는 벌목기에 올라타는 데까지는 성공했지만, 그것을 움직일 열쇠가 없다는 것을 깨달았다. 그는 적지 한가운데 갇힌 채 구조대가 올 때까지 기다렸고, 그제야 기계는 회사 일꾼들의 코앞에서 걸어 나갈 수 있었다.",
	["s:1413:southern gold road"] = "남부 황금길이라는 이름은 이 길을 오가는 짐마차 행렬에서 왔다. 길은 불모의 땅 남쪽 끝의 구름 승강장에서 시작해 북쪽으로 불모의 땅의 두 지역을 잇는 다리까지 이어지며, 그곳에서부터는 그냥 황금길이 된다.\n\n상인들은 먼 곳에서 이 길로 온다. 타나리스의 가젯잔에서, 어둠의 해안의 아우버다인에서, 북쪽의 나이트헤이븐에서. 모두 같은 길을 따르며, 그 이름을 지어 준 바로 그 교역에 이끌려 온다.",
	["s:1413:southfury river"] = "분노의 강은 하이잘 산 높은 곳에서 발원해, 산정 호수에서 쏟아져 저지대로 우레처럼 떨어지는 폭포를 이룬다. 그곳에서부터 강은 넓고 빠르게 흐르며 땅을 둘로 가른다. 잿빛 골짜기가 아즈샤라로 바뀌는 곳을 표시하고, 더 남쪽에서는 불모의 땅이 끝나고 듀로타가 시작되는 곳을 가른다. 하구에서 강은 고블린 항구 톱니항의 바로 북동쪽에서 마지막 폭포를 넘어 대해로 뛰어든다.\n\n강을 따라 세 개의 다리가 놓여 있다. 하나는 아즈샤라와 잿빛 골짜기를 잇고, 하나는 여행자들을 오그리마로 실어 나르며, 하나는 듀로타와 불모의 땅을 잇는다. 그중 가장 서쪽 다리의 바로 북쪽에는 네 땅에 한꺼번에 닿는 물줄기가 한 곳 있다. 잿빛 골짜기와 아즈샤라, 듀로타, 불모의 땅이 만나는 유일한 곳이다.",
	["s:1413:stagnant oasis"] = "죽은 오아시스는 무역 해안과 황금길 사이에 고인 푸른 물웅덩이이다. 콜카르 켄타우로스가 그 가장자리에 야영하는데, 그들의 존재와 활력은 이 고인 물 자체에서 나온다고 한다. 이곳을 떠도는 코도는 남쪽 거인의 들판의 거대한 무리와 달리 약하고 외톨이여서 훨씬 쉬운 먹잇감이다. 수면 아래로는 요리하면 귀하게 여겨지는 돌연변이 물고기가 헤엄치고, 그 곁의 탁한 물속에는 오아시스 치악거북이 도사리고 있다.",
	["s:1413:thorn hill"] = "가시덩굴 언덕은 크로스로드와 듀로타 사이의 산꼭대기 북쪽 면에 자리하며, 그 비탈에는 서슬갈기 부족의 가시멧돼지가 우글거린다. 그들은 이 높은 곳에서 이 지역을 지나는 호드 짐마차 행렬을 습격해, 아래쪽 길을 지키는 이들의 분노를 샀다.",
	["s:1413:tidus stair"] = "타이더스 계단은 무역 해안 위로 넓은 돌 계단식 단들이 층층이 쌓여 솟아 있어, 마치 바다를 내려다보는 거인의 계단 같다. 두 타우렌, 이슬렌 워터시어와 마렌 스카이시어가 이 바위 턱에 머물며 파도에 낚싯줄을 드리우고 아래 물속에 깃든 정령들과 이야기를 나눈다.",
	["s:1413:wailing caverns"] = "통곡의 동굴이라는 이름은 이곳 자체의 소리에서 왔다. 바위 틈으로 증기가 터져 나와 길고 구슬픈 울음처럼 어둠 속을 울린다.\n\n이 동굴을 발견하고 그 쓰임새를 정한 이는 나이트 엘프 드루이드 나랄렉스였다. 초원 아래로는 물길이 흘러 다른 곳에서 불모의 땅의 흩어진 오아시스로 솟아났는데, 나랄렉스는 그 물을 에메랄드의 꿈 자체와 이으면 그 푸른 생명력을 위쪽의 메마른 땅에 다시 쏟아부을 수 있으리라 믿었다. 그는 제자들을 이끌고 동굴로 내려가 명상에 들어갔고, 꿈과 깨어 있는 세상 사이의 통로로 자신을 열었다.\n\n그러나 그를 삼킨 것은 에메랄드의 악몽이었다. 나랄렉스는 깨어날 수 없었다. 열린 채 잠든 그의 몸을 통해 악몽의 타락이 동굴로 쏟아져 들어와 물을 오염시키고, 야생 동물을 기이한 돌연변이 형태로 뒤틀었으며, 제자 대부분을 광기로 몰아넣었다. 남은 자들은 송곳니 드루이드가 되었다.\n\n나랄렉스는 지금도 그곳에서 잠들어 있고, 송곳니 드루이드는 그를 깨우려는 자라면 누구에게서든 동굴을 지키고 있다.",
	["s:1416:dalaran"] = "달라란은 트롤 전쟁 이후 아라소르 제국의 마법사들이 세운 마법사의 도시로 일어섰으며, 그 자체로 하나의 나라가 되었다. 이곳 사람들은 어떤 왕관이 아니라 오직 키린 토, 곧 6인 의회가 다스리는 세계에서 가장 강력한 마법사들의 정예 집단만을 따랐다. 그 중심에는 비전을 연구하는 이들의 성소이자 안식처인 보랏빛 성채가 서 있었고, 엘프의 땅 쿠엘탈라스를 제외하면 어떤 도시도 그토록 거대한 마력을 품고 있지 않았다. 자존심 강한 쿠엘탈라스의 하이 엘프 마법사들조차 키린 토의 주권 앞에 고개를 숙였다.\n\n그 주권은 불길 속에 무너졌다. 스컬지가 달라란을 덮치자 백성들은 자신들의 왕국에서 쫓겨났고, 아키몬드가 직접 도시를 폐허로 만들어 살아남은 키린 토 일원들을 아제로스 곳곳으로 흩어 놓았다.\n\n살아남은 자들은 도시를 죽은 채로 두지 않았다. 그들은 잔해로 돌아와 재건에 나섰고, 부서진 심장부를 더 이상의 해로부터 지키기 위해 거대한 마법의 돔을 세웠다.",
	["s:1416:dandreds fold"] = "고원의 서쪽 끝, 땅이 물안개 호숫가와 만나고 항구가 로다미어 호수로 열린 곳에 작은 농장과 저택이 서 있다.\n\n이곳에는 알리덴이 살며, 그의 정부 엘리사도 함께 산다. 그녀는 한때 타레사 폭스턴의 것이었던 목걸이를 걸고 있다.",
	["s:1416:lordamere internment camp"] = "로다미어 포로수용소는 달라란 분화구 위의 언덕에 자리하며, 알터랙 산맥에 세워진 유일한 수용소로서 달라란 병력의 감시 아래 있다.\n\n달라란으로 가던 길에 아서스 메네실 왕자와 제이나 프라우드무어는 한때 밤의 어둠을 틈타 순찰대와 감시탑을 몰래 지나 안에 갇힌 오크들을 보러 온 적이 있다. 그들이 본 것은 두 사람을 갈라놓았다. 제이나는 오크 여인들과 아기들을 보며 확신이 흔들려 의심과 후회로 바뀌는 것을 느꼈다. 아서스는 아무것도 느끼지 않았고, 어쨌든 수용소는 필요하다고 주장했다. 둘 다 발각되지 않았다. 그들은 온 길로 돌아갔고, 두 사람 사이의 이견도 그들과 함께 떠났다.\n\n지금은 교도관 벨라무어가 주둔군을 지휘하며, 키건 다크마와 그의 동료들이 가져온 혈석 유물을 연구하고 있다.",
	["s:1416:ruins of alterac"] = "한때 도시가 서 있던 알터랙 산맥의 비탈에는 부서진 성벽이 올라가 있다. 궁전은 반쯤 서 있고, 교회와 시청은 안으로 무너져 내렸으며, 성문은 스톰윈드의 것을 본떠 지어졌다.\n\n도시의 몰락은 자기 왕에게서 비롯되었다. 2차 대전쟁 때 에이든 페레놀드 왕은 반역자가 되어 오크 호드와 손잡고 동족인 인간들에게 등을 돌렸다. 알터랙 병사들이 오크와 함께 싸우는 것이 발견되었고, 도시 근처의 포로수용소에는 달라란 시민들이 갇혀 있었다. 진실이 드러나자 다른 인간 왕국들은 보복을 위해 알터랙으로 진군했다. 백성들은 달아나거나 집에서 쫓겨났고, 로데론의 테레나스 메네실 2세 왕은 도시에 계엄령을 선포하고 페레놀드를 끌어내려 사슬로 묶었다.\n\n도시는 다시 일어서지 못했다. 무그톨이 이끄는 산사태 오우거가 텅 빈 거리와 궁전에 자리를 잡았고, 옛 알터랙 백성의 흩어진 잔존자들은 그 너머 외곽 마을들을 지켰다. 부서진 고기 수레가 지금도 북쪽 성벽과 성문 근처에 놓여 있고, 성벽 안팎의 묘지들과 눈에 파묻힌 농장, 잔해 사이의 부서진 대형 쇠뇌는 버려진 그대로 남아 있다.",
	["s:1416:uplands"] = "고원은 한때 한 왕국을 먹여 살렸다. 그 언덕들은 알터랙의 곡창이었고, 옛 나라에 곡물과 목초지를 내주었다.\n\n그 나라는 무너졌다. 고원은 어떤 왕관에게도 넘어가지 않고 비밀결사의 손에 들어갔으며, 산맥 어디에서도 이곳만큼 그들이 굳게 장악한 곳은 없다. 바르두스 남작이 이곳 야영지들을 지휘하며, 무너진 왕국의 남은 땅을 다스리는 영주 노릇을 하고 있다.\n\n가장 서쪽 끝에는 단드레드 장원이 서 있다. 그 이름은 그것이 한때 무엇을 뜻했든 그 의미보다 오래 살아남았다.",
	["s:1417:boulderfist hall"] = "돌주먹일족 소굴은 아라시 고원 남부, 탄돌 교각과 마른나무껍질 마을 근처에 서 있으며, 오우거의 손으로 요새화된 돌무더기 언덕이다. 그 중심의 큰 동굴 안에서는 돌주먹 부족의 족장 코르그레쉬 콜드레이지가 군림한다.\n\n그 뒤로 오우거들은 주변 언덕으로 세력을 넓히며 방어를 더욱 강화했다.",
	["s:1417:bouldergor"] = "스트롬가드 요새 북쪽에는 돌주먹 언덕이 부서지고 거칠게 솟아 있다. 돌주먹 오우거가 이곳에 소굴을 두고 있으며, 마른나무껍질 숲 트롤이 그들과 함께 비탈에 머문다. 동쪽 면에는 정령의 마법진이 서 있고, 언덕 바로 남쪽에는 농장 두 곳이 있다.",
	["s:1417:circle of east binding"] = "동쪽 봉인의 돌은 해머폴 근처, 아라시 고원 동부를 굽어보며 이 지역 곳곳에 흩어진 봉인의 마법진 가운데 하나를 표시한다. 물의 정령들이 지금도 이 돌을 지키고 있다. 마치 끝내지 못한 오래된 임무를 붙들고 있기라도 하듯 이곳에 묶여 있다.",
	["s:1417:circle of inner binding"] = "내부 봉인의 마법진은 아라시 고원 남부, 스트롬가드 요새 근처에 있으며 대지의 정령들이 지킨다. 이곳에는 돌들 가운데 가장 강한 내부 봉인의 돌이 놓여 있다.\n\n미즈라엘은 그 파편을 통해 필멸자들과 이야기할 길을 찾아냈다.",
	["s:1417:circle of outer binding"] = "외부 봉인의 마법진은 아라시 고원의 임시 주둔지 근처에 있다. 그 중심에는 외부 봉인의 돌이 서 있으며, 언제나 바람의 정령들이 지키고 있다.",
	["s:1417:circle of west binding"] = "서쪽 봉인의 마법진은 아라시 고원 서부, 소라딘의 성벽 근처에 있다. 그곳에는 서쪽 봉인의 돌이 놓여 있고, 불의 정령들이 한시도 눈을 떼지 않고 지키고 있다.",
	["s:1417:dabyries farmstead"] = "아라시 고원 북쪽에는 다비리 농장이 있으며, 스트롬가드의 시민이자 얼라이언스에 충성하는 케나타 다비리와 그녀의 자식 파델과 마르셀이 지키고 있다. 이 가족에게는 적이 있기 때문에 민병대가 들판을 감시한다.",
	["s:1417:drowned reef"] = "아라시 고원 남쪽 해안 앞의 만 아래에는 오래되고 폐허가 된 엘프의 도시가 가라앉아 있다. 그곳은 더 이상 비어 있지 않다. 비수지느러미 나가가 그곳을 차지했으며, 나즈자크 왕자가 다스린다.\n\n그 위의 산호초는 처녀의 어리석음호와 은빛소나무의 혼호를 비롯해 많은 배를 삼켰다. 비수지느러미 나가는 만의 조류마저 움직일 수 있어서, 팔디르의 만에서 안전한 항구를 찾았다고 생각한 선원들을 대신 바위로 꾀어낸다고 한다.",
	["s:1417:drywhisker gorge"] = "마른수염 골짜기는 해머폴 북동쪽, 아라시 고원 동부의 산맥을 가로지른다. 그 끝에는 동굴이 있는데, 이 고원을 함께 쓰는 거인들과 동맹을 맺은 마른수염 코볼트의 보금자리이다.\n\n굴을 지나 깊숙한 곳에는 미즈라엘 공주의 정수 일부가 갇혀 있는 돌 파편이 놓여 있다. 코볼트들은 동굴 깊은 곳에 모인 티끌들과 함께 그것을 사납게 지키지만, 그 파편에 진정으로 무엇이 담겨 있는지 아는 이는 그들 가운데 없는 듯하다.",
	["s:1417:faldirs cove"] = "팔디르의 만이라는 이름은 팔디르에게서 왔다. 그가 추종자들과 함께 길을 떠날 때 이곳을 표시해 두었다고 전해진다.\n\n한참 뒤, 검은바다 약탈단이 근처 바다에 있다는 엘프의 보물을 찾아왔다. 스틸거트 선장과 오브린 선장이 배 세 척을 이끌고 만으로 들어왔지만, 산호초 아래 가라앉은 폐허를 지키는 나가가 일으킨 기이한 조류가 그들을 덮쳐 세 척 가운데 두 척이 가라앉았다. 오직 전령호만이 해안에 닿았고, 선원들은 나가를 몰아내고 아래의 난파선에서 항해 일지를 되찾을 때까지 만에 갇혀 떠나지 못했다.\n\n훗날 노움 기술자 드랙슬게이지 박사와 피즐소프 교수는 가라앉은 산호초의 바위 속에 굳어 있다는 엘프의 보석을 찾는 장치를 만들었다.\n\n만은 지금도 그 물에 잠긴 역사의 상처를 안고 있다. 산호초와 난파선과 폐허 모두가 결코 가라앉지 말았어야 할 배들과, 바다가 아직 내놓지 않은 보물에 대해 이야기한다.",
	["s:1417:goshek farm"] = "고셰크 농장은 아라시 고원 동부, 마른나무껍질 마을 근처에 있다. 3차 대전쟁 이후 해머폴에서 온 포세이큰과 오크들이 저마다의 목적으로 이 농장을 차지했다. 오크들은 이곳에서 보급품을 얻었고, 포세이큰은 들판과 헛간을 더 어두운 종류의 연금술 실험장으로 바꾸었다.\n\n얼라이언스 요원 퀘와 키넬로리가 이곳에서 벌어지는 일을 조사하러 왔다. 그들은 도움을 받아 타렌 밀농장으로 향하던 포세이큰 전령을 전갈을 전하기 전에 처치했고, 농장 자체를 뒤져 약제사 조렐의 기록을 찾아냈다. 그의 연구는 새롭고 끔찍한 무언가가 모습을 갖추어 가고 있음을 가리키고 있었다. 또 다른 역병이 만들어지고 있었던 것이다.\n\n지금은 해머폴 병사들이 농장을 지키고 있다.",
	["s:1417:hammerfall"] = "해머폴의 땅은 자신이 한때 무엇이었는지 기억한다. 2차 대전쟁 이후 로데론 연합은 이곳에 가장 큰 수용소 가운데 하나를 짓고, 붙잡힌 오크들을 그 벽 안에 가두었다. 이곳은 계속 감옥으로 남지 않았다. 대족장 스랄과 오그림 둠해머는 동족을 풀어 주기 위해 호드를 이끌고 수용소를 공격했고, 그 해방의 혼란 속에서 스랄이 후퇴를 엄호하는 동안 돌격해 온 기사 하나가 오그림의 등에 창을 꽂았다. 창은 그의 갑옷 앞뒤를 꿰뚫을 만큼 강했다. 둠해머는 자신이 해방하러 온 바로 그 땅에서 숨을 거두었다.\n\n3차 대전쟁 이후 호드는 폐허로 돌아와 그 사이에 전진 기지를 세웠고, 그곳을 차지하다 쓰러진 대족장을 기려 해머폴이라 이름 지었다. 그곳은 전초기지 이상의 곳이 되었다. 세상에 더는 설 자리가 없다고 느끼는 이들의 안식처가 된 것이다. 한때 수용소의 벽이 서 있던 자리에는 이제 정령의 오두막과 마구간, 대장간, 대전당이 서 있다.",
	["s:1417:northfold manor"] = "스트롬가드가 함락된 뒤, 북부습곡 장원은 비밀결사의 손에 넘어가 아라시 고원의 전초기지가 되었다.\n\n트롤 주술사 톨간은 공기 중의 무언가 잘못된 기운에 이끌려 이곳에 왔다. 그것을 장원까지 추적한 그는 그곳에 아직 들러붙어 있는 악마 소환의 잔재를 발견했고, 가까이 다가가자 온전히 자기 것이 아닌 분노로 피가 끓어오르기 시작했다. 그는 바닥에서 악마를 불러내는 데 쓰이는 혈석 부적을 발견했는데, 그것은 이미 힘이 다한 것이었다. 비밀결사의 음모가 단순한 도적질보다 깊다고 의심한 그는 그들의 진짜 속셈을 알아내기 위해 다른 부적들을 찾아 나섰다.",
	["s:1417:refuge pointe"] = "3차 대전쟁 때 스트롬가드의 수도가 폐허로 무너지자, 백성 대부분은 남쪽의 아라시 고원으로 달아났다. 그러나 스트롬가드 군의 잔존 병력은 그들을 따라가지 않았다. 그들은 잃어버린 것을 되찾겠다는 결의로 남았고, 바로 이곳 임시 주둔지에서 버티기로 했다.\n\n이 전초기지는 고원에서 벌어지는 얼라이언스 전쟁의 본거지가 되었고, 병사들은 스트롬가드 요새를 탈환하고 얼라이언스의 대의를 위해 확보할 수 있는 모든 자원을 확보하는 데 몰두했다. 그 한결같은 목표는 다른 무엇에도 여지를 남기지 않았다. 탄돌 교각이 검은무쇠 드워프의 맹공을 받고 그곳 드워프들이 던 모드르와 교각을 되찾을 지원을 요청하는 전갈을 보냈을 때, 니알스 대장은 단 한 명도 내줄 수 없었다. 스트롬가드가 함락되었으니, 그곳을 되찾을 때까지 임시 주둔지의 모든 검과 모든 손은 오직 그 대의에 속한다고 그녀는 말했다. 명예와 의무가 그들을 고원에 묶어 두고 있으니, 냉혈한 롱브레이드는 그들 없이 해 나가야 할 것이라고 그녀는 전령에게 전했다.",
	["s:1417:stromgarde keep"] = "스트롬가드는 한때 최초의 인간 왕국의 요람이자 아라소르 제국의 수도인 스트롬이었다. 오크 호드가 동부 왕국에 왔을 때에도 스트롬가드는 여전히 로데론 연합의 강국으로 서 있었고, 2차 대전쟁 이후에도 그 이름은 굽히지 않았다.\n\n도시는 3차 대전쟁 이후 약탈당해 부서진 채 남겨졌다. 지금 이곳은 셋으로 나뉘어 있다. 안쪽 요새는 비밀결사가, 폐허가 된 마법사 지구는 마른나무껍질 트롤의 도움을 받는 돌주먹 오우거가 차지했고, 마지막 구역은 여전히 스트롬가드 군이 지키고 있다. 갈렌 트롤베인 왕자가 그곳에서 남은 백성을 지휘한다.",
	["s:1417:thandol span"] = "저습지와 아라시 고원 사이의 틈에는 두 개의 거대한 돌 아치가 걸쳐 있다. 드워프의 손으로 세워져 삼대에 걸쳐 앤빌마 가문이 지켜 온 다리이다. 이 다리는 세 망치의 전쟁 이후, 아이언포지가 맹금의 봉우리에 있는 와일드해머 동족과의 신의를 지키려 했을 때 세워졌다. 다리는 두 드워프 왕국 사이의 길이자 상징이 되었고, 두 왕국 모두를 부유하게 한 교역을 실어 날랐다.\n\n이 다리는 군대 전체의 무게를 견딜 수 있었고, 한때 드워프와 인간 사이의 주요 교역로였다. 안두인 로서가 구 호드의 마지막 잔당을 로데론에서 몰아내 카즈 모단으로 되돌려 보낸 곳도 바로 이곳이었다. 패배한 그들은 교각을 건너 쫓겨 갔다.\n\n이제 교각은 상처를 입은 채 서 있다. 캄 딥퓨리와 추악한 발가라스가 꾸민 검은무쇠 드워프의 음모가 다리에 큰 피해를 입혔고, 드워프 병력은 남은 것을 지키고 근처의 던 모드르 마을을 되찾기 위해 싸우고 있다. 많은 드워프가 이 싸움에서 목숨을 잃었는데, 그중에는 설리 발루와 에버니저 러스트록, 그리고 냉혈한 롱브레이드의 형제도 있었다.",
	["s:1417:thoradins wall"] = "소라딘 왕은 스트롬이 아직 젊고 아라소르가 인류를 위해 이 땅을 막 차지했던 시절, 아마니 트롤을 막기 위해 이 성벽을 세웠다. 여러 세대 동안 성벽은 굳건한 파수꾼으로 서서, 트롤의 침입으로부터 인류를 지키는 방어선 역할을 했다.\n\n수 세기가 지난 지금도 성벽은 서 있지만, 심하게 손상되어 돌은 부서지고 그 오랜 감시는 폐허로 전락했다.",
	["s:1417:tower of arathor"] = "아라소르의 탑은 스트롬가드 요새의 마법사 지구에 서 있으며, 왕국이 그 혈통을 이어받은 옛 아라소르 제국의 이름을 따서 불린다.\n\n대마법사 트렐레인은 한때 이 탑 안에서 연구했으며, 마법이 깃든 보석으로 깨우기 전까지 잠들어 있는 방어 장치를 탑 자체에 엮어 넣었다. 비밀결사와 돌주먹 오우거가 스트롬가드를 조여 오자 트렐레인은 자신의 창조물로 탑을 지키려 했지만, 역부족이었다. 그는 도시를 떠나 달아났고, 탑도 도시와 함께 무너졌다. 돌주먹 오우거가 그 지구를 차지했고, 오우거 마법사 룰 원스톤이 탑의 전당에 자리를 잡았다.\n\n트렐레인은 그곳에 두고 온 것들을 결코 잊지 못했다. 그의 성구함과 보주, 그리고 손수 다듬은 불씨 마노였다. 그는 옛 제자인 대마법사 말린에게 지금 탑을 차지한 오우거들에게서 그것들을 되찾아 달라고 부탁했다. 이윽고 말린에게 옛 스승의 물건들이 다시 발견되었다는 소식이 전해졌다. 한때 그가 자기 집이라 부르던 전당 안의 상자들 속에 숨겨져 있었다.",
	["s:1417:witherbark village"] = "마른나무껍질 마을은 아라시 고원 남동쪽의 작은 호수를 둘러싸고 자리하며, 마른나무껍질 부족 트롤의 보금자리이다. 마을 뒤에는 커다란 동굴이 있는데, 부족의 지도자들은 대개 그곳에 있다.\n\n마른나무껍질 부족은 근처의 돌주먹 오우거와 손을 잡았고, 그 동맹은 스트롬가드와 해머폴을 겨누고 있다. 트롤과 오우거는 함께 옛 주인들에게서 빼앗은 스트롬가드의 한 구역을 차지하고 있다.\n\n그 힘 때문에 마른나무껍질 부족은 표적이 되었고, 그들의 종말을 바라는 얼라이언스와 호드 모두에게 쫓기고 있다. 그 심판에 맞선 이들 가운데 학살자 니마르가 가장 위험한 자로 꼽혔다. 그는 죽으면서 많은 적을 함께 데려간 전사였다.",
	["s:1418:agmonds end"] = "황야의 땅 중남부의 발굴지는 그곳에서 죽은 드워프의 이름을 지니고 있다. 아그몬드는 바위를 깨러 왔다가 이미 그 땅을 차지한 트로그들을 만났다. 그들은 그 자리에서 그를 끝장냈고, 발굴지는 그들에게 버려졌다.",
	["s:1418:angor fortress"] = "검은무쇠 드워프는 고통의 요새를 황야의 땅의 본거지로 삼아, 울다만을 향한 발굴을 지휘하고 있다.",
	["s:1418:apocryphans rest"] = "아포크리판의 안식처의 뼈들은 카르가스 남쪽 황야의 땅에 널브러져 있다. 쓰러진 용의 해골이 메마른 열기 속에 하얗게 바래도록 버려져 있는 것이다. 이제 대머리수리들이 갈비뼈 사이에 둥지를 틀고 사냥하며, 그 거대한 사체를 보금자리로 삼은 것은 그들뿐이다.",
	["s:1418:camp boff"] = "보프 야영지는 먼지목도리 오우거의 남동쪽 야영지로, 카그, 코쉬, 우르그 야영지와 함께 네 야영지 가운데 하나이다. 이곳을 지키는 오우거는 얼마 되지 않는다.",
	["s:1418:camp cagg"] = "카그 야영지는 먼지목도리 오우거의 보금자리 가운데 하나로, 근처에 흩어진 다른 세 야영지와 같은 이름을 공유한다.",
	["s:1418:camp kosh"] = "코쉬 야영지는 먼지목도리 영역의 북쪽 끝에 자리하며, 카르가스로 굽이지고 이글거리는 협곡으로 내려가는 황량한 길을 지켜본다. 황야의 땅을 건너는 짐마차 행렬은 이 구간을 두려워한다. 코쉬의 오우거들이 무엇을 싣고 있든 빼앗으려고 그들을 덮치기 때문이다.",
	["s:1418:camp wurg"] = "우르그 야영지는 먼지목도리 오우거의 보금자리 가운데 하나로, 이곳 오우거들은 카그, 보프, 코쉬 야영지의 오우거들과 한 핏줄이다.",
	["s:1418:dustbelch grotto"] = "황야의 땅 남서부에는 흙과 돌로 된 거대한 언덕이 솟아 있는데, 먼지목도리 오우거가 그 속을 파내고 차지했다. 먼지목도리 소굴은 그들의 보금자리로, 갈라지고 햇볕에 그을린 주변 땅 한가운데에 부족이 굴과 방을 얽어 만든 소굴이다.",
	["s:1418:dustbowl"] = "먼지받이는 카르가스와 송곳니 골짜기 사이에 놓인, 황야의 땅 북서부의 갈라지고 메마른 땅이다. 코요테와 대머리수리가 그 위를 누비고, 바위 정령들이 돌 사이에서 꿈틀댄다. 선인장과 몇 그루의 끈질긴 나무 말고는 자라는 것이 거의 없다. 우르그 야영지가 이 황무지 안에 서 있다.",
	["s:1418:dustwind gulch"] = "바람이 먼지바람 협곡을 쓸어내려 부드러운 것은 하나도 남지 않았고, 오직 돌과 협곡의 메마른 뼈대만 남았다. 이곳은 레슬로 협곡 서쪽에 있는 황야의 땅의 척박한 골짜기로, 흙먼지가 오래 가라앉는 법이 없다.",
	["s:1418:hammertoes digsite"] = "해머토의 발굴현장은 황야의 땅 북부에 있으며, 한때 광부들이 일하던 발굴 참호는 이제 고요하다. 해머토 자신은 이곳을 버리고 떠났고, 그 자리에는 검은무쇠 드워프 무리가 들어왔다. 아마 울다만으로 밀고 들어간 바로 그 세력일 것이다.",
	["s:1418:kargath"] = "카르가스는 카즈 모단에서 호드가 보유한 유일한 전초기지로 홀로 서 있으며, 산산조각난손 부족의 족장 카르가스 블레이드피스트의 이름을 땄다.\n\n대족장 스랄의 직접 명령에 따라 카르가스 원정대는 혹독한 황야의 땅으로 거듭 출정한다. 그들의 진짜 목적은 이글거리는 협곡을 지나 검은바위 산까지 길을 뚫어, 호드가 검은 호드의 대족장 렌드 블랙핸드를 그의 본거지에서 칠 수 있게 하는 것이다. 그 길은 검은무쇠 드워프가 자기 땅이라 부르는 곳을 지나기에, 호드는 계획해서가 아니라 단지 건너야 할 땅 때문에 다시 그들과 전쟁을 벌이게 되었다.\n\n카르가스의 또 다른 가치는 더 분명하다. 이곳은 북과 남을 잇는 경첩으로, 해머폴과 언더시티에서 오는 길이 그롬골과 무법항, 스토나드로 내려가는 길과 만나는 지점이다.",
	["s:1418:lethlor ravine"] = "레슬로 협곡은 황야의 땅 동부를 넓고 험준하게 가로지르며, 그 바닥에는 검은용군단의 새끼용과 비룡들이 출몰한다. 협곡 곳곳에는 수정 오벨리스크들이 서 있는데, 바위와 용의 불길 한가운데서 기이하고도 의도적으로 세워진 듯하다.",
	["s:1418:makers terrace"] = "울다만 입구 바깥의 땅은 넓고 의도적으로 깎여 나가, 하늘을 향해 열린 발굴의 흉터로 남아 있다. 지금은 검은무쇠 드워프가 정원을 차지하고, 발굴지와 아래의 묻힌 곳으로 내려가는 길을 지켜보고 있다.",
	["s:1418:mirage flats"] = "신기루 벌판은 황야의 땅의 먼지목도리 소굴 동쪽에 있다. 이곳에는 거대한 대머리수리와 마루 추적자 우두머리, 광포한 바위산 코요테만이 차지한 무인지대만 남아 있다.",
	["s:1418:uldaman"] = "카즈 모단의 산맥 깊숙한 곳에는 먼 옛날 티탄의 관리인들이 세운 거대하고 오래된 금고, 울다만이 있다. 3차 대전쟁 전 아이언포지의 드워프들이 한때 그 안을 파고들어 묻힌 방들을 깎아 냈지만, 그 후 금고는 트로그와 검은무쇠 드워프의 손에 넘어갔고, 그들은 지금 그 안에 남아 있을 대지의 보물을 찾아 돌을 파헤치고 있다.\n\n울다만에는 티탄이 빚어낸 그 시대의 유산이 여전히 풍부하며, 그 깊은 곳에 용감히 들어가는 이들은 지금도 그 안에 묻힌 유물을 찾아낸다. 탐험가 연맹의 고고학자와 모험가들이 폐허를 계속 뒤지며 그것들을 천천히 발굴해 내고 있다.",
	["s:1418:valley of fangs"] = "송곳니 골짜기는 황야의 땅의 두 암벽 사이로 좁게 뻗어 있으며, 늑대와 퓨마가 이곳을 차지하고 있다. 이곳의 이름은 그들의 이빨에서 왔다.\n\n그 안에는 어디에선가 쫓겨난 추방자 마르테크가 리글퍼즈, 재즈릭과 함께 야영하고 있다.",
	["s:1419:dark portal"] = "어둠의 문은 그 첫 순간부터 배신으로 만들어졌다. 굴단과, 암흑의 티탄 살게라스에게 사로잡힌 인간 마법사 메디브가 함께 균열을 찢어 열었다. 드레노어에서는 문의 돌 틀을 세운 오크 석공들이 마지막 봉인을 준비하기 위해 흑마법사들에게 살해당했고, 호드가 아직 붙잡아 두고 있던 드레나이 포로 거의 모두가 문 아래로 끌려와 한순간에 생명을 빨려, 굴단이 두 세계를 이을 힘을 얻었다. 그 관문을 통해 호드는 스톰윈드로 쏟아져 들어와 1차 대전쟁을 일으켰고, 뒤이은 전쟁에서 끝없는 오크와 오우거를 아제로스로 들여보냈다. 그 주변의 늪지는 엉겨 붙어 훗날 저주받은 땅이라 불리는 핏빛 황무지가 되었다.\n\n전쟁이 끝날 무렵, 대마법사 카드가와 동료 마법사들은 호드의 퇴각을 막기 위해 아제로스 쪽의 구조물을 부수었는데, 그 폭발이 너무나 격렬해 드레노어 쪽의 틀까지 파괴되었다. 카드가는 그 뒤 폐허를 감시하기 위해 네더가드 요새를 세웠지만, 두 세계 사이의 균열은 결코 완전히 봉인되지 않았고, 그 후 몇 해 동안 악마들이 다시 그곳을 통해 넘어오게 된다.",
	["s:1419:dreadmaul post"] = "우레망치 주둔지는 우레망치 오우거 부족이 쌓아 올린 언덕이다. 그들은 드레노어에서 아제로스로 건너와 어둠의 문에서 멀리 벗어난 적이 없다. 그들은 지금도 이 땅을 지키고 있다.",
	["s:1419:garrison armory"] = "저주받은 땅의 상처 입은 대지에서, 얼라이언스 광부들은 요새 무기고에서 일하며 네더가드 요새를 위해 땅에서 광물을 캐낸다. 그들이 모은 것은 스톰윈드로 보내지고, 그 대가로 요새는 그 황폐한 땅에서 버티는 데 필요한 다른 보급품을 받는다.",
	["s:1419:nethergarde keep"] = "네더가드 요새는 저주받은 땅으로 들어가는 유일한 길 위의 높은 절벽에 서 있으며, 그 성벽은 아무도 다시 열리기를 원치 않는 세상의 상처를 지켜보기 위해 세워졌다.\n\n2차 대전쟁 이후, 첫 번째 어둠의 문이 부서지고 그 너머 오크의 고향이 시들어 폐허가 되었을 무렵, 대마법사 카드가가 이 요새의 건설을 요청했다. 로데론 연합이 비용을 댔는데, 어떤 왕국은 다른 왕국보다 기꺼이 냈다. 석공 조합은 에드윈 밴클리프의 지휘 아래 요새를 세웠다. 그 뒤로 키린 토가 요새를 맡아, 문의 상처에서 스며 나와 그 너머 땅으로 번지려는 오염을 막는 데 힘썼다.\n\n카드가는 넬쥴의 부족들이 드레노어 쪽에서 어둠의 문을 다시 만들어 요새를 포위할 때까지 이곳의 주인이었다. 카드가와 그의 동료 투랄리온, 다나스 트롤베인, 알레리아 윈드러너, 쿠르드란 와일드해머는 얼라이언스를 이끌고 문을 통과해 그곳에서 호드를 무너뜨렸고, 드레노어의 파멸이 그들을 따라 고향까지 오지 못하도록 저편에 남아 문을 봉인했다. 그 후 이십 년 동안 어둠의 문은 침묵했다.",
	["s:1419:rise of the defiler"] = "파멸자의 봉우리는 저주받은 땅 한가운데에 부서진 산의 험준한 자락으로 솟아 있다. 이곳에는 거대한 악마 라젤리크가 살며, 그 존재만으로도 이곳의 이름이 되기에 충분하다.",
	["s:1419:serpents coil"] = "뱀의 보금자리는 저주받은 땅 동부의 구불구불한 동굴로, 그 입구는 2차 대전쟁 때 남은 불타 버린 오크 건물들로 표시되어 있다. 그 전쟁이 끝나고 한참 뒤, 동굴은 더 어두운 것들의 소굴이 되었다. 저주받은 키리스를 숭배하는 데 몸을 바친 광신도들이다.\n\n그 미로에 대마법사 알리스타르즈가 찾아와 그 안에서 자신의 그림자 서약단을 부리기 시작했다. 입구 근처의 상자에는 그의 이름이 새겨진 목걸이가 들어 있다.",
	["s:1419:tainted scar"] = "타락의 흉터는 한때 검은늪의 일부였다. 어둠의 문의 타락이 스며들어 땅을 메마르게 하고 나무 한 그루 없이 피처럼 붉게 만들기 전까지는. 이제 그곳에는 물이 흐르지 않는다. 악마의 짐승들이 무엇이 자랐는지 더는 기억하지 못하는 흙 위를 배회한다.\n\n하이잘 산 전투 이후, 에레드루인 군주 카자크는 아제로스에 남은 불타는 군단의 병력을 흉터로 물려 그곳을 자신의 영토로 삼았다. 그는 부관인 파멸자 라젤리크를 그 위에 세워 땅을 굳게 지키라 명했다. 카자크 자신은 그 뒤로도 그곳에 머물렀고, 하이잘에서 싸움이 벌어지고 승패가 갈린 지 여러 해가 지난 지금도 그의 존재만으로 흉터는 여전히 군단의 영토임이 드러난다.\n\n한참 뒤, 늙은 인간 흑마법사 노쇠한 다이오가 흉터에 와서 그 제단에 거처를 마련했다. 그는 이 땅이 이미 길러 낸 악마들 사이에서 방해받지 않고 의식을 행하며 젊은 신참들을 받아들였고, 이미 지옥의 기운에 넘어간 이곳에서 그들에게 지옥의 마법을 가르쳤다.",
	["s:1420:agamand family crypt"] = "아가만드 밀농장 북쪽, 한때 아가만드 가문의 망자들이 이 납골당에 잠들어 있었다. 스컬지의 하수인인 다르골 대장이 이곳을 차지하고 그 안의 모든 시체와 영혼을 깨웠다. 이제 어두운 통로에는 먼지가 자욱하고, 복수심에 찬 망자들은 허락 없이 들어오는 자를 누구든 공격한다.",
	["s:1420:agamand mills"] = "아가만드의 풍차들은 한때 티리스팔에서 가장 부유한 가문 가운데 하나를 위해 돌았다. 스컬지가 북쪽으로 쳐들어왔을 때, 그레고르 아가만드는 달아나기를 거부했다. 그는 밀농장을 요새화하고 포위에 대비해 물자를 비축했으며, 가문의 일꾼들을 설득해 함께 남아 싸우게 했다.\n\n버텼어야 했다. 그러나 버티지 못했다. 배신이 성벽 안에서 나왔기 때문이다. 아가만드 가의 막내아들 데블린이 자기 핏줄에게 등을 돌리고 스컬지를 도왔고, 수비대는 뒤이은 공격을 막아 내지 못했다. 결국 역병은 나머지 가족마저 데려갔고, 집을 지키다 죽은 아가만드 가 사람들은 그 안에서 정신 없는 망자로 되살아났다.\n\n풍차들은 지금도 티리스팔 북부의 고지대에 서 있으며, 그것을 세운 가문은 이제 자신들을 무너뜨린 바로 그 군세를 섬기고 있다.",
	["s:1420:balnir farmstead"] = "발니르 농장은 폐허가 된 수도의 북동쪽에 있으며, 울타리는 부서졌고 마구간은 떠도는 스컬지 말고는 텅 비어 있다.\n\n한때 발니르 가문이 이 땅을 일구며 로데론 왕가가 타던 거대한 백마를 길렀다. 수도가 함락된 날, 스컬지가 농장에 들이닥쳐 가족 전체를 죽였고, 남은 것은 유령이 출몰하는 땅뿐이었다.\n\n한때 농장 정원에서 가꾸던 금어초는 지금도 그곳에서 제멋대로 자라는데, 역병지대의 타락이 그 꽃들에까지 스며들었을지 모른다는 소문이 산 자들에게 전해졌다. 보루를 빠져나온 스컬지가 폐허가 된 농장 주변에 무리 지어 모여든다.",
	["s:1420:brightwater lake"] = "청명 호수는 브릴 북동쪽에 있으며, 그 한가운데에는 지금 군터의 은거지가 서 있는 커다란 섬이 있다.",
	["s:1420:brill"] = "브릴은 한때 로데론 왕국의 평범한 마을로, 바로프 가문이 다스렸고 아가만드 가문도 그 안에 저택을 두고 있었다. 그 평범함은 켈투자드가 이곳에 온 날 끝났다. 아직 살아 있는 인간이었던 그 강령술사는 죽음의 역병을 처음 시험할 곳으로 브릴을 골랐고, 그 감염이 너무나 완벽하게 성공한 나머지 그는 대담해져 리치 왕에게 로데론 침공을 때 이르게 시작하자고 밀어붙였다. 티리스팔 숲의 망자는 땅이 제대로 묻어 줄 수 있는 것보다 많았다. 브릴 성벽 밖의 거대한 묘지가 그 넘치는 망자들에 대한 답으로 남아 있다. 마을의 수비대는 마을을 지키지 못했고, 살아남은 이들은 북부를 휩쓰는 타락의 근원을 쫓던 아서스 메네실 왕자에게 합류하러 달아났다.\n\n브릴은 침묵 속에 남지 않았다. 몇 해 뒤 포세이큰이 이곳을 차지했고, 이제 행정관 세브렌이 한때 역병이 앗아 간 것을 다스린다. 오래된 원한도 이곳에 남아 있다. 한때 아가만드 가문을 섬겼던 콜맨 파딩은 지금도 그들의 유해를 찾고 있다. 자비가 아니라, 그들 탓이라 여기는 죽음에 대한 복수로 바치는 뼈이다.",
	["s:1420:brill town hall"] = "마을회관은 브릴에서 가장 눈에 띄는 건물이다. 그 연단에서 행정관 세브렌은 마을을 대변하며 티리스팔의 망자들에게 저마다의 임무를 맡긴다. 이처럼 포세이큰의 손에 있는 회관은 어디에서도 드물며, 그것은 브릴이 얼마나 확고하게 그들의 것인지 보여 준다.",
	["s:1420:bulwark"] = "보루는 티리스팔 숲이 서부 역병지대와 만나는 곳에 서 있으며, 포세이큰이 동쪽에 여전히 집결한 스컬지에 맞서 지키는 방어선이다. 이곳에서 포세이큰 수비대와 은빛 여명회는 공동의 적 앞에서 서로의 차이를 제쳐 두고, 함께 경계를 감시하며 리치 왕의 하수인들을 치러 동쪽으로 전사들을 보낸다.\n\n티리스팔의 다른 곳과 달리 이 구간은 전혀 숲처럼 보이지 않는다. 역병의 안개가 그 위에 드리워, 하늘을 그 너머 서부 역병지대와 같은 병든 누런 잿빛으로 물들이고 있다.",
	["s:1420:cold hearth manor"] = "버려진 장원은 한때 따뜻한 난롯가와 기름진 들판으로 이름이 높았다. 죽음의 역병이 그 모든 것을 끝냈다. 이곳에 살거나 일하던 사람은 모두 병으로 죽었고, 풍요롭던 땅은 황폐해져 밭고랑마다 정신 없는 스컬지 망자들이 차지했으며, 그들은 지금도 그곳을 비틀거리며 돌아다닌다.\n\n포세이큰은 농가를 차지하고 근처 길을 오가는 여행자들을 상대하고 있다.",
	["s:1420:crusader outpost"] = "티리스팔 숲 동쪽 언덕에는 붉은십자군이 지키는 정찰탑이 솟아 있다. 그들은 그 높은 곳에서 숲을 지나 남쪽으로 뻗은 길을 감시하며, 그 너머 붉은십자군 수도원으로 감히 진군하는 세력이 있으면 측면을 칠 준비를 하고 있다. 바숑 대장이 이곳을 지휘한다.",
	["s:1420:deathknell"] = "데스넬은 좁고 경비가 삼엄한 골짜기에 자리하며, 새로 되살아난 포세이큰이 자신들에게 주어진 세상에 처음 눈을 뜨는 곳이 바로 이곳이다.\n\n밴시 여왕이 이끄는 반역 언데드의 다른 거점들은 살아 있던 시절 마을의 이름을 그대로 간직했지만, 데스넬만은 완전히 새로운 이름을 얻었다. 한때 그곳에 무엇이 있었는가가 아니라 그곳에서 무슨 일이 일어나는가에 걸맞은 이름이었다. 지금은 그 까닭을 기억하는 이가 아무도 없다.\n\n이곳에서 살아남는 것은 날마다의 싸움이며, 가장 귀한 것은 금이다. 마을 북서쪽에는 금속이 풍부한 광산이 있지만 거미들에게 점령당해, 데스넬의 망자들은 그 아래 광석을 마침내 캘 수 있도록 광산을 되찾으려고 거듭 나선다. 죽음의 경비대 정예병들이 골짜기 가장자리를 따라 감시를 서며, 연약한 새 망자들과 그들을 두 번째로 죽이려는 스컬지와 붉은십자군 사이를 막아선 유일한 존재가 되어 준다.",
	["s:1420:faols rest"] = "붉은십자군 수도원 남서쪽, 티리스팔 숲 동부에는 한때 추모객들이 돌보던 땅이 있다. 대주교 알론서스 파올의 무덤, 파올의 안식처이다.\n\n파올은 살아생전 존경을 받았고, 스컬지가 오기 얼마 전 그가 세상을 떠나자 추모객들이 이곳으로 모여들었다.\n\n그가 남긴 무덤은 이제 찾는 이가 없다. 한때 찾아오던 추모객들은 사라졌고, 무덤은 돌보는 이 없이 거의 잊혀 있다.",
	["s:1420:gallows end tavern"] = "갤로우 선술집은 브릴에 있으며, 그 이름은 이 선술집이 자리한 마을을 음울하게 되울린다. 그 바닥 아래 지하실에는 이렇다 할 술통 하나 없다. 대신 사로잡힌 붉은십자군 광신자와 드워프 산악병이 포세이큰의 포로로 갇혀 있다.",
	["s:1420:garrens haunt"] = "가렌의 흉가는 한때 티리스팔 숲 북부의 풍요로운 농장으로, 들판은 넓고 곡식 창고는 가득했다. 죽음의 역병이 그 모든 것을 끝냈다. 로데론 정화 때 스컬지가 휩쓸고 지나가자 가렌과 그의 가족은 살던 곳에서 학살당했고, 폐허가 된 집 주변의 땅마저 잿빛으로 생명을 잃었다.\n\n아직 서 있는 것은 구더기눈이 이끄는 썩은가죽 놀이 차지했다. 그들은 농가와 헛간을 자기 것으로 삼고, 너무 가까이 다가오는 자는 누구든 망설임 없이 공격했다.\n\n농장은 끝내 회복되지 못했다. 들판은 비었고 가족은 사라진 채 버려져 있으며, 이제 누가 이곳을 차지하고 있는지 대답할 수 있는 것은 놀들뿐이다.",
	["s:1420:gunthers retreat"] = "청명 호수의 한 섬에는 군터의 은거지가 서 있으며, 포세이큰 리치 군터 아르카누스와 그의 좀비 하수인들이 차지하고 있다. 그 남서쪽 해안 앞의 이름 없는 헐벗은 작은 섬에는, 그저 릴리스의 식탁이라고만 알려진 기이한 표지가 놓여 있다.",
	["s:1420:night webs hollow"] = "검은그물 거미굴은 오래된 금광이 가로지르는 작은 골짜기로, 골짜기와 광산 모두 거미들의 차지이다. 어린 거미들은 탁 트인 골짜기를 돌아다니고, 다 자란 검은그물 거미는 광산의 더 어두운 굴을 지킨다.\n\n새로 되살아난 포세이큰은 자신의 몸이 아직 무엇을 할 수 있는지 시험하러 이곳에 와서, 바깥의 어린 거미들을 베어 낸 뒤에야 감히 광산 안으로 들어간다.\n\n그 가장 깊숙한 곳에는 위쪽 무리 모두의 어미인 검은그물 여왕거미가 도사리고 있다.",
	["s:1420:nightmare vale"] = "티리스팔 숲의 붉은십자군 감시탑 서쪽에는 폐허가 된 골짜기가 있다. 나무들은 시들었고, 한때 그 사이에 살던 야생 동물은 어둠사냥개와 거대한 흡혈박쥐에게 모조리 잡아먹혔다. 이 사냥꾼들 사이로 다른 것들과는 다른 희귀한 흰 박쥐, 가시바늘 레산이 날아다닌다.",
	["s:1420:north coast"] = "북부 해안은 티리스팔 숲이 대해와 만나는 곳으로, 이제는 멀록과 물의 생물들에게 넘어갔다. 죽음의 역병 이후 해안은 어둡고 차가워졌고, 밀물은 죽은 바다 생물들을 물가에 남겨 썩게 한다.",
	["s:1420:ruins of lordaeron"] = "묻힌 도시 위로 로데론의 궁전은 여전히 서 있다. 전당은 하늘을 향해 뚫려 있고 정원은 폐허가 되었다. 얼라이언스의 위대한 왕국이 죽은 곳이 바로 이곳이며, 그 유령들은 이곳을 끝내 떠나지 못했다.\n\n그것을 끝낸 이는 아서스 메네실이었다. 왕자는 자기 백성에게 겨눈 군대를 이끌고 고향으로 돌아왔고, 그가 무엇이 되었는지 누구도 깨닫기 전에 종소리와 환호 속에 이 성문을 지나 환영받았다. 그는 왕좌의 방에서 기다리던 아버지 테레나스 왕을 찾아내 그 자리에서 죽였다. 시신을 굽어보며 그가 한 말은 지금도 그 방에 머무는 이에게 메아리친다. 왕국은 무너질 것이고, 그 잿더미에서 세상을 뒤흔들 새로운 질서가 일어나리라고. 헛된 호언이 아니었다. 며칠 만에 도시와 백성은 학살당했고, 로데론은 스컬지의 것이 되었다.\n\n지금도 안뜰을 걸으면 돌이 기억하는 것을 들을 수 있다고 한다. 속삭이는 목소리, 환영하는 종소리, 결코 완전히 사라지지 않는 왕좌의 방의 웅얼거림. 장막 너머를 볼 수 있는 이들은 로데론의 시민들이 자기 왕국이 사라진 줄도 모른 채 아직 그곳을 걷고 있다고 말한다.",
	["s:1420:scarlet monastery"] = "십자군의 손에 넘어간 옛 수도원은 병영이자 감옥이 되었다. 종교재판관 화이트메인과 르노 모그레인이 이곳을 본거지로 삼았고, 예배당은 기도의 장소일 뿐 아니라 심판의 장소가 되었다.\n\n요새가 되기 전 옛 수도원은 성스러운 빛의 교회에 속한 대성당으로, 성기사들이 수련하는 도서관으로 가득했다. 알렉산드로스 모그레인도 젊은 시절 칼을 들기 전에 이곳에서 여러 달 동안 기도하고 공부했다.",
	["s:1420:scarlet watch post"] = "붉은십자군 경비초소는 붉은십자군 수도원이 홀로 지킬 수 없는 길목을 지키기 위해 경계를 서고 있다. 멜라쉬 대장이 이곳을 지휘하며, 수도원의 드러난 측면을 몰래 치려는 자라면 누구에게서든 초소를 지킨다.",
	["s:1420:shadow grave"] = "암흑의 무덤은 티리스팔의 산속 높은 곳, 데스넬 묘지 안 비탈 꼭대기에 서 있다. 그 입구에서 닳은 길이 구불구불 내려가 아래의 데스넬에 이른다.",
	["s:1420:solliden farmstead"] = "솔리덴의 호박밭은 티리스팔에서 옛 삶이 역병이나 죽음에 삼켜지지 않은 몇 안 되는 땅 가운데 하나이다. 주변 땅이 스컬지에게, 그리고 그로부터 일어난 포세이큰에게 넘어가는 동안에도, 이곳 농부들은 근처 붉은십자군 방책에 있는 붉은십자군의 보호를 받으며 여전히 밭고랑을 일군다.\n\n그 보호 때문에 솔리덴은 별난 곳이 되었다. 농부들은 붉은십자군이 아닌 누구도 믿지 않는다. 자신들을 거의 앗아 갈 뻔했던 역병의 괴물이라며 포세이큰을 내치고, 얼라이언스도 경계한다. 얼라이언스의 깃발이 작고 잊힌 채로 지내 지금껏 피해 온 전쟁 속으로 그들을 끌어들일지 모르기 때문이다.\n\n포세이큰이 그냥 두지 못하는 것은 바로 그 고요이다. 죽음의 경비병 시머는 솔리덴의 지금 모습이 아니라 앞으로 될지도 모를 모습을 감시한다. 오늘은 평화로운 농부들이지만, 내일은 얼라이언스의 무장한 소작인이자 포세이큰이 지키려는 땅의 발판이 될 수도 있다.",
	["s:1420:stillwater pond"] = "역병이 오기 전 고요의 연못은 산 자들이 젊음을 누리던 곳이었다. 숲의 가족들이 이 기슭에 소풍을 왔고, 청명 호수의 깊은 물에 들어가기에는 너무 어린 아이들이 대신 이곳에서 헤엄을 배웠다.\n\n이제 그 물은 잿빛이다. 수면 아래의 물고기는 누구도 멈추라고 말해 주지 않은 듯 계속 헤엄치는 뼈일 뿐이다. 떠도는 언데드와 야수들이 물가를 지나가고, 어둠사냥개 베인이 물가를 배회하며 머뭇거릴 만큼 방심한 것이라면 무엇이든 잡아먹는다.\n\n포세이큰이 폐허에서 브릴을 일으켜 세우기 시작했을 무렵, 붉은십자군 전사들은 고요의 연못 기슭을 순찰하기 시작했다.",
	["s:1420:terrace of repose"] = "붉은십자군 수도원 바로 북쪽에는 역병이 한 번도 닿지 않은 땅이 있다. 이곳에는 푸른 산울타리가 자라고, 티리스팔 숲의 다른 곳과 달리 분수는 고여 썩지 않고 맑게 흐른다. 붉은십자군은 이 작은 정원을 돌보며, 역병 한가운데서도 깨끗한 무언가가 여전히 살아남을 수 있다는 증거로 지켜 내고 있다.",
	["s:1420:undercity"] = "포세이큰이 차지하기 훨씬 전부터 언더시티에는 이름과 쓰임새가 있었다. 로데론 궁전 저 아래로는 왕실 망자들의 오래된 납골당과 지하 감옥, 하수도가 뻗어 있었다. 그곳은 오직 죄수와 시체를 위한 곳이었지만, 로데론에서 가장 가난한 사람들은 어떻게든 그 어둠 속으로 몰려들었고, 그들을 몰아내려는 경비병들의 소탕은 한 번도 효과를 거두지 못했다.\n\n리치 왕이 자신의 피조물에 대한 장악력을 잃자, 실바나스 윈드러너는 정신을 유지한 언데드들과 함께 스컬지에서 떨어져 나와, 자신을 이렇게 만든 타락한 왕자 아서스에게 칼끝을 돌렸다. 그녀는 폐허가 된 왕국에서 그를 함정으로 꾀어냈지만, 그는 켈투자드의 도움으로 빠져나가 북쪽으로 달아나 스스로 리치 왕이 되었다. 싸움터의 주인으로 남은 실바나스와 그녀의 추종자들은 스스로를 포세이큰이라 부르며 폐허가 된 수도 아래의 납골당을 차지했고, 스컬지가 짓기 시작한 요새를 완성했다.\n\n지금 서 있는 것은 방어를 위해 지은 미로이다. 모든 길을 따라 독성 오물의 강이 흐르고, 공기는 산 자가 숨쉬기도 힘들 만큼 짙은 독기로 가득하다. 포세이큰에게 그곳은 여전히 자신들을 사냥하는 세상 속의 피난처이다.",
	["s:1420:venomweb vale"] = "독그물 골짜기는 한때 사슴과 토끼가 가득한 푸른 곳이었으나, 지금은 독거미들이 들끓는 골짜기가 되었다. 희귀하고 치명적인 스리스컬크가 그들을 이끌며, 그 거미줄이 풀을 대신해 이 골짜기에 이름을 주었다. 북쪽의 붉은십자군 야영지 근처에는 어둠사냥개들이 어슬렁거리며, 그 야영지는 샌더스 중위가 지키고 있다.",
	["s:1420:whispering gardens"] = "붉은십자군 수도원 남쪽의 언덕에서는 한때 훗날 붉은십자군이 될 사람들과 스컬지 군세 사이에 전투가 벌어졌다. 양쪽 모두 많은 이가 쓰러졌다. 황혼이 내리면 그들의 영혼은 여전히 그곳에 머물며, 정원의 고요한 돌 사이에서 희미한 속삭임으로 웅얼거린다.",
	["s:1420:whispering shore"] = "속삭임의 해안은 티리스팔 숲 서부, 솔리덴 농장 북쪽에 있다. 어부들은 한때 이곳의 잔잔한 물과 꾸준한 어획을 좋아했다.\n\n그 풍요는 사라졌다. 멀록들이 해안을 점령해 다가오는 자는 누구든 덮치고, 물은 차갑고 어두워졌다.",
	["s:1421:ambermill"] = "앰버밀은 한때 은빛소나무 숲 로다미어 호수 남서쪽에서 목재를 베던, 별로 중요하지 않은 제재소 마을이었다.\n\n스컬지와 불타는 군단이 이 마을의 가치를 바꾸어 놓았다. 스스로의 폐허에서 재건 중이던 달라란의 키린 토가 마을을 점령했고, 한동안 앰버밀은 이제껏 한 번도 되어 본 적 없는 무언가가 되었다. 달라란의 마법에 힘입어 은빛소나무 숲에서 인간이 벌이는 진정한 저항의 원천이 된 것이다.\n\n포세이큰은 그것을 그냥 지켜보지 않았다. 그들의 죽음추적자들은 한 포로를 통해, 마법사들이 그곳에 달라란 자체의 상황과 관련된 문서를 보관하고 있다는 사실을 알아냈다. 제재소와 마구간, 시청은 여전히 키린 토의 손에 있지만, 첩자들은 숲의 그림자 속에서 그들을 노리고 움직인다.",
	["s:1421:berens peril"] = "앰버밀 남서쪽의 언덕에는 베렌의 동굴이 있다. 3차 대전쟁이 끝나고 몇 해 뒤, 포세이큰 정찰병들은 암흑사제 알리스터에게 언데드들이 그곳에 몰래 모여 공동묘지를 공격하려 집결하고 있다는 소식을 전했다. 그 언데드들은 강령술사 툴 레이븐클로를 섬겼다. 그는 공동묘지를 위협할 만큼 가깝고 길에서 눈에 띄지 않을 만큼 먼 이곳을 골라 남몰래 하수인들을 모았다.",
	["s:1421:dawning isles"] = "여명의 섬은 한때 로다미어 호수의 수정같이 맑은 물에서 낮고 완만하게 솟아 있었고, 어떤 어려움도 닿지 않은 고요한 섬들이었다. 죽음의 역병이 그것을 바꾸어 놓았다. 나무들은 병들었고, 멀록과 늪괴물이 작은 섬들을 점령했다. 늪괴물은 이제 사라졌지만, 썩은지느러미 멀록은 거침없이 번식해 지금은 섬 전체를 차지하고 있다.",
	["s:1421:dead field"] = "죽음의 농장은 은빛소나무 숲 북부에 버려져 있으며, 들판은 썩었고 원래 주인들은 잊혔다. 알려진 것은 그 뒤로 이곳을 차지한 것들이다. 스컬지를 섬기는 썩은가죽 놀이 폐허가 된 농장을 거점으로 삼았고, 그 수는 점점 불어나 이곳에서 어떤 공격이 아직 준비되고 있음을 짐작케 한다.\n\n포세이큰은 놀들이 움직이기 전에 무너뜨리려고 여러 번 농장을 공격했다. 모든 시도가 실패했다. 썩은가죽 놀이 위협을 받을 때마다, 놀들을 자기 부하처럼 부리는 밴시 나이트래시가 그들의 부름에 응답해 허공에서 나타나 그들을 지켰다.",
	["s:1421:decrepit ferry"] = "오래된 나루터는 한때 영주와 그 가족이 저택을 두고 있던 펜리스 섬으로 물자를 실어 날랐고, 사람들은 한 번 건널 때마다 뱃사공에게 동전 몇 닢을 냈다.\n\n그러다 스컬지가 로데론을 덮쳤다. 뱃사공은 일하던 자리에서 살해당했고, 나룻배는 부서졌다.\n\n이제 폐허가 된 부두에는 구울과 해골 전사, 썩은가죽 놀이 출몰하며, 나루터는 버려진 채 강한 자가 아니면 누구에게나 위험한 곳으로 남아 있다.",
	["s:1421:deep elem mine"] = "심원 광산은 은빛소나무 숲에 있다. 아루갈이 이곳까지 마법을 퍼뜨렸고, 늑대인간들은 한때 이곳의 작업반장이었던 창백한 그림슨을 우두머리로 삼아 광산을 소굴로 만들었다.\n\n달라 던위버는 포세이큰이 바리마트라스의 이름으로 광산을 자원으로 차지할 수 있도록 그림슨의 죽음을 바랐다.",
	["s:1421:fenris isle"] = "펜리스 섬은 로다미어 호수 한가운데에 있으며, 여명의 섬과 함께 이루는 끊어진 고리 모양의 뭍 가운데 하나로, 대략 은빛소나무 숲의 일부로 여겨진다.\n\n3차 대전쟁 전, 이 섬에는 로데론의 군사 거점인 펜리스 요새가 있었다. 스컬지가 땅을 휩쓸자 요새는 함락되었다. 사람들은 달아나거나 그 자리에서 죽임을 당했고, 섬은 텅 빈 채 남았다.\n\n그 빈자리에 썩은가죽 놀이 들어와 버려진 요새를 소굴로 삼았다. 그들의 주인은 놀들 사이에서조차 배신자로 기억되는 툴 레이븐클로였다. 그는 썩은가죽 놀을 다스리고 그들을 통해 펜리스 섬 전체를 지배하며, 자신이 차지한 요새와 근처의 오래된 나루터까지 손에 쥐고 있다.",
	["s:1421:fenris keep"] = "펜리스 요새는 은빛소나무 숲 로다미어 호수 한가운데의 펜리스 섬 위에 서 있으며, 한때 로데론 군의 상당 부분이 머물던 곳이다.\n\n스컬지가 땅을 휩쓸자 요새도 함께 무너졌다. 그 폐허에 한때 키린 토에 속했던 젊은 마법사 툴 레이븐클로가 찾아왔다. 그는 스컬지와 손을 잡고 섬의 놀들을 자기 뜻대로 굴복시켜 썩은가죽 부족으로 만들었다. 그 부족을 등에 업고 그는 펜리스 요새의 주인이 되었고, 썩은가죽 놀은 주인에게 다가오는 자는 누구든 덮친다.",
	["s:1421:greymane wall"] = "겐 그레이메인 왕은 3차 대전쟁 전에 이 성벽을 세웠다. 오크 수용소에 길니아스의 돈이 쓰이는 데 지치고, 로데론 연합의 왕들을 갈라놓은 다툼에 진력이 났기 때문이다. 그는 왕국의 문을 안으로 걸어 잠그고, 길니아스를 로데론과 산 너머의 세상으로부터 단절시켰다.\n\n성벽은 죽음의 역병을 막아 냈지만, 대가가 따랐다. 스컬지가 로데론을 휩쓸자 피난민들이 남쪽으로 달아나 성문 밖에 진을 쳤지만, 여러 해 동안 성문은 열리지 않았다. 피난민들은 아무 대답도 듣지 못한 채 그곳에서 죽어 갔다.",
	["s:1421:ivar patch"] = "이바르 호박밭은 한때 가질 만한 농장이었다. 밭고랑마다 호박이 탐스럽게 열렸고, 집에는 이바르라는 사내를 위해 밭을 일구는 일꾼들이 가득했다. 넉넉한 살림이었다. 죽음의 역병이 로데론을 덮쳐 그에게서 그것을 앗아 가기 전까지는.\n\n이바르는 그저 죽지 않았다. 그는 되살아났고, 그의 가족도, 그의 땅을 일구던 모든 일꾼도 되살아나 썩어 가는 구울이 되었으며, 이제 가까이 오는 자는 누구든 덮친다. 이바르 자신은 더 끔찍한 것으로 되살아나, 지금은 추악한 이바르로 기억된다.\n\n위험을 가늠하라고 북쪽으로 보내진 죽음추적자 셋이 이곳에서 구울들에게 붙잡혔고, 추악한 이바르는 그중 하나인 퀸 요릭에게 상처를 입혔다. 퀸과 그의 친족 레인은 이바르의 옛집 안에 방책을 치고 틀어박혔다.",
	["s:1421:lordamere lake"] = "로다미어 호수는 한때 그 기슭을 고향으로 삼았던 왕국들의 그림자 아래 펼쳐져 있다. 로데론이 호수 북쪽 끝에 세워졌으며, 호수의 이름은 옛 로데인의 이름을 딴 그 위대한 도시에서 왔을 가능성이 크다. 로데론 연합이 인간 왕국들을 하나로 묶던 시절에는 달라란과 알터랙 또한 이 물가에서 번영을 누렸다.\n\n그 시대는 지나갔고, 남은 것은 경계선이다. 이제 호수는 티리스팔 숲과 은빛소나무 숲의 포세이큰 영토와 분쟁 중인 알터랙 산맥 사이에 놓여, 죽은 자와 산 자를 갈라놓는다.\n\n그 한가운데에는 펜리스 섬이 있으며, 그 요새는 툴 레이븐클로 휘하의 썩은가죽 놀이 차지하고 있다.\n\n펜리스 섬 동쪽의 작은 여명의 섬들은 썩은지느러미 멀록이 차지해 완전히 점령해 버렸다.",
	["s:1421:maldens orchard"] = "말덴의 과수원의 나무들은 어둡게 변해 늘 푸른 채로, 열매는 철이 지나도록 따는 이 없이 매달려 있다. 말덴 자신은 스컬지가 로데론을 덮쳤을 때 집에서 쫓겨나 오래전에 사라졌다.\n\n이제 과수원은 늑대들의 차지로, 그들은 나무 사이와 아직 서 있는 작은 오두막 한 채 주변에 무리 지어 굴을 틀고 있다. 죽음추적자 얼랜드 맥크리가 북부 숲을 정찰하던 중 과수원을 살피라는 명을 받고 들어선 곳이 바로 이곳이었다. 늑대들은 그가 얼마 가지도 못해 그를 몰아붙였고, 그는 버려진 오두막 안에 방책을 치고 며칠 동안 갇혀 있다가, 다른 포세이큰 요원들의 도움으로 빠져나와 기다리던 동료들에게 돌아갔다.",
	["s:1421:north tides hollow"] = "북부 해안 골짜기는 은빛소나무 숲의 공동묘지 바로 북쪽에 있다. 이곳은 대마법사 아루갈의 하수인인 달울음 늑대인간이 출몰하는 여러 곳 가운데 하나이다. 그들은 이곳에 투박한 야영지를 세우는데, 이빨과 힘으로 살아가는 존재에게 충분한 피난처로서 생존에 필요한 가장 초라한 것들만 갖추고 있다.",
	["s:1421:north tides run"] = "은빛소나무 숲의 북서쪽 해안, 모래사장이 차가운 대해와 만나는 곳은 북부 해안가라 불린다. 얕은 물에는 부서진 호드 배 한 척이 반쯤 가라앉아 선체를 파도에 묻고 있으며, 이 해안에서 가장 눈에 띄는 표지이다.",
	["s:1421:olsens farthing"] = "올슨 농장은 한때 은빛소나무 숲을 지나는 교역로 가장자리에 서 있던, 지나가는 행렬을 먹여 살리던 농장이었다.\n\n3차 대전쟁이 그것을 끝냈다. 몇 해 지나지 않아 농장은 폐허가 되었다.",
	["s:1421:pyrewood village"] = "장작나무 마을은 은빛소나무 숲 가장자리에 자리하며, 3차 대전쟁 때 스컬지의 첫 습격을 견디고 살아남은 인간들이 모여 사는 곳이다. 북쪽에는 한때 실버레인 남작이 다스리던 요새가 서 있었고, 성기사 스프링베일 사령관과 백은의 손이 그곳을 지켰다. 실버레인과 그의 부하들은 대마법사 아루갈의 늑대인간들에게 학살당했고, 아루갈은 요새를 차지해 그림자송곳니 성채라 이름을 바꾸었다. 그곳에서 아루갈은 광기를 장작나무 마을로 돌려 주민들에게 저주를 걸었다. 그들은 밤마다 침을 흘리는 달울음 늑대인간으로 변해 길을 가로지르는 자는 누구든 물어뜯고, 새벽이 오면 다시 인간으로 깨어난다.\n\n그럼에도 마을은 낮이면 여전히 여행자에게 문을 열며, 주민들은 끝이 보이지 않는 아루갈의 저주에 묶여 있다.",
	["s:1421:sepulcher"] = "공동묘지는 은빛소나무 숲 서쪽 언덕, 로데론 해안선 위에 자리한다. 한때 길이 가로지르던 소박한 묘지로, 그 납골당은 망자의 안식처 이상을 뜻하지 않았다.\n\n3차 대전쟁 이후 포세이큰은 옛 묘지를 차지해 작전 기지로 바꾸었고, 죽은 자를 위해 지어진 곳을 죽지 않는 자를 위한 곳으로 만들었다.\n\n그것은 어쩔 수 없는 선택이었다. 남쪽에는 늑대인간이 어슬렁거렸고, 동쪽에는 여전히 스컬지가 땅을 차지하고 있었으며, 남동쪽에서는 키린 토가 지켜보고 있었다. 거의 사방이 포위된 포세이큰에게 공동묘지는 은빛소나무 숲에서 호드가 안전하게 설 수 있는 몇 안 되는 곳 가운데 하나였다.",
	["s:1421:shadowfang keep"] = "그림자송곳니 성채는 장작나무 마을 위의 높은 절벽에 서 있다. 이곳은 한때 길니아스의 영주 실버레인 남작의 것이었다. 스컬지가 로데론을 덮치고 왕실 대마법사 아루갈이 그들을 막을 방법을 찾기 전까지는. 마법사 우르의 연구를 바탕으로, 겐 그레이메인 왕의 축복을 받되 키린 토의 조언은 거스른 채, 아루갈은 늑대인간을 소환했다. 늑대인간들은 언데드의 물결을 되돌려 놓았지만, 곧 길니아스 자체에 등을 돌려 그레이메인 성벽을 유린하고 은빛소나무 숲으로 풀려났다. 그들은 요새를 덮쳐 실버레인 남작과 그의 일가를 죽였다.\n\n자신이 풀어놓은 것에 무너진 아루갈은 그것을 피해 달아나지 않았다. 그는 늑대인간을 자기 자식이라 부르며 요새를 차지하고 그림자송곳니라 이름을 바꾸었다. 늑대 교단에서 섬기던 주인과 교감하며 그는 숲 전체에 저주를 퍼뜨렸고, 마침내 장작나무 마을까지 변해 버렸다. 주민들은 낮에는 인간, 밤에는 짐승이 되었고, 오직 그에게만 답하는 의회가 마을을 다스렸다.",
	["s:1421:shining strand"] = "반짝이는 호숫가는 로다미어 호수를 따라, 북쪽의 로데론 수도에서 은빛소나무 숲과 알터랙 산맥을 가르는 거친 언덕까지 이어진다.\n\n썩은지느러미 부족 멀록이 호숫가를 빽빽한 거주지로 채우고 있어, 이 물가를 모르는 여행자들은 이곳을 두려워하게 되었다. 고인이 된 약제사 베라드는 일지에 썩은지느러미 멀록에게서 얻을 수 있는 희귀한 물건인 굳은 종양에 대해 적으며, 그것으로 새로운 역병을 만들 수 있을지도 모른다고 추측했다.",
	["s:1421:skittering dark"] = "암흑 땅거미굴이라 알려진 광산은 땅거미 거미들이 차지했고, 그들의 거미줄이 부서진 목재와 녹슨 연장 위에 드리워 있다. 그 깊은 곳에는 괴물처럼 자라난 땅거미 여왕거미가 숨어, 결코 떠나지 않는 어둠 속에서 무리를 다스린다. 바깥에서는 희귀한 그림자실잣기 크레시스가 이따금 홀로 바위 사이를 누빈다.\n\n땅바닥에는 고치가 널려 있는데, 그 안에는 늑대인간과 늑대, 곰, 그리고 서쪽 해안의 난파선에서 끌려온 오크들이 묶여 있다.",
	["s:1421:south tides run"] = "남부 해안가는 은빛소나무 숲의 남서쪽 해안을 따라, 땅이 대해와 만나는 곳에 이어져 있다.",
	["s:1421:valgans field"] = "발간 농장은 은빛소나무 숲 북부의 황폐한 농장들 사이, 반짝이는 호숫가 서쪽이자 작은 강의 북쪽에 있다. 이곳의 이름은 스컬지가 은빛소나무 숲을 휩쓸었을 때 죽거나 땅에서 쫓겨난 한 농부에게서 왔다. 좋았던 시절 이 농장은 로다미어 호수를 굽어보았고, 그 풍경은 한때의 명성에 걸맞았다.\n\n지금 농장은 텅 빈 채 옛 모습의 폐허로 남아 있지만, 이따금 나이트래시가 그 주변에서 목격된다.",
	["s:1422:bulwark"] = "보루는 티리스팔 숲이 서부 역병지대와 만나는 곳에 서 있으며, 포세이큰이 동쪽에 여전히 집결한 스컬지에 맞서 지키는 방어선이다. 이곳에서 포세이큰 수비대와 은빛 여명회는 공동의 적 앞에서 서로의 차이를 제쳐 두고, 함께 경계를 감시하며 리치 왕의 하수인들을 치러 동쪽으로 전사들을 보낸다.\n\n티리스팔의 다른 곳과 달리 이 구간은 전혀 숲처럼 보이지 않는다. 역병의 안개가 그 위에 드리워, 하늘을 그 너머 서부 역병지대와 같은 병든 누런 잿빛으로 물들이고 있다.",
	["s:1422:caer darrow"] = "다로미어 호수의 섬에는 먼 옛날 인간의 손으로 세운 요새가 서 있었고, 그 안에는 고대 하이 엘프의 룬석이 있었다. 2차 대전쟁 때 호드가 섬을 점령하고 요새를 약탈했으며, 룬석을 뜯어내 폭풍의 제단을 만들었다. 굴단은 그 제단을 통해 호드의 오우거들에게 마법을 불어넣었다.\n\n요새는 재건되어 바로프 가문의 본거지가 되었다. 세월이 전쟁으로 기울어 가자, 바로프 가는 수십 년 동안 일군 것을 잃을까 두려워 저주받은 교단의 수장 켈투자드와 거래를 맺었다. 저택 아래의 지하 묘지는 강령술 학교 스칼로맨스가 되었고, 가문의 하인들은 죽음의 역병 실험 대상으로 넘겨졌다. 반년도 안 되어 병이 풀려나 섬의 모든 이를 죽였다. 희생자들은 그저 죽지 않았다. 그들은 마지막 순간을 되풀이하도록 묶인 유령으로 되살아나, 지금도 카엘 다로우의 폐허가 된 전당을 거닐고 있다.",
	["s:1422:chillwind camp"] = "서리바람 야영지는 서부 역병지대의 남쪽 관문, 알터랙의 산들이 독에 물든 땅으로 바뀌는 곳에 자리한다. 얼라이언스 여행자가 아직 땅이 깨끗하다고 말할 수 있는 마지막 장소이다.\n\n은빛 여명회의 소규모 파견대가 이곳을 지키는데, 병력과 전문가는 몇 명뿐이다. 야영지는 수가 모자란 만큼 대담함으로 이를 메운다. 이곳 사람들은 안돌할의 스컬지 거점과 땅에 죽음을 뿌리는 역병 가마솥을 상대로 게릴라전을 벌이며, 지킬 수 없는 땅을 붙들기보다 치고 사라질 용병들에게 기대고 있다.\n\n그레이슨 섀도브레이커 경은 촉망받는 젊은 백은의 손 기사들을 이곳으로 보내, 애슐람 밸러피스트 사령관과 함께 이 지역의 스컬지에 맞서게 했다.",
	["s:1422:dalsons tears"] = "달슨의 과수원은 한때 이름을 내준 가족을 위해 열매를 맺었다. 이제 그 나무들은 서부 역병지대에서 수확이 아닌 슬픔을 기억하는 이름, 달슨의 눈물로 서 있다.\n\n스컬지는 농장을 차지해 대지의 상처로 만들었다. 그 한가운데에 그들은 거대한 가마솥을 두었고, 가마솥은 그 뒤로 한 번도 멈추지 않고 공기 중에 질병을 뿜어낸다. 가마솥 군주 말비니우스와 그를 섬기는 역병 걸린 망자들이 그것을 지킨다.\n\n달슨 가족은 결코 떠나지 않았다. 달슨 부인은 지금도 해골이 되어 이 땅을 떠돌며, 살아생전 가꾸던 땅을 뒤진다. 그녀의 남편은 그녀 곁에서 죽지 않았다. 그는 옥외 변소에 갇힌 채 버려졌고, 잠긴 어둠 속에서 그가 된 것은 더 이상 사람이 아닌 구울이었다.",
	["s:1422:darrowmere lake"] = "다로미어의 물은 호수가 돛으로 가득했던 2차 대전쟁의 기억을 아직 간직하고 있다. 이곳에 닻을 내린 배 대부분은 프라우드무어 함대의 깃발을 달았고, 쿠엘탈라스가 불타기 전에 대제독은 그중 몇 척을 이 물 건너로 보내 투랄리온과 알레리아 윈드러너, 그리고 그들의 군대를 스트라솔름으로 실어 나르게 했다. 투랄리온은 곧장 쿠엘탈라스까지 항해할지 고민했지만, 알레리아는 엘프들이 인간의 배가 자기네 강을 거슬러 오르도록 결코 허락하지 않을 것이라고 경고했고, 함대는 대신 스트라솔름으로 향했다. 줄진과 그의 무리가 호숫가로 밀려나고 그 트롤 전쟁군주가 사로잡힌 것도 바로 이 전쟁에서였다.\n\n호수 한가운데에는 한때 바로프 가문이 다스리던, 지금은 텅 빈 섬마을 카엘 다로우가 서 있다. 마을의 돌 아래에는 스칼로맨스가 있어 저주받은 교단이 언데드들 사이에서 일하고 있으며, 섬의 물에 잠긴 고요 아래에 어둠이 잠들어 있다.",
	["s:1422:felstone field"] = "펠스톤 농장은 한때 산 자들을 먹여 살렸다. 스컬지가 그 위를 덮쳐 다시는 농장이 되지 못하게 하면서 그것은 끝났다.\n\n스컬지는 농장 한가운데에 거대한 가마솥을 두었고, 가마솥은 그 뒤로 한 번도 일을 멈추지 않았다. 질병으로 가득한 증기가 쉼 없이 쏟아져 나온다. 가마솥 군주 빌마우가 해골 마법사와 해골 가죽벗기미, 침을 흘리는 구울들을 거느리고 그것을 지켜, 살아 있는 어떤 것도 가까이 다가와 깨끗한 몸으로 떠날 수 없게 한다.\n\n북동쪽 구석에는 옛집이 아직 서 있고, 재니스 펠스톤은 여전히 그곳에 머물며 한때 가족의 곡식이 자라던 땅을 떠나지 못하고 있다.",
	["s:1422:gahrrons withering"] = "서부 역병지대 동쪽 끝의 농장은 한때 델 가론의 것이었고, 좋았던 시절에는 파종과 성장의 땅, 가론의 소생지로 알려져 있었다. 이제 그곳에는 아무것도 자라지 않는다. 스컬지가 들판을 차지하고 그 한가운데에 거대한 가마솥을 두었으며, 가마솥은 결코 일을 멈추지 않고 질병 가득한 증기를 공기 중에 뿜어내 땅마저 병든 것처럼 보이게 한다. 가마솥 군주 소울래스가 다른 스컬지 지휘관들과 함께 그것을 지키고, 그 증기는 걸어 다녀서는 안 될 것들을 불러냈다. 폐허가 된 밭고랑 사이를 떠도는 망령의 환영들, 그리고 굶주림 말고는 어떤 주인에게도 따르지 않는 울부짖는 죽음과 굶주린 망령들이다.",
	["s:1422:hearthglen"] = "하스글렌은 안돌할 북쪽에 서 있으며, 그 성벽은 요새와 마법사의 탑, 방앗간과 광산을 에워싸고 있다. 폐허가 된 지역 한가운데서 질서를 보여 주는 모습이다. 여러 해 동안 하스글렌은 마르덴홀드의 영주 티리온 폴드링 아래에서 그 질서를 지켰으나, 그가 오크 에이트리그를 도왔다는 이유로 반역죄로 추방되면서 끝났다. 시간이 흘러 그의 아들 탈란이 마르덴홀드의 영주 자리를 이었다.\n\n훗날 하스글렌은 백은의 손 기사단의 잔존자들을 받아들였다. 그들은 수도가 함락된 뒤 탈란이 내민 피난처 제안에 응했다. 성기사들은 그 뒤 몇 해 동안 이 성벽에서 승리를 거두었지만, 결국 기사단은 붉은십자군으로 뒤틀려 마을을 자기 것으로 삼았다.",
	["s:1422:mardenholde keep"] = "마르덴홀드 요새는 그 전당을 거니는 이들 대부분이 기억하기도 전부터 하스글렌의 중심에 서 있었으며, 오크가 로데론을 침공한 가장 어두운 시절에도 그 성벽은 무너지지 않았다. 여러 해 동안 이곳은 티리온 폴드링의 본거지였다. 거대한 떡갈나무 탁자와 하스글렌의 가장 작은 길까지 그려 넣은 지도가 자리한 회의실에서, 성기사는 참모들과 왕국의 일을 논했다. 오크 에이트리그를 도운 죄로 반역자로 몰린 티리온은 파문당해 추방되었고, 마르덴홀드는 시간이 흘러 그의 아들 탈란에게 넘어갔다.\n\n로데론 정화 이후, 탈란은 살아남은 백은의 손 기사들에게 하스글렌에 머물 곳을 내주었다. 알렉산드로스 모그레인이 죽었다는 소식이 이 성벽 안에 전해졌고, 배신에 대한 의심이 기사단을 갈라놓았다. 맥스웰 티로서스는 추종자들을 이끌고 떠나 은빛 여명회를 세웠고, 남은 이들은 붉은십자군이라는 이름을 택했다. 마르덴홀드는 그들의 요새가 되었고, 탈란은 대영주로 추대되었다.",
	["s:1422:northridge lumber camp"] = "북마루 벌목지는 서부 역병지대 북부, 하스글렌 근처에 있으며, 붉은십자군의 벌목으로 산비탈이 헐벗었다. 십자군은 목재를 얻기 위해 제재소를 돌리고 있으며, 얼라이언스와 호드 모두 그 공급을 망쳐 놓을 까닭이 있다.\n\n3차 대전쟁 전, 제재소는 나다니엘 두마의 가족 것이었고, 그들은 전쟁과 역병에 쫓겨날 때까지 이 땅을 일구었다. 미키 레빈의 가족도 한때 이곳에서 일했다.",
	["s:1422:plaguemist ravine"] = "협곡 하나가 카엘 다로우를 향해 북쪽으로 뻗어 있으며, 그 입구는 산 반대편의 숲속에 있다. 그 통로에는 아무것도 살지 않는다. 새도 그 위를 건너지 않고, 짐승도 그 바위에 굴을 틀지 않는다.\n\n그 안에는 병든 듯 어울리지 않는 안개가 드리워 이 길 하나만을 더럽힌다. 이곳이 지금의 이름을 갖게 된 것도 그 때문이다. 이곳을 다른 곳과 구별하는 안개 때문에 최근에야 붙은 이름, 역병안개이다.",
	["s:1422:ruins of andorhal"] = "안돌할은 서부 역병지대의 심장부에 폐허로 누워 있으며, 부서진 집들이 탁 트인 땅 위에 흩어져 있다. 남은 것은 상당한 힘을 지닌 리치 소환사 아라즈와 그를 섬기는 망자들이 차지하고 있다. 무너진 돌 사이로 몸을 끄는 구울들, 한때 경비병이 서던 자리를 지키는 해골들, 폐허 위로 울음소리가 퍼지는 밴시들, 그리고 집들의 잔해 사이를 육중하게 걷는 누더기골렘들이다.\n\n아라즈는 여전히 그 모든 것의 중심에서, 다시는 일어서지 못한 도시를 다스리고 있다.",
	["s:1422:scholomance"] = "버려진 도시 카엘 다로우 위의 언덕에는 한때 바로프 가문의 본거지였던 저택이 서 있다. 그 가문의 영향력은 카엘 다로우에서 브릴, 사우스쇼어, 타렌 밀농장까지 뻗어 있었다. 수십 년 동안 그들은 편안히 다스렸지만, 세월이 전쟁으로 기울어 가자 바로프 가는 원한과 탐욕에 사로잡혀 자신들이 일군 것을 죽음으로 끝내게 두려 하지 않았다. 그래서 그들은 필멸의 수명을 넘어 재산과 땅을 지키기 위해 저주받은 교단의 수장 켈투자드와 거래를 맺었다.\n\n여섯 달 만에 요새는 완전히 다른 무언가로 썩어 버렸다. 교단의 수련생들은 강령술을 연구했고, 가문의 하인들은 죽음의 역병을 위한 산 실험체로 넘겨졌다. 빛의 인도자 우서가 예정된 저택 방문을 하기도 전에, 그 전당에서 배양된 병이 카엘 다로우에 풀려났다. 병은 아무도 살려 두지 않았고, 희생자들을 그 뒤로도 유령이 되어 떠돌도록 묶어 두었다.\n\n바로프 가 사람들 자신도 언데드로 되살아나, 팔아넘긴 전당에 여전히 묶여 있다. 지금은 필멸의 강령술사인 암흑스승 간들링이 교장을 맡고 있다. 그는 켈투자드의 뒤를 이었던 소환사 아라즈의 후임이다.",
	["s:1422:sorrow hill"] = "슬픔의 언덕은 평온하던 시절 안돌할을 위한 곳이었다. 부자든 가난한 이든 마을의 망자들이 납골당과 소박한 비석 아래 잠든 곳이었다. 그 평화는 죽음의 역병이 오면서 끝났다. 스컬지가 안돌할에 거듭 몸을 던지자 언덕은 감당할 수 있는 것보다 빠르게 채워졌다. 수비대가 쓰러진 곳에는 서둘러 판 표식 없는 무덤들이 지금도 땅에 상처로 남아 있다. 결국 살아남은 이들은 역병이 사랑하는 이들을 되살려 자신들에게 겨눌까 두려워 망자를 묻는 일을 아예 그만두었고, 대신 시신을 태우기 위해 묘지 남쪽에 거대한 구덩이를 팠다.\n\n마을의 마지막 행동은 가장 슬픈 것이었다. 아서스가 우서 경을 쓰러뜨리자, 안돌할에 남은 사람들은 언덕 꼭대기에 거대한 무덤을 세우고 성기사의 망가진 시신을 그 안에 안치한 뒤 고향을 영영 버리고 떠났다. 어떤 이들은 언덕의 이름이 오직 그 무덤에서 왔다고 말한다.\n\n근처의 역병 가마솥은 언덕의 망자들조차 가만두지 않았다. 병사들과 마을 사람들이 무덤에서 일어나, 한때 자신들이 채웠던 무덤을 지키고 서 있다.",
	["s:1422:thondroril river"] = "톤드로릴 강은 서부 역병지대와 동부 역병지대를 가른다. 강은 저 북쪽 공포의 거미굴 근처에서 발원해 남쪽으로 흘러 다로미어 호수로 흘러들고, 그 너머로는 다로미어 강이 되어 이어진다.\n\n강기슭은 역병의 차지이다. 구더기와 흡혈박쥐가 축축한 땅에 들끓고, 역병곰과 거미가 얕은 물을 누비며, 물살이 느려지는 곳에는 치악거북이 도사리고 있다.",
	["s:1422:uthers tomb"] = "우서 경의 무덤은 슬픔의 언덕에 서 있으며, 서부 역병지대에서 빛이 아직 땅의 죽음에 맞서 버티고 있는 유일한 곳이다.\n\n빛의 인도자 우서는 한때 현자 트루스베어러, 빛나는 발라도르와 나란히 서서 백은의 손 기사단을 등 뒤에 두고 스컬지로부터 안돌할을 지켰다. 그 저항을 끝낸 이는 아서스 메네실이었다. 그는 언데드 군대를 이끌고 도시로 쳐들어와 트루스베어러와 발라도르, 그리고 우서 자신을 베어 쓰러뜨렸다.\n\n아서스가 남긴 것을 우서의 병사들이 거두었다. 그들은 그의 시신을 안돌할 폐허 남쪽으로 옮겨 그 위에 무덤을 세웠다. 그의 묘석은 살아생전 모습 그대로, 한 손에는 빛의 경전을, 다른 손에는 전투망치를 들고 있으며, 그 앞의 표석에는 공용어로 글귀가 새겨져 있다.\n\n대사제 텔다니스가 지금도 무덤을 돌보는 관리인이자 수호자이다. 이 무덤은 빛을 따르는 이들에게 성스러운 곳이며, 역병지대에서 그러한 신앙이 아직 무언가를 의미하는 몇 안 되는 곳 가운데 하나이다.",
	["s:1422:weeping cave"] = "진흙탕 동굴은 톤드로릴 강 서쪽에 있으며, 그 굴마다 역병에 물든 땅에서 태어난 늪괴물과 수액괴물이 우글거린다. 썩어 가는 거수와 부패한 공포들이 어둠 속을 비틀거리며 돌아다닌다. 더 깊은 곳에는 껍데기라 불리는 정령이 드물게 모습을 드러낸다고 하는데, 목격하기에는 기이하고 불안한 존재이다.",
	["s:1422:writhing haunt"] = "고통의 흉가는 한때 산 자들의 양식을 위해 가꾸던 농지였다. 그 쓰임새는 사라졌다. 스컬지는 들판을 차지하고 그 한가운데에 거대한 가마솥을 두었으며, 가마솥은 그 뒤로 한 번도 일을 멈추지 않았다. 질병으로 가득한 증기가 끊임없이 뿜어져 나와 한때 곡식이 자라던 밭고랑 위로 굴러간다.\n\n가마솥은 무방비로 남겨져 있지 않다. 가마솥 군주 라자르크가 그것을 지키고, 썩어 가는 구울과 얼어붙은 구울, 악취 나는 좀비들이 그 주위를 맴돌며 이곳의 수호자로 묶여 있다.",
	["s:1423:blackwood lake"] = "검은나무 호수의 물은 더럽게 썩어 있으며, 타락한 물의 정령들이 탁한 물속을 휘감으며 들끓는다. 다로우샤이어의 옛 연대기에 따르면 호수 바닥 그 어둠 속 어딘가에 약탈자 호르거스의 머리가 가라앉아 있다고 한다.\n\n역병이 오기 전, 이곳에는 대원수 오스마르 가리토스의 고향인 검은나무라는 마을이 있었다. 이제 그 이름을 지닌 호수 말고는 아무것도 남아 있지 않다.",
	["s:1423:browman mill"] = "스티븐 브라우만은 한때 희망의 빛 예배당 북쪽의 제재소에서 목재를 베었다. 스컬지는 역병이 닿은 다른 모든 이처럼 그를 죽였고, 자신들을 섬기는 구울로 되살렸다. 그는 결코 떠나지 않았다. 이제 그는 한때 자신이 소유했던 벽 안에서 보초를 서고 있다.\n\n제재소에는 해골과 밴시, 누더기골렘이 들끓어 폐허라기보다 주둔지에 가까우며, 누구도 머물고 싶게 만드는 구석이 하나도 없다.",
	["s:1423:corins crossing"] = "코린 삼거리는 안돌할, 다로우샤이어, 스트라솔름, 티르의 손 수도원으로 가는 길들이 오염의 흉터와 메렐다르 호수 사이에서 만나는 곳에 있다. 한때는 평범한 교차로 마을로, 시청과 대장간이 있었다.\n\n이제 스컬지가 거리를 완전히 메우고 있으며, 망자들 사이로는 전혀 보이지 않는 것들이 움직인다. 은신을 아무것도 아닌 듯 꿰뚫어 보는 보이지 않는 하인들이다. 코린 삼거리를 조용히 지나갈 길은 없다.",
	["s:1423:crown guard tower"] = "산마루 경비탑은 동부 역병지대의 정찰탑 가운데 하나로 이 땅을 굽어보고 있다. 스컬지의 로데론 침공이 이 지역을 휩쓸었고, 탑은 지금도 그 상처를 안은 채 죽은 땅의 말 없는 표지로 서 있다.",
	["s:1423:darrowshire"] = "다로우샤이어는 한때 어엿한 마을이었다. 3차 대전쟁이 스컬지를 그 문 앞까지 데려오기 전까지는. 약탈자 호르거스라는 구울 군주가 죽음의 기사 마르두크 블랙풀과 함께 공격을 이끌었다. 마을의 수비대는 처음에는 어느 정도 성공적으로 맞서 싸웠지만, 전세가 뒤집혔고 결국 한 사람도 남김없이 학살당했다.\n\n죽음도 그들을 끝내지 못했다. 쓰러진 이들은 구울로 다시 일어나 자신들을 죽인 바로 그 스컬지를 섬기도록 묶였고, 그들의 영혼은 한때 자신의 것이었던 썩어 가는 살 안에 갇혔다.\n\n다로우샤이어는 이제 유령과 기억 말고는 텅 빈 채, 부서진 모습으로 침묵하고 있다.",
	["s:1423:eastwall gate"] = "동부방벽 관문은 스트라솔름으로 들어가는 옆문으로, 아우리우스가 머무는 알론서스 예배당 근처의 장로의 광장으로 곧장 이어진다.",
	["s:1423:eastwall tower"] = "동부방벽 경비탑은 동부 역병지대에 서 있으며, 한때 로데론을 위해 이 땅을 지켜보던 정찰탑이다. 스컬지가 왕국을 휩쓸었고, 탑은 지금도 그 상처를 안은 채 죽은 땅을 지켜보고 있다.",
	["s:1423:fungal vale"] = "마리스 농장과 산마루 경비탑 북쪽에는 곰팡이 계곡이 있으며, 탁한 안개 아래 땅은 짙은 보랏빛으로 변해 있다. 이곳은 죽음의 역병이 가장 깊이 뿌리내린 곳으로, 스컬지와 저주받은 교단이 타락 속을 자유로이 오가며 이 분지를 완전히 자기들 것으로 삼고 있다.",
	["s:1423:infectis scar"] = "코린 삼거리 근처에서 죽음의 기사 마르두크 블랙풀의 룬검이 한 드워프 대장의 방패에 부딪혀 산산조각 났다. 그는 자루만 챙기고 망가진 칼날은 쓸모없다며 내던졌다. 그러나 칼날은 땅속으로 가라앉았고, 그 아래 땅이 갈라지며 검은 물로 채워졌다.\n\n남은 것은 처음부터 끝까지 부자연스럽다. 한낱 자연의 협곡일 뿐인 근처 전염의 흉터와는 다르다.",
	["s:1423:lake mereldar"] = "메렐다르 호수의 물은 코린 삼거리 남쪽에서 역병으로 짙게 물들어 있으며, 타락한 물의 정령들이 수면 아래를 누빈다. 호숫가에는 오래된 집의 폐허와 함께, 지금은 버려진 농장에 딸려 있던 오두막과 나룻배가 남아 있다.",
	["s:1423:lights hope chapel"] = "역병지대 동쪽의 산 아래에는 주변의 폐허보다 훨씬 오래된 예배당이 서 있다. 성스러운 빛의 교회가 세운 성지 가운데 가장 오래되고 가장 존경받는 곳 가운데 하나이다.\n\n붉은십자군이 걸어가는 길을 따르지 않으려던 성기사들은 대신 동부 역병지대로 물러나 이 예배당을 본거지로 삼고 스스로를 은빛 여명회라 불렀다. 처음에는 레이몬드 조지 경이 그들을 이끌었고, 그가 죽자 맥스웰 티로서스 경이 그 자리를 이었다. 붉은십자군과 달리 그들은 종족을 이유로 누구도 내치지 않았다.\n\n은빛 여명회는 붉은십자군과 따로 서 있지만, 예배당은 여전히 두 세력이 만나 이야기를 나누는 중립 지대로 남아 있다.",
	["s:1423:marris stead"] = "마리스 농장은 이 지역의 큰길 위 낮은 마루에 자리한 농장으로, 한때 나사노스 마리스의 것이었다. 그의 사촌 스테폰이 한동안 이곳에 살았고, 실바나스 윈드러너가 이 지붕 아래로 나사노스를 찾아오곤 했다고 알려져 있다.\n\n밴시 여왕이 언더시티에서 포세이큰을 일으킨 뒤 그녀에게서 자유를 얻은 나사노스는, 그녀의 명에 따라 잃어버렸던 집으로 돌아와 다시 자기 것으로 삼았다. 그는 이곳에서 호드 병사들을 불러 모아 여전히 역병지대에 들끓는 스컬지와 붉은십자군에 맞서 싸우게 했고, 다로우샤이어 전투의 유물들을 모아 아무에게도 밝히지 않은 이유로 농장 안에 보관했다.",
	["s:1423:mazraalor"] = "줄마샤르의 심장부에는 마즈라알로가 솟아 있다. 돌을 쌓아 올린 지구라트로, 주변의 폐허가 된 땅 위에 우뚝 서 있다. 이끼가죽 부족이 여전히 이곳을 지키며, 그들의 암흑사냥꾼들은 그 꼭대기에서 아래의 트롤 거주지를 감시한다.",
	["s:1423:northdale"] = "노스데일은 희망의 빛 예배당 북쪽, 쿠엘탈라스의 경계에 자리한 폐허가 된 마을이다. 탈란 폴드링이 백은의 손 기사단을 버리고 붉은십자군을 택한 곳이 바로 이곳이다.\n\n이제 잔해 사이에는 밴시와 보이지 않는 감시자들이 출몰한다. 근처 호수에는 타락한 물의 정령들이 있다. 살아 있는 것은 아무것도 남아 있지 않다.",
	["s:1423:northpass tower"] = "북부관문 경비탑은 동부 역병지대의 감시탑 가운데 가장 북쪽에 서 있으며, 쿠엘탈라스의 유령의 땅으로 향하는 길을 표시한다. 스컬지가 로데론을 휩쓸었고, 탑은 지금도 그 상처를 안고 있다.",
	["s:1423:noxious glade"] = "맹독의 숲은 희망의 빛 예배당 북쪽의 언덕 위에 자리하며, 주변의 역병지대보다도 더 심하게 역병에 물들어 있다. 공기는 짙고 병든 초록빛으로 드리워 있고, 땅은 짙은 보랏빛으로 물들어 푸른 것은 아무것도 자랄 수 없다.\n\n스컬지는 이 숲을 자기 것으로 삼았다. 독에 물든 땅 위에 역병 가마솥과 도살장, 지구라트 몇 개가 서 있고, 스컬지 생물들이 무리 지어 그 사이를 오간다.",
	["s:1423:pestilent scar"] = "전염의 흉터는 역병에 물든 동부 역병지대의 깊은 협곡으로, 아마도 죽음의 역병이 닥쳤을 때 말라 버린 호수였을 것이다. 이제는 거의 말라 대지의 상처로 남아 있으며, 그 깊은 곳에는 오래된 타락에서 태어난 수액괴물들이 산다.",
	["s:1423:plaguewood"] = "스트라솔름 남쪽의 나무들은 한때 푸르고 평온하게 서 있었다. 엘윈 숲과 다르지 않은 숲이었고, 그 가장자리의 돌 아치 근처에는 작은 마을이 포근히 자리하고 있었다. 켈투자드가 일을 시작했을 때, 그 마을에서 태어난 로데론 병사 모리건 하사가 안돌할에서 온 오염된 곡물이 이 땅에 불길한 짓을 하고 있음을 처음 알아챈 곳이 바로 이곳이었다. 그의 경고는 왕국을 구하기에는 너무 늦었고, 그가 지키던 바로 그 길을 훗날 아서스 왕자가 스트라솔름으로 향하며 달려 내려갔다.\n\n그 뒤에 남은 것은 더 이상 숲이 아니었다. 흙 자체가 발밑에서 스펀지처럼 푹신해졌고, 버섯과 독버섯이 나무만큼 부풀어 올라 옛 숲의 잔해 위로 우뚝 솟았다. 그것들은 스컬지의 역병 가마솥에서 피어오르는 연기와 다르지 않은 짙은 갈색 가스를 내뿜는데, 버섯이 그저 독에 물든 땅에서 자라는 것인지, 아니면 스컬지가 병을 더 퍼뜨리려고 그것을 기르는 것인지는 누구도 확실히 말할 수 없다. 이 숲이 새 이름을 얻은 것은 바로 이 변화 때문이었다.",
	["s:1423:quellithien lodge"] = "쿠엘리시엔 오두막은 쿠엘탈라스 근처의 순찰자 야영지로, 따뜻함과 환대가 있는 곳이었다. 로르테마 테론은 직접 이곳을 찾았을 때 이곳을 고향이라 부르던 동료들에게 따뜻한 환영을 받았던 모습으로 이곳을 기억했다. 오두막에는 한때 여러 엘프 문서가 보관되어 있었는데, 그중 일부는 왕가와 실버문의 순찰대 사령관에 관한 것이었다. 2차 대전쟁 무렵에는 렌타르 호크스피어가 그곳의 사냥꾼들을 이끌었다.",
	["s:1423:scarlet base camp"] = "티르의 손 수도원이라는 신앙의 보루에서 멀지 않은 메렐다르 호수 동쪽 기슭에, 붉은십자군 주둔지가 방책 뒤에 서 있으며 무엇이 오든 대비해 방어를 강화해 두었다.",
	["s:1423:scarlet basilica"] = "붉은십자군 대성당은 티르의 손 수도원 안에 서 있는 붉은십자군 신앙의 최고 본산으로, 근처의 수도원, 그리고 멀리 티리스팔 숲의 붉은십자군 수도원과 이어져 있다. 십자군 군주 발델마가 이곳을 지키며, 십자군의 대의에 대한 그의 헌신은 절대적이다.",
	["s:1423:stratholme"] = "스트라솔름의 몰락은 곡물에서 시작되었다. 저주받은 교단이 몰래 감염시킨 안돌할의 곡물은 빵으로 구워졌고, 자신이 죽어 가는 줄도 모르는 주민들이 그것을 먹었다. 아서스 메네실 왕자가 빛의 인도자 우서, 제이나 프라우드무어와 함께 도착했을 때 역병은 이미 뿌리를 내리고 있었다. 걸어 다니는 망자로 서서히 변해 가느니 깨끗한 죽음만이 남은 유일한 자비라고 믿은 아서스는 도시를 불태우라고 명령했다. 우서와 제이나는 거부하고 병사들을 물렸다. 아서스는 물러서지 않았다. 불길이 거리를 휩쓸었고 스트라솔름의 거의 모든 이가 죽었다. 아서스가 죽이러 왔던 공포의 군주 말가니스는 웃으며 빠져나갔고, 왕자에게는 남은 것을 불태우는 일만 남았다.\n\n그것으로는 충분하지 않았다. 망자들은 결국 되살아났고, 도시는 로데론에서 스컬지의 수도가 되어 처음에는 리치 켈투자드가, 나중에는 죽음의 기사 리븐데어 남작이 다스렸다.\n\n스트라솔름은 지금도 불타고 있다.",
	["s:1423:terrordale"] = "테러데일은 역병의 숲 가장자리에 자리하며, 거리는 텅 빈 채 스컬지와 역병 걸린 짐승들에게 넘어갔다. 폐허 사이에는 오직 상인 정신나간 아우구스투스와 유령 사냥꾼 이건만이 남아 있다.\n\n마을에는 유령이 출몰한다. 영혼들이 골목을 거닐고, 어떤 곳에서는 테러데일 자체가 흔들리는 듯하다. 마치 땅이 떨쳐 버리지 못하는 오래된 고통을 기억하기라도 하듯, 물질 세계가 그 너머 세계의 무게에 휘어진다.\n\n그레이슨 섀도브레이커 경을 이곳으로 이끈 것은 바로 이 불안이었다. 그는 이 영혼들이 심판과 희생에 걸맞은 자격을 증명하려는 성기사들에게 적합한 시련이자, 진정 자격 있는 이들에게만 허락되는 군마를 얻기 위한 한 걸음이 되리라 보았다. 영혼들이 살아생전 무엇이었는지는 기록되지 않았다. 다만 그들의 고통이 주변 마을을 뒤틀 만큼 실재했다는 것만 전해질 뿐이다.",
	["s:1423:terrorweb tunnel"] = "이 굴은 테러데일 북서쪽의 산을 관통해 남쪽으로 톤드로릴 강과 만나는 곳까지 이어진다. 네루비안 지하마귀들이 통로를 가득 메우고 있으며, 그 사이로 더 끔찍한 것이 도사린다. 동족보다 훨씬 치명적인 네루비안 감독관이다.\n\n강가의 굴 입구에서는 티리온 폴드링이 바깥의 빛 속에서 통로의 어둠을 마주하며 감시를 서고 있다.",
	["s:1423:thondroril river"] = "톤드로릴 강은 서부 역병지대와 동부 역병지대를 가른다. 강은 저 북쪽 공포의 거미굴 근처에서 발원해 남쪽으로 흘러 다로미어 호수로 흘러들고, 그 너머로는 다로미어 강이 되어 이어진다.\n\n강기슭은 역병의 차지이다. 구더기와 흡혈박쥐가 축축한 땅에 들끓고, 역병곰과 거미가 얕은 물을 누비며, 물살이 느려지는 곳에는 치악거북이 도사리고 있다.",
	["s:1423:tyrs hand"] = "티르의 손 수도원은 요새화된 인간의 도시로, 이 지역에서 스컬지에 맞서 버티는 산 자들의 마지막 거점 가운데 하나이다. 그 주변은 역병지대의 다른 곳보다 훨씬 나은 상태이지만, 나무와 풀은 여전히 썩어 가고 있다.\n\n이 도시는 빛의 교회의 성지 가운데 가장 오래되고 가장 존경받는 곳 가운데 하나로, 거의 전부가 교회로 이루어져 있으며 붉은십자군 대성당과 요새화된 수도원이 그 정점에 서 있다.\n\n스컬지가 들이닥쳐 동쪽 숲이 역병지대로 변했을 때에도 티르의 손 수도원은 무너지지 않았다. 발델마 경 아래에서 이 도시는 날마다 이어지는 공격을 견뎌 냈다. 처음에는 백은의 손 기사단이, 나중에는 붉은십자군이 이곳을 지켰고, 도시는 다른 붉은십자군 거점으로 보급품과 증원군을 보냈으며, 역병이 짙은 길을 뚫고 싸우며 오가는 전령들이 날마다 스트라솔름의 보고를 가져왔다.",
	["s:1423:undercroft"] = "지하 납골당은 동부 역병지대 남서부의 지하 묘지로, 되살아난 흉포한 트롤인 추방자 자엘다르가 이끄는 언데드 트롤들의 보금자리이다. 그는 이곳에서 희망의 빛 예배당에 있는 은빛 여명회의 매장 구덩이를 습격해 자신을 위한 시신을 훔쳐 간다.",
	["s:1423:zulmashar"] = "줄마샤르는 한때 동부 역병지대 북동쪽의 숲 트롤인 이끼가죽 부족의 수도였다. 로데론 인간들과의 오랜 전쟁으로 부족의 땅은 혼란에 빠졌고, 뒤이은 죽음의 역병은 더 깊은 파멸을 불러왔다. 한때 이곳을 다스리던 도시는 이제 옛 영광의 그림자로 서 있다.\n\n도시의 지구라트 마즈라알로는 여전히 도시의 심장부에 서 있으며, 지금은 전쟁군주 스레쉬진과 줄브린 워프브랜치가 지키고 있다. 그러나 이끼가죽 부족민들은 은밀히 역병에 의해 변해 가고 있으며, 줄마샤르는 언데드의 보루로 전락할 위기에 놓여 있다.",
	["s:1424:alterac mountains"] = "이 봉우리들에는 비가 좀처럼 그치지 않고, 그 위의 하늘은 언제나 잿빛이다. 한때 이 산맥은 북부 대부분을 다스리던 도시국가 알터랙의 왕관이었고, 달라란도 품고 있었다. 이제 둘 다 사라졌으며, 남은 것을 보면 왜 이곳을 오르려는 이가 그토록 적은지 알 수 있다.\n\n2차 대전쟁이 끝났을 때, 로데론 연합은 알터랙의 영주들이 호드와 몰래 내통했다는 사실을 알고 배신자들을 그들의 본거지에서 치기 위해 이 산맥으로 군대를 보냈다. 도시는 함락되었고 백성은 흩어지거나 투옥되었으며, 그 혈통은 끝내 왕좌를 되찾지 못했다. 몰락한 가문의 후대 왕자인 알리덴 페레놀드는 도적 두목으로 일어나 추방자와 복수심에 불타는 자들을 비밀결사로 불러 모았다. 이 무법자 집단은 지금도 스트란브래드를 장악하고 이 비탈 곳곳을 누비며 그의 가문이 잃은 것을 되찾으려 한다.\n\n오늘날 알터랙 성의 폐허는 산사태 오우거의 차지가 되었고, 오우거가 차지하지 못한 곳의 대부분은 비밀결사가 쥐고 있다.",
	["s:1424:azurelode mine"] = "청금석 광산은 힐스브래드 구릉지 남서쪽 끝에 있으며, 그 언덕은 그레이메인 성벽이 세워져 왕국이 세상과 단절되기 전까지 길니아스의 일부로 여겨졌다.\n\n광산은 얼라이언스의 것으로, 경비병들의 감시 아래 광부들이 일하며, 이곳에서 나오는 철은 얼라이언스의 무기고를 채운다.",
	["s:1424:chillwind point"] = "서리바람 거점이라는 이름은 서부 역병지대에서 쏟아져 내려와 아래 협곡으로 몰아치는 차가운 바람에서 왔다. 언덕 꼭대기에는 고대 트롤 유적이 얹혀 있는데, 그것을 세운 이들이 남긴 전부이다. 이 고갯길은 한때 로데론 왕국의 것이었다. 지금은 정글 트롤 바람지기 바스라가 유적에 머물고 있다.",
	["s:1424:corrahns dagger"] = "코란의 비수는 힐스브래드의 네 손가락 가운데 두 번째 언덕이다. 비밀결사가 이 언덕을 차지하고 있다.",
	["s:1424:crushridge hold"] = "산사태 오우거 소굴은 알터랙 폐허 근처에 솟아 있으며, 흙더미 언덕 속을 파낸 동굴이다. 그 주변에는 산사태 오우거들이 야영지를 세웠는데, 수가 많고 성질이 난폭하며 아래 폐허가 된 도시 위의 비탈을 지키고 있다.",
	["s:1424:dandreds fold"] = "고원의 서쪽 끝, 땅이 물안개 호숫가와 만나고 항구가 로다미어 호수로 열린 곳에 작은 농장과 저택이 서 있다.\n\n이곳에는 알리덴이 살았고, 그의 정부 엘리사도 함께 살았다. 그녀는 한때 타레사 폭스턴의 것이었던 목걸이를 걸고 있었다. 알리덴이 죽자, 엘리사는 목걸이를 간직했다가 해를 입을까 두려워 곧바로 그것을 내놓았다.",
	["s:1424:darrow hill"] = "다로우 언덕은 힐스브래드 구릉지 북부, 마루터기 아래에 있다. 퓨마와 수사슴이 탁 트인 들판을 누비고, 구릉지 동굴 안에는 바위 속을 지나는 알터랙 화강암 광맥 사이에 설인들이 굴을 틀었다.",
	["s:1424:dun garok"] = "던 가록은 힐스브래드 구릉지의 언덕에 서 있는 드워프 요새로, 부대장 아이언힐이 지휘한다. 그의 수비대는 힐스브래드의 인간들을 지키고 청금석 광산을 감시하는데, 포세이큰은 그 존재를 견디지 못해 요새에 숨어들어 그곳 드워프들을 칼로 베어 줄 자에게는 누구에게든 금을 내걸었다.",
	["s:1424:durnholde keep"] = "던홀드 요새는 타렌 밀농장 동쪽에 부서진 채 서 있다. 병영과 마법사의 탑은 안으로 무너져 내렸고, 투기장은 고요하다. 한때 이곳은 2차 대전쟁 이후 세워진 오크 수용소 체계의 본거지였으며, 수용소를 자신의 출세에 이용한 자기도취적인 술꾼, 중장 아에델라스 블랙무어가 다스렸다.\n\n살해당한 부모의 시신 사이에서 오크 아기를 발견해 요새로 데려와 스랄이라 이름 지은 이가 바로 블랙무어였다. 소년은 그곳에서 자라며 교육을 받았고, 한 인간 여인이 그에게 젖을 먹였는데 그 여인의 딸 타레사 폭스턴은 그와 가까워졌다. 블랙무어는 여러 해 동안 소년을 때리고 투기장에서 싸우게 했으며, 그의 힘을 팔아 지위를 높였다. 타레사는 몰래 그에게 편지를 썼고 그도 답장을 보냈는데, 마침내 그는 탈출하겠다고 그녀에게 알렸다. 그녀는 그가 빠져나갈 수 있도록 소란을 일으켰고, 성벽 너머에서 그를 만나 떠나기 전에 식량을 건넸다.\n\n몇 해 뒤, 그는 자신이 모은 자유로운 오크들을 이끌고 돌아왔다. 스랄은 던홀드를 포위하고 일대일 결투로 블랙무어를 죽였으며, 대지의 정령을 불러 요새를 완전히 무너뜨렸다. 남은 폐허에는 그 뒤로 비밀결사가 들어와 자기들 것이라 주장하고 있다.",
	["s:1424:eastern strand"] = "동부 해안은 힐스브래드 구릉지의 남동쪽 해안을 따라 이어지며, 같은 해안의 더 서쪽에 짝을 이루는 해안이 있다. 이 모래사장은 비수지느러미 나가의 차지로, 그들은 해변과 그 너머의 얕은 물을 지키고 있다.",
	["s:1424:gallows corner"] = "알터랙의 폐허가 된 전당 근처, 알터랙 산맥에서 길들이 만나는 갤로우 삼거리에는 정찰탑 하나가 부서진 채 텅 비어 서 있다. 이제는 산사태 오우거들이 교차로를 차지하고 탑의 잔해 주변 바위를 어슬렁거리며, 그 밖에는 아무것도 움직이지 않는다.",
	["s:1424:gavins naze"] = "가빈 절벽은 힐스브래드의 네 언덕 가운데 마지막이자 가장 삼엄하게 지켜지는 언덕이다.\n\n이 언덕에는 퓨마들이 누비는데, 그중에는 흔치 않은 털빛으로 눈에 띄는 아라가도 있다.",
	["s:1424:growless cave"] = "알터랙 산맥의 한 동굴에는 산악 설인들이 살며, 그 입구 바로 바깥에서는 흔히 스카울을 볼 수 있다. 깊은 곳에는 우젤의 불꽃이 서 있다. 인간 헬큘러가 리치가 되기 위한 의식을 위해 세운 화장단이다. 그 위에서 고기를 태우면 거대한 설인 서리아귀가 입구로 이끌려 온다.",
	["s:1424:headland"] = "마루터기는 힐스브래드 너머로 뻗어 나간 손가락 모양의 땅 가운데 하나이다.\n\n이곳 절벽에서는 아라가가 새끼들 사이에서 쉬고 있다.",
	["s:1424:hillsbrad fields"] = "힐스브래드 농장은 힐스브래드 구릉지 서부에 비옥하게 일구어진 들판으로, 사우스쇼어와 힐스브래드 마을까지 먹여 살린다. 사과 과수원과 호박밭, 풀을 뜯는 소 떼가 땅을 덮고 있으며, 청금석 광산에서는 아직도 마을 사람들이 일한다.\n\n2차 대전쟁 초기, 둠해머는 군대를 힐스브래드로 돌려 인간 왕국들에게 경고하려는 끔찍한 본보기로 마을을 파괴했다. 전쟁 후 마을은 재건되었고 지금도 사람들이 살고 있다. 옛 로데론 땅 가운데 폐허로 남지도 붉은십자군에 삼켜지지도 않은 몇 안 되는 곳이다. 경비병들은 아직 자기 왕국의 휘장을 두르고 있고, 행정관 번사이드가 힐스브래드 의회와 서기 호레이스 화이트스티드를 곁에 두고 시청에서 다스린다.\n\n이제 들판은 다시 위협을 받고 있다. 타렌 밀농장에 있는 대집행관 다살리아의 병력 때문이다. 농민과 농부들은 습격을 견디고 있지만, 많은 이가 대장장이 베링턴과 그의 도제들이 만든 무기를 들고 매복으로 언데드에게 반격한다.",
	["s:1424:lordamere lake"] = "로다미어 호수는 한때 그 기슭을 고향으로 삼았던 왕국들의 그림자 아래 펼쳐져 있다. 로데론이 호수 북쪽 끝에 세워졌으며, 호수의 이름은 옛 로데인의 이름을 딴 그 위대한 도시에서 왔을 가능성이 크다. 로데론 연합이 인간 왕국들을 하나로 묶던 시절에는 달라란과 알터랙 또한 이 물가에서 번영을 누렸다.\n\n그 시대는 지나갔고, 남은 것은 경계선이다. 이제 호수는 티리스팔 숲과 은빛소나무 숲의 포세이큰 영토와 분쟁 중인 알터랙 산맥 사이에 놓여, 죽은 자와 산 자를 갈라놓는다.\n\n그 한가운데에는 펜리스 섬이 있으며, 그 요새는 스컬지의 하수인들이 차지한 채 포세이큰에게 시달리고 있다. 그 동쪽의 여명의 섬은 썩은지느러미 멀록에게 점령당해 그들의 것이 되었다.\n\n3차 대전쟁 이후 얼마 뒤, 여군주 바쉬와 그녀의 나가들은 달라란의 폐허를 피해 이 물로 물러났다.",
	["s:1424:misty shore"] = "물안개 호숫가는 단드레드 장원과 달라란 사이로 로다미어 호수를 따라 이어진다. 거북들이 얕은 물속을 느릿느릿 움직인다.\n\n붉은십자군 두 명이 이 호숫가를 지키며, 마치 땅 자체를 지켜야 한다는 듯 너무 가까이 다가오는 자는 누구든 덮친다.\n\n물 건너로는 여명의 섬이 보이고, 펜리스 요새가 안개 너머로 희미하게 음울한 모습을 드러낸다.",
	["s:1424:nethander stead"] = "네산더 농장은 사우스쇼어 바로 동쪽에 있으며, 들판은 오래전에 버려져 진흙주둥이 놀이 점령했다. 그들 부족을 볼 수 있는 유일한 곳이다. 그곳에는 진흙주둥이 꽃이라 불리는 거대한 흰 버섯이 제멋대로 자라는데, 한때 약제사 라이돈이 치명적인 고통의 비약을 만들기 위해 찾던 것이다.",
	["s:1424:purgation isle"] = "힐스브래드 해안 남쪽에 나선형의 바위가 솟아 있고, 그 꼭대기에는 묘지와 부서진 정찰탑의 잔해가 얹혀 있다. 1차 대전쟁 전, 속죄의 섬은 쿨 티라스의 것이었다.\n\n그 뒤에 무슨 일이 있었는지는 분명하지 않지만, 망자들은 안식하지 못한다. 수십 명의 영혼이 섬을 걷는다. 인간과 드워프, 성기사와 사제, 수도사와 마법사까지, 그 돌에 묶인 저주받은 영혼들이다.",
	["s:1424:ravenholdt manor"] = "라벤홀트 장원은 일부러 세상과 떨어져 자리 잡고 있다. 던홀드 요새 북서쪽의 고원에서 올라가는 좁고 구불구불한 길을 따라 산과 작은 동굴을 지나야만 영지에 닿을 수 있으니, 우연히 발견할 수 있는 곳이 아니다. 이방인은 이곳에서 환영받지 못하며, 조라크 라벤홀트 경을 섬기는 이들은 그 원칙을 지킨다.\n\n장원은 그의 소유로, 1차 대전쟁 전 이 땅을 다스리던 알터랙 왕국의 옛 양식대로 주황색 지붕을 얹고 있다.\n\n그 뒤로 비밀결사가 고원의 이 지역을 떠돌았고, 라벤홀트는 숨겨진 길과 지켜지는 문 뒤에서 그 골칫거리에 맞서 왔다.",
	["s:1424:ruins of alterac"] = "한때 도시가 서 있던 알터랙 산맥의 비탈에는 부서진 성벽이 올라가 있다. 궁전은 반쯤 서 있고, 교회와 시청은 안으로 무너져 내렸으며, 성문은 스톰윈드의 것을 본떠 지어졌다.\n\n도시의 몰락은 자기 왕에게서 비롯되었다. 2차 대전쟁 때 에이든 페레놀드 왕은 반역자가 되어 오크 호드와 손잡고 동족인 인간들에게 등을 돌렸다. 알터랙 병사들이 오크와 함께 싸우는 것이 발견되었고, 도시 근처의 포로수용소에는 달라란 시민들이 갇혀 있었다. 진실이 드러나자 다른 인간 왕국들은 보복을 위해 알터랙으로 진군했다. 백성들은 달아나거나 집에서 쫓겨났고, 로데론의 테레나스 메네실 2세 왕은 도시에 계엄령을 선포하고 페레놀드를 끌어내려 사슬로 묶었다.\n\n도시는 다시 일어서지 못했다. 무그톨이 이끄는 산사태 오우거가 텅 빈 거리와 궁전에 자리를 잡았고, 옛 알터랙 백성의 흩어진 잔존자들은 그 너머 외곽 마을들을 지켰다. 부서진 고기 수레가 지금도 북쪽 성벽과 성문 근처에 놓여 있고, 성벽 안팎의 묘지들과 눈에 파묻힌 농장, 잔해 사이의 부서진 대형 쇠뇌는 버려진 그대로 남아 있다.",
	["s:1424:slaughter hollow"] = "알터랙 산맥 깊숙한 곳, 산사태 오우거는 언덕 속에 파묻힌 흙더미인 살육의 동굴에 보금자리를 틀었다. 이곳에 대해 알려진 것은 그곳을 차지한 오우거들뿐이지만, 이름만으로도 너무 가까이 다가가는 자에게 무엇이 기다리는지 알 수 있다.",
	["s:1424:soferas naze"] = "소페라 절벽은 힐스브래드의 네 손가락 가운데 하나로 솟아 있다. 비밀결사가 이 언덕을 차지하고 아래 땅을 감시하고 있다.",
	["s:1424:southpoint tower"] = "남부 경비탑은 힐스브래드 구릉지의 서쪽 끝, 은빛소나무 숲으로 이어지는 길의 바로 남쪽에 서 있다. 석조물은 낡고 금이 갔으며 버려진 정찰 초소이지만, 탑 자체는 이곳을 휩쓸고 지나간 싸움 속에서도 무너지지 않았다. 근처에는 이름 없는 탑이 하나 더 타렌 밀농장과 사우스쇼어 사이에 서 있는데, 그것 역시 구릉지의 나머지를 휩쓴 파괴를 피했다.",
	["s:1424:strahnbrad"] = "스트란브래드는 알터랙 산맥 북동쪽 구릉지에 자리하며, 시청과 대장간은 이제 텅 비어 있다. 한때 이곳은 알터랙 왕국의 것이었고, 2차 대전쟁 이후 로데론의 손에 넘어갔다.\n\n마을의 몰락은 3차 대전쟁 직전, 검은바위 오크들이 불타는 군단에 제물로 바칠 노예를 잡으러 들이닥치면서 시작되었다. 스트란브래드에는 마을을 지킬 보병이 몇 명뿐이었지만, 소식은 제때 백은의 손 기사단에 전해졌다. 빛의 인도자 우서는 공격을 막으려고 앞서 달려갔고, 아서스 메네실 왕자는 마을을 지키도록 파견되었다. 아서스는 제때 도착하지 못했다. 그가 스트란브래드에 닿기 전에 딘, 조, 마이크, 스콧을 비롯한 많은 이가 죽었고, 남은 수비병들은 그와 함께 오크를 격퇴하고 습격을 이끈 노예 감독관을 죽였다. 얼라이언스는 싸움에서 이겼지만, 스트란브래드의 주민들은 이미 사라진 뒤였다.\n\n훗날 비밀결사가 폐허가 된 마을을 차지해 알터랙 산맥을 손에 넣기 위한 거점으로 삼았고, 오크 골디르를 감방 하나에 가두어 짐을 나르고 땅을 파는 노예로 부렸다.",
	["s:1424:tarren mill"] = "타렌 밀농장은 한때 알터랙 산맥 아래 초원에 자리한 소박한 로데론의 마을이었다. 2차 대전쟁 초기, 오크의 위협을 직접 확인하러 남쪽으로 파견된 실버문의 하이 엘프 궁수들이 마을 근처에서 매복을 당해 근처 포로수용소로 끌려갔다. 테레나스 왕은 그들을 구하러 얼라이언스 병사들을 보냈고, 구출은 성공했다. 그 성공으로 실버문 의회는 쿠엘탈라스의 군대를 로데론 연합에 합류시켰다.\n\n타렌 밀농장은 인간의 손에 남지 않았다. 시간이 흘러 포세이큰이 이곳을 차지했고, 다른 거점들처럼 이곳도 그렇게 남겨 두었다. 교회 하나, 흩어진 집 몇 채, 썩어 버린 과수원. 모두 서 있지만 온전한 것은 하나도 없다. 포세이큰은 이곳에서 사우스쇼어와 던 가록의 얼라이언스 병력을 상대로 전쟁을 벌이며, 타렌 밀농장과 사우스쇼어 사이의 땅은 어느 쪽도 상대를 꺾지 못하는 두 마을 사이의 끝없는 교전으로 악명이 높아졌다.",
	["s:1424:thoradins wall"] = "소라딘 왕은 스트롬이 아직 젊고 아라소르가 인류를 위해 이 땅을 막 차지했던 시절, 아마니 트롤을 막기 위해 이 성벽을 세웠다. 여러 세대 동안 성벽은 굳건한 파수꾼으로 서서, 어떤 트롤 무리도 넘을 수 없는 방어선이 되었다.\n\n수 세기가 지난 지금도 성벽은 서 있지만, 심하게 손상되어 돌은 부서지고 그 오랜 감시는 폐허로 전락했다.",
	["s:1424:uplands"] = "고원은 한때 한 왕국을 먹여 살렸다. 그 언덕들은 알터랙의 곡창이었고, 옛 나라에 곡물과 목초지를 내주었다.\n\n그 나라는 무너졌다. 고원은 어떤 왕관에게도 넘어가지 않고 비밀결사의 손에 들어갔으며, 산맥 어디에서도 이곳만큼 그들이 굳게 장악한 곳은 없다. 바르두스 남작이 이곳 야영지들을 지휘하며, 무너진 왕국의 남은 땅을 다스리는 영주 노릇을 하고 있다.\n\n가장 서쪽 끝에는 단드레드 장원이 서 있다. 그 이름은 그것이 한때 무엇을 뜻했든 그 의미보다 오래 살아남았다.",
	["s:1424:western strand"] = "서부 해안은 힐스브래드 구릉지의 남서쪽 해안에 있다. 너덜지느러미멀록들이 해안을 따라 작은 야영지를 세웠고, 앤디 머골이 이 바다를 순찰하며 그들이 사는 해안선을 감시한다.",
	["s:1425:aerie peak"] = "와일드해머 드워프가 처음부터 동부 내륙지를 택한 것은 아니다. 그들의 고향은 산속 깊은 그림 바톨이었다. 그러나 세 망치의 전쟁이 끝나고 돌아온 드워프들은 모드구드의 죽음으로 요새가 오염되었음을 알게 되었다. 그림 바톨에는 다시는 살 수 없었다. 그래서 와일드해머는 이곳에 새로 터전을 세웠다. 검은무쇠 드워프와의 굴속 전투에서 겪은 공포 이후, 다시는 바위 속에 몸을 묻고 싶지 않았던 그들은 산속이 아니라 산허리 꼭대기에 보금자리를 지었다. 맹금의 봉우리가 하늘을 향해 열려 있는 것은 그 전쟁 때문이다.\n\n진짜 호드 군대가 쿠엘탈라스로 향하는 동안 양동 작전으로 동부 내륙지를 치러 보내진 오크 병력에 맞서, 쿠르드란 와일드해머가 그리핀 기수들을 이끌고 출격한 곳도 바로 이곳이었다. 안두인 로서의 군대가 그를 도우러 와서 와일드해머의 땅에서 오크와 숲 트롤을 몰아냈고, 그 일로 쿠르드란은 자기 부족이 얼라이언스를 따르겠다고 맹세했다.\n\n쿠르드란이 돌아오지 않자 대영주가 된 팔스타드 와일드해머가 지금도 맹금의 봉우리를 다스린다. 와일드해머를 조상의 땅에 무단으로 눌러앉은 자들이라 부르는 동부 내륙지의 숲 트롤은 여전히 그리핀 둥지를 습격하고, 쿠엘다닐의 하이 엘프들은 그 같은 적에 맞서 드워프의 동맹으로 남아 있다.",
	["s:1425:agolwatha"] = "아골와타의 돌들은 마지막으로 그것을 신성하게 여겼던 트롤들보다 오래되었다. 아마니 제국이 무너지기 전, 그 제국의 신전으로 세워진 것이다. 그 뒤에 온 썩은가지 트롤이 폐허를 자기 것으로 삼았다. 이제 신전은 되살아난 진흙덩이들에게 점령당해, 그것들이 부서진 뜰을 가득 메우고 있다.",
	["s:1425:altar of zul"] = "줄의 제단은 동부 내륙지에 솟아 있으며, 썩은가지 숲 트롤이 옛 의식을 위해 세운 것이다. 문지기 퀴아가가 돌 위에서 감시를 서며, 제단이 아직 간직한 힘이 무엇이든 그것을 지킨다.",
	["s:1425:bogens ledge"] = "보겐의 절벽은 동부 내륙지 남서쪽에 있는 동굴이다.",
	["s:1425:creeping ruin"] = "굼벵이 폐허는 동부 내륙지에 부서진 채 놓여 있다. 한때 숲 트롤의 손으로 다듬어진 돌이다. 이제 무너진 전당 사이로 끈적이들이 기어 다니며, 한때 트롤들이 거닐던 오래된 돌 위로 스며 나온다.",
	["s:1425:featherbeards hovel"] = "맹금의 봉우리 곁에는 한때 페더비어드라는 이의 것이었던 작은 집이 서 있다. 그곳에는 수비대도, 보물도 없다. 이제 그 집은 그것을 채웠던 삶이 무엇이었든 텅 빈 채, 늘 서 있던 자리에 서 있는 것 말고는 아무 쓸모도 없다.",
	["s:1425:hiriwatha"] = "마른나무껍질 트롤은 히리와타를 차지하고 있다. 동부 내륙지의 쿠엘다닐 오두막 남쪽, 그들이 자기 것이라 주장하는 숲 깊숙이 자리한 마을이다.",
	["s:1425:jinthaalor"] = "진타알로는 동부 내륙지 위로 계단식으로 솟아 있으며, 숲 트롤 도시 가운데 줄아만 다음으로 크다. 아마니 제국 시절에 세워졌으며, 아마니의 고대 지도자 가운데 하나인 진타의 이름을 땄다.\n\n도시는 썩은가지 부족의 것이며, 그들은 그 높은 곳을 제물의 요새로 바꾸었다. 사악한 여사제 헥스가 영혼의 약탈자 학카르를 섬기며 그곳을 다스리고, 썩은가지 부족은 신의 굶주림을 채우기 위해 더 약한 레반터스크 부족을 무자비하게 사냥한다. 레반터스크의 장로 톤터스크는 그런 습격 가운데 하나에서 잡혀가 지금도 도시 안에 갇혀 있다. 그의 경비대장 사냥꾼 말코르도 같은 공격에서 사로잡혀 처형당했고, 그 유해는 성벽 안에서 기르는 늑대와 수액괴물에게 던져졌다.\n\n썩은가지 부족에 대한 공통된 원한으로 묶인 와일드해머 부족과 레반터스크 부족은 함께 도시를 포위하고, 그들의 습격을 끝내고 망자들의 복수를 하려 하고 있다.",
	["s:1425:overlook cliffs"] = "전망대 절벽은 동부 내륙지가 산이기를 멈추고 하늘이 되는 곳이다. 이 지역을 굽이쳐 흐르는 큰 강이 이곳에 모여 하나의 거대한 폭포가 되어 가장자리 너머로 쏟아지며 아래 해안으로 떨어진다.\n\n절벽은 가파르고 보기보다 높다. 그 가장자리까지 걸어간 많은 이가 높이를 잘못 가늠해 떨어져 죽었다.",
	["s:1425:plaguemist ravine"] = "쿠엘다닐 오두막 서쪽, 산의 벽이 갈라진 곳에 안개가 드리워 카엘 다로우를 향해 북쪽으로 뻗은 협곡을 표시한다. 그 통로에는 아무것도 살지 않는다. 새도 그 위를 건너지 않고, 짐승도 그 바위에 굴을 틀지 않는다.\n\n주변의 동부 내륙지는 푸르고 깨끗하지만, 협곡은 숲에 어울리지 않는 다른 무언가를 내뿜는다. 이곳이 지금의 이름을 갖게 된 것도 그 때문이다. 땅의 나머지는 멀쩡한데 이 길 하나만을 더럽히는 병든 안개에서 온 이름, 역병안개이다.",
	["s:1425:queldanil lodge"] = "쿠엘다닐 오두막은 하이 엘프의 마지막 진정한 거처 가운데 하나로, 로데론에 남은 단 두 곳의 정착지 가운데 더 큰 곳이다. 3차 대전쟁 이후 이곳은 서신 교류의 장이 되었고, 그곳의 사절들은 얼라이언스의 다른 종족들에게 손을 내밀었다. 그 노력으로 높은골짜기 엘프들은 와일드해머 드워프와 동맹을 맺었지만, 레반터스크 트롤의 증오도 샀다. 트롤들은 엘프들을 학살하고 그들의 기록을 불태우려 했다. 문서들은 살아남았다. 죽음과 탄생, 계절, 그리고 엘프들이 맺은 모든 조약의 기록이다.",
	["s:1425:revantusk village"] = "레반터스크 마을은 동부 내륙지의 해안에 서 있으며, 생존보다 신의를 택한 숲 트롤 부족의 마지막 보금자리이다.\n\n2차 대전쟁에서 구 호드가 무너지자, 오크를 붙잡은 자들은 옛 동맹에게 등을 돌렸고, 곳곳의 숲 트롤 부족들은 망설임 없이 호드를 버렸다. 레반터스크는 그러지 않았다. 그들에게는 사로잡힌 오크들을 풀어 줄 만한 수가 없었고, 어차피 오크들도 풀려나려는 의지를 별로 보이지 않았다. 하지만 그들의 변함없는 신의 때문에, 오크와 더는 얽히기 싫어하던 다른 트롤들의 공격 표적이 되었다. 땅에서 쫓겨난 레반터스크는 고립이 안전을 지켜 주리라 믿으며 동부 내륙지 해안으로 달아나 그곳에 마을을 세웠다.\n\n마침내 스랄이 호드를 새로 일으켜 동족을 조상들의 주술적 전통으로 되돌렸다는 소식이 그들에게 닿았다. 레반터스크는 가장 빠른 전령들을 보내 그를 찾게 했고, 그 만남에서 부족과 새로운 호드 사이의 우호 협약이 맺어졌다. 다른 숲 트롤들은 결코 그것을 용서하지 않고 레반터스크를 나약한 배신자라 부르지만, 레반터스크는 호드를 저버린 모든 이야말로 진정한 배신자라 말한다.",
	["s:1425:seradane"] = "동부 내륙지 북동쪽에는 세라데인이 있으며, 그곳에는 에메랄드의 꿈으로 열린 거대한 원형 차원문이 서 있다. 숲은 녹색용군단의 것으로, 그들은 자기 종족이 신성하게 여기는 문턱을 지키려고 이곳에 모였다. 비룡 로도스와 꿈추적자가 이 나무들 사이에 보금자리를 틀었다.\n\n숲을 지키는 이들 대부분은 용군단의 힘에서 태어난 용족이다. 그들은 셋씩 무리 지어 움직인다. 신록의 신탁자 하나를 가지 수호병과 나무 파수병이 양옆에서 호위하며, 꿈으로 가는 길을 늘 지키기 위해 얽힌 오솔길을 순찰한다.",
	["s:1425:shadraalor"] = "동부 내륙지에는 샤드라알로가 서 있다. 아마니 제국의 숲 트롤이 세운 거주지이다. 이곳에서는 로아 샤드라를 불러내어 소환할 수 있었으며, 오직 그 목적만을 위해 따로 마련된 곳이다.",
	["s:1425:shaolwatha"] = "샤올와타는 동부 내륙지 북동쪽에 있는 썩은가지 숲 트롤의 폐허이다. 한때 이곳은 신전이었다.",
	["s:1425:shindiggers camp"] = "술을 좋아하는 드워프 랩소디 신디거는 하이 엘프 길베라딘 선체이서와 함께 동부 내륙지에 작은 야영지를 두고 있으며, 이 별난 한 쌍이 이 고요한 땅을 지키고 있다.",
	["s:1425:skulk rock"] = "굼벵이 바위굴은 끈적이들이 들끓는 숲 트롤의 폐허이다. 그 아래 동굴은 유령버섯이 아직 자라는 몇 안 되는 곳 가운데 하나이다.\n\n2차 대전쟁 때 구 호드는 이 바위를 거점으로 삼았지만, 로데론 연합이 그들을 몰아냈다.",
	["s:1425:valorwind lake"] = "돌개바람 호수는 샤드라알로 북동쪽에 고요히 놓여 있으며, 그 물은 겉보기에 별다를 것이 없다. 그러나 그 가장자리를 따라 세상 어디에서도 알려지지 않은 것이 자란다. 비밀을 여전히 간직한 수수께끼의 버섯, 보랏빛 트라간이다.",
	["s:1425:wildhammer keep"] = "와일드해머 요새는 맹금의 봉우리 한가운데에 솟아 있으며, 이곳을 지키는 와일드해머 드워프의 본거지이다. 그 전당은 봉우리에 닿은 여행자들에게 열려 있다.",
	["s:1425:zunwatha"] = "준와타의 돌들은 한때 동부 내륙지의 마른나무껍질 트롤에게 안식처가 되었고, 지금도 그러하다. 그들이 남겨 둔 폐허 사이로 이따금 줄아레크 증오새가 모습을 드러내며, 마른나무껍질 트롤이 여전히 사는 곳을 거닌다.",
	["s:1426:amberstill ranch"] = "앰버스틸 목장은 모단 호수로 가는 길에서 조금 벗어난 골볼라 채석장 북쪽에 있으며, 앰버스틸 가문의 드워프들이 던 모로의 추위 속에서 가축을 기르는 곳이다. 루드라 앰버스틸은 이곳에서 귀한 산양을 기르고, 어린 얄린은 눈신토끼들을 발치에 데리고 다닌다.\n\n가축들이 아무 탈 없이 지내는 것은 아니다. 바가쉬라는 웬디고가 목장의 짐승들을 노리기 시작했고, 앰버스틸 가족은 그 굶주림으로부터 자신들이 기르는 것을 지켜야 했다.",
	["s:1426:anvilmar"] = "눈마루 골짜기에는 거대한 용광로를 중심으로 지은 전당, 앤빌마가 서 있다. 이곳은 드워프가 이 북쪽 지역에 처음으로 세운 진정한 정착지로, 다른 곳들이 모습을 갖추기 전부터 모임의 장소였다. 그 중심의 용광로는 지금도 타오르지만, 이제 그곳에서 기술을 가르치는 대장장이는 없다.",
	["s:1426:brewnall village"] = "브루날 마을은 놈리건 근처의 찬바람 골짜기에 있으며, 발리브루 가문의 보금자리이다. 발리브루 가문은 오직 한 가지, 드워프 양조술을 완성하는 일에 몸을 바쳤다. 그들은 마을의 젊은이들을 내보내 야생 동물로부터 마을을 지키고, 궁극의 맥주를 위한 희귀한 재료를 찾게 한다.",
	["s:1426:chill breeze valley"] = "찬바람 골짜기는 놈리건과 카라노스 사이로 동서로 뻗어 있으며, 그 길은 오가는 젊은 드워프와 노움의 발길로 낯익게 다져져 있다. 그러나 골짜기는 남북으로도 굽어지는데, 그곳의 눈은 다른 이야기를 들려준다. 하얀 눈 위로 핏자국이 넓게 번져 있고, 찢긴 짐승의 사체가 버려져 있다. 이 갈래길을 기꺼이 지나는 이는 드물다. 그 길로 가는 이들은 드워프의 땅을 위협하는 짐승들을 끝장내려고 사냥에 나서지만, 많은 이가 돌아오지 못한다. 한 동굴 깊숙한 곳에는 눈 위의 피에 가장 큰 책임이 있는 웬디고가 도사리고 있다.",
	["s:1426:coldridge pass"] = "눈마루 고개는 눈마루 골짜기를 빠져나가는 좁은 길로, 드워프가 카라노스와 던 모로의 넓은 길에 닿기 전에 건너야 하는 마지막 구간이다. 트로그들이 고개를 점령해, 여행자에게 남은 선택은 두 가지뿐이다. 다리가 허락하는 한 빨리 달려 빠져나가거나, 침입자들 사이로 피비린내 나는 길을 뚫는 것이다.\n\n펜드리그 레드비어드는 한때 다른 광부 열두 명을 이끌고 고개로 들어가 트로그의 침입을 조사했다. 깊숙한 곳에서 그는 무너진 바위 밑에 깔렸다. 다른 이들은 그를 파내려고 되돌아왔지만, 그 노력은 고개를 그들 위로 무너뜨렸다. 광부 열두 명이 죽었다. 잔해에서 끌려 나온 펜드리그만이 살아남았다.",
	["s:1426:coldridge valley"] = "눈마루 골짜기에는 눈이 두텁게 쌓여 있고 사방이 막혀 있으며, 유일한 출구는 북동쪽의 좁은 굴인 눈마루 고개뿐이다. 그 통로에는 트로그 약탈자들이 들끓는다. 이 난폭한 것들 때문에 카라노스와 아이언포지로 가는 길은 오래전부터 홀로 여행하는 이에게 위험한 길이 되었다.\n\n고개를 지나면 길은 동쪽으로, 이어 북쪽으로 카라노스를 지나 올라간 뒤 산을 굽이굽이 올라 아이언포지의 성문에 이른다.",
	["s:1426:frostmane hold"] = "서리갈기 소굴은 던 모로의 차가운 산맥 서쪽 끝, 놈리건 남쪽에 서 있다. 산허리를 파고든 동굴과 이어진 건물들이 흩어져 있는 곳이다. 이곳은 서리갈기 얼음 트롤의 본거지로, 그들은 모든 길목을 지키는 머리사냥꾼과 가죽벗기미들로 이 땅을 지키고 있다.",
	["s:1426:gates of ironforge"] = "아이언포지 성문은 던 모로의 거대한 비탈길이 산과 만나는 곳에 솟아 있으며, 여행자가 닿기 한참 전부터 설원 너머 수십 리 밖에서도 보인다. 성문은 탁 트인 드워프의 땅과 아이언포지 본성 사이의 문턱으로 서 있다.\n\n문을 지나면 대왕 모디무스 앤빌마를 기려 세운 거대한 석상의 시선 아래 서게 된다. 석상은 입구 바로 안쪽에서 감시하도록 세워져, 누구도 먼저 그의 눈 아래를 지나지 않고서는 도시에 들어갈 수 없다.",
	["s:1426:gnomeregan"] = "놈리건은 같은 이름을 지닌 노움 왕국의 지하 수도로, 노움의 탁월함과 야망, 창의력을 보여 주는 무쇠 증거이다.\n\n3차 대전쟁 동안 트로그의 침공이 놈리건의 몰락을 불러왔다. 티탄 유적의 격변으로 잠에서 깨어난 트로그들이 아래에서 도시로 떼 지어 올라왔다. 침입자들을 죽이려는 절박한 시도로, 땜장이왕 겔빈 멕카토크는 고문 시코 서마플러그의 조언에 따라 거대한 연마 기계들의 압력 밸브를 열어 놈리건 전체에 유독한 방사능을 퍼뜨리라고 명령했다. 가스는 일부 트로그를 죽였지만 다른 트로그는 오히려 더 강하게 만들었고, 노움의 거의 팔십 퍼센트가 며칠 만에 죽었다. 살아남은 이들은 아이언포지의 보호를 찾아 달아났다. 다른 이들은 끔찍하고 정신 없는, 악행을 일삼는 문둥병 노움으로 뒤틀려 지금도 폐허가 된 굴에 출몰한다.\n\n자신도 방사능에 미쳐 버린 서마플러그는 스스로를 놈리건의 왕이라 선포하고 오염된 도시를 장악했으며, 트로그와 문둥병 노움의 군대를 이끌고 부서진 전당과 작업장을 누비고 있다.",
	["s:1426:golbolar quarry"] = "골볼라 채석장은 던 모로 남동부에 파 들어간 채굴장으로, 그 아래에서 기어 올라온 것 때문에 중단되었다. 드워프들은 산이 품은 것을 찾아 발굴을 시작했지만, 그 채굴은 트로그들을 깨웠다. 트로그들은 광산 깊은 곳에서 떼 지어 올라와 광부들이 파 놓은 구덩이와 굴을 점령했다.\n\n남은 야영지는 승리가 아니라 발판일 뿐이다. 드워프들이 지상을 지키고 있지만, 아래의 광산은 여전히 트로그에게 빼앗긴 채이다.",
	["s:1426:grizzled den"] = "카라노스 남서쪽에는 던 모로의 얼음 깊숙이 파고든 커다란 동굴이 열려 있다. 웬디고가 이곳에 굴을 틀었다. 텁수룩하고 서리 입김을 내뿜는 이 짐승들은 침입하는 자라면 누구에게든 떼 지어 맞선다. 그들의 갈기는 안장 덮개로 귀하게 여겨지지만, 그것을 얻으러 들어간 이 가운데 싸움 없이 나오는 이는 드물다. 웬디고는 흩어지지 않고 대열을 좁혀 발톱과 얼어붙은 입김으로 침입자를 몰아내기 때문이다.",
	["s:1426:helms bed lake"] = "투구바닥 호수는 한 해의 대부분 얼어붙어 있으며, 수면을 덮은 얼음은 안전하게 걸어 건널 수 있을 만큼 두껍다. 딱 한 곳에만 구멍을 뚫어 두어, 얼음 아래에서 여전히 맑은 물을 길을 수 있게 했다.\n\n그 안전은 물가에서 끝난다. 늑대와 다른 야생 동물들이 기슭을 누비고, 길 잃은 트로그들이 주변 바위에 출몰한다. 호수 남쪽에는 검은무쇠 드워프가 차지한 버려진 건물이 서 있는데, 그들은 너무 가까이 다가오는 자는 누구든 공격한다.",
	["s:1426:iceflow lake"] = "얼음 호수는 던 모로의 추위 속에 단단히 얼어붙지만, 브루날 마을의 드워프들은 얼음에 구멍 하나를 뚫어 두고 언 수면 아래에서 맑은 물과 물고기를 얻는다.\n\n호수 한가운데 쪽으로는 섬 두 개가 솟아 있는데, 가만히 두는 편이 낫다. 굶주린 늑대 무리가 팀버라는 늑대를 우두머리로 삼아 섬을 차지했고, 그들 때문에 섬에는 그곳을 차지한 짐승들 말고는 아무도 없다.",
	["s:1426:ironbands compound"] = "투구바닥 호수 남쪽에 있는 아이언밴드 야영지는 검은무쇠 드워프의 거점으로, 그들은 너무 가까이 다가오는 자는 누구든 공격한다. 이곳은 검은무쇠 드워프의 손에 넘어가기 전까지 스터기 아이언밴드의 것이었다.",
	["s:1426:ironforge"] = "던 모로 북부의 아이언포지 산 아래 깊은 지하 궁륭에, 드워프들은 조상들이 처음 울다만에서 파고 나와 서쪽으로 향했던 시절부터 수도를 두어 왔다. 이곳은 드워프 종족의 가장 오래된 보금자리로 대용광로를 중심으로 세워졌으며, 마그니 브론즈비어드 왕이 다스리는 카즈 모단 왕국의 본거지이다.\n\n도시는 수도인 만큼이나 요새이기도 하다. 동심원 모양의 고리로 깎여 내려갈수록 바위 속으로 더 깊이 가라앉고, 통로는 좁으며 방들은 넓고 소리가 울린다. 인간과 나이트 엘프의 도시와 달리 아이언포지는 온전한 하나의 동굴로, 바닥과 천장 모두 깎아 낸 바위이다. 모든 화로에서 불이 타오르고, 전당은 망치 소리와 웃음소리, 흥정 소리로 시끄럽다. 드워프는 땅속에서도 결코 조용한 종족이 아니었기 때문이다.\n\n폐허가 된 자신들의 도시를 떠나온 노움들은 아이언포지의 성벽 안에서 피난처를 찾았다. 마그니 왕은 그들에게 한 구역을 내주었고, 그들은 그곳을 자기들의 지구로 삼아 일하고 계획을 세운다.",
	["s:1426:kharanos"] = "카라노스는 던 모로의 산봉우리들 사이에 자리하며, 그 거리를 둘러싼 겨울의 황야는 주민들이 결코 나약해지지 않게 만든다. 마을 한가운데에는 용광로가 타오르고, 노움의 작업장은 달그락거리며, 썬더브루 양조장은 어디서도 찾기 힘든 최고의 맥주를 따르지만, 마을은 그 매력 속에서 한 번도 마음 놓고 쉴 수 없었다. 서쪽에는 웬디고가 들끓는 동굴이 있고, 북서쪽에서는 서리갈기 트롤이 쉼머 마루를 차지하고 아래 마을을 지켜보고 있다.\n\n그 지켜봄은 한때 전쟁으로 번졌다. 거대한 서리갈기 트롤이 카라노스를 덮쳐 그곳에 사는 드워프를 거의 모조리 쓸어버릴 뻔했다. 마을의 수비대가 흔들릴 때에도 흔들리지 않은 드워프가 하나 있었다. 라즐로 그라인드위젯이 트롤에 맞서 홀로 그것을 쓰러뜨렸고, 마을은 그를 영웅이라 불렀다. 그 칭호는 침묵에 얼마나 가까이 다가갔었는지 기억하는 거리마다 그 뒤로 줄곧 그를 따라다녔다.",
	["s:1426:misty pine refuge"] = "안개소나무 은거처는 던 모로 중부에 고요히 자리한, 눈을 무겁게 인 소나무들 사이의 아늑한 빈터이다.",
	["s:1426:north gate outpost"] = "북부 관문 전초기지는 던 모로와 모단 호수를 잇는 산속의 좁은 길인 북부 관문 통행로에 걸쳐 있으며, 이 고지대의 드워프 거점 가운데 가장 북동쪽에 있다.\n\n이곳에 주둔한 산악병들은 주변 봉우리에서 밀려드는 야생 동물을 막아 내며 하루를 보낸다. 더 위험한 짐승을 사냥하러 나선 이들 가운데 몇몇은 돌아오지 않았고, 그들의 소식을 찾아 산을 뒤졌지만 이렇다 할 성과는 없었다.",
	["s:1426:north gate pass"] = "이 통행로는 높은 산맥을 가로질러 던 모로에서 모단 호수 쪽으로 내려간다. 두 곳 사이의 가장 짧은 길이라, 호수 너머의 땅으로 향하는 여행자들은 다른 어떤 길보다 이곳을 많이 지난다.\n\n북부 관문 전초기지가 이곳에서 통행로를 지키고 있다.",
	["s:1426:shimmer ridge"] = "쉼머 마루는 던 모로 북부에 솟아 있으며, 서리갈기 트롤이 다리로 이어진 두 야영지를 두고 바위 사이에서 어스름 풀을 가꾸고 멧돼지를 길들인다.",
	["s:1426:south gate outpost"] = "남부 관문 전초기지는 던 모로와 모단 호수 사이의 고개가 좁아지는 곳에 자리한 바위 길목으로, 드워프 산악병들이 지키고 있다. 그들의 일은 북부 관문의 동족보다 조용하다. 그들은 한때 고개를 압박하던 야생 동물을 몰아냈고, 그 길은 텔사마를 오가는 이들에게 열린 채 안전하게 유지되고 있다.",
	["s:1426:south gate pass"] = "남부 관문 통행로는 산맥을 가로질러 던 모로의 높은 설원과 모단 호수의 낮은 골짜기를 잇는다. 텔사마로 내려가는 가장 짧은 길로, 두 땅을 오가는 여행자들의 발길에 닳아 있다.\n\n이곳에는 고개를 감시하기 위해 세운 경비 초소, 남부 관문 전초기지가 서 있다.",
	["s:1426:steelgrills depot"] = "스틸그릴의 정비소는 카라노스 동쪽에 자리한, 던 모로의 얼어붙은 땅에서 일하는 광부와 기술자들의 작은 야영지이다.",
	["s:1426:thunderbrew distillery"] = "썬더브루 양조장은 카라노스에 있으며, 그 이름은 맥주의 품질 덕분에 드워프 마을 너머 멀리까지 알려져 있다. 여관 주인 벨름이 이곳을 운영하며 지나가는 이들에게 쉼터와 술을 내준다.",
	["s:1426:tundrid hills"] = "툰드리드 언덕은 골볼라 채석장 남쪽에 펼쳐진 바람에 깎인 땅으로, 칼을 손에 쥐지 않고 이곳을 지나는 이는 드물다. 늑대와 다른 야생 짐승들이 비탈을 어슬렁거리고, 눈마루 골짜기와 던 모로 동부 사이를 가로지르려고 언덕을 넘는 이들은 카라노스를 지나는 길이 더 안전했으리라는 것을 알면서도 이 길을 택한다.\n\n서리갈기 트롤은 이곳 골짜기에 야영지를 세우고, 드워프의 채석장이 보이는 곳에서 이 땅을 지키고 있다.",
	["s:1427:blackchar cave"] = "검은재 동굴은 검은바위 산 근처에 봉인된 채 놓여 있으며, 그 어두운 바위는 고요히 바깥 세상과 단절되어 있다.",
	["s:1427:blackrock mountain"] = "검은바위 산은 평범한 불에서 태어나지 않았다. 세 망치의 전쟁 때 브론즈비어드와 와일드해머 군대가 검은무쇠 부족을 몰아내려고 진군하자, 마법사 영주 타우릿산은 세계의 녹아내린 심장부로 손을 뻗어 그 힘을 무기로 끌어올렸다. 그에게 응답한 것은 라그나로스였다. 불의 군주가 다시 태어나면서 산들이 찢겨 나갔고, 주변 땅은 불길에 잠겼으며, 두 왕은 그와 맞서느니 군대를 돌려 물러갔다. 검은무쇠 왕국이 서 있던 자리에는 이제 화산이 연기를 피우고 있으며, 그 남쪽에는 불타는 평원이, 북쪽에는 이글거리는 협곡이 있다. 라그나로스는 산의 중심부로 물러나, 살아남은 검은무쇠 드워프를 노예로 삼아 폐허가 된 그들의 옛 보금자리 아래에 어둠괴철로 도시를 깎아 만들게 했다.",
	["s:1427:cauldron"] = "용광로는 이글거리는 협곡 한가운데를 파낸 거대한 발굴지로, 검은무쇠 드워프가 라그나로스를 소환한 뒤 얼마 지나 요새화했다. 그곳을 파헤칠 때 쓴 거대한 기계들이 아직도 가장자리를 둘러싸고 있다. 아래에서는 불과 용암의 정령들이 갈라지고 빛나는 틈 사이를 움직인다.\n\n검은무쇠 드워프에게 끌려온 노예 일꾼들이 그 아래에서 끝없이 일하며, 노동과 숨 막히는 열기에 짓눌려 부서졌다. 그들은 더 이상 친구와 포획자를 구별하지 못하고, 들어오는 자는 누구든 여느 감독관과 다를 바 없는 정신 없는 폭력으로 맞이한다.",
	["s:1427:dustfire valley"] = "먼지불 골짜기는 이글거리는 협곡을 가로지르는 바람 부는 땅으로, 북쪽으로 돌다지 고개의 문과 그 너머 모단 호수의 왕의 계곡으로 이어진다.",
	["s:1427:firewatch ridge"] = "불망루 마루는 이글거리는 협곡에 있는 검은무쇠 드워프의 주 야영지로, 용광로의 거대한 발굴지를 내려다본다. 검은무쇠 드워프는 기계 골렘과 거대한 화염 거미들을 거느리고 비탈을 지키고 있어, 이 마루는 발을 들이기 위험한 곳이 되었다.",
	["s:1427:grimesilt dig site"] = "한때 아이언포지 드워프들이 이곳을 팠지만, 검은무쇠 드워프가 와서 발굴지를 빼앗았다. 이곳은 여전히 검은무쇠 드워프의 손에 있다.",
	["s:1427:sea of cinders"] = "잿더미 바다는 이글거리는 협곡 남쪽, 검은바위 산 바로 북쪽에 평평하고 탁 트이게 펼쳐져 있다. 그곳에는 아무것도 자라지 않는다. 땅은 아직도 연기를 피우고, 재는 끊임없이 바람에 날려 황량한 평원 위로 흩날린다. 불과 바람은 황무지 말고는 아무것도 남기지 않았고, 불길은 한 번도 멈추지 않았다.",
	["s:1427:slag pit"] = "잿가루 채석장은 이글거리는 협곡의 용광로 발굴지 깊숙이 파여 있으며, 노예들이 검은무쇠 드워프의 잔혹함 아래에서 일하고 있다. 노예 상인과 감독관들이 노동을 몰아붙이고, 겁에 질린 일꾼들조차 감독관을 공격하는 자에게는 등을 돌린다. 검은무쇠 드워프는 채굴을 방해하는 모든 것에 노골적인 적대로 대응하며, 구덩이 깊은 어둠 속 발굴지 사이에는 굶주린 화염도마뱀들이 둥지를 틀고 있다.",
	["s:1427:stonewrought pass"] = "돌다지 고개라 알려진 굴은 먼지불 골짜기 북쪽 끝에서 산맥을 뚫고 이글거리는 협곡과 모단 호수의 왕의 계곡을 잇는다. 이 굴은 프랜클론 포지라이트의 작품으로, 그는 돌다지 댐을 비롯해 동부 왕국 곳곳의 수많은 드워프 석조물을 세웠다.\n\n모단 호수 쪽 문은 산악병 페블비티가 굳게 닫아 두고 있으며, 광포한 마르골을 상대로 스스로를 증명한 이가 아니면 누구도 지나가지 못하게 막는다.",
	["s:1427:tanner camp"] = "정령 가죽세공의 대가 사라 태너는 이글거리는 협곡에 천막 하나를 홀로 치고 있다. 그 뒤로는 긴 통로가 산속으로 굽이굽이 이어지며, 그 끝에서 천둥도마뱀 광포한 마르골이 기다리고 있다.",
	["s:1427:thorium point"] = "이글거리는 협곡의 그을린 북쪽에는 토륨 조합 거점이 서 있다. 토륨 형제단이 지키는 작은 중립 마을로, 산 아래의 어둠의 힘이 아니라 형제단을 따르는 검은무쇠 드워프들이 주로 살고 있다. 이곳에는 화덕과 모루가 준비되어 있고, 재와 열기 속에서도 불이 꺼지지 않아, 협곡이 어떻게 변했든 여전히 쇠가 다듬어진다.",
	["s:1428:blackrock mountain"] = "검은바위 산은 평범한 불에서 태어나지 않았다. 세 망치의 전쟁 때 브론즈비어드와 와일드해머 군대가 검은무쇠 부족을 몰아내려고 진군하자, 마법사 영주 타우릿산은 세계의 녹아내린 심장부로 손을 뻗어 그 힘을 무기로 끌어올렸다. 그에게 응답한 것은 라그나로스였다. 불의 군주가 다시 태어나면서 산들이 찢겨 나갔고, 주변 땅은 불길에 잠겼으며, 두 왕은 그와 맞서느니 군대를 돌려 물러갔다. 검은무쇠 왕국이 서 있던 자리에는 이제 화산이 연기를 피우고 있으며, 그 남쪽에는 불타는 평원이, 북쪽에는 이글거리는 협곡이 있다. 라그나로스는 산의 중심부로 물러나, 살아남은 검은무쇠 드워프를 노예로 삼아 폐허가 된 그들의 옛 보금자리 아래에 어둠괴철로 도시를 깎아 만들게 했다.",
	["s:1428:blackrock pass"] = "검은바위 고개는 두 세계 사이의 문턱이다. 한쪽에는 푸르고 고요한 붉은마루가 있다. 다른 쪽에는 알아볼 수 없을 만큼 그을리고 뒤틀린 불타는 평원이 기다리고 있다. 경계에는 문이 서 있어 그 선을 분명히 표시한다.\n\n그 문을 지나는 것은 한 걸음에 안전을 등지는 일이다. 준비 없이 들어선 이들은 그 변화가 가혹하다는 것을 알게 된다. 그 너머의 생물들은 뒤편 산속에서 꿈틀대는 어떤 것보다 훨씬 잔혹하다.",
	["s:1428:blackrock stronghold"] = "이 요새는 불타는 평원의 끝자락, 검은바위 첨탑의 그림자에 바짝 붙어 솟아 있는 검은 바위의 요새로, 검은바위 부족이 지키고 있다. 성벽 밖 명예의 들판에서는 부족의 전사들과 동맹들이 집결해 훈련하며, 검은바위 부사관들의 채찍과 고함 아래 대열을 맞춘다.\n\n요새의 지휘는 장군 소르기조그가 맡고 있다. 그는 들판에 모인 병사들을 단련하고, 자신의 명령이 이의 없이 수행되도록 한다.",
	["s:1428:dracodar"] = "드라코다르의 언덕은 검게 그을린 채 완전히 검은용군단에게 넘어갔다. 그들의 족속이 이곳을 자유로이 오가며, 그 수가 워낙 많아 누구도 조심성과 동행 없이는 발을 들여서는 안 된다.",
	["s:1428:dreadmaul rock"] = "우레망치 바위굴은 돌길과 속을 파낸 오우거 흙더미로 이루어진 요새로, 불먹보 부족의 본거지이다. 불먹보 부족은 그 높은 곳과 굴에서 남쪽의 붉은마루 산맥으로 습격을 준비하며, 이 바위굴을 거점으로 삼았다가 다시 그 깊은 곳으로 물러난다.",
	["s:1428:flame crest"] = "화염 마루는 불타는 평원의 헐벗은 바위 위에 있으며, 투박한 다리로만 닿을 수 있다. 그 뒤편의 작은 동굴에는 말 많은 앵무새를 기르는 키블러가 산다.",
	["s:1428:morgans vigil"] = "모건의 망루는 불타는 평원 남동쪽에 폐허로 남아 있다. 집들은 잿더미가 되도록 불탔고, 마법사의 탑은 무너져 돌무더기가 되었다. 잔해 사이에는 천막들이 서서 남은 이들에게 쉴 곳을 내준다.\n\n얼라이언스는 이 천막들에서 검은바위 산을 감시하며, 위험의 근원 가까이에서 그것을 치고 있다.",
	["s:1428:pillar of ash"] = "검은이빨 오두막 동쪽 끝에는 그을린 바위로 된 높은 탑이 솟아 있으며, 그 표면은 마치 불길 자체가 타고 올라갔다가 멈춘 듯 검게 그을려 있다. 그 근처에는 아무것도 자라지 않으며, 이곳에서 그만큼 높이 솟은 것은 없다.",
	["s:1428:ruins of thaurissan"] = "불타는 평원의 이 잿빛 평지는 한때 푸르렀고, 이곳의 도시는 그 창건자의 이름을 지니고 있었다. 타우릿산 시, 세 망치의 전쟁 때 아이언포지에서 추방되어 마법사 영주 타우릿산을 따라 남쪽으로 온 검은무쇠 부족의 수도였다.\n\n검은무쇠 부족은 그 전쟁에서 지고 있었다. 그들의 군대가 다른 두 부족의 요새 앞에서 막 무너졌을 때, 전세를 뒤집으려 절박해진 타우릿산은 가장 신임하는 일곱 드워프를 모아 땅 아래 잠든 힘들에게 전쟁을 되찾아 줄 하수인을 달라고 외쳤다. 응답한 것은 하수인이 아니라 불의 정령 군주 라그나로스였고, 그의 강림은 산을 갈라 화산을 솟게 하여 골짜기를 잿더미로 태웠다. 도시는 완전히 소멸했고, 살아남은 검은무쇠 드워프는 불의 군주의 노예가 되었다. 그들은 폐허를 버리고 검은바위 산 아래에 새 보금자리를 지었으며, 타우릿산의 잿더미에서 검은바위 첨탑과 새로운 검은무쇠 나라가 일어섰다.",
	["s:1428:slither rock"] = "뱀갈퀴 바위굴은 불타는 평원 북동쪽 끝, 공포의 날개 골짜기 너머에 숨겨진 작은 동굴이다. 이곳에는 검은용족 사이러스 테레펜투스가 머물고 있다. 그는 공동의 적에 맞서 다른 이들을 도와주지만, 무례하고 비웃는 말을 빼놓는 법이 없다.",
	["s:1428:terror wing path"] = "공포의 날개 골짜기는 불타는 평원 동부의 골짜기로, 완전히 검은용군단에게 넘어갔다. 새끼용과 용족이 바위와 재 사이에 둥지를 틀고 있다.",
	["s:1429:brackwell pumpkin patch"] = "엘윈 숲 남동쪽에는 한때 브랙웰 가문의 것이었던 농장이 서 있다. 그들이 어떻게 되었는지는 아무도 모른다. 데피아스 단이 이곳을 차지했고, 브랙웰 가족은 밭과 울타리에서 그냥 사라져 버렸다.\n\n그들에 대해 남은 기억은 단 하나이다. 도적들이 오기 훨씬 전, 밤마다 이웃 스톤필드 농장으로 몰래 건너가 훔친 채소를 먹고 엄청나게 커진 상품 암퇘지, 프린세스이다.",
	["s:1429:crystal lake"] = "수정 호수는 골드샤이어 동쪽에 있으며, 물에는 멀록이 우글거려 방심한 이들에게는 좋지 않은 물가이다. 남쪽 기슭의 인간 농가 한 채가 호수를 내려다보고 있다.",
	["s:1429:eastvale logging camp"] = "동부 벌목지의 제재 야영지들은 엘윈 숲 동부 곳곳에 흩어져 있으며, 톱질 구덩이 사이로 숙소가 늘어서 있고 일은 결코 멈추지 않는다. 목재 주문은 기한보다 빠르게 밀려들고, 벌목꾼들은 스톰윈드의 목재를 기다리는 구매자들의 끊임없는 재촉 속에서 일한다.\n\n한때 스톰윈드 경비대를 이끌었던 원수 해거드는 몇 해 전 그 지휘에서 물러나, 한때 자신이 지켰던 도시 대신 야영지 안의 저택에서 여생을 보내기로 했다. 세야 노스브룩도 이곳에서 자랐다.\n\n숲은 사방에서 바짝 다가와 있고, 그 야성은 결코 작은 문제가 아니다. 늑대와 곰이 벌목꾼들을 괴롭혀 작업반을 흩어 놓고 야영지의 기한을 완전히 묻어 버릴 위협을 가했다. 문제가 너무 심각해지자 스톰윈드 경비대는 짐승들을 솎아 내기 위해 외부의 도움을 청할 수밖에 없었다.",
	["s:1429:echo ridge mine"] = "메아리 광산의 굴은 노스샤이어 계곡 북서쪽에 있다. 코볼트들이 갱도에 몰려들어 그곳을 차지했고, 근처에 사는 인간들은 크게 속을 끓였다. 원수 맥브라이드가 할 수 있는 일은 거듭 병사들을 보내 그 수를 줄이는 것뿐이었다.",
	["s:1429:fargodeep mine"] = "개미굴 광산은 한때 스톰윈드의 금을 캐던 곳으로, 그 갱도는 엘윈 숲의 땅속 깊이 파여 있었다. 이제 광산은 버려졌고, 그 굴은 코볼트 무리가 차지했다. 본 갱도 아래의 더 깊은 곳인 아래층 광산은 어둠 속으로 더 멀리 이어진다.\n\n엘윈의 안전을 책임지는 원수 듀간은 안에 코볼트가 있다는 것이 확인되자 주변 순찰을 늘렸다. 코볼트들 사이에는 금니가 숨어 다니는데, 그는 버니스 스톤필드 아주머니에게서 훔친 목걸이를 가지고 있다. 그녀가 다시 보기를 포기하지 않은 기념품이다.",
	["s:1429:forests edge"] = "숲 가장자리는 스톰윈드 남서쪽에 있으며, 거울 호수 과수원과 나즈페리티 강, 그리고 서부 몰락지대로 흐르는 작은 개울 사이로 혀처럼 뻗은 숲이다. 멧돼지들이 덤불을 헤집고, 강둑을 따라 구리 광맥이 뻗어 있다. 숲은 놀 무리의 차지인데, 그중에는 한낱 무리 짐승이 아닌 자가 하나 있다. 호거는 하급 놀들 사이에서 숲을 누비며, 결코 흔한 들개 따위가 아니다.",
	["s:1429:goldshire"] = "골드샤이어는 엘윈 숲의 심장부에 자리하며, 들판에서는 노스샤이어가 보이고 길은 스톰윈드와 서부 몰락지대, 붉은마루로 뻗어 있다. 이 마을은 스톰윈드가 세워진 뒤 몇 해 동안, 왕국의 백성이 수도에서 주변 땅으로 퍼져 나가던 시절에 생겨났다.\n\n마을의 가장 암울한 시기는 1차 대전쟁 때, 대족장 블랙핸드가 스톰윈드 성과 그 백성을 잇는 생명줄로 호드를 돌렸을 때 찾아왔다. 골드샤이어와 문브룩은 오크와 수도 사이에 남은 마지막 두 마을이었고, 그 둘이 함락되자 성으로 가는 길이 활짝 열렸다. 골드샤이어는 2차 대전쟁이 끝나고 로데론 연합이 재건할 때까지 다시 일어서지 못했다. 최고 사령관 투랄리온이 직접 흩어진 스톰윈드 시민들의 귀환을 챙겼다.\n\n지금 남아 있는 것은 더 평온하다. 사자의 자존심 여관이 마을 한가운데에 서 있고, 그 화로와 맥주가 이곳에서 만나는 모든 길에서 여행자들을 불러들인다. 스톰윈드 경비대의 원수 듀간은 한때 이 마을을 잃은 대가가 무엇이었는지 기억하며 지금도 마을을 지키고 있다.",
	["s:1429:heroes vigil"] = "돌무덤 호수의 작은 섬에는 선돌들이 둥글게 서 있고, 그 중심에는 추모의 돌이 있다. 이것은 오크가 골드샤이어와 주변 땅을 약탈하고 불태웠던 1차 대전쟁의 망자들을 기린다.\n\n이제는 변절한 마법사들이 섬을 차지하고 있다. 돌들 사이에는 쓰러진 자리에 그대로 남겨진 헨즈 폴크의 시신이 놓여 있다.",
	["s:1429:jasperlode mine"] = "석영 광산은 한때 스톰윈드의 대장간을 먹여 살렸다. 도시가 전쟁에 필요로 하던 원광을 대던 엘윈 숲의 여러 채굴지 가운데 하나였다. 그 일은 이제 끝났다. 코볼트들이 굴을 점령했고, 더 심각한 위협들에 병력이 분산된 스톰윈드 군에는 그들을 뿌리 뽑을 병사가 남아 있지 않다.\n\n아래에 있는 위험은 코볼트만이 아니다. 광산 가장 깊숙한 곳에는 광산 거미 무리가 자리를 잡았는데, 그들에게 코볼트는 두려워할 침입자가 아니라 사냥할 먹잇감이다. 그들의 여왕 어미 송곳니는 어둠 속에 웅크린 채 둥지를 침범하는 것을 결코 용납하지 않는다.",
	["s:1429:jerods landing"] = "제로드 선착장은 나즈페리티 강의 엘윈 숲 쪽 강둑에 있는 나루터이다. 데피아스 단이 이곳을 차지했고, 부두 관리인과 그의 부하들은 이곳을 이용해 훔친 물건을 붉은마루 산맥에서 서부 몰락지대의 클라벤의 탑으로 밀수한다.",
	["s:1429:maclure vineyards"] = "맥클루어 포도밭은 엘윈 숲 남부에 있으며, 맥클루어 가족이 포도나무와 흙으로 이어진 긴 이랑을 가꾼다. 맥클루어 가족은 이웃 스톤필드 가족과 쓰라린 앙숙 관계로, 다른 것은 몰라도 반감만큼은 서로 아낌없이 주고받는다. 그런데 맥클루어 가의 아이 하나와 스톤필드 가의 아이 하나가 두 가문이 지켜 온 모든 것을 거슬러 서로 사랑에 빠졌고, 어떤 이들은 그 사랑이 여러 세대에 걸친 악연이 고치지 못한 것을 고쳐 주기를 바란다.",
	["s:1429:mirror lake"] = "거울 호수는 엘윈 숲 서부에 작고 고요하게 자리하며, 그 폭포는 근처 과수원 곁으로 반짝이며 쏟아진다. 헤엄치거나 낚시하기에 딱 좋아 보이는 곳이다. 하지만 이제는 그리 간단하지 않다. 데피아스 도적들이 주변 숲에 자리를 잡았고, 쉼터여야 할 곳은 조심해서 건너야 하는 곳이 되었다.",
	["s:1429:mirror lake orchard"] = "거울 호수 과수원은 거울 호수의 남쪽 기슭에 있으며, 늘어선 나무들과 오두막 한 채가 엘윈 숲 서부의 들판 사이에 서 있다. 한때 데피아스 도적들이 과수원과 그 옆의 오두막을 차지해 제 것처럼 썼는데, 과수원의 진짜 주인들이 그들에게 쫓겨났는지는 누구도 확실히 말할 수 없다.",
	["s:1429:northshire abbey"] = "노스샤이어 수도원은 엘윈 숲 기슭의, 그 이름을 딴 계곡에 자리하고 있다. 본당과 무기의 전당, 도서관 동이 서 있는 이곳은 성스러운 빛의 교회 사제들이 로데론에서 남쪽으로 내려와 처음 정착한 곳이다. 노스샤이어 사제들의 성스러운 교단은 이곳에서 스톰윈드에 위안과 지혜를 전했고, 티리스팔의 수호자 메디브가 기나긴 혼수상태에 빠져 있던 여러 해 동안 보살핌을 받은 곳도 바로 이 벽 안이었다.\n\n수도원은 1차 대전쟁을 무사히 넘기지 못했다. 수도원장은 노스샤이어의 사제들을 스톰윈드 방어에 내주었고, 반오크 가로나가 포로로 이곳에 끌려온 지 얼마 지나지 않아 오크들이 노스샤이어를 휩쓸고 불태워 폐허로 만들었다. 피난민들은 로데론으로 달아났지만, 그 전에 잔해 속에서 신성한 서적들을 건져 냈다. 훗날 달라란의 마법사들에게 투명화의 기술을 가르쳐 준 책들이다.\n\n폐허가 된 터는 비어 있지 않았다. 2차 대전쟁 동안 초갈의 황혼의 망치 부족이 이곳을 본부로 삼았지만, 얼라이언스가 엘윈 숲을 되찾자 대주교 알론서스 파올이 돌 하나하나 수도원을 재건하고 그 전당에서 노스샤이어 형제단을 세웠다.",
	["s:1429:northshire valley"] = "노스샤이어 계곡은 한쪽을 제외한 사방이 막혀 있다. 산들은 뚫을 수 없고, 남쪽의 유일한 통로는 두꺼운 돌벽과 경비가 선 문 뒤에 봉해져 있다. 강이 그 고요 속을 가르며 수도원과 포도밭 이랑을 지나 수정 호수로 굽이져 내려가고, 이곳에 평화로운 분위기를 더한다.\n\n그 평화가 늘 확실했던 것은 아니다. 2차 대전쟁 동안 노스샤이어 수도원은 굴단의 대의를 따르는 초갈의 황혼의 망치 부족의 본부였고, 그 벽은 수련사와 농부 대신 오크의 전쟁 회의를 품었다.\n\n이제 원수 맥브라이드가 수도원 수비대를 지휘하며 노스샤이어 전체의 안전을 책임지지만, 그의 감시 아래에서도 계곡이 완전히 평온한 것은 아니다. 누구도 설명할 수 없을 만큼 많은 늑대가 그늘숲에서 밀려들고, 코볼트들은 메아리 광산을 파고든다.",
	["s:1429:northshire vineyards"] = "포도밭은 수도원 동쪽으로 펼쳐져 있으며, 데피아스 단이 땅을 차지하기 전까지는 수확을 위해 가꾸어졌다. 개릭 패드풋이 그곳을 장악한 요원들을 이끌며 이랑을 데피아스 하수인들의 발판으로 삼았고, 그들은 밀리 오스워스의 물건을 훔쳐 갔다.",
	["s:1429:ridgepoint tower"] = "마루목 감시탑은 엘윈 숲의 경계를 지키는 스톰윈드 경비대의 정찰탑 가운데 하나이다. 그곳의 보초들은 놀과 오크가 모이는 붉은마루로, 망자가 묻힌 채로 있지 않는 그늘숲으로, 그리고 근처의 데피아스 야영지로 눈을 돌린다. 수비대는 그 셋 모두에 맞서 튼튼히 방어를 갖추고 있다.",
	["s:1429:stone cairn lake"] = "돌무덤 호수라는 이름은 호수 한가운데 섬에 세운 돌무덤, 수호영웅의 안식처에서 왔다. 오크와의 1차 대전쟁 때 너무나 많은 이가 쓰러져 어떤 무덤도 그들의 기억을 다 담을 수 없었기에, 그 망자들을 기리려고 세운 것이다. 이곳은 한때 조용한 순례지였다.\n\n그 평화는 사라졌다. 변절한 마법사들이 섬을 차지했고, 애도를 위해 세운 돌무덤은 이제 그들 뒤에 서 있다. 남쪽 기슭에는 멀록 부족이 물 건너의 기념비에는 아랑곳없이 투박한 거처를 세웠다.",
	["s:1429:stonefield farm"] = "스톤필드 농장은 엘윈 숲 남부에 있으며, 근처의 맥클루어 가족과 쓰라린 앙숙 관계인 스톤필드 가족이 일군다. 그런데 두 집안의 아이가 하나씩 두 가문 사이의 오랜 원한을 거슬러 사랑에 빠졌다. 어떤 이들은 여러 해의 다툼이 결코 해내지 못한 일을 그 사랑이 해내어, 반목이 부순 것을 고쳐 주기를 바란다.",
	["s:1429:stormwind city"] = "오크 호드가 불태운 뒤, 스톰윈드는 젊은 바리안 왕의 치세 아래 석공 조합의 손으로 하얀 돌의 도시로 다시 일어섰다. 그러나 전쟁 빚으로 왕실 금고가 바닥나고 귀족들이 조합에 품삯을 주지 않자, 조합장 에드윈 밴클리프의 항의에 돌아온 것은 조합의 해산이었다. 폭동이 뒤따랐고, 그 혼란 속에서 티핀 린 왕비가 목숨을 잃었다. 바리안의 분노는 석공들을 서부 몰락지대로 내쫓았고, 그들은 그곳에서 데피아스 단이 되었다. 그동안 왕좌 뒤에서는 카트라나 프레스터라는 고문이 자신의 목적을 위해 은밀히 왕과 조합을 이간질했고, 그 뒤로 여러 해 동안 정치와 마법을 이용해 그를 앞질렀다.",
	["s:1429:thunder falls"] = "거울 호수의 폭포에서 올라가는 길은 가파르고 좁게 산속으로 이어지다가 천둥 폭포에서 열린다. 양쪽 끝에 모두 폭포가 떨어지는, 엘윈 숲의 다른 협곡과는 다른 곳이다. 북쪽 절벽에서는 세 번째 폭포가 쏟아져 내려 위에서 협곡을 채운다. 비탈 아래에는 모루와 불을 늘 지펴 둔 작은 시골 오두막이 서 있고, 집 옆 강가에는 작은 부두와 배가 놓여 있다. 오두막 근처에는 도적들이 서성인다. 강은 서부 몰락지대 가장자리 근처에서 두 번째 폭포를 지나 계속 흘러간다. 이 물에서 헤엄치는 보라농어는 이곳만큼 쉽게 볼 수 있는 곳이 없다고 한다.",
	["s:1429:tower of azora"] = "아조라의 탑은 엘윈 숲 중부의 들판 한가운데 솟아 있으며, 대마법사 테오크리투스를 섬기는 노움 하인들이 머무는 곳이다.\n\n멀리 붉은마루 산맥에는 그 경쟁자인 일갈라의 탑이 서 있으며, 마법사 모간스가 다스린다. 두 탑은 공공연히 전쟁을 벌인 적은 없지만, 마법으로 서로를 끊임없이 감시하며 저마다 상대의 실수를 잡아내기를 기다린다.\n\n탑의 마법은 주변 들판으로 흘러넘쳐, 너무 가까이 머무는 것은 무엇이든 그것에 닿아 원래보다 기이한 무언가로 변할 수 있다. 하인들은 이 작지만 끊임없는 골칫거리로부터 탑을 돌보면서도, 한쪽 눈은 늘 붉은마루를 향하고 있다.",
	["s:1429:westbrook garrison"] = "서부 주둔지는 엘윈 숲 서쪽 끝, 나무들이 더 척박한 서부 몰락지대의 땅으로 바뀌는 곳에 서 있으며, 스톰윈드 경비대에게는 언제나 외로운 근무지였다.\n\n가장 힘든 시절은 카트라나 프레스터 부인의 타락이 왕국을 무겁게 짓누르고 스톰윈드 군 주력이 다른 곳에 투입되어 있던 때였다. 내줄 병사가 너무 적은 탓에 서부 몰락지대의 놀과 도적들은 철마다 숲을 더 거세게 압박했고, 수비대는 간신히 길의 안전을 지켜 냈다.\n\n놀들 가운데 강발톱 부족장 호거는 공포의 이름이 되었다. 그는 자신을 사로잡으려는 모든 시도를 힘으로 꺾었고, 그의 이름을 적은 현상 수배 전단은 아직도 해결되지 못한 채 주둔지 문에 걸려 있다.",
	["s:1430:aridens camp"] = "이 야영지는 죽음의 고개를 지나는 길 북쪽에 버려져 있으며, 늘 어두운 나무들 아래에 식은 모닥불 자리와 빈 침낭들만 흩어져 있다. 아리덴은 저주받기 전 한때 이곳에 야영지를 차리고 어둠의 기수단을 이끌었으며, 이곳에서 메디브의 것이었다고 주장하는 가짜 유물을 팔아 치우려 했다. 이제는 야영지 자리 말고 아무것도 남아 있지 않다.",
	["s:1430:deadmans crossing"] = "갈림길에는 교수대 나무가 서 있고, 그 가지에는 아직도 시체 두 구가 흔들리고 있다. 그 곁의 표지판에는 두 가지 경고가 적혀 있다. “돌아가라!” 그리고 “여기 들어오는 자여, 모든 희망을 버려라.”\n\n이곳에서 서쪽 길은 그늘숲으로, 동쪽 길은 슬픔의 늪으로, 남쪽 길은 카라잔이 서 있는 죽음의 고개로 이어진다. 교수대와 경고문은 갈림길에서 벗어나 그 너머 고개로 들어가고 싶은 유혹을 느끼는 모든 이를 위해 세워졌다.",
	["s:1430:deadwind ravine"] = "이 협곡은 산맥 사이로 험준한 틈을 가르며, 서쪽 길은 위쪽 층을 따라 카라잔으로 이어지고 그 끝에는 탑의 실루엣이 불길하게 기다리고 있다. 협곡의 끝에는 탑에 이르기 전의 마지막 건널목인 남쪽 다리가 놓여 있다.",
	["s:1430:groshgok compound"] = "죽음의 고개 오우거들은 악의 소굴에 쌓아 올린 흙과 돌의 언덕, 그로쉬고크 주둔지를 자기들 것이라 주장한다. 그 일대의 땅을 곰보처럼 파고든 동굴들 가운데 이곳이 가장 남쪽에 있으며, 크기에서 이곳에 견줄 만한 동굴은 없다.",
	["s:1430:karazhan"] = "카라잔은 죽음의 고개 남쪽에 버려진 채 서 있으며, 지맥들이 교차하는 결절점 위에 세워졌다. 이 탑은 마지막 거주자였던 티리스팔의 마지막 수호자 메디브로 가장 잘 알려져 있다. 메디브가 카드가와 안두인 로서, 가로나에게 살해당한 뒤 탑은 스스로 세상과 문을 닫았다. 그러나 최근 카라잔이 다시 꿈틀대고 있다. 사악한 존재가 탑을 차지했고, 그 전당에는 영혼과 악마가 들끓으며, 메디브의 망령은 아직도 머물고 있다. 그의 힘이 워낙 강대해 그의 마법은 지금도 탑 안에 메아리친다.\n\n카라잔을 바라보면서 그 주인의 어두운 이야기를 떠올리지 않기란 불가능하다. 그 칭호에 걸맞게, 티리스팔의 마지막 수호자는 키린 토의 것조차 초라하게 만들 만큼 방대한 저술과 유물을 모아 두었다. 탑은 거대하고 위험하며, 그 전당에는 유령들이 가득하다.",
	["s:1430:masters cellar"] = "카라잔 남쪽, 한때 탑의 하인들이 살던 폐허가 된 마을 아래로는 더 이상 산 자의 것이 아닌 지하실들이 열려 있다. 내려가는 입구는 둘이다. 하나는 거대한 포도주 저장고로 이어지는데, 그 선반과 술통은 오래전에 망자들에게 버려졌다. 다른 하나는 바닥이 완전히 꺼져 땅속 깊이 뻗은 동굴로 무너져 내린 두 번째 지하실로 떨어진다.\n\n두 곳 모두 안식하지 못하는 것들로 가득하다. 주인 없는 집을 여전히 돌보는 듯한 죽지 않은 관리인들, 저주받은 영혼들, 가라앉지 않는 망령들, 그리고 부서진 돌 틈으로 울부짖음이 올라오는 유령들이다. 살아생전 그들을 카라잔에 묶어 두었던 섬김이 무엇이었든, 그것은 뒤틀려 죽어서도 그들을 떠나지 못하게 하는 무언가가 되었다.\n\n망자들 가운데 따로 눈에 띄는 것을 품은 곳은 포도주 저장고뿐이다. 고요하고 어둠에 잠긴 아래쪽 동굴에는 똑같이 안식하지 못하는 망자들 말고는 아무것도 없다. 이름 붙은 것도, 누군가 기억할 만하다고 여긴 것도 없다.",
	["s:1430:morgans plot"] = "카라잔 뒤편에는 작고 낡은 교회가 서 있으며, 그 묘지와 납골당은 죽음의 고개의 어둠 속에 잠겨 있다. 이 예배당은 오래전부터 편히 잠들지 못하는 것들을 품어 왔고, 바로 아래 언덕에는 또 다른 무언가가 아직도 순찰을 돈다.\n\n망자를 위해 마련된 곳이 그토록 자주 망자를 붙잡아 두지 못한다는 것은, 그 뒤에 무엇이 있는지를 말해 준다.",
	["s:1430:sleeping gorge"] = "수면의 협곡은 죽음의 고개 동부를 가로지르는 작은 틈으로, 남쪽으로 카라잔에 다가가는 여행자는 길이 동쪽의 악의 소굴로 꺾이기 전에 이곳을 지나야 한다.",
	["s:1430:vice"] = "악의 소굴은 카라잔으로 가는 길의 남쪽 구간을 따라 펼쳐져 있으며, 죽음의 고개 오우거들이 바위산 사이에 흙더미 소굴과 야영지를 세운 곳이다. 황량한 땅으로, 안식하지 못하는 영혼들과 그 위를 맴도는 독수리들 말고는 사는 것이 거의 없다. 오우거들이 왜 이토록 텅 비고 불길한 곳에 뿌리를 내렸는지는, 이곳을 본 누구도 알지 못한다.",
	["s:1431:addles stead"] = "에이들의 은신처는 그늘숲 남서쪽의 들판 사이에 버려져 있으며, 어둠이 땅을 덮쳤을 때 썩도록 버려진 수많은 농가 가운데 하나이다. 헛간은 텅 비었고 농가는 고요하며, 이제는 쓸쓸한 영혼들만이 머물고 있다. 한때 이곳을 차지했던 데피아스 단원들의 망령이라고 한다.\n\n데피아스 단은 에이들의 은신처를 통째로 차지하고, 웃자란 밭을 기어 다니고, 헛간에 숨고, 농가의 방들을 몰래 누볐다.",
	["s:1431:beggars haunt"] = "부랑자 소굴이라 불리는 탑은 미스트맨틀 장원 북동쪽, 죽음의 고개로 들어가는 길 위에 버려진 채 서 있다. 스톰윈드 경비대의 정찰 초소로 세워졌던 이 탑은 이제 포세이큰이 쓰고 있으며, 죽음추적자 즈레이더스와 약제사 파우스틴이 그 안에서 실험을 한다.\n\n길은 폭포가 채우는 작은 웅덩이로 굽어 내려가는데, 그곳에는 어둠의 문에 있는 것과 같은 모양으로 깎은 거대한 석상 둘 아래 표식 없는 무덤이 하나 있다. 탑 근처에는 또 다른 작은 묘지가 있어, 무명용사의 무덤을 품고 있다.",
	["s:1431:brightwood grove"] = "밝은숲은 다크샤이어 바로 서쪽에 있으며, 몇 안 되는 건물은 오래전에 폐허가 되었다. 이곳에 남은 것은 이제 밤의 파멸 늑대인간의 차지이다. 그들은 무리 지어 어두운 들판을 어슬렁거리고, 잔해 사이에 투박한 야영지를 세우며, 너무 가까이 다가오는 자는 누구든 덮친다.",
	["s:1431:darkened bank"] = "어스름 강둑은 그늘숲의 북쪽 기슭을 따라, 서쪽 끝에서 동쪽으로 붉은마루와 이어지는 다리까지 뻗어 있다. 서쪽 끝에는 피난민 스벤 요르겐과 라스가 몸을 피한 작은 야영지가 있다. 그들은 그늘숲의 나머지 땅을 지킬 수 없을 만큼 위험하게 만든 무언가에 쫓겨 물가까지 밀려났다.",
	["s:1431:darkshire"] = "다크샤이어가 처음부터 그렇게 불린 것은 아니다. 오래전 이곳은 스톰윈드 백성이 근처 땅으로 퍼져 나가면서 세운 작은 숲속 마을, 그랜드 햄릿으로 시작되었다. 그러나 땅 자체는 카라잔에서 일어난 일에서 끝내 회복되지 못했다. 수호자 메디브가 그곳 탑에서 살해당했을 때, 그의 죽음으로 풀려난 지옥의 기운이 주변 숲으로 스며들어 지금처럼 가시투성이에 빛 한 줄기 없는 곳으로 뒤틀어 놓았다. 밝은숲은 그늘숲이 되었고, 그랜드 햄릿은 더 진실한 이름인 다크샤이어를 얻었다.\n\n마을의 민병대인 밤의 감시단이 존재하는 것은 스톰윈드가 이곳을 버렸기 때문이다. 스톰윈드에서 카트라나 프레스터 부인의 음모로 왕국의 수비대가 숲에서 빠져나가자, 마을 사람들은 결코 오지 않을 병사들을 기다리는 대신 스스로 무장했다. 오로지 숲의 사람들로 조직되고 훈련된 그들은 그 뒤로 기댈 곳이라고는 자신들뿐인 채 늑대와 걸어 다니는 시체, 그리고 더 끔찍한 것들로부터 길을 지켜 왔다.",
	["s:1431:dawning wood catacombs"] = "까마귀 언덕 묘지 아래로 땅이 열려 새벽숲 지하묘지가 펼쳐진다. 너무 깊이 뒤얽힌 굴의 미로라, 홀로 들어간 이 가운데 다시 나오는 이는 드물다. 내려가는 길은 둘이다. 동쪽 통로는 병들고 사나운 구울들의 소굴로 이어진다. 서쪽 통로는 해골들의 전당으로 이어지는데, 그들은 한때 자신들이었던 망자의 무덤을 지키며 서 있다.",
	["s:1431:forlorn rowe"] = "까마귀 언덕 묘지 북쪽 끝의 언덕인 버려진 흉가는 주변 나무의 그림자보다 더 짙게 들러붙는 어둠에 싸여 있다. 이곳에는 사악한 비전 마법으로 숲의 언데드를 제 뜻대로 부리는 강령술사 모벤트 펠의 집이 서 있다. 그를 잠재울 수 있는 것은 오직 위대한 힘을 지닌 단 하나의 무기뿐이다.",
	["s:1431:hushed bank"] = "고요의 강둑은 그늘숲 서쪽의 강을 따라, 서부 몰락지대와 엘윈 숲, 그늘숲이 만나는 곳에서 남쪽으로 가시덤불 골짜기를 향해 이어진다. 이곳에는 지붕 덮인 다리가 강을 건너 그늘숲과 서부 몰락지대를 잇는다.\n\n강둑의 북쪽 모퉁이에는 라스와 스벤 요르겐 형제가 야영지를 두고 있다.\n\n늑대와 거미들이 나무 사이로 강둑을 누빈다.",
	["s:1431:manor mistmantle"] = "미스트맨틀 장원은 그늘숲 북동쪽에 서 있으며, 그 땅은 썩었고 정원은 폐허가 되었다. 이곳은 한때 교사이자 가정교사였다가 언데드의 하수인이 된 스탈반 미스트맨틀의 집이었고, 그는 자기 대신 구울들이 집 안팎을 비틀거리며 돌아다니게 두었다. 타락 한가운데서도 단 하나가 여전히 자란다. 틸로아의 눈물이라 불리는 꽃 한 송이로, 썩음에 넘어간 정원에 남은 유일한 생명의 흔적이다.",
	["s:1431:raven hill"] = "까마귀 언덕의 집들은 그늘숲 서부에 텅 빈 채 썩음과 어둠에 내맡겨져 있다. 그래도 몇몇은 버텼다. 지터스, 그리고 위층에 숨어 지내던 고블린 블리즈틱이다.\n\n마을에는 보이지 않는 자들이 출몰한다. 이름만이 아니라 정말로 보이지 않는 그들이 빈 방들 사이를 움직인다.",
	["s:1431:raven hill cemetery"] = "까마귀 언덕 묘지는 그 이름을 준 마을의 북쪽에 넓게 펼쳐져 있으며, 그늘숲의 타락이 뿌리내린 뒤로 옛 경계를 훨씬 넘어 커졌다. 이제 비석 사이로 언데드가 걸어 다니고, 거대한 거미와 도굴꾼 무리가 아무 방해 없이 무덤을 파헤치며 그들의 일에 끼어드는 자는 누구든 쫓아낸다.\n\n묘지 북서쪽 구석에는 강령술사 모벤트 펠의 집인 버려진 흉가가 서 있으며, 그의 어둠의 작업이 묘지의 망자들을 뒤흔든다.\n\n그 이름, 래디모어는 묘지의 가장 오래된 슬픔을 새기고 있다. 모건 래디모어는 3차 대전쟁에서 돌아와 아내와 아이들이 이미 이곳에 묻혀 있는 것을 보았다. 슬픔은 그를 무너뜨렸고, 그는 그들의 무덤 위에서 묘지 관리인 셋을 살해했다. 이제 언데드가 된 모르라딤이 묘지를 순찰하며, 비석 사이에서 방심한 자를 발견하면 죽음이 빠르고 보이지 않게 찾아온다.",
	["s:1431:rolands doom"] = "롤랜드 광산은 그늘숲 남동쪽, 오염된 과수원 동쪽에 있는 광산이다. 나이트 엘프 여사제 벨린데 스타송은 사라지기 전 엘룬의 낫을 이 언덕으로 가져왔고, 그 유물은 광산에서 잃어버렸다. 지터스라는 사내가 그곳에서 그것을 찾아냈고, 그 발견은 더 많은 늑대인간을 그늘숲과 다크샤이어로 불러들였다.\n\n광산은 이제 밤의 파멸 무리의 거트스필과 네파루의 차지이며, 그들의 늑대인간은 오염된 과수원까지 누빈다.",
	["s:1431:rotting orchard"] = "과수원은 그늘숲 남부에 있으며, 나무들은 썩어 검게 변했고 건물들은 요르겐 농장과 고요의 정원 묘지 사이에서 폐허로 무너졌다.\n\n밤의 파멸 무리의 늑대인간들이 이곳을 차지했다. 그림자술사들은 폐허가 된 건물 사이에서 마법을 부리고, 추적자들은 나무 사이의 어둠 속에서 보이지 않게 기다린다.\n\n지금 이곳에 서는 것은 농장이기를 멈추고 사냥터가 된 곳에 서는 것이다.",
	["s:1431:tranquil gardens cemetery"] = "고요의 정원 묘지는 다크샤이어 남동쪽에 있으며, 그 이름은 이제 씁쓸한 농담이 되었다. 이곳의 망자들은 안식하지 못한다. 그늘숲의 다른 곳에 있는 언데드보다는 약하지만, 비석 사이와 묘지 한가운데의 무너진 교회 사이를 떠돈다. 미친 구울이 이 땅에 출몰하는데, 때로는 부서진 교회 안에, 때로는 무덤 사이에 있다. 바로 북쪽에는 눈먼 메리의 집이 서 있다.",
	["s:1431:twilight grove"] = "그늘숲 깊은 곳, 황혼의 숲 한가운데에는 이름 없는 거대한 나무 한 그루가 달샘과 오래된 나이트 엘프 정자 곁에 서 있다. 그 가지 아래에는 에메랄드의 꿈으로 들어가는 단 네 개의 차원문 가운데 하나가 있으며, 페랄라스와 동부 내륙지, 잿빛 골짜기에 숨겨진 차원문들과 자매를 이룬다.\n\n숲의 차원문은 무방비로 남겨지지 않았다. 꿈의 위상 이세라의 자랑스러운 부관이었던 거대한 용 넷이 그녀가 택한 꿈의 수호자로서 이곳을 지켰다. 그러나 에메랄드의 악몽이 그들마저 타락시켜 수호자를 오직 죽음만을 바라는 파괴자로 뒤틀었고, 한때 이곳을 지키던 바로 그 용들에 맞서 무기를 드는 일은 얼라이언스와 호드 모두의 몫이 되었다.",
	["s:1431:vulgol ogre mound"] = "그늘숲 남부는 가시덤불 골짜기로 향하는 길이 갈라지는 작은 분지로 움푹 꺼지는데, 오우거가 오기 전에는 그곳에 농가들이 서 있었다. 이제는 부서진주먹 오우거가 이곳을 차지하고 있으며, 소굴 안에서 이곳을 다스리는 그들의 우두머리 즈자르크불의 이름을 따서 불린다.\n\n폐허가 된 농가들만이 오우거가 분지를 차지하기 전 이곳에 사람이 살았음을 보여 준다. 그 가족들이 어떻게 되었든, 오우거는 무너진 벽 말고는 아무것도 남기지 않았다.\n\n밤의 감시단은 이곳에 병력을 내주지 않는다. 그늘숲을 압박하는 다른 위협들보다 이곳의 위협이 덜 급하다고 보기 때문이며, 그래서 필요할 때 오우거의 수를 줄이는 일은 외부인의 몫으로 남았다. 오우거의 약탈품 가운데에는 강령술사 애버크롬비를 덮친 뒤 소굴로 가져간, 그에게서 훔친 도구와 약초 상자도 있었다. 그리고 즈자르크불 자신은 한 연구자가 연구를 위해 탐내던 외알 안경을 끼고 있는데, 잔혹한 괴물에게 어울리지 않는 작은 허영이다.",
	["s:1431:yorgen farmstead"] = "요르겐 농장은 그늘숲 남부에 버려져 있으며, 밭은 썩어 버렸다. 스벤 요르겐은 한때 이 땅을 일구었지만, 지금은 어스름 강둑의 작은 야영지에 머물고 있다. 농장 자체는 그 뒤로 데피아스 단의 손에 넘어갔고, 그들의 암살자들은 보이지 않게 밭을 누비다가 이미 늦었을 때에야 덮친다.",
	["s:1432:algaz station"] = "알가즈 주둔지는 북부 관문 통행로 동쪽에 서 있으며, 북쪽의 던 알가즈에서 이름을 따왔다. 이곳에서는 드워프 산악병들이 감시를 서는데, 산악병 스톰파이크도 그중 하나이며, 방어구 제작자 고소르 브룸이 그들의 장비를 손본다.",
	["s:1432:dun algaz"] = "던 알가즈를 지나는 굴은 드워프를 갈라놓은 다툼보다도 오래되었다. 세 망치의 전쟁으로 와일드해머 부족이 아이언포지에서 쫓겨났을 때, 그들이 퇴각한 길이 바로 이 고개였다.\n\n이 고개는 호드의 퇴각로이기도 했다. 던 모드르에서 밀려난 오크들은 탄돌 골짜기를 건너 남쪽으로 물러나 이곳의 전초기지에 버텼고, 그들을 카즈 모단에서 완전히 몰아내고자 한 안두인 로서는 군대를 보내 그 요새를 무너뜨리려 했다. 공격은 실패했다. 오크들은 버텼고, 던 알가즈는 호드가 이 지역에서 지켜 낸 마지막 땅, 뽑히지 않는 발판이 되었다.\n\n이 고개를 지키던 드워프 산악병들은 주로 그 위의 언덕에 머물렀지만, 용아귀 부족이 그들의 초소를 점령해 위쪽 굴로 몰아냈고, 그들은 지금도 그곳에서 버티고 있다. 아래쪽 고개를 잃으면서, 드워프의 고향과 메네실 항구 사이의 길은 훨씬 더 위험해졌다.",
	["s:1432:farstrider lodge"] = "순찰자의 오두막은 모단 호수 남동쪽에 서 있으며, 그 건축은 틀림없는 하이 엘프 양식이지만 그 전당에 남은 하이 엘프는 단 하나뿐이다. 그 뒤로 인간과 드워프가 그곳에 자리를 잡았는데, 그중에는 사냥꾼들도 있다. 그들은 오래전에 이곳을 떠난 손들이 세운 벽 안에서 살아가고 있다.",
	["s:1432:grizzlepaw ridge"] = "곰발바닥 마루는 텔사마 남쪽에 솟아 있으며, 높은 곳을 제 땅으로 삼은 곰들이 가득하다. 그중 으뜸은 무시무시한 덩치와 성질을 지닌 곰, 늙은 검댕이이다. 그는 굴에서 골짜기 아래까지 어슬렁어슬렁 내려오며, 운 나쁘게 자신의 심기를 건드린 자에게는 누구든 재빨리 덤벼든다.\n\n고릭 거즐드라우트도 이 마루에 머물고 있다.",
	["s:1432:ironbands excavation site"] = "아이언밴드의 발굴현장은 모단 호수 남동쪽에 있는 드워프 발굴지로, 탐사꾼 아이언밴드가 고대인들이 묻어 둔 것을 찾으려고 열었다. 그러나 땅은 유물 이상의 것을 내놓았다. 다른 드워프 발굴지에서 볼 수 있는 것보다 더 크고 더 난폭한 트로그들이 아래에서 올라와 발굴지를 점령하고, 그곳을 연 탐사꾼과 광부들을 몰아냈다.",
	["s:1432:loch"] = "대호수는 모단 호수의 심장부를 채우고 있다. 카즈 모단 전체에서 가장 큰 호수이며, 알려진 세계 전체에서는 로다미어와 다로미어 다음으로 세 번째로 크다.",
	["s:1432:mogrosh stronghold"] = "모그로쉬 소굴의 동굴들은 모단 호수 북동쪽에 있으며, 오우거 부족의 보금자리이다. 그들의 암흑망치와 대지술사들은 오직 자기 족속에게만 따른다.",
	["s:1432:north gate pass"] = "이 통행로는 높은 산맥을 가로질러 던 모로에서 모단 호수 쪽으로 내려간다. 두 곳 사이의 가장 짧은 길이라, 호수 너머의 땅으로 향하는 여행자들은 다른 어떤 길보다 이곳을 많이 지난다.\n\n북부 관문 전초기지가 이곳에서 통행로를 지키고 있다.",
	["s:1432:silver stream mine"] = "은여울 광산에는 한때 은이 풍부하게 흘렀고, 여러 세대 동안 아이언포지의 드워프들은 그 광맥에서 부를 끌어냈다. 광석이 바닥나자 광부 조합은 굴을 버리는 대신 저장고로 바꾸었다.\n\n광산에는 아직 가져갈 만한 것이 하나 있다. 다른 어디에서도 찾을 수 없는 충전된 균열 보석으로, 마법사 로브를 만드는 데 귀하게 쓰인다.\n\n그러나 이제 이 굴은 드워프의 것이 아니다. 굴쥐 코볼트들이 남은 자원을 차지하려고 광산을 점령했다.",
	["s:1432:south gate outpost"] = "남부 관문 전초기지는 던 모로와 모단 호수 사이의 고개가 좁아지는 곳에 자리한 바위 길목으로, 드워프 산악병들이 지키고 있다. 그들의 일은 북부 관문의 동족보다 조용하다. 그들은 한때 고개를 압박하던 야생 동물을 몰아냈고, 그 길은 텔사마를 오가는 이들에게 열린 채 안전하게 유지되고 있다.",
	["s:1432:south gate pass"] = "남부 관문 통행로는 산맥을 가로질러 던 모로의 높은 설원과 모단 호수의 낮은 골짜기를 잇는다. 텔사마로 내려가는 가장 짧은 길로, 두 땅을 오가는 여행자들의 발길에 닳아 있다.\n\n이곳에는 고개를 감시하기 위해 세운 경비 초소, 남부 관문 전초기지가 서 있다.",
	["s:1432:stonesplinter valley"] = "가루바위 골짜기는 모단 호수 남서쪽의 산들 사이로 파고들어 있다. 한때 깨끗했던 이곳은 이제 가루바위 트로그의 차지가 되어, 그들이 골짜기 바닥과 비탈을 점령했다. 모단 호수의 드워프들은 그들을 솎아 내야 할 해충으로 여긴다. 골짜기 가장 깊은 곳에는 트로그들이 따르는 우두머리 그로머그가 산다.",
	["s:1432:stonewrought dam"] = "돌다지 댐은 던 알가즈 고개 동쪽, 모단 호수의 북쪽 끝을 따라 솟아 있다.\n\n댐을 지은 이는 검은무쇠 드워프였다. 그 부족의 건축가 프랜클론 포지라이트가 댐을 쌓아 올린 돌다지 공법을 고안했지만, 댐을 건너는 이들 가운데 그것을 검은무쇠 드워프의 손이 지었다는 사실을 아는 이는 드물다.\n\n댐은 호수를 가두어 전보다 두 배 넘게 불렸고, 그로 인한 범람이 한때 대부분 물속에 잠겨 있던 그 너머의 땅을 저습지로 만들었다.\n\n검은무쇠 부족이 댐을 공격하자 아이언포지는 감시를 강화하는 것으로 응수했다. 지금은 수석 기술자 힌더위어 7세가 그 임무를 맡고 있다.",
	["s:1432:stoutlager inn"] = "스타우트라거 여관은 텔사마에 있으며, 그 화로는 좀처럼 식지 않는다. 드워프와 여행자 모두 이곳에 모여 술을 마시며 호수 소식을 나누고, 이 지역에서 이만큼 꾸준히 손님이 드나드는 곳은 드물다.",
	["s:1432:thelsamar"] = "텔사마는 모단 호수의 서쪽 기슭, 곰발바닥 마루 북쪽이자 가루바위 골짜기 북동쪽에 자리한다. 마을 바로 서쪽으로 길이 지나며, 던 모로와 저습지를 향해 고개를 넘어 올라간다. 그리핀들이 그 둥지에 깃들고, 여관은 고지대를 건너는 여행자들에게 쉴 곳을 내준다.",
	["s:1432:valley of kings"] = "왕의 계곡은 모단 호수의 남서쪽 끝에 있으며, 이곳에서 푸른 땅은 검게 그을린 이글거리는 협곡으로 내려가는 문을 향해 좁아진다. 그 문은 잠긴 채 감시받고 있으며, 산악병 페블비티가 지키고 서서 자격을 증명한 이에게만 길을 내준다.\n\n이곳에서 눈길을 끄는 것은 고개 위로 솟은 두 거대한 석상, 마도란 브론즈비어드와 카드로스 와일드해머이다. 그들은 남쪽 길을 지키도록 돌로 새겨졌다. 두 왕이 죽자, 그 아들들이 함께 석상을 세워 아버지들이 살아생전 그러했듯 브론즈비어드와 와일드해머를 돌 속에 하나로 묶었다. 그 너머 남쪽 땅은 라그나로스에 의해 불과 재로 변했고, 석상은 그 폐허를 정면으로 마주하고 있다. 드워프 왕국들에 맞서려는 자에게는 경고이자, 검은무쇠 부족이 저지른 일로 치른 대가를 일깨우는 표지이다.",
	["s:1433:althers mill"] = "레이크샤이어 북동쪽의 제재소는 물레바퀴가 멈춘 지 오래되어 텅 비어 있다. 이곳은 돌망루 요새로 가는 길의 경유지에 불과했으며, 그 폐허에는 거미와 대머리수리, 그리고 이따금 길 잃은 오크가 산다.",
	["s:1433:galardell valley"] = "붉은마루 산맥 북동쪽의 갈라델 골짜기에는 송곳니 부관이 이끄는 놀들이 우글거린다. 그의 울부짖음은 준비 없이 그와 맞선 자에게 무리를 불러 내린다.\n\n골짜기 위로는 사악한 모간스의 거처인 일갈라의 탑이 서 있으며, 그 이름만으로도 이곳이 두려워해야 할 곳임을 알 수 있다.",
	["s:1433:lake everstill"] = "영원의 호수는 붉은마루 산맥의 심장부에 자리하며, 넓고 푸른 그 물은 한적한 마을 레이크샤이어가 존재하는 이유 그 자체이다. 호수는 동쪽으로 흘러나가고, 그 강은 돌망루 요새의 검은 바위를 향해 흘러간다.\n\n한때 이곳은 고요하고 믿음직한 어부의 호수였지만, 그것도 달라졌다. 멀록 부족들이 얕은 물과 깊은 물을 가리지 않고 점령했고, 깊은 물속 어딘가에서는 아직도 탈곡상어 한 마리가 순찰을 도는데, 너무 늙고 거대해서 멀록 부족의 노련한 사냥꾼들조차 멀찍이 피해 다닌다. 영원의 다리는 여전히 멀록 야영지와 아래에서 지켜보는 그것 위로 여행자들을 건네준다.",
	["s:1433:lakeridge highway"] = "호수마루 오솔길은 한때 영원의 호수 남쪽 기슭을 따라 꾸준히 사람들이 오갔지만, 오크가 돌망루 요새를 차지한 뒤로 길은 쓰이지 않게 되었다. 이제 길 대부분에는 놀이 누비고, 더 아래쪽에는 위장한 검은바위 사냥꾼들이 숨어 기다린다. 누구도 이 길로 가라고 권하지 않을 것이다.",
	["s:1433:lakeshire"] = "영원의 호수는 붉은마루 봉우리 아래에 고요하고 차갑게 놓여 있으며, 그 기슭의 마을은 이 땅을 위해 여러 번 피를 흘렸다. 대족장 블랙핸드가 처음 오크를 이끌고 이 산맥으로 들어왔을 때, 안두인 로서 경과 스톰윈드 기사단은 비탈에서 그들을 매복 공격해 거의 무너뜨렸지만, 어둠의 의회 흑마법사 둘이 전세를 뒤집어 로서를 물러나게 했다. 몇 주 뒤 블랙핸드는 더 큰 군세를 이끌고 돌아와 레이크샤이어를 완전히 점령했다. 2차 대전쟁이 끝난 뒤에야 로데론 연합이 마을을 되찾았고, 최고 사령관 투랄리온이 흩어진 주민들의 귀환을 챙겼다.",
	["s:1433:redridge canyons"] = "붉은마루 협곡은 붉은마루 북서쪽을 가르고 있으며, 그 벽 뒤에는 이 땅을 차지한 놀들을 이끄는 요울러의 굴이 숨겨져 있다.",
	["s:1433:renders camp"] = "검은바위 오크는 불타는 평원으로 들어가는 길 가까이, 붉은마루 산맥 북서쪽에 야영지를 두고 있다. 그들은 이곳에서 고개를 감시하며, 주인의 영토로 이어지는 산맥에 바짝 붙은 검은바위 부족의 발판을 지키고 있다.",
	["s:1433:renders rock"] = "약탈의 바위굴은 불타는 평원 근처, 붉은마루 산맥 북서쪽의 넓은 동굴이다. 검은바위 오크가 대군으로 이곳을 지키고 있다.\n\n이곳에는 키샨 상병이 부상을 입고 고립된 채, 살아서 레이크샤이어에 닿아야 하는 처지로 누워 있다.",
	["s:1433:renders valley"] = "약탈의 계곡은 붉은마루 산맥 남동쪽에 있으며, 검은바위 오크의 전초기지가 요새로 커진 곳이다. 탑들이 둘러싸고 정예 전사들이 지킨다.",
	["s:1433:rethban caverns"] = "레스밴 동굴은 붉은마루 산맥 북서쪽 깊숙이 파고들어 있다. 교활한 아르도 더트포가 이끄는 놀들이 굴을 차지하고, 바위에서 캐낸 레스밴 광석을 쌓아 두고 있다. 이 동굴의 이름은 바트 레스밴이라는 사내에게서 왔을지도 모르지만, 그에 대해 기억되는 것은 거의 없다.",
	["s:1433:stonewatch"] = "돌망루 요새는 한때 레이크샤이어 인간들의 것으로, 요새 아래로 폭포가 쏟아지는 절벽에 기대어 세워진 채 불타는 평원의 오크 위협으로부터 붉은마루를 지켜보았다.\n\n그 감시는 배신으로 무너졌다. 흑마법사 모간스는 가스일조그와 그의 검은바위 오크와 동맹을 맺었고, 그들의 연합군은 수비대를 무너뜨릴 만큼 잔혹하게 돌망루 요새를 덮쳤다. 오크들은 요새를 차지했지만, 그 승리의 신의는 오래가지 않았다. 모간스가 자신에게 승리를 안겨 준 동맹에게 등을 돌렸기 때문이다. 그는 자신을 위해 일갈라의 탑을 세우고, 송곳니 부관 휘하의 그늘가죽 놀 무리를 제 목적대로 부렸다. 그 배신 이후로 놀의 길을 가로지르는 오크와 인간 모두가 그 대가를 치렀다.\n\n자신들을 이용한 흑마법사에게 버림받은 검은바위 오크들은 스스로 요새를 지켰고, 가스일조그가 부관 타릴준을 곁에 두고 그곳을 다스렸다.",
	["s:1433:stonewatch falls"] = "돌망루 요새 아래에서 영원의 호수의 동쪽 강은 언덕 비탈을 따라 길게 떨어져, 붉은마루 산맥의 구석진 곳에 깊은 호수를 이룬다. 작은 멀록 부족이 그 기슭에 자리를 잡고, 물고기를 잡으며 폭포 아래에 투박한 거처를 세웠다.",
	["s:1433:stonewatch keep"] = "돌망루 요새는 한때 붉은마루를 지키기 위해 세워진 레이크샤이어 인간들의 것이었다. 흑마법사 모간스가 검은바위 오크 전쟁군주 가스일조그와 동맹을 맺으면서 요새는 무너졌다. 그들의 연합군은 모간스의 어둠의 마법에 힘입은 잔혹함으로 요새에 몸을 던졌다. 수비대는 무너졌고, 요새는 함락되었다.\n\n동맹은 오래가지 않았다. 돌망루가 함락되자마자 모간스는 자기 곁에서 피를 흘린 오크들에게 등을 돌렸다. 그는 근처에 일갈라의 탑을 세우고, 오직 자기 뜻에만 따르는 송곳니 부관 휘하의 그늘가죽 놀로 그곳을 채웠다. 그 뒤로 오크와 인간 모두가 그가 풀어놓은 짐승들에게 쓰러졌다.\n\n흑마법사 동맹에게 버림받은 검은바위 오크들은 스스로 요새를 지켰고, 가스일조그와 그의 부관 타릴준이 남은 것을 다스렸다. 전투 중에 그들은 스톰윈드 군의 키샨 상병을 포로로 잡아 북쪽의 야영지로 끌고 갔다. 행정관 솔로몬은 그 일로 가스일조그의 목에 현상금을 걸었고, 레이크샤이어의 원수 마리스는 타릴준도 그 죄의 대가를 치르게 하겠다고 맹세했다.",
	["s:1433:stonewatch tower"] = "돌망루 탑은 한때 돌망루 요새 곁에 서 있었고, 둘 다 레이크샤이어 인간들의 것이었다. 검은바위 부족이 요새를 차지하기 전까지는. 탑은 가스일조그의 부하들이 쓰는 정찰 초소가 되었고, 검은바위 부족 오크들이 동족이 레이크샤이어 사람들에게서 빼앗은 요새를 감시하고 있다.",
	["s:1433:three corners"] = "붉은마루 삼거리에서 길은 세 갈래로 나뉜다. 서쪽은 엘윈 숲의 골드샤이어로, 동쪽은 레이크샤이어로, 남쪽은 그늘숲의 다크샤이어로 이어진다. 이곳에 선 여행자는 세 땅이 맞물리는 이음매에 서 있는 셈이며, 그 사이의 통로를 표시하는 것은 교차로뿐이다. 근처 언덕에서 놀들이 밀려든다.",
	["s:1433:tower of ilgalar"] = "일갈라의 탑은 붉은마루 산맥 동부에 솟아 있다. 어둠의 연구 때문에 스톰윈드 마법사 지구에서 추방된 마법사 모간스가 이곳을 다스리며, 그는 탑을 피난처로 삼고 그늘가죽 놀 부족을 제 뜻대로 부렸다.",
	["s:1434:baliamah ruins"] = "발리아마 폐허의 돌들은 오래된 트롤의 작품으로, 모쉬오그 아래 강의 동쪽에 서 있다. 이제는 해골망치 트롤이 조상이 세운 것을 보금자리로 삼아 차지하고 있다.",
	["s:1434:ballal ruins"] = "그롬골 주둔지 북쪽, 썩은내 산호초 근처에는 부서진 기둥들이 솟아 있다. 먼 옛날 트롤들이 세운 거주지에서 남은 전부이다. 옛 모습은 거의 남아 있지 않다. 이제는 붉은두피 트롤이 폐허를 차지하고, 조상들이 남긴 돌 사이에서 살고 있다.",
	["s:1434:bloodsail compound"] = "붉은해적단은 가시덤불 골짜기 서쪽 해안을 따라, 해안의 한가운데쯤에 느슨한 야영지를 두고 있다. 이곳에는 질서의 깃발도, 제대로 된 항구의 규율도 없다. 그저 이곳을 제집이라 부르는 해적들이 흩어져 모여 있을 뿐이다.",
	["s:1434:booty bay"] = "무법항은 가시덤불 골짜기 남쪽 끝의 푸른 석호에 자리하며, 거대한 상어의 하얗게 바랜 턱뼈를 지나 걸어서 들어간다. 이곳에서는 목숨이 헐값이고 누구도 믿을 수 없다. 온갖 부류의 밀고자와 상인이 들끓는 도적들의 낙원이다.\n\n그 이름을 얻기 전, 이 만은 검은바다 만이라 불렸다. 정글 트롤에게 짓밟히기 전까지는 작은 인간 항구였다. 스팀휘들 무역회사의 고블린들은 1차 대전쟁이 벌어지기도 전에 트롤을 해안에서 몰아내고 만을 차지했으며, 그곳에 동부 왕국에서의 활동 중심지를 세웠다.\n\n지금은 검은바다 약탈단이 무역회사와 긴밀히 손잡고 항구를 운영하며, 그 문은 어떤 깃발 아래에 있든 모든 여행자에게 열려 있다. 레빌가즈 남작은 약탈단의 함대장 시혼과 함께 여관 꼭대기에서 다스리며, 만 자체를 빼앗으려고 음모를 꾸몄다가 실패한 해적, 붉은해적단에 맞서 돈을 아끼지 않고 칼잡이들을 고용해 왔다.",
	["s:1434:cape of stranglethorn"] = "가시덤불 골짜기 남부에는 밀림에 반쯤 삼켜진 트롤 유적이 빽빽하고, 나무들이 바다에 자리를 내주는 곳에는 모래 해안이 길게 펼쳐져 있다.\n\n해안을 따라 고블린 해적들이 운영하는 항구 도시 무법항이 자리하며, 그 부두와 시장은 깃발을 가리지 않고 돈만 있으면 누구에게나 열려 있다.\n\n그 중립은 평화가 아니다. 무법항의 고블린들은 교역과 무력으로 항구를 지키며, 그들의 경쟁자는 붉은해적단이다. 이 해적들은 고블린에게 등을 돌려 고블린이 자기 것이라 부르는 바다와 해안을 약탈하기 시작했다. 두 세력의 다툼은 배와 배, 야영지와 야영지가 맞붙으며 점점 악화될 뿐이다. 고블린들은 자신들이 세운 것을 지키고, 붉은해적단은 그것을 빼앗으려 밀어붙인다.\n\n항구와 유적 너머의 땅은 고요하다. 모래와 오래된 돌, 그리고 그 너머의 바다뿐이다.",
	["s:1434:crystal shore"] = "수정 해안은 가시덤불 남동쪽의 모래 해안으로, 남쪽 바다가 본토와 자구에로 섬의 동쪽 해변에 부딪히는 곳이다. 해안은 거친 해안에서 땅이 북쪽으로 솟아오르는 절벽까지 이어지며, 가파른 능선에 막혀 내륙과 단절되어 있다. 그 능선을 넘는 길은 둘뿐인데, 하나는 안개계곡 골짜기로 올라간다.\n\n해안 북쪽 끝에는 아보라즈의 폐허가 있다.",
	["s:1434:crystalvein mine"] = "크랭크 피즐버브는 그것을 노래하는 수정이라 불렀다. 가시덤불에만 있는, 한 재산이 되는 수정이다. 그 수정은 줄맘웨 근처 수정 광산의 바위에 줄지어 박혀 있고, 그곳에 둥지를 튼 바실리스크들은 그것을 날로 먹어 가죽을 돌처럼 단단하게 만든다. 투자개발회사가 광산을 털어 가려고 밀고 들어갔지만, 바실리스크들이 모든 시도를 물리쳤다. 입구 밖에는 트롤과 인간들이 쓰러진 자리에서 수정으로 굳은 채 서 있다.",
	["s:1434:gromgol base camp"] = "그롬골 주둔지는 가시덤불 남서쪽 해안에 요새화되어 자리하며, 그 방책은 해안의 정글 트롤, 파도에서 솟아오르는 나가, 그리고 무법항과 그늘숲에서 밀고 들어오는 얼라이언스에 맞서 세워졌다. 사령관 아그로고쉬가 주둔지를 지키며, 슬픔의 늪의 스토나드로 이어지는 보급로의 안전한 고리로 이곳을 유지하고 있다.",
	["s:1434:gurubashi arena"] = "구루바시 투기장은 가시덤불 북서쪽에 서 있으며, 구루바시 제국이 동부 왕국 남부의 광대한 땅을 다스리던 시절에 세워진 유물이다.\n\n옛날 이곳에서 벌어진 싸움은 경기가 아니라 학살이었다. 싸우는 자들이 죽을 때까지 싸우는 동안 모래는 트롤의 피로 진창이 되었다. 이제는 쇼티 존 미스릴이 한결 부드러운 경기를 주관하며, 죽음 대신 명성과 전리품을 내건다. 그래도 옛이야기는 한밤중에 핏빛 목걸이를 발견하는 자는 동이 트기 전에 악마에게 잡아먹힌다고 여전히 경고한다.",
	["s:1434:jaguero isle"] = "거친 해안 앞바다에는 자구에로 섬이 있으며, 그 밀림은 누구에게도 따르지 않는 표범과 고릴라의 차지이다. 그중 으뜸은 거대한 유인원 무클라 왕으로, 그는 섬을 다스리며 타우렌인 푸바 공주를 그녀의 뜻과 달리 사로잡아 두고 있다.\n\n해안을 따라 바다에서 밀려온 병들이 반쯤 묻혀 있는데, 그중 하나에는 접힌 쪽지가 들어 있다.",
	["s:1434:janeiros point"] = "자네이로 섬은 무법항 앞바다의 작은 섬으로, 두 팔을 활짝 벌린 거대한 고블린 석상이 서 있다. 배들을 항구로 맞아들이는 등대로 세운 것이다. 그 석상이 누구의 모습인지 이제 기억하는 이는 없다. 바다 거인 도살자 모크라쉬가 이 섬을 거처로 삼았다.",
	["s:1434:kalai ruins"] = "칼아이 폐허는 가시덤불 골짜기에서 바다에 반쯤 삼켜진 채 놓여 있으며, 오래된 트롤 석조물이 파도와 세월에 닳아 있다. 이제는 어둠아가미 부족 멀록이 무너진 기둥 사이에 둥지를 틀고, 물에 잠긴 전당을 자기들 것으로 삼았다.",
	["s:1434:kurzens compound"] = "쿠르젠 주둔지는 반란군 야영지 동쪽에 서 있는 쿠르젠 원정대의 본거지이다. 쿠르젠 대령이 원정대를 이끌지만, 그는 광기에 사로잡혔다. 그가 무엇이 되었는지는 말해지지 않고, 그 결과만 전해진다. 그의 부하들이 갈라선 것이다. 더는 그를 따르지 않으려던 이들은 떨어져 나가 반란군 야영지의 밀림 전사가 되었고, 그 뒤로 주둔지는 그들과 전쟁을 벌이고 있다. 한때 한 지휘 아래 있던 사람들이 이제 나무 사이에서 서로를 죽이고 있다.\n\n쿠르젠 자신은 이제 부하들 사이에서 좀처럼 모습을 보이지 않으며, 전사들이 무기를 보관하는 주둔지 뒤편의 보급창에 틀어박혀 있다고 한다. 마구간 근처에는 표범과 가시덤불 호랑이가 우리에 갇혀 있는데, 길들여지고 훈련받아 원정대가 쓸 전투 짐승이 된다.",
	["s:1434:lake nazferiti"] = "나즈페리티 호수의 물에는 광란꾼 물고기와 악어가 들끓고, 그 기슭에는 투자개발회사의 커다란 기지가 들어차 있다.\n\n호수는 나즈페리티 강에서 물을 받는데, 어떤 이들은 이 강이 동부 왕국 남부에서 가장 긴 강이라 여긴다. 강은 붉은마루 산맥의 폭포에서, 어쩌면 더 멀리 죽음의 고개에서 발원한다.",
	["s:1434:mistvale valley"] = "안개계곡 골짜기 위로는 안개가 낮게 깔려, 가시덤불 골짜기 남부의 숲 가장자리를 흐릴 만큼 짙다. 거대한 안개계곡 고릴라들이 이곳을 보금자리로 삼고 나무 사이의 안개 속을 오가며, 이 고요하고 축축한 분지를 방해받지 않고 다스린다.",
	["s:1434:mizjah ruins"] = "미즈자 폐허는 그롬골 주둔지 남동쪽에 있으며, 모쉬오그 폭력배와 그들의 부두술사들이 차지하고 있다. 오우거들은 이 부서진 돌무더기에서 스토나드로 향하는 짐마차 행렬을 습격하고, 누가 대응하기도 전에 보급로를 덮친 뒤 다시 폐허 속으로 사라진다.",
	["s:1434:moshogg ogre mound"] = "모쉬오그 오우거 소굴은 줄구룹 남쪽에 있으며, 그 어두운 굴은 모쉬오그 부족 오우거의 보금자리이다. 깊은 곳에서 그들의 우두머리인 오우거 마법사 마이조스가 정신의 눈이라 알려진 강력한 유물을 쥐고 있으며, 지금 그가 소굴을 다스리는 곳이 바로 그 깊은 곳이다.",
	["s:1434:nekmani wellspring"] = "네크마니 수원지는 가시덤불 서쪽 끝, 폭풍 해안 남부 위의 절벽에서 솟아난다.\n\n모든 종족의 학자들이 이 물이 오직 자기 종족을 위해 신성해졌다고 주장하며, 그 논쟁은 한 번도 결론이 난 적이 없다.",
	["s:1434:nesingwarys expedition"] = "드워프 명사냥꾼 헤메트 네싱워리는 밀림의 야생 사냥감에 이끌려 가시덤불로 원정대를 이끌었다. 그는 나즈페리티 호수 북쪽 강 바로 아래에 야영지를 차렸고, 그 야영지는 가시덤불의 무성한 초록 속에 새겨진 사냥꾼의 발판으로 지금도 서 있다.",
	["s:1434:rebel camp"] = "반란군 야영지는 가시덤불 골짜기 북부, 그늘숲에서 남쪽으로 뻗은 길의 서쪽이자 쿠르젠 주둔지의 북서쪽에 서 있다.\n\n이곳을 세운 이들은 쿠르젠 대령의 원정대에서 복무했으나, 광기가 대령과 그의 부하들을 사로잡아 그들의 정신을 알아볼 수 없을 만큼 뒤틀어 놓았다. 도렌 중위가 이끄는 작은 무리는 광기에 사로잡히기 전에 벗어나, 쿠르젠 주둔지에서 밀림을 가로질러 서쪽으로 달아났다.\n\n그곳에서 그들은 쿠르젠이 된 것을 되돌리기 위한 발판으로 반란군 야영지를 세웠다. 무법항의 크라제크가 그들에게 지뢰와 다른 방어 수단을 대 주고 있으며, 반란군은 그 덕분에 한때 함께 복무했던 저주받은 주둔군에 맞서 버틸 수 있다.",
	["s:1434:ruins of aboraz"] = "아보라즈는 고대 트롤들이 세웠지만, 지금은 누구의 것도 아니다. 자기 종족에게서 추방당한 추방자 잔질이 폐허를 자신의 영역으로 삼고, 그의 부두술에 따르는 구울과 나가, 트롤 하수인들로 그곳을 채웠다.",
	["s:1434:ruins of jubuwal"] = "주부왈의 폐허는 구루바시 투기장 동쪽에 있는 옛 트롤 거주지로, 지금은 추방자 잔질을 섬기는 구울과 나가, 트롤이 차지하고 있다. 그들 사이에는 까마귀 존존과 절름발이라 불리는 모리 윌킨스가 숨어 있다. 무자비한 바다늑대 매킨리에게 진 빚을 피하려고 그 음울한 무리 속으로 달아난 자들이다.",
	["s:1434:ruins of zulkunda"] = "줄쿤다의 돌 계단식 단들은 이제 붉은두피 트롤의 것이며, 흉포한 네즐리오크와 간줄라가 다스린다. 줄다이아 폐허에서 동쪽으로 난 길은 곧장 그들의 영역으로 이어지며, 그곳의 오래된 트롤 석조물은 살아 있는 자들의 차지가 되어 있다.",
	["s:1434:ruins of zulmamwe"] = "줄맘웨의 폐허는 모쉬오그 오우거 소굴 남쪽에 있으며, 북쪽을 제외한 사방이 산으로 둘러싸여 있다. 이곳은 가시덤불 골짜기의 두 번째 트롤 부족인 해골망치 부족의 본거지로, 족장 잔혹한 아나테크가 다스린다.",
	["s:1434:savage coast"] = "폭풍 해안은 가시덤불 골짜기의 북쪽 해안을 따라, 서부 몰락지대 경계에서 썩은내 산호초를 지나 그롬골까지 이어진다.\n\n악어들이 얕은 물에 출몰하고 바실리스크가 바위를 누비며, 그 시선은 방심한 자를 돌로 만든다. 여러 트롤 거주지가 이 바다를 굽어보고 있다.",
	["s:1434:south seas"] = "남쪽 바다는 알려진 대륙들 사이의 바다를 채우고 있으며, 대해의 일부이다. 트롤 제국의 옛 고향인 잔달라가 이 바다에서 솟아 있다. 본토의 세력들과 떨어져 자기 백성을 품고 있는 화산섬 케잔도 그 사이에 있다. 가시덤불 골짜기에 가까워질수록 바다는 암초와 작은 섬들로 험해지는데, 어떤 섬은 모래톱에 지나지 않고, 어떤 섬은 세운 이들이 사라진 폐허를 품고 있다. 남쪽 바다는 가시덤불과 타나리스, 울둠의 경계를 따라 펼쳐져 있다.",
	["s:1434:southern savage coast"] = "폭풍 해안 남부는 남쪽 바다가 탁 트인 해변과 얕은 물에 부딪히는 곳으로, 무법항과 자네이로 섬 근처의 바다까지 내려가며, 그곳에서 해안은 그 너머의 거친 해안으로 이어진다.\n\n썩은내 산호초는 이 해안과 북쪽 해안 사이의 경계를 이루며, 그곳에서 대해는 남쪽 바다로 바뀐다. 만과 후미를 통해 해안은 구루바시 투기장, 네크마니 수원지와 맞닿는다.",
	["s:1434:spirit den"] = "정기의 동굴은 안개계곡 골짜기 북쪽 끝의 동굴 속에 숨겨져 있다. 그곳에서 부두술사 운바그와는 동굴의 그림자 속에 머물며, 그 고요하고 보이지 않는 굴에 머무는 영혼들이 무엇이든 그들을 돌본다.",
	["s:1434:stockpile"] = "쿠르젠 주둔지 뒤편의 동굴에 쿠르젠 대령은 전쟁 장비를 보관하고 있다.",
	["s:1434:tkashi ruins"] = "트카시 폐허는 가시덤불 골짜기에 있으며, 밀림에 되찾아진 오래된 트롤 석조물이다. 이제는 붉은두피 부족이 이곳을 차지하고 있으며, 그 주술사들은 부서진 벽 사이에서 고대 의식을 행하고, 유물들은 아직도 잔해 곳곳에 흩어져 있다.",
	["s:1434:venture co base camp"] = "투자개발회사는 이곳에 탐사기지를 두고 굴러다니는 수정을 찾는 데 몰두하고 있다. 근처에는 그들의 기계조작실이 서 있어, 두 곳이 같은 발견을 향해 손발을 맞춰 일한다.",
	["s:1434:venture co operations center"] = "투자개발회사의 석유 굴착 시설은 밀림 속 호수에서 솟아 있으며, 황야로 밀고 들어가는 그들의 작전 본부이다. 정비공과 지질학자, 그 밖의 고블린 일꾼들이 굴착기에 북적이며, 이익을 위해 땅을 벗겨 내는 데 혈안이 된 회사의 기계를 돌린다.",
	["s:1434:vile reef"] = "가시덤불 골짜기 서쪽 해안 앞바다, 그롬골 근처에서는 바다가 산호초 위로 눈부시게 부서진다. 그 아래에는 가라앉은 트롤 폐허가 있고, 그 물에 잠긴 돌 사이에 이제 멀록들이 보금자리를 틀어, 한때 다른 이의 것이었던 전당 사이로 빽빽한 무리가 움직인다. 파도의 제단이 아직 그곳에 서 있다. 산호초 바닥에는 푸른 진주를 품었다는 거대한 조개들이 널려 있고, 산호초를 끝내 빠져나가지 못한 배들의 잔해가 해안으로 밀려온다.",
	["s:1434:wild shore"] = "거친 해안은 동부 왕국이 남쪽 바다에 자리를 내주는 곳으로, 그 해변은 붉은해적단이 차지하고 있다. 그들의 함대는 앞바다에 떠 있고, 선원들은 모래사장을 자기들 것이라 주장한다. 해안 어딘가에는 외톨이 거인 고를래쉬가 떠돌고 있으며, 해적과 거인 사이에서 이 해안은 어떤 왕관에도 따르지 않는다.\n\n땅은 서쪽으로 좁아져 바위 곶을 이룬 뒤 무법항 쪽으로 꺾인다. 얕은 해협 건너 동쪽에는 자구에로 섬이 있다. 북쪽으로 모래밭은 수정 해안으로 흐릿하게 이어진다.",
	["s:1434:yojamba isle"] = "가시덤불 북서쪽 해안 앞, 서부 몰락지대와의 경계 근처에 있는 이 작은 섬들에서 잔달라 부족은 미쳐 버린 신에 맞서 버티었다.\n\n영혼의 약탈자 학카르는 줄구룹을 피와 광기의 땅으로 바꾸어 놓았고, 잔달라는 홀로 그와 맞설 수 없음을 알았다. 그래서 그들은 요잠바 섬으로 와서, 얼라이언스와 호드 모두에게 그를 쓰러뜨릴 수 있을 만큼만이라도 전쟁을 멈추고 도와 달라고 호소했다. 오래되고 자존심 강한 부족이 신의 손길이 닿은 도시의 운명을 이방인들에게 맡긴 것이었다.",
	["s:1434:ziatajai ruins"] = "지아타자이 폐허는 먼 옛날 트롤들이 세운 고대의 돌무더기로, 지금은 해골망치 부족이 차지하여 옛 성벽을 자기들 것으로 지키고 있다.",
	["s:1434:zulgurub"] = "줄구룹은 가시덤불 골짜기 북동쪽의 밀림에서 솟아 있다. 계단식 단과 우상들은 덩굴에 뒤덮였어도 여전히 서 있으며, 한때 한 제국의 고동치는 심장이었던 신전 도시이다. 수천 년 전 이곳은 구루바시 제국의 수도로서, 제국에 속한 모든 정글 트롤 부족의 본거지였다. 이제 이곳은 남은 구루바시 부족만의 것이지만, 그 주변의 밀림은 결코 비어 있는 것처럼 느껴지지 않는다.\n\n제국은 아탈라이라 불리는 사제 집단이 고대 피의 신, 영혼의 약탈자 학카르의 화신을 소환했을 때 스스로 무너졌고, 사제들은 그 일로 추방되었다. 그들은 학카르가 오직 한 곳, 옛 구루바시 수도에서만 육신을 얻을 수 있다는 것을 알아냈다. 바로 이곳에서 주술사 진도가 구루바시의 대사제 여럿을 노예로 삼아 학카르를 세상으로 불러내는 일에 부리고 있다. 그를 막으러 보내진 용사들, 저마다 태고의 신에게 묶인 이들은 오히려 학카르의 지배 아래 떨어졌고, 그들의 힘은 이제 그들이 무찌르러 온 바로 그것을 먹여 살리고 있다.",
	["s:1434:zuuldaia ruins"] = "가시덤불 골짜기 서쪽 해안 위로 풍화된 돌들이 솟아 있다. 오래전에 무너진 거주지의 폐허이다. 이제는 붉은두피 트롤이 부서진 벽을 차지하고 옛 토대 사이에 빽빽이 모여, 자기 조상이 세운 적도 없는 땅을 제 것이라 주장한다.",
	["s:1435:fallow sanctuary"] = "슬픔의 늪에는 드레노어 성역이 서 있으며, 그저 잃어버린 자들이라고만 알려진 잃어버린 자 부족의 보금자리이다. 향수병이 그들 모두를 사로잡아 완전히 야성으로 몰아넣었고, 그들의 마을에 다가오는 이를 맞이할 옛 모습은 아무것도 남아 있지 않다.",
	["s:1435:harborage"] = "슬픔의 늪 북쪽에는 드레노어에서 아제로스로 건너온 이들 가운데, 그 많은 동족과 달리 온전한 정신을 지킨 자들의 피난처가 서 있다. 마그투어가 이곳에서 그들을 이끈다.",
	["s:1435:ithariuss cave"] = "슬픔의 늪 남서쪽의 한 동굴에는 하이 엘프 이타리우스가 머물고 있다. 바깥에서는 날개도 불도 다룰 줄 모르는 어린 말썽꾸러기 녹색 새끼용들이 티격태격하며 비틀거린다. 이타리우스는 그들이 자라는 동안 돌보는 일을 스스로 맡았다.",
	["s:1435:misty reed post"] = "안개갈대 주둔지는 진흙늪과 남쪽 안개갈대 해안 사이에 자리한 스토나드의 작은 전초기지이다. 톡카르가 카타르와 스토나드 사냥꾼 몇, 그리고 스토나드 주술사 하나와 함께 이곳을 지킨다. 땅굴도 탑도 없는 그저 야영지일 뿐이지만, 톡카르는 언젠가 그런 것을 세울 날을 꿈꾼다.",
	["s:1435:misty reed strand"] = "안개갈대 해안은 슬픔의 늪을 따라 이어진 음울한 해변으로, 떠밀려 온 나무와 썩은 것 말고는 자라는 것이 거의 없다. 악어들이 얕은 물에서 햇볕을 쬐고, 그 너머 해안에는 게와 멀록이 머문다.",
	["s:1435:misty valley"] = "슬픔의 늪의 이 구석에는 소리마저 삼킬 만큼 짙은 안개가 낮게 깔려 있다. 골짜기 안쪽의 동굴 깊숙한 곳에는 정령의 힘인 수렁 군주가 살고 있었다.",
	["s:1435:pool of tears"] = "눈물의 연못은 슬픔의 늪 동쪽 끝에 넓고 고요하게 펼쳐져 있다. 그 잔잔한 수면 아래에는 아탈학카르 신전이 있다. 트롤들이 세운 뒤 이세라가 가라앉혀 세상에서 숨긴 곳이다. 녹색용군단은 오랫동안 그 물에 잠긴 곳을 감시하며, 아래에 잠든 것을 깨울지 모를 모든 것을 막아 왔다.\n\n이제는 피에 굶주린 광란꾼 물고기들이 물속을 누비고, 부서진 아탈라이 석조물이 물가에 흩어져 있다.",
	["s:1435:shifting mire"] = "변화의 늪의 진흙은 결코 가만히 있지 않는다. 고운 더미로 땅에 쌓였다가, 마치 보이지 않는 무언가가 끌고 가는 듯 늪을 가로질러 기어가며 살아 있는 것처럼 휘감기고 고인다.\n\n어떤 이들은 그 움직임 뒤에 있는 힘이 악의적인 것이 아니라, 해칠 뜻 없이 진흙을 휘젓는 어떤 긍정적인 기운이라고 말한다.",
	["s:1435:sorrowmurk"] = "슬픔의 그늘은 눈물의 연못 동쪽, 가라앉은 사원 근처에 있다. 이곳은 용족의 차지로, 녹색용족이 거대한 녹색 비룡의 감시 아래 수렁 속을 기어 다니며, 가장 무모한 여행자가 아니면 누구도 다가오지 못하게 한다.",
	["s:1435:splinterspear junction"] = "슬픔의 늪으로 들어가는 길이 갈라지는 곳에 오래된 오크 감시탑이 아직 서 있고, 호드 순찰대가 그 교차로를 지켜보고 있다.\n\n이 탑은 1차 대전쟁 때 이곳에 세워진 오크 전초기지 키로스의 잔해이다. 키로스는 늪에 있는 호드의 어느 거점보다도 인간 마을 그랜드 햄릿에 가까이 서 있었고, 스톰윈드는 그것을 그냥 둘 수 없었다. 그것을 무너뜨리러 전투 부대가 보내졌다.\n\n탑은 지금도 길의 갈림목을 지켜보고 있다.",
	["s:1435:stagalbog"] = "눈물의 연못 남쪽, 슬픔의 늪이 산으로 솟아오르는 곳에서 늪지대는 짙어져 진흙늪이 된다. 축축한 황야의 서쪽, 산기슭에는 바위 속으로 동굴이 열려 있다.",
	["s:1435:stagalbog cave"] = "슬픔의 늪 동쪽의 진흙늪에는 수렁 쪽으로 동굴 하나가 열려 있다.",
	["s:1435:stonard"] = "스토나드는 슬픔의 늪의 수렁에서 솟아 있으며, 다른 수많은 오크 전당이 오래전에 무너진 지금도 그 대전당은 여전히 서 있다. 두 개의 땅굴이 진입로를 지키고, 오크 순찰대는 근처의 작은 야영지들을 지키러 나간다. 하나하나가 늪에 맞서 박아 둔 또 하나의 말뚝이다.\n\n이 전초기지는 오래되었다. 세계의 이쪽 편에 있는 오크의 거의 어느 거점보다도 오래되었으며, 한때 로카드라 불렸던 요새와 자매를 이룬다. 어둠의 문이 처음 열린 뒤 구 호드가 검은늪에 세운 것이다. 2차 대전쟁이 닥쳐 호드가 무너지자, 스토나드는 고요해졌다. 오크들이 세운 다른 많은 것들과 함께 버려졌거나 파괴되었을 것이다.\n\n이곳은 비어 있지 않았다. 새로운 호드가 일어서고 이 땅을 지키려는 의지가 되살아나면서, 스토나드는 재건되었다. 전당은 복원되었고 땅굴은 다시 파였다. 로카드는 그리 운이 좋지 않았다. 우레망치 오우거가 옛 요새를 차지해 우레망치 요새라 이름을 바꾸었고, 스토나드는 늪에 남은 호드의 유일한 전초기지이자 이 저지대에서 아직 불이 켜진 마지막 전당이 되었다.",
	["s:1435:temple of atalhakkar"] = "천 년도 더 전에 구루바시 제국은 내전으로 스스로를 찢어 놓았다. 그 중심에는 피의 신, 영혼의 약탈자 학카르를 세상으로 다시 불러오려 한 트롤 사제들, 아탈라이가 있었다. 패배하고 추방당한 그들은 북쪽의 슬픔의 늪으로 달아나 그의 귀환을 준비하려고 그곳에 신전을 세웠다.\n\n용의 위상 이세라는 그들의 계획을 알아채고, 그들의 작업을 영원히 묻어 버리려고 신전을 늪 아래로 가라앉혔다. 그러나 일은 그렇게 되지 않았다. 물에 잠긴 어둠 속에서 방해받지 않고, 그들을 막을 수 있었을 모든 눈으로부터 가려진 채, 아탈라이는 평온하게 의식을 계속했다. 이세라가 폐허를 지키라고 보낸 녹색용들은 그 뒤로 줄곧 감시를 이어 가며, 한 번도 진정으로 봉인된 적 없는 문을 닫아 두고 있다.\n\n신전은 여전히 가라앉아 반쯤 물에 잠긴 채 학카르의 제단을 온전히 간직하고 있으며, 그 안에 들어가는 이는 죽음보다 끔찍한 위험을 무릅쓴다. 피의 로아에게는 살점뿐 아니라 영혼도 바쳐져야 하며, 바쳐지는 영혼 하나하나가 그가 실패하지 않을 그날을 살찌운다.",
	["s:1436:alexston farmstead"] = "알렉스턴 농장의 들판은 데피아스 단이 땅을 차지하기 전까지 여러 가족을 먹여 살렸다. 이제는 기계 수확 감시자들만이 지칠 줄 모르고 돌보는 이 없이 밭고랑 사이를 움직이며, 더는 아무도 씨를 뿌리지 않는 이랑을 지킨다.\n\n훗날 스톰윈드의 건축가가 된 바로스 알렉스턴은 이 땅에서 태어났다. 그를 빚어낸 땅이 다른 이의 손에 넘어가기 전, 그는 소년 시절 지금 수확 감시자들이 순찰하는 바로 그 들판에서 일했다.",
	["s:1436:dagger hills"] = "비수 언덕은 서부 몰락지대 남쪽, 문브룩 뒤편에 마루처럼 솟아 있다. 이제 그곳에는 움직이는 것이 거의 없다. 그림부즈 썬더브루가 언덕에 머물고 있는데, 그 고요한 땅에서 볼 수 있는 몇 안 되는 산 자 가운데 하나이며, 구울 레프리투스도 그곳 땅에서 일어난다고 알려져 있다.",
	["s:1436:dead acre"] = "메마른 논밭은 한때 서부 몰락지대 남동쪽, 그늘숲으로 가는 다리 근처의 여러 농장 가운데 하나였다. 데피아스 단이 이 지역을 장악했을 때, 그들은 그곳에 있던 농장을 들판과 함께 차지했다.\n\n이제 그곳을 걷는 농부는 없다. 대신 기계 수확 감시자들이 한때 곡식이 자라던 땅을 돌아다닌다.",
	["s:1436:deadmines"] = "문브룩 아래로는 굴이 깊이 뻗어 있고, 한때 그곳에는 금이 흘렀다. 오크가 인간의 땅으로 건너오기 전, 죽음의 폐광은 스톰윈드의 국고를 채웠다. 어떤 기록에 따르면 국고의 삼분의 일이 이 바위에서 나왔다. 1차 대전쟁으로 광부들이 모두 떠났고, 그 뒤로 광산은 죽은 곳으로 버려져 유령이 나온다고 여겨지며 오랫동안 손대지 않은 채 남았다.\n\n그 침묵 속으로 에드윈 밴클리프가 들어왔다. 그는 산적이 된 옛 일꾼들, 데피아스 단을 모아 고블린의 도움을 받아 깊은 곳에서 거대 전함을 짓게 했다.\n\n그 깊은 곳에 밴클리프는 형제단의 호위를 받으며 머물고 있고, 그리안 스타우트맨틀은 감시의 언덕에서 그의 목을 가져오겠다고 맹세한 이들을 모으고 있다.",
	["s:1436:demonts place"] = "문브룩 서쪽의 데몬트의 집터에는 부서진 목재와 웃자란 밭 말고는 남은 것이 거의 없다. 한때 일하던 농장이었던 이곳은 이제 데피아스 요원들이 차지해 자기들 것으로 삼고 있다.",
	["s:1436:dust plains"] = "먼지 언덕은 서부 몰락지대의 남쪽에 펼쳐진 메마른 땅으로, 놀들에게 넘어가 그들이 흩어진 야영지를 두고 자기 영역을 지나는 자는 누구든 위협한다.\n\n동쪽 끝에는 모트웨이크의 탑이 서 있다. 오래된 마법사의 탑으로, 원래의 목적은 오래전에 새 주인들에게 자리를 내주었다.",
	["s:1436:furlbrows pumpkin farm"] = "펄브로우 호박밭은 한때 농부 펄브로우와 그의 아내 베르나가 가꾸던 곳이지만, 데피아스 단이 기계 수확 골렘을 앞세워 서부 몰락지대를 휩쓸자 이 농장도 그 땅의 수많은 다른 농장들처럼 무너졌다. 펄브로우와 베르나는 달아나 북쪽 얀센 농장 근처의 길가에 몸을 피했고, 호박과 자신들의 이름을 뒤에 남겨 두었다.",
	["s:1436:gold coast quarry"] = "황금해안 채석장은 서부 몰락지대가 폐허가 되기 전까지 스톰윈드에 금과 광석을 내주었다. 이제는 데피아스 단이 차지하고 자기들 깃발 아래에서 구덩이를 파고 있다. 서부 몰락지대 민병대와 그 대원들은 이곳에서 형제단과 충돌했으며, 여전히 순찰을 도는 바위 사이에서 데피아스의 매복을 당했다.",
	["s:1436:jangolode mine"] = "장고로드 광산은 한때 스톰윈드로 광석을 보냈으며, 서부 몰락지대에서 비교적 꾸준한 광물 자원의 원천 가운데 하나였다.\n\n그 꾸준함은 데피아스 단이 광산을 장악하면서 무너졌다. 그 뒤로 코볼트들이 갱도로 기어들어 그곳을 자기들 것으로 삼았다.",
	["s:1436:jansen stead"] = "얀센 농장은 서부 몰락지대 북쪽 끝, 엘윈 숲으로 가는 다리 가까이에 있다. 이 지역의 다른 농장들처럼, 데피아스 단이 주인들을 몰아내면서 이곳도 텅 비게 되었다.\n\n근처에는 펄브로우 호박밭의 자기 집에서 달아나 지금은 이 농장에 몸을 의탁한 농부 펄브로우와 그의 아내가 있다.",
	["s:1436:longshore"] = "서부 몰락지대의 해안은 길고 텅 비어 있으며, 아제로스에서 가장 넓은 해변 가운데 하나이다. 멀록들이 막을 수 없을 만큼 많은 수로 해변을 오가고, 그 사이에서 해안의 어부들이 두려워하며 이름까지 붙인 괴물, 늙은 흐린눈이 헤엄친다. 파도가 부서지는 곳 너머에는 끝내 들어오지 못한 배들의 잔해가 누워 있는데, 엘프의 구축함들도 그중에 섞여 파도에 내맡겨져 있다.\n\n해변의 남서쪽 끝에는 대프니 스틸웰의 농장이 서 있다. 데피아스 단은 서부 몰락지대의 다른 많은 것을 불태웠듯 그녀도 불태워 쫓아내려고 여러 번 찾아왔다. 그녀의 곤경이 두소리안 랄에게 전해졌고, 그는 백은의 손 기사가 되려는 이들을 해안으로 보내 그녀의 땅을 지키게 했으며, 그들은 그 땅을 지켜 냈다.",
	["s:1436:molsen farm"] = "몰센 농장은 데피아스 단이 차지한 서부 몰락지대의 수많은 농장 가운데 하나이다. 이랑은 녹과 기계에 내맡겨졌고, 기계 수확 감시자들이 들판을 돌아다니며 너무 가까이 다가오는 자는 누구든 쓰러뜨린다.",
	["s:1436:moonbrook"] = "문브룩의 들판 아래에는 한때 스톰윈드 국고의 삼분의 일이 흐르고 있었다. 훗날 죽음의 폐광이라 불리게 된 굴에서 캐낸 금이었다. 마을은 왕국의 곡창이었다. 석공 조합의 해산이 폭동을 일으켜 티핀 린 왕비가 목숨을 잃기 전까지는. 왕비의 죽음에 대한 바리안 왕의 복수는 누구보다 조합에 가혹하게 떨어졌고, 석공들은 그를 피해 서부 몰락지대의 농토로 달아났다. 그림자 속에서 부채질된 그들의 분노는 데피아스 단이 되었다. 에드윈 밴클리프 아래에서 그들은 도적질에 나섰고, 문브룩에서 농부들을 몰아냈으며, 마을 아래 버려진 광산 굴을 본부로 삼아 바다에서 스톰윈드를 파괴할 무기를 몰래 만들었다.\n\n여러 해 동안 그들에게 맞서러 온 군대는 없었다. 형제단은 여전히 문브룩을 차지하고 있고, 오직 그리안 스타우트맨틀의 민병대만이 그들에 맞서 감시의 언덕에서 다가올 심판을 위해 힘을 모으고 있다.",
	["s:1436:saldeans farm"] = "살딘 농장은 서부 몰락지대에서 유일하게 데피아스 단에게 점령당하지 않은 곳이다. 데피아스의 수확 골렘이 들판을 돌아다니지만, 농부 살딘과 그의 아내 살마는 떠나기를 거부했다. 그들의 농가는 여러 해 동안 쉼터 역할을 해 왔고, 부부는 손님들을 살려 두기 위해 할 수 있는 모든 일을 한다.",
	["s:1436:sentinel hill"] = "감시의 언덕은 서부 몰락지대의 농토 위 높은 곳에 서 있으며, 그 탑은 아래 비탈에 지어진 오두막과 대장간, 방앗간을 내려다본다.\n\n강발톱 놀과 데피아스 단 모두 이 언덕과 그 땅을 공격해 왔다.",
	["s:1436:stendels pond"] = "감시의 언덕 남서쪽에는 작은 연못이 있는데, 놀 무리에 둘러싸인 채 물이 고요히 멎어 있다. 물가에는 무덤 두 기와 흩어진 오래된 뼈가 놓여 있고, 물속의 무언가는 마치 다시는 마실 물이 될 수 없다는 듯 불길하게 느껴진다.\n\n그곳에서 운을 시험하는 낚시꾼들은 대개 흔한 현자물고기를 낚는다. 그러나 수면 아래에는 다른 것도 헤엄친다고 한다. 스텐들의 골칫덩이라 불리는 물고기로, 좀처럼 보이지 않고 잡히는 일은 더더욱 드물다.",
	["s:1436:westfall lighthouse"] = "등대는 서부 몰락지대의 남쪽 끝에 서 있으며, 밤이면 그 불빛이 아직도 바다 위를 돌지만, 그것을 지키는 손은 이제 죽은 자의 것이다.\n\n한때 한 가족이 불을 돌보았는데, 멀록 늙은 흐린눈이 파도 속에서 나와 그들을 공포에 질려 쫓아냈다. 그들은 돌아와 다시 불을 밝혔지만, 늙은 흐린눈도 돌아왔고, 이번에는 해안의 멀록들을 이끌고 등대를 습격했다. 가족은 살아남지 못했다. 그레이슨은 그들이 눈앞에서 죽어 가는 것을 막지 못한 채 지켜보았고, 이제 불빛을 지키는 것은 그의 유령이다. 그는 교대해 줄 이 하나 없이 탑 밖에서 파수를 서고 있다.",
	["s:1437:angerfang encampment"] = "성난송곳니 야영지는 저습지 중부에 넓게 펼쳐져 있으며, 이 지역에서 용아귀 부족이 차지한 가장 큰 야영지이자 성난송곳니 오크의 보금자리이다.\n\n네크로스 스컬크러셔의 아들 네크로쉬 스컬크러셔 아래에서 야영지는 메네실 항구를 공격하기 위한 투석기를 집결시키는 전진 기지가 되었다. 위협이 실재하기에, 스타우트피스트 대장은 투석기가 굴러가기 전에 네크로쉬를 죽이고 부족의 전투 깃발을 찢어 버리겠다고 맹세했다.",
	["s:1437:baradin bay"] = "바라딘 만의 물은 카즈 모단과 로데론이 만나는 해안을 적시며, 메네실 항구와 스트롬가드 요새의 기슭에 닿는다. 멀록과 악어가 얕은 물에 떠다니고, 상어와 게가 깊은 물을 차지한다.\n\n만의 진짜 역사는 그 바닥에 부서진 채 놓여 있다. 2차 대전쟁 동안 쿨 티라스 함대는 이 바다를 순찰하며, 동부 왕국 곳곳으로 번지는 전쟁에 맞서 해안을 지켰다. 그러나 쿨 티라스는 그 경계의 대가를 비싸게 치렀다. 그 나라의 제3함대가 전투에서 궤멸한 것이다. 그 잔해 일부는 지금도 저습지 해안을 따라 산산조각 난 채, 부서진 자리의 얕은 물에서 보이고, 다른 일부는 완전히 가라앉아 누구도 건져 올리지 못한 어둠 속에 자리 잡았다.",
	["s:1437:black channel marsh"] = "메네실 항구로 가는 길은 저습지 남서쪽의 검은바닥 습지대 가장자리를 지난다. 랩터들이 늪지 곳곳에 둥지를 틀고, 더 굶주린 녀석들은 길가 가까이까지 어슬렁거리므로, 이 구간을 지나는 여행자들은 경계를 늦추지 않는 편이 좋다.",
	["s:1437:bluegill marsh"] = "저습지 서부의 푸른아가미 습지대 물에는 푸른아가미 멀록의 야영지들이 있다. 그들은 결코 홀로 다니지 않고, 갈대 사이를 둘이나 셋씩 무리 지어 다닌다. 그들의 우두머리는 다른 멀록보다 사나운 먹보로, 그의 존재 때문에 습지대는 조심해서 들어가야 하는 곳이 되었다.",
	["s:1437:deepwater tavern"] = "깊은바다 선술집은 메네실 항구에 있으며, 그 휴게실은 지나가는 선원들의 이야기로 북적인다. 거친 곳이다. 맥주가 따라지는 만큼 의자가 날아다니고, 싸움은 흔히 홀쭉이라 불리는 타포크 잔의 부추김으로 시작된다.",
	["s:1437:direforge hill"] = "불길한 언덕은 한때 흑마법사 추악한 발가라스가 이끄는 검은무쇠 드워프의 주요 야영지였다.",
	["s:1437:dragonmaw gates"] = "용아귀부족 관문은 비룡 악스트로즈 휘하의 붉은용군단이 지키며, 그는 그림 바톨에 닿으려는 자들에게서 길을 막아선다.",
	["s:1437:dun algaz"] = "던 알가즈를 지나는 굴은 드워프를 갈라놓은 다툼보다도 오래되었다. 세 망치의 전쟁으로 와일드해머 부족이 아이언포지에서 쫓겨났을 때, 그들이 퇴각한 길이 바로 이 고개였다.\n\n이 고개는 호드의 퇴각로이기도 했다. 던 모드르에서 밀려난 오크들은 탄돌 골짜기를 건너 남쪽으로 물러나 이곳의 전초기지에 버텼고, 그들을 카즈 모단에서 완전히 몰아내고자 한 안두인 로서는 군대를 보내 그 요새를 무너뜨리려 했다. 공격은 실패했다. 오크들은 버텼고, 던 알가즈는 호드가 이 지역에서 지켜 낸 마지막 땅, 뽑히지 않는 발판이 되었다.\n\n이 고개를 지키던 드워프 산악병들은 주로 그 위의 언덕에 머물렀지만, 용아귀 부족이 그들의 초소를 점령해 위쪽 굴로 몰아냈고, 그들은 지금도 그곳에서 버티고 있다. 아래쪽 고개를 잃으면서, 드워프의 고향과 메네실 항구 사이의 길은 훨씬 더 위험해졌다.",
	["s:1437:dun modr"] = "던 모드르는 탄돌 교각 남쪽에 서 있는 오래된 드워프 도시로, 오래전에 폐허가 되었다. 대장간과 양조장 겸 여관이 잔해 한가운데 아직 서 있으며, 지금은 검은무쇠 드워프가 그곳을 자기 것이라 주장한다.\n\n2차 대전쟁 때 오크 호드가 폐허를 점령해 전초기지를 세웠고, 그곳을 얼라이언스 군대를 물리치고 주변 농토를 약탈하는 데 쓰며 군대의 핵심 집결지로 삼았다. 스트롬가드 전사들은 섬 요새 톨 바라드에서 출격해 그 전초기지를 무너뜨리려 포위했고, 오크들을 남쪽의 두 번째 거점 던 알가즈로 몰아냈다. 호드는 반격해 던 모드르를 되찾았고, 그 힘을 톨 바라드에까지 돌렸다. 호드가 수도에서 무너지고 나서야 안두인 로서는 그들을 탄돌 교각 너머 카즈 모단으로 몰아냈고, 던 모드르는 얼라이언스의 손에 넘어갔다.\n\n그 평화는 오래가지 않았다. 아이언포지의 병사들이 고향에서 먼 전쟁에 소진되자 검은무쇠 드워프가 탄돌 교각을 뚫고 들어왔고, 던 모드르는 곧 흑마법사 추악한 발가라스의 손에 떨어졌다. 그는 지금 자기 종족이 차지한 도시를 쥐고 있다.",
	["s:1437:green belt"] = "녹지대에는 악어와 늪괴물, 수액괴물이 들끓으며, 녹색 감시자 레시엘이 기이하고 불안하게 변한 땅에 분노하며 이곳을 지키고 있다.\n\n서쪽에서는 수렁괴물들이 사나워졌다. 북동쪽에서는 뜻밖에 불길한 언덕에서 불의 정령들이 솟아오른다. 둘 다 레시엘이 지키는 땅의 상처이며, 어느 쪽도 잦아들지 않았다.\n\n녹지대 안에는 용아귀 부족 짐마차 행렬의 잔해가 있다. 이제는 붉은 새끼용들이 그 잔해 사이에 굴을 틀었다. 검은용군단의 새끼를 훔치려다 이곳에서 늪에 삼켜져 끝을 맞은 시도가 남긴 전부이다.",
	["s:1437:grim batol"] = "그림 바톨은 저습지 동부에 자리한 산악 요새이다. 강철빛 잿빛 하늘로 뻗은 거대한 성벽과 첨탑이 있지만, 요새의 대부분은 지하에 있다. 와일드해머 드워프가 세웠으나 세 망치의 전쟁 중에 저주를 받았다. 훗날 오크들이 이곳을 차지해 용의 위상 알렉스트라자의 감옥으로 썼고, 그녀는 그림 바톨 전투에서 풀려났다.",
	["s:1437:ironbeards tomb"] = "아이언비어드의 고분은 저습지 중북부, 던 모드르로 가는 길 서쪽에 있다. 이곳 묘지 위에는 드워프 석상이 서 있는데, 아마 아이언비어드 자신의 모습을 새긴 것으로 보인다.\n\n망자들은 더 이상 그 안에서 편히 쉬지 못한다. 검은빛, 진홍빛, 그리고 괴물 같은 빛깔의 수액괴물들이 납골당으로 기어들어 그곳을 더럽혔고, 묘지 전체로 퍼져 이제 가족을 묻으려는 이 누구도 그곳 가까이 오지 않는다.",
	["s:1437:lost fleet"] = "파도의 여왕호와 용맹호의 잔해는 북쪽 푸른아가미 습지대 해안 앞, 바라딘 만의 해저에 누워 있다.\n\n두 배는 2차 대전쟁 때 대제독 데일린 프라우드무어의 맏아들 데릭 프라우드무어가 지휘한 쿨 티라스 제3함대에 속해 있었다. 크레스트폴 전투에서 용아귀 부족에게 노예가 된 붉은용들이 하늘에서 내려와 함대에 불을 질렀다. 데릭은 아버지에게 위험을 알리려고 돛대 망루로 올라갔다. 경고가 소용 있기도 전에 용 한 마리가 그곳에서 그를 죽였고, 그의 배는 곧 함대의 나머지와 함께 가라앉았다. 살아남은 사람은 파도의 여왕호의 일등 항해사 피츠시먼스 단 한 명이었다.\n\n망자들은 조용히 있지 않았다. 용맹호의 선창 깊숙이, 선장 할린도르는 탐욕에 사로잡혀 검게 그을린 보주 하나를 숨겨 두었다. 저주받은 팔레스의 눈이었다. 그 저주는 몇 해 뒤 가라앉은 선원들에게까지 뻗쳐 그들을 언데드로 묶었다. 그 속에서도 정신을 지킨 것은 일등 항해사 스넬리그뿐이었고, 그의 유령은 지금도 근처 해안을 걷고 있다.",
	["s:1437:menethil bay"] = "메네실 만은 항구와 던 모로의 절벽 사이, 바라딘 만의 후미 안에 접혀 들어가 있다.\n\n만 입구 근처에는 날쌘물수리호의 잔해가 부서진 선체를 물속에 묻은 채 놓여 있다.",
	["s:1437:menethil harbor"] = "누구든 가장 먼저 눈에 띄는 것은 성벽이다. 반은 바위 위에, 반은 바다 위에 자리한 항구 마을을 두꺼운 돌벽이 에워싸고 있다. 그 위로 네 개의 탑이 솟아 바다와 길을 함께 지켜보며, 들어가는 길은 다리와 밀물, 그리고 본토로 이어지는 숨겨진 지하 통로뿐이다.\n\n이곳에 처음 조선소를 세운 것은 오크였다. 1차 대전쟁 이후 대족장 오그림 둠해머는 로데론의 지상 방어선을 넘어 호드를 실어 나를 함대를 짓기 위해 이 해안을 골랐고, 그러기 위해 카즈 모단의 드워프 광산에서 철과 목재를 빼앗았다. 2차 대전쟁이 끝나자 얼라이언스가 이곳을 차지해 자기 것으로 재건했고, 대제독 데일린 프라우드무어는 로데론의 왕 테레나스 메네실 2세를 기려 이곳을 메네실 항구라 이름 지었다.\n\n그 뒤로 여러 해 동안 랩터들이 언덕에서 나와 마을을 습격했다. 결코 대규모는 아니었지만, 충분히 잦았다.",
	["s:1437:menethil keep"] = "메네실 항구 위로 네 개의 탑이 솟아, 엄격한 수호자처럼 아래 마을을 지켜본다. 이것이 메네실 요새이다.",
	["s:1437:mosshide fen"] = "이끼가죽 수렁은 저습지 동부의 물에 잠긴 땅으로, 그 땅은 이끼가죽 놀의 야영지들로 조각나 있다. 부족은 수렁을 차지하고 늪 깊숙이 너무 멀리 들어온 자는 누구든 붙잡아 잡아먹는다.",
	["s:1437:raptor ridge"] = "랩터 마루는 저습지 동부, 용아귀부족 관문 북서쪽에 솟아 있으며, 그 비탈과 동굴에는 랩터가 가득하다. 깊은 곳에서는 무쇠턱 우두머리랩터가 알을 품고 있다.",
	["s:1437:saltspray glen"] = "소금물 습지대는 저습지가 바라딘 만과 만나는 곳, 푸른아가미 습지대와 아이언비어드의 고분 사이에 있다. 그 이름은 바람에서 왔다. 만에서 바람이 거세게 불면 바다는 이 해안의 어느 곳보다 멀리 이곳 내륙까지 물보라를 던져, 마침내 땅 자체가 소금으로 미끈거리게 된다. 근처의 늪과 마루처럼 이 습지대 곳곳에도 랩터들이 빽빽이 둥지를 틀고 있다.",
	["s:1437:sundown marsh"] = "저습지 북서쪽 깊숙한 곳에는 해몰이 늪이 있으며, 악어와 놀, 랩터, 늪괴물, 수액괴물이 들끓어 대부분의 여행자를 멀리한다. 그 한가운데에는 풍차가 딸린 작은 돌집, 스위프트기어 정거장이 서 있는데, 프래드 스위프트기어와 웨나 실크비어드가 이곳에 보금자리를 마련했다. 두 사람은 늪이 내놓는 것들, 진흙탕에서 건져 낸 기이한 물건들과 다른 곳에서는 좀처럼 찾을 수 없는 제조법을 거래한다.",
	["s:1437:thandol span"] = "저습지와 아라시 고원 사이의 틈에는 두 개의 거대한 돌 아치가 걸쳐 있다. 드워프의 손으로 세워져 삼대에 걸쳐 앤빌마 가문이 지켜 온 다리이다. 이 다리는 세 망치의 전쟁 이후, 아이언포지가 맹금의 봉우리에 있는 와일드해머 동족과의 신의를 지키려 했을 때 세워졌다. 다리는 두 드워프 왕국 사이의 길이자 상징이 되었고, 두 왕국 모두를 부유하게 한 교역을 실어 날랐다.\n\n이제 다리는 상처를 입은 채 서 있다. 캄 딥퓨리와 추악한 발가라스가 검은무쇠 드워프를 이끌고 교각을 공격해, 두 아치 가운데 하나를 완전히 무너뜨리고 나머지 하나마저 거의 빼앗았다. 드워프 병력은 남은 것을 지키고 근처의 던 모드르 마을을 되찾기 위해 맹렬히 싸웠고, 그 싸움에서 많은 이가 목숨을 잃었다. 그중에는 설리 발루와 에버니저 러스트록, 그리고 냉혈한 롱브레이드의 형제도 있었다. 검은무쇠 드워프는 아직 잔해를 차지하고 있으며, 추악한 발가라스도 여전히 그들 사이에 살아 있다.",
	["s:1437:thelgen rock"] = "텔겐 바위굴은 저습지 남부에 솟아 있으며, 그 동굴은 산속 깊이 뻗어 있고 틈마다 비단실을 자아내는 독거미로 가득하다. 더 깊은 굴 어딘가에는 거미 떼가 지키는 인센디사이트 광맥이 있다.",
	["s:1437:whelgars excavation site"] = "메네실 항구 동쪽의 발굴지는 한때 기억보다 오래된 땅을 파 들어가던 드워프들의 조용한 일터였다. 그러다 얼룩무늬 랩터들이 이곳을 덮쳐 발굴꾼들을 자신들의 발굴지 위 능선에 몰아넣었다. 그들은 버티지 못하고 발굴지를 버린 채 큰길에서 벗어난 곳에 직접 차린 야영지, 웰가르의 은신처로 물러났다.\n\n그들이 남기고 간 것은 아직 반쯤 드러난 채로 있다. 이제는 살아 있는 화석과 오래된 정령들이 구덩이를 거닐며, 녹슬어 가는 곡괭이들에는 아랑곳하지 않는다.",
	["s:1438:aldrassil"] = "알드랏실은 그늘 협곡의 심장부에 솟아 있으며, 그 가지 안에 마을 하나를 품을 만큼 거대하게 자란 나무이다. 아래 마을이 닿지 않는 맨 꼭대기에는 테나론 스톰그립이 보금자리를 틀고, 거대한 나무의 우듬지에서 협곡을 지켜본다.",
	["s:1438:banethil barrow den"] = "바네실 지하굴은 나이트 엘프가 잠든 발톱의 드루이드들을 평화로이 쉬게 하려고 세운 성스러운 지하굴이다.\n\n그 평화는 이제 깨졌다. 타락한 나무옹이 퍼볼그들이 아래층 굴과 위층 굴을 점령했고, 한때 신성했던 이 땅은 이제 나이트 엘프가 홀로 거닐 수 있는 곳이 아니다.",
	["s:1438:banethil hollow"] = "돌라나르와 다르나서스 사이의 길 남쪽으로 협곡이 파고들어 있으며, 그 비탈은 너무 가까이 다가오는 여행자를 매복해 덮치는 적대적인 퍼볼그들이 차지하고 있다. 동굴 안쪽에는 땅속에 묻힌 바네실 지하굴이 있다. 위쪽 길에서는 조심하는 것이 좋다.",
	["s:1438:cleft"] = "바위 동굴은 돌라나르 북서쪽에 있으며, 난도질꾼 우르살이 이끄는 타락한 나무옹이 퍼볼그의 소굴이다. 그들은 다르나서스로 가는 길의 여행자를 매복해 덮치고, 잠든 드루이드 무리를 안에 가두어 두고 있다. 달의 여사제 아마라와 그녀의 호위병들이 입구 근처 길에서 감시를 서고 있다.",
	["s:1438:darnassus"] = "나이트 엘프는 3차 대전쟁 이후, 그들의 오랜 불멸이 사라졌을 때 다르나서스를 세웠다. 많은 이들이 갑작스레 찾아온 노화와 나약함의 무게를 견디지 못했다. 슬픔에 잠긴 드루이드 몇몇은 영원한 세계와의 유대를 되찾기 위해 새로운 세계수를 심기로 결심했다. 말퓨리온 스톰레이지가 실종되자, 판드랄 스테그헬름이 대드루이드의 자리를 이어받아 그 일을 이끌었다. 그들이 키운 나무 텔드랏실은 해안에서 솟아올라 그 꼭대기가 구름을 뚫었고, 나이트 엘프는 그 가지 사이에 동족이 살아남았음을 증명하는 도시를 세웠다.\n\n다르나서스는 인간과 드워프의 비좁고 성벽에 둘러싸인 도시들과 달리 하늘을 향해 열려 있다. 도시는 넓은 호수를 둘러싸고 세워졌으며, 호숫가는 우아한 다리로 이어져 있고, 길에는 낙엽이 양탄자처럼 깔려 있다. 달의 신전은 대여사제 티란데 위스퍼윈드와 엘룬의 자매단의 본거지로서 나무들 위로 솟아 있다. 도시는 처음 세워진 목적 그대로 남아 있다. 평온한 안식처이자, 필멸과 함께 사는 법을 배워 가는 한 종족의 기념비로서.",
	["s:1438:dolanaar"] = "돌라나르는 텔드랏실 중동부, 그늘 협곡 남서쪽에 서 있으며, 그 뿌리와 밧줄 다리는 거대한 나무 자체에 엮여 있다. 섬의 길들 한가운데에 자리한 덕분에 이곳은 오래전부터 오가는 이들의 중심지였고, 주변에서 벌어지는 모든 일의 맥박을 느끼는 마을이었다.",
	["s:1438:fel rock"] = "돌라나르 북쪽에는 한때 아름다웠으나 이제는 타락한 동굴이 있다. 그렐들이 그 어두운 굴에 들끓고, 안에는 사티로스 군주 멜레나스가 살며 그 존재만으로 이곳을 오염시켰다. 나이트 엘프 드루이드 탈론카이 스위프트루트는 한때 아름다웠던 땅이 이제 불길한 곳이 된 것을 두려움 속에 지켜본다.",
	["s:1438:gnarlpine hold"] = "텔드랏실의 남서쪽 끝 구석에는 나무옹이 퍼볼그의 보금자리인 나무옹이 요새가 서 있다.",
	["s:1438:lake alameth"] = "알아메스 호수는 돌라나르 남쪽에 넓게 펼쳐진 텔드랏실의 큰 호수 가운데 하나이다. 호숫가에는 작은 부두 하나 말고는 눈에 띄는 것이 거의 없다.\n\n요즘 그 고요는 흐려졌다. 분노한 나무정령들이 호숫가에 출몰하고, 이제 호수는 홀로 걷기에 안전하지 않다.",
	["s:1438:oracle glade"] = "신탁의 숲은 텔드랏실 북서쪽에 있으며, 거대한 나무의 달샘 가운데 최초이자 가장 강력한 달샘을 품고 있다. 이곳에는 신탁의 나무가 서 있는데, 넓은 줄기가 곰 위에 앉은 독수리 모양의 가지로 뻗어 오른다. 많은 이가 평범한 성장으로는 그런 모습이 될 수 없으며, 오직 자연의 마법만이 그것을 빚어냈다고 속삭인다.\n\n이 나무는 드루이드들과 함께 텔드랏실이 자라는 것을 지켜보았다.\n\n근처에 핏빛깃털 하피가 둥지를 틀어 나무를 위협하자, 작은 파수꾼 부대가 그들을 막으러 파견되었다.",
	["s:1438:pools of arlithrien"] = "다르나서스 남쪽, 텔드랏실 서부의 아리스리엔 연못은 한때 평화로웠다. 나무옹이 퍼볼그들이 이 지역을 점령하자 나이트 엘프들은 그곳의 달샘을 버렸다. 달샘은 아직도 연못 사이에 돌보는 이 없이 서 있으며, 이제는 적대적인 야생 동물의 보금자리가 되었다.",
	["s:1438:ruttheran village"] = "루테란 마을은 세계수가 물과 만나는 텔드랏실의 뿌리에, 저 높이 다르나서스 아래에 자리하고 있다. 그 건물들은 수도의 것에 비해 소박하지만 아주 깔끔하게 관리되어 있어, 크기보다 소박함에 자부심을 갖는 듯하다.\n\n이곳에서 칼도레이는 히포그리프 둥지를 돌보며, 알을 모아 보살피고 새끼를 날 수 있을 때까지 기른다. 조용한 일이며, 평소에는 위쪽 도시를 뒷받침하기 위해 마을을 꾸려 가는 사람들이 별다른 인정도 바라지 않고 해내는 일이다.\n\n그렇다고 마을이 일만 하는 것은 아니다. 한여름 불꽃 축제가 오면 화로에 불이 밝혀지고, 히포그리프 알을 돌보고 배에 짐을 싣던 바로 그 손들이 축제로 향한다.",
	["s:1438:shadowglen"] = "텔드랏실의 가지 아래, 섬의 북동쪽 끝에 포근히 자리한 곳에 한 번도 온전한 햇빛을 보지 못하는 숲이 있다. 그늘 협곡은 늘 황혼에 잠겨 있으며, 한쪽을 제외한 사방이 산으로 둘러싸여 있다. 남쪽으로만 바위가 갈라져 돌라나르로 가는 길이 빠져나간다.\n\n숲 한가운데에는 거대한 나무 알드랏실이 서 있는데, 마치 협곡 전체가 그것을 중심으로 놓인 듯 빈터를 완전히 압도한다. 북서쪽으로는 땅이 열려 그늘 거미굴이 나 있다. 협곡을 둘러싼 언덕에 새겨진 어두운 틈이다.",
	["s:1438:shadowthread cave"] = "그늘 거미굴은 텔드랏실의 뿌리, 그늘 협곡의 북서쪽 구석에 있다. 이곳은 언제나 섬의 거대한 거미들의 것이었지만, 최근 들어 거미들이 불안해지면서 동굴은 더 위험해졌다.\n\n가장 깊은 곳에는 무리 가운데 가장 큰 사악한 기티스가 살며, 너무 깊이 들어온 어린 칼도레이를 여럿 파멸시켰다.",
	["s:1438:starbreeze village"] = "별바람 마을은 한때 나이트 엘프의 것으로, 그늘 협곡 남동쪽에 작은 집들이 모여 있는 곳이었다. 이제 나이트 엘프는 모두 떠났고, 집들은 타락한 나무옹이 퍼볼그들이 차지했다. 우루손이 마을 길을 서성이고, 그 가장자리에는 꿈을 먹는 자 페로시타스가 도사리고 있다. 그 짐승의 존재만으로도 마을이 옛 모습에서 얼마나 추락했는지 알 수 있다.",
	["s:1438:wellspring lake"] = "생명의 호수는 텔드랏실 자체의 깊은 곳에 있는 샘에서 물을 얻으며, 넘친 물은 생명의 강이 되어 흘러나간다. 나이트 엘프 어부들은 한때 이 고요한 물을 좋아했다. 이제 이곳에 사는 나무정령들은 타락했고, 나이트세이버와 거미들이 주변 땅으로 스며들어, 한때 평화롭던 낚시터는 위험한 곳이 되었다.",
	["s:1438:wellspring river"] = "생명의 강은 텔드랏실 깊은 곳의 샘에서 발원해, 생명의 호수에서 북쪽으로 나무 끝자락까지 흐른 뒤 거대한 폭포가 되어 아래 바다로 떨어진다.\n\n이제 미쳐 버린 나무정령들이 강둑을 누비며 가까이 오는 자는 누구든 공격한다.",
	["s:1439:ametharan"] = "아메스아란의 폐허는 어둠의 해안의 아우버다인 남동쪽에 있으며, 마을의 무언가가 아직도 그곳을 걷고 있다.\n\n아즈샤라 여왕은 한때 아메스아란을 바샬아란의 쌍둥이 도시로 세우고, 총애하는 명가를 그 시장과 엘룬의 신전에 앉혔다. 그 위에 그녀는 알살락스의 탑에 머물던 강력한 마법사 아트리쿠스 나라신을 두었다.\n\n대분리가 닥쳐 마을이 이미 무너져 내리고 있을 때, 사람들은 그것만이 자신들을 구해 줄 수 있다는 듯 땅에 매달렸다. 아트리쿠스 나라신이 그들 사이에 나타나, 다가올 파멸에서 그들을 구하고 자신이 지닌 영혼석 안에서 영원한 생명을 주겠다는 주문을 약속했다. 그가 주문을 외우자 그의 주변의 엘프들은 죽었다. 그가 준 영원은 구원이 아니라 감옥이었고, 그 뒤로 아메스아란에 머물러 온 것은 그들의 삶이 아니라 영혼이다.\n\n폐허 사이에는 마을의 몰락 이야기를 새긴 거대한 석판 두 개가 아직 서 있다. 그것을 읽으러 온 한 파수꾼은 다 읽기도 전에 안식하지 못한 명가의 습격을 받고 달아났다.",
	["s:1439:auberdine"] = "아우버다인은 대분리가 땅을 부순 곳, 고대 칼도레이 제국의 거대한 도시들을 삼킨 해안에 서 있다. 그 뒤로 어둠의 해안에 세우려던 정착지는 모두 실패했고, 장막의 바다에 면한 이 마을만이 예외였다.\n\n이 마을은 나이트 엘프 사회의 다른 곳과 다르게 자랐다. 항구는 동부 왕국의 배와 상인들을 불러들이고, 거리는 드워프와 노움, 인간, 심지어 하이 엘프로 가득하다. 그래서 아우버다인은 나이트 엘프 마을이라면 그럴 까닭이 없을 만큼 밝게 불을 밝히고, 이방인들을 위해 표지판을 두 가지 말로 적어 둔다. 다르나서스는 이 때문에 이곳을 얕본다. 한때 이 마을을 찾았던 브롤 베어맨틀은 이곳 사람들을 추방자와 부적응자보다 나을 것이 없다고 여기며, 이곳에 주둔한 파수꾼들은 자신들이 지키는 사람들과 거리를 둔다. 그러나 한때 이곳에 주둔했던 샨드리스 페더문은 이곳을 웃음소리가 울려 퍼지던 곳으로 기억한다.\n\n등대 근처에는 한때 엘프 엘루라가 지휘하던 배의 잔해가 아직도 바위에 걸려 있으며, 배가 가라앉을 때 싣고 있던 엘루나이트 광석도 함께 사라졌다.",
	["s:1439:bashalaran"] = "바다가 솟아올라 세계를 부수기 전, 아즈샤라 여왕은 어둠의 해안 북부에 총애하는 명가를 위해 쌍둥이 마을, 아메스아란과 바샬아란을 세웠다. 그녀는 강대한 마력을 지닌 엘프 아트리쿠스 나라신에게 그곳을 다스리게 했고, 그의 아래에는 비전 기술에 능한 만큼 무예에도 뛰어난 마법사 아스테리온이 있었다. 그는 바샬아란 사람들 사이에 살며 아메스아란의 백성을 돌보러 자주 오갔다. 그 시절 쌍둥이 도시에는 시장과 엘룬의 신전이 있었고, 여왕의 총애가 그곳을 빛냈다.\n\n최초의 영원의 샘이 산산조각 났을 때, 두 도시는 폐허가 되었다. 그런데 어느 때인가 아트리쿠스 나라신은 자신의 마법을 자기 부관에게 돌려, 아스테리온을 월장석 봉인 안에 묶고 바샬아란의 돌 사이에 가두었다. 주인이 왜 하수인에게 등을 돌렸는지는 지금 살아 있는 누구도 말할 수 없다. 아스테리온은 길고 고통스러운 생애 내내 감옥을 견뎠고, 마침내 죽었을 때 죽음이 그를 풀어 주지 않았음을 알게 되었다. 그의 영혼은 그의 육신이 그러했던 것만큼 단단히 묶여 있었다.",
	["s:1439:blackwood den"] = "어둠의 해안 남쪽 끝, 잿빛 골짜기와의 경계 근처에는 흩어진 퍼볼그 야영지와 작은 동굴이 모여 검은나무일족 소굴이라 불리는 곳을 이루는데, 때로는 검은나무 요새라고도 불린다. 그곳을 차지한 퍼볼그들은 타락해 있으며, 한때의 모습이 무엇이었든 뒤틀려 버렸다.\n\n동굴 안에는 볼코르라는 나이트 엘프가 홀로 퍼볼그들 사이에 포로로 붙잡혀 있다.",
	["s:1439:cliffspring falls"] = "절벽 폭포는 폭포수 강의 발원지로, 한때 그 가장 맑은 물은 어둠의 해안 전체의 식수였다. 그 물은 이제 깨끗하지 않다. 폭포가 솟아 나오는 동굴은 더럽혀졌고, 그 타락은 물살을 따라 한때 자신이 먹여 살리던 지역으로 퍼져 내려간다.\n\n그 이유에 대해서는 의견이 엇갈린다. 어떤 이들은 악령의 숲 탓이라며, 그 폐허가 된 숲에서 오염이 그저 스며 나오는 것이라고 말한다. 다른 이들은 동굴 깊은 곳에서 발견된 것을 가리킨다. 물의 근원인 그곳 어둠 속을 이제 나가가 기어 다니고 있다.",
	["s:1439:cliffspring river"] = "폭포수 강은 어둠의 해안 북부에서 절벽 폭포로부터 바다까지 흐른다. 그 물은 폭풍비늘 나가에게 오염되어, 그 물을 마시는 야생 동물은 흔히 병에 걸린다.",
	["s:1439:grove of the ancients"] = "고대정령의 숲은 오래된 나이트 엘프 신전으로, 그 돌들은 어둠의 해안 산속에서 세차게 흐르는 성난굽이 강 주위에 자리 잡고 있다. 이곳에는 지식의 고대정령 오누가 잠든 드루이드 하나와 상인 두 명과 함께 머물며, 고대정령 의회가 지금도 이곳에 모인다.",
	["s:1439:long wash"] = "침식지는 아우버다인에서 남쪽으로 아메스아란 서쪽 바다까지 이어지며, 그 이름과 달리 어둠의 해안에서 가장 짧은 해안이다. 끊임없이 흐린 하늘 아래 잿빛 모래가 깔려 있다. 파도는 떠밀려 온 나무와 죽은 바다 생물의 사체 말고는 거의 남기지 않는다. 해안을 따라 멀록들이 보인다.",
	["s:1439:masters glaive"] = "어둠의 해안 남서쪽에는 반쯤 땅에 묻힌 거대한 두개골이 있고, 그 뼈에는 아직도 아다만틴 검이 박혀 있다. 이것은 고대 신의 전령인 미끄러지는 자 소고스였으며, 그 칼날은 지배자의 무덤이라 불린다.\n\n렘트레블의 발굴현장에서 발굴된 석판들이 이곳에서 일어난 일을 전해 주었다. 티탄은 소고스에 맞서 스무 명의 돌 거인을 보냈는데, 뒤이은 전투가 너무나 끔찍해서 그 끝을 본 것은 단 하나뿐이었다. 스물 가운데 가장 컸던 크론이다. 소고스의 촉수가 그를 휘감았을 때, 크론은 그것을 떨쳐 내려 싸우지 않았다. 그는 괴물의 두개골에 점점 더 가까이 끌려가도록 자신을 내맡겼고, 마침내 내리칠 수 있을 만큼 가까워졌다. 소고스를 죽인 일격은 그 괴물의 손아귀 안에서 내리쳐졌고, 두개골에 박힌 채 남은 검은 그 승리의 이름을 얻었다.\n\n그 뒤로 황혼의 망치단이 이곳을 차지하고 소고스의 유해를 파헤치며, 크론의 검이 이룬 것을 되돌려 고대 신의 전령을 세상으로 다시 불러내려 하고 있다.",
	["s:1439:mists edge"] = "안개 해안이라 불리는 해안은 어둠의 해안 전체를 따라 이어지며, 이 지역에서 가장 긴 해안선이다.\n\n음울한 곳이다. 잿빛 해변과 음산한 만에는 죽은 바다 짐승의 거대한 사체와 가라앉은 배의 잔해가 널려 있다.\n\n해안 전체를 따라 게들이 종종걸음 치고, 얕은 만에는 멀록들이 도사리고 있어 해안을 걷는 이에게는 늘 위협이 된다.",
	["s:1439:remtravels excavation"] = "렘트레블의 발굴현장은 탐사꾼 렘트레블의 이름을 딴 어둠의 해안의 발굴지이다. 발굴 중에 그는 신비한 기운으로 웅웅거리는, 전에 없던 화석을 찾아냈지만, 건망증 심한 이 탐사꾼은 그 뒤로 그것을 어디에 두었는지 잊어버렸다.\n\n발굴지 자체는 위험해졌다. 자갈부싯돌 트로그가 굴을 차지했고, 발굴로 파헤쳐진 거대한 골렘들이 이제 그 안에서 꿈틀댄다.",
	["s:1439:ruins of mathystra"] = "어둠의 해안 북부, 알살락스의 탑 너머에는 마시스트라의 폐허가 있다. 대분리 이전에 이곳은 명가의 시대에 세워진 나이트 엘프의 도시였다. 영원의 샘이 스스로 찢어지고 그 아래에서 세계가 부서졌을 때, 마시스트라는 다른 많은 것과 함께 폐허가 되었고, 살아남은 나이트 엘프들은 그곳을 재건하러 돌아오지 않았다. 대신 그들은 더 남쪽 해안의 작은 마을들로 물러났고, 폐허는 뒤에 남겨졌다.\n\n무너진 돌 사이에는 옛 명가의 유물이 아직 흩어져 있고, 젊은 나이트 엘프들은 이따금 그것을 찾아 마시스트라를 뒤진다. 그들은 자기 종족이 한때 세운 것의 폐허 사이를 배회하는 유령 표범들을 경계한다.",
	["s:1439:tower of althalaxx"] = "대분리의 시대, 아즈샤라 여왕이 명가를 다른 모든 이 위에 올려놓았을 때, 그녀는 아트리쿠스 나라신이라는 엘프에게 쌍둥이 마을 아메스아란과 바샬아란을 다스리게 했다. 아트리쿠스는 처음에는 그럭저럭 그녀를 잘 섬겼지만, 그 일에 싫증을 느끼고 마을을 떠나 알살락스라는 자신만의 탑에서 나날을 보내게 되었다.\n\n만 년이 지나, 그 탑에 대해 오래 속삭여지던 소문이 사실로 드러났다. 어둠의 실타래 교단이라 자칭하는 교단이 그곳에 모였는데, 흑마법사들과 사티로스 하나가 그중에 있었고, 그 우두머리는 다름 아닌 아트리쿠스 나라신 자신이었다. 그들의 목적은 알 수 없었지만, 교단이 어둠의 의회를 따르고 있으며 알살락스가 그 오랜 음모의 그물을 이루는 또 하나의 실이 되었다는 사실이 드러났다.",
	["s:1439:twilight vale"] = "아메스아란 남쪽에서 잿빛 골짜기와의 경계까지 이어지는 숲은 황혼의 계곡이라 불린다. 타락한 퍼볼그와 야생 나이트세이버, 광포한 곰들이 이 숲에 출몰하며, 여행자들은 나무 아래를 헤매지 말고 길을 따라가라는 조언을 듣는다.",
	["s:1439:wildbend river"] = "성난굽이 강은 산에서 병을 싣고 내려온다. 악령의 숲에서 흘러나온 피멍울 강이 고대정령의 숲 근처 어둠의 해안 남부로 이어진 것이다. 그 물은 오염된 채 흐르고, 악령의 숲의 타락은 물살을 따라 이 낮은 땅으로 내려온다.",
	["s:1440:astranaar"] = "아스트라나르는 잿빛 골짜기 한가운데의 섬에서 솟아 있으며, 이 지역 나이트 엘프 정착지 가운데 가장 크고, 물 위로 길을 잇는 두 개의 다리로만 닿을 수 있다. 호수는 이곳을 주변 숲과 떼어 놓아, 분쟁 중인 땅 한가운데서 고요하고 방어하기 좋은 곳으로 만든다.\n\n묘지는 물가에 있으며, 고요히 늘어선 비석 사이에 마을의 망자들을 품고 있다.\n\n마을 너머 북쪽에서는 엉겅퀴 퍼볼그가 세력을 불리고 있고, 아스트라나르에서는 그들이 언젠가 그 힘을 마을 자체로 돌릴 용기를 낼지도 모른다는 두려움이 있다.",
	["s:1440:bathrans haunt"] = "배스랜 서식지의 기둥들은 한때 칼도레이 유적의 일부로, 나이트 엘프가 아직 잿빛 골짜기의 이 지역을 거닐던 시대에 세워졌다. 그 시대는 지나갔고, 엘프들은 물러갔으며, 대리석은 갈라지고 무너지도록 버려졌다.\n\n지금은 비어 있지 않다. 포세이큰 요원들, 곧 약초꾼들과 그들을 지키는 폭력배들이 부서진 기둥 사이에 자리를 잡았고, 그들이 머무는 곳마다 땅도 그에 걸맞게 응답했다. 풀은 갈색으로 변했고 꽃은 시들었다. 그들은 무너진 돌 사이에 임시 실험실을 세우고 자기들만의 목적으로 이 지역의 약초를 다루고 있다.\n\n그들을 이곳으로 이끄는 가장 큰 이유는 근처 다른 곳에서는 찾을 수 없는 식물, 배스랜의 머리카락이다. 이 땅을 홀로 차지할 만한 가치가 있을 만큼 귀한 약초이다.",
	["s:1440:blackfathom deeps"] = "옛 도시 조람이 바다 속으로 가라앉은 조람 해안 아래에는, 한때 엘룬의 신전이었던 라타르라잘의 물에 잠긴 전당들이 있다. 대분리가 그것을 완전히 파괴했다고 여겨졌고, 수천 년 동안 바다가 그것을 품고 있었다.\n\n그러다 황혼의 망치단이 속삭임과 불길한 꿈에 이끌려 신전이 변해 버린 물속 동굴로 찾아왔다. 교단은 그 깊은 곳에서 헤아릴 수 없이 많은 무고한 이를 제물로 바쳤고, 그 대가로 임무를 받았다. 고대 신의 총애를 받는 괴물, 포식자 아쿠마이라는 거대한 히드라를 세상에 풀어놓을 그날까지 기르고 지키라는 것이다. 이제 이곳은 검은심연이라 불리며, 그 이름은 잘 어울린다.",
	["s:1440:bloodtooth camp"] = "붉은송곳니 야영지는 팔파렌 강 서쪽, 잿빛 골짜기 남쪽 달샘의 남서쪽에 있다. 이곳의 이름은 이곳을 차지한 퍼볼그 부족의 족장 란 블러드투스에게서 왔다.\n\n이 퍼볼그들도 한때는 다른 동족과 다를 바 없었지만, 타락이 그들 모두를 사로잡았고, 이제 야영지는 다가오는 모든 이방인에게 적의로 응답한다.",
	["s:1440:bough shadow"] = "잿빛 골짜기의 나무들이 빽빽하고 오래된 숲의 노래 너머, 어둠의 나무에는 에메랄드의 꿈으로 가는 차원문 가운데 하나가 있다.\n\n녹색용군단이 그것을 지킨다. 비룡 판팀과 꿈추적자가 통로를 지켜보고, 용족들은 셋씩 순찰대를 이루어 주변 숲을 누빈다. 에메랄드 신탁자 하나를 가지 수호병과 나무 파수병이 양옆에서 호위하며, 긴 감시 속에 같은 땅을 거듭 밟는다.",
	["s:1440:demon fall canyon"] = "악마벼락 협곡은 오크가 오랜 속박에서 벗어난 순간의 상처를 간직하고 있다.\n\n이곳에서 구덩이 군주 만노로스는 그롬마쉬 헬스크림, 스랄과 맞붙었다. 악마는 스랄을 쓰러뜨렸지만, 그롬의 도끼를 피할 만큼 빨리 몸을 돌리지 못했고, 도끼는 그의 가슴에 박혔다. 만노로스의 죽음은 불길과 빛으로 터져 나갔고, 악마를 삼킨 바로 그 불길이 그롬의 생명도 앗아 갔다. 오크들은 그가 자신을 희생한 곳에 그의 이름을 붙였다. 불타는 군단이 그들 종족에게 건 저주가 깨진 곳이 바로 그곳이었기 때문이다.\n\n지금도 많은 오크가 그 자유의 대가를 치른 전사를 기리러 이곳을 찾고, 그를 기억하는 기념비가 서 있다. 그러나 땅은 여전히 지옥의 기운에 물들어 있고, 이제는 하급 악마들이 협곡에 출몰한다.",
	["s:1440:demon fall ridge"] = "악마벼락 협곡 위로 마루가 부서진 채 솟아 있으며, 그 비탈과 옆구리에 파인 땅굴은 하급 악마들에게 점령당했다. 햇빛이 닿지 않는 더 깊은 곳에서는 잿빛 골짜기에 모인 악마 집회를 다스리는 공포의 군주, 탐색자 디아토루스가 기다린다. 그는 어둠 속에서 알현을 받고, 하급 마귀들은 위쪽 마루를 지킨다.",
	["s:1440:dordanil barrow den"] = "도르다닐 지하굴은 오래전부터 나이트 엘프 드루이드들의 안식처였다. 그들은 몸은 그곳에서 잠들고 영혼은 자유로이 떠돈다. 잠든 이들에게 눈독을 들인 것은 포세이큰이었다. 그들은 드루이드들을 떠도는 영혼과 끊어 놓았다. 그 실험은 드루이드들을 죽이지 않았다. 그들을 미치게 했다.\n\n이제 지하굴에는 평화롭게 잠든 이가 없다. 포세이큰 암살자들이 보이지 않게 그 안을 오가고, 끊어진 드루이드들의 분노한 영혼은 돌아갈 곳을 잃은 채 흙더미 안을 날뛴다. 그들 가운데 다른 이들보다 강한 영혼 셋이 머물고 있다. 우실 문콜, 마보리스 클라우드브레이크, 타닐 다크우드이다.",
	["s:1440:falfarren river"] = "팔파렌 강은 잿빛 골짜기를 거의 반으로 가른다. 서쪽에는 아스트라나르 아래의 나이트 엘프가 있고, 동쪽에는 오크들이 토막나무 주둔지를 지키고 있다. 강은 걸어서 건널 수 있을 만큼 얕고 큰 어려움 없이 건널 수 있을 만큼 좁으며, 비가 둑을 넘치게 불릴 때만 예외이지만, 그래도 경계선을 이룬다. 두 종족 모두 말하지 않아도 아는 경계이다.\n\n강물은 하이잘 산의 비탈에서 솟아 폭포를 거쳐 사비안의 호수로 떨어진 뒤, 토막나무와 어둠의 터 사이를 흘러, 대부분의 여행자가 잿빛 골짜기를 건널 때 쓰는 큰 다리 아래를 지나고, 은빛날개 전초기지와 정화의 달샘을 지나, 북쪽 산맥 아래 땅속으로 스며들어 불모의 땅으로 향한다.\n\n지옥불 언덕 근처에서 강은 또 다른 위험을 숨기고 있다. 그곳의 수면 아래에는 늪괴물이 도사리고 있어, 물속에 너무 오래 머무는 것은 무엇이든 덮친다.",
	["s:1440:fallen sky lake"] = "잿빛 골짜기의 은빛날개 전초기지 남쪽에는 작은 호수가 있고, 그 물은 외딴 섬 하나를 둘러싸고 있다. 그 섬에는 그늘덤불족의 원로인 그늘덤불 신탁자가 살며, 더 적은 수의 그늘덤불족이 물가를 둘러싸고 주변의 갈대와 덤불에서 물을 지켜본다.",
	["s:1440:felfire hill"] = "지옥불 언덕은 3차 대전쟁 때 지옥불정령들이 불타며 하늘에서 떨어져 이곳 땅을 강타한 상처를 아직도 안고 있다. 그 뒤로 악마들이 머물며, 더러운 것들이 바위 사이에 굴을 틀고 있다.\n\n호드는 언덕으로 이어지는 두 다리를 모두 요새화하고, 악마들이 근처 정착지로 쏟아져 나오지 못하도록 지키고 있다.",
	["s:1440:fire scar shrine"] = "불타버린 신전은 잿빛 골짜기 남서쪽에 서 있으며, 어둠의 의회의 악마적 영향으로 타락해 거대한 악의 장소가 되었다. 오크 흑마법사 일크루드 마그스럴은 한때 이곳에 머물며 어둠의 실타래 교단의 우두머리 아트리쿠스 나라신을 섬겼다.\n\n이제는 바위에 남은 오염에 이끌린 악마들이 신전에 들끓는다. 그들 가운데 아크릴루스라는 파멸의 수호병이 이따금 이 지역에 나타난다고 알려져 있는데, 타락이 얼마나 깊은지 보여 주는 드물고 위험한 징조이다.",
	["s:1440:forest song"] = "숲의 노래는 잿빛 골짜기의 숲에 있는 오래된 나이트 엘프 유적으로, 오랫동안 이끼와 기억에 내맡겨져 있었다. 한동안 그곳에는 거의 아무도 없었다.\n\n그러다 드루이드 케이네스 스틸윈드가 이곳을 자기 것으로 삼았다. 유적의 유일한 거주자인 그는 그 돌 위에서 이 지역의 포세이큰에 맞선 싸움을 지휘했다. 잊힌 곳이 파수꾼의 초소가 되었고, 그곳을 지킨 것은 수가 아니라 떠나기를 거부한 한 드루이드였다.",
	["s:1440:greenpaw village"] = "푸른발 마을은 족장 머거트와 주술사 오크포가 이끄는 퍼볼그, 악취숲 부족의 보금자리이다. 이곳의 곰인간들은 타락해 있다.",
	["s:1440:howling vale"] = "멜산드리스의 제단이 서 있는 골짜기로 동굴 하나가 열려 있다. 그 돌에는 엘룬을 찬미하는 고대의 글귀가 새겨져 있고, 그 위에는 다르나서스어로 이렇게 적혀 있다. 진실은 길을 인도하는 빛이다.\n\n이 제단은 엘룬의 낫을 맡았던 멜산드리스를 기려 벨린데 스타송의 어머니가 세웠다. 멜산드리스가 죽자 낫은 이곳에 안치되어 제단 안에 숨겨졌다. 그것은 다르나서스에서 그 이야기를 담은 책을 발견한 벨린데가 골짜기로 와서 직접 찾아낼 때까지 잊혀 있었다.\n\n시간이 흘러 제단은 폐허가 되었고, 테로울프라는 늑대인간 무리가 그곳을 점령해 동굴을 소굴로 삼았다. 바위 사이로 메아리치는 그들의 울부짖음이 골짜기에 지금의 이름을 안겨 주었다.",
	["s:1440:iris lake"] = "아이리스 호수는 잿빛 골짜기 중북부, 아스트라나르 동쪽이자 샤엘드린의 달샘 서쪽에 있다. 한때 끊김 없던 나이트 엘프 숲의 일부였던 이곳은 악령의 숲에서 퍼져 온 타락에 무너졌고, 물은 병든 누런 초록빛으로 변했다. 이제 뒤틀린 늪괴물들이 호숫가에 출몰하며 엘룬의 눈물을 찾으러 온 이는 누구든 공격한다.",
	["s:1440:kargathia keep"] = "카르가시아 요새는 잿빛 골짜기 동부, 분노의 강 근처 전쟁노래부족 벌목기지 안에 뾰족한 방책들 사이로 솟아 있다. 이곳은 전쟁노래 부족 장교들의 본거지로, 얼라이언스가 대군을 이끌고 기지로 쳐들어올 경우 오그리마에서 증원군을 불러올 수 있는 곳에 자리를 잡았다.\n\n요새의 이름은 황야의 땅의 카르가스와 듀로타의 칼날주먹 만에서도 기려지는 오크 영웅 카르가스 블레이드피스트에게서 왔다. 감독관 고르탁이 그 벽 안에서 기지를 지휘하며 잿빛 골짜기의 나무 베기를 지시한다.",
	["s:1440:lake falathim"] = "팔라딤 호수는 잿빛 골짜기 서부에 있으며, 낮이든 밤이든 여신의 달빛이 늘 물에 닿는 곳이다. 나이트 엘프들은 한때 이곳에 자유로이 와서 헤엄치고 낚시했지만, 멀록들이 호수를 점령해 사나운 곳으로 만들었다. 학자 테로니스는 마지막으로 이 호숫가 근처에서 목격된 뒤 돌아오지 않았다.",
	["s:1440:maestras post"] = "이곳에는 탑 하나와 나이트 엘프의 전당 한 채가 고요히 서 있으며, 몇 안 되는 수비병과 함께, 잿빛 골짜기에서 가장 기이하게도 엘프들 사이에 인간 둘이 있다. 피로 아이언핸드와 정화자 델그렌으로, 이 초소에서 유일한 인간이다.\n\n이곳 병력은 적다. 근처 퍼볼그들 사이에 번지는 타락이 이곳을 지켰을 손들을 빼앗아 가, 초소의 수비는 얇게 흩어져 있다.",
	["s:1440:morshan rampart"] = "몰샨의 망루는 황금길이 불모의 땅에서 북쪽으로 뻗어 나가는 곳에 서 있으며, 북쪽 잿빛 골짜기에서 이 지역으로 밀고 들어오는 얼라이언스를 막기 위해 세워졌다. 전쟁을 위해 세운 투박한 곳이다. 전선을 지키고, 북쪽의 나이트 엘프 마을 아스트라나르를 습격하기 위한 토루와 감시탑들이 서 있다.",
	["s:1440:mystral lake"] = "미스트랄 호수의 물은 한때 나이트 엘프에게 충성하는 정령들이 지켰다. 호수의 수호자로 묶인 존재들이었다. 사릴루스 파울본이 그들을 돌려세웠다. 그는 정령들을 타락시켜, 한때 섬기던 엘프 대신 자신에게 따르게 했다. 지금 호수에서 기다리는 것은 예전의 그것이 아니다.",
	["s:1440:night run"] = "어둠의 터는 땅으로 튀어나온 곶 위에 자리하며, 절벽이 너무 가팔라 오를 수 없다. 그래서 여행자는 팔파렌 강을 따라 거의 사비안의 물가까지 간 뒤 서쪽으로 꺾거나, 라이네나무 북쪽의 좁은 바위 턱을 찾아야 한다. 안에 들어가도 찾을 것은 별로 없다. 부서진 기둥과 무너진 석조물 몇 조각뿐인, 잿빛 골짜기의 세 사티로스 거점 가운데 가장 작고 초라한 곳으로, 사비안과 사티르나르 모두에 비하면 보잘것없다. 이 폐허에 몸을 숨긴 지옥사향 사티로스는 땅 자체가 그들을 지켜 주니 성벽이 거의 필요 없다. 잔해 사이에는 지옥사향 사티로스와 동맹을 맺은 어둠의 실타래 교단의 영혼석 하나가 놓여 있다.",
	["s:1440:nightsong woods"] = "팔파렌 강은 동쪽 숲을 둘로 가르며, 강이 그은 선은 끝나지 않는 전쟁의 전선이다. 강둑 서쪽에서는 은빛날개 파수대가 얼라이언스를 위해 땅을 지키고, 동쪽에서는 전쟁노래 부족이 땅에 말뚝을 박아 두었으며, 이곳에서 두 종족 간의 싸움은 가장 치열하고 끊임이 없다.\n\n더 동쪽에서는 이름 없는 두 번째 강이 또 다른 경계를 이룬다. 한쪽에는 이 숲에서 호드 세력의 심장인 토막나무 주둔지가, 다른 쪽에는 얼라이언스를 대표하는 은빛날개 숲이 있다. 그 강 너머의 땅은 누구의 것으로도 오래 남지 않는다. 숲의 노래의 나이트 엘프, 사티르나르와 사비안의 사티로스, 전쟁노래 오크, 그리고 불타는 군단 자체가 조각조각 차지하고 있다. 그곳에서 도전받지 않고 휘날린 깃발은 하나도 없었다.\n\n싸움터 남쪽에서 숲은 전쟁의 대가를 치렀다. 전쟁노래 부족이 정착지를 세울 목재를 얻으려고 오래된 나무들을 베어 이 지역을 헐벗게 만들었고, 한때 태고의 숲이 끊김 없이 서 있던 곳에는 상처 입은 빈 땅만 남았다.",
	["s:1440:raynewood retreat"] = "이곳에 이름을 준 거대한 나무의 높은 가지 속에는 숲의 수호자이자 세나리우스의 가장 나이 많은 아들 가운데 하나인 오르다누스가 숨어 있다. 그는 자신을 죽이기로 표적 삼은 어둠의 의회 요원들을 피해 이곳에 몸을 숨겼다. 그중 으뜸은 브래린 파이어핸드였다. 그녀는 그의 죽음을 유일한 목적으로 삼아 그에게 자객을 보냈다. 오르다누스는 그 시도에서 살아남았고, 지금도 나무의 높은 가지에 숨어 있다.\n\n그의 아래에서는 세나리온 수호병, 점멸용, 그리고 웃음 자매단이 전초기지에서 감시를 서며, 역병에 물든 악령의 숲으로 들어가는 북쪽 길을 지킨다.",
	["s:1440:ruins of ordilaran"] = "오르딜아란에는 이제 부서진 돌 말고는 남은 것이 거의 없다. 어둠의 실타래 교단이 한때 이 폐허를 자기 것으로 삼고, 너무 가까이 다가오는 자는 누구든 덮칠 준비를 하고 있었다. 그것은 피로 끝났다. 엉겅퀴 퍼볼그가 그들을 몰아내고 폐허를 차지했으며, 광신도들의 시신은 아직도 쓰러진 자리에 흩어져 있다.\n\n잔해 한가운데에는 한때 이름 있고 번듯했던 도시에 뿌리내린 심장나무가 서 있다. 그 도시가 무엇이었는지 말해 줄 것은 그 밖에 아무것도 남아 있지 않다.",
	["s:1440:ruins of stardust"] = "별가루의 폐허는 호수의 섬에 있다. 한때는 성스러움에 잠겨 있었으나, 이제는 썩음에 잠겨 있다. 악령의 숲에서 흘러내린 악마의 오염이 물과 돌 모두에 스며들어, 섬을 병든 누런 초록빛으로 물들였다. 독에 물든 호수로 뒤틀린 늪괴물들이 이제 잔해 사이를 몸을 끌며 지나간다.\n\n그래도 별가루 덤불은 주변의 타락에 물들지 않고 여전히 그곳에서 자란다. 그 잎에는 치유의 효험이 있다고 하며, 썩음이 오기 전 이곳이 어떤 모습이었을지를 여전히 닮은 폐허의 유일한 부분이다.",
	["s:1440:satyrnaar"] = "사티르나르는 잿빛 골짜기 북동쪽의 나무들 사이에 부서진 채 서 있다. 건물들은 오래전에 폐허가 되었지만, 이제 잔해 사이에는 싸늘한심장 사티로스가 보금자리를 튼 천막들이 모여 있다. 숲의 세 사티로스 거점 가운데 사티르나르만이 대체로 온전히 남아 있으며, 토막나무에서 아즈샤라로 가는 길 옆에 자리한 탓에 셋 가운데 가장 닿기 쉽고 가장 치열하게 다투는 곳이 되었다.\n\n싸늘한심장 사티로스가 이곳에서 지키는 것은 은신처만이 아니다. 사티르나르 안에는 어둠의 실타래 교단의 영혼석 하나가 놓여 있는데, 사티로스를 그 교단의 어두운 목적에 묶는 맹약의 징표이다.",
	["s:1440:shady nook"] = "그늘 동굴은 라이네나무 은신처 남쪽이자 푸른발 마을 동쪽에 있는, 잿빛 골짜기에 조용히 접혀 들어간 작은 골짜기이다. 그 언덕 비탈에는 동굴 하나가 열려 있는데, 나무와 그늘 사이에서 조용히 지내는 작은 곰 가족의 보금자리이다.",
	["s:1440:shrine of aessina"] = "아에시나의 제단은 잿빛 골짜기 남서쪽, 마에스트라 주둔지와 아스트라나르 사이에 숨듯이 서 있다.",
	["s:1440:silverwind refuge"] = "실바람 산장은 나이트 엘프의 것으로, 파수꾼들과 그들과 함께 섬기는 물의 정령들이 지키고 있다. 아스트라나르와 함께 이곳은 잿빛 골짜기의 주요 전초기지 가운데 하나이며, 그 이름에 걸맞게 따뜻하게 맞아 주는 곳이다. 그 여관은 이 지역에서 가장 편안한 여관 가운데 하나로 꼽힌다.",
	["s:1440:silverwing grove"] = "은빛날개 숲은 잿빛 골짜기 중남부에 있으며, 은빛날개 파수대가 지키는 숲으로 그들의 전초기지 남서쪽이자 유성 호수 서쪽에 자리한다. 파수꾼 파송이 숲을 지키기로 맹세한 이들 사이에서 이곳의 감시를 맡고 있다.",
	["s:1440:silverwing outpost"] = "은빛날개 전초기지는 팔파렌 강의 불리한 쪽, 토막나무 주둔지의 오크들이 쓸어버리려는 땅 깊숙이 서 있다. 두리엘 문파이어가 이곳을 지휘하며, 이곳에서 지휘한다는 것은 끝없는 전쟁을 뜻한다. 오크들이 습격하는 것은 약탈을 위해서가 아니라, 전초기지를 지워 버리고 모든 파수꾼을 이 숲에서 영원히 몰아내기 위해서이다.",
	["s:1440:southfury river"] = "분노의 강은 하이잘 산 높은 곳에서 발원해, 산정 호수에서 쏟아져 저지대로 우레처럼 떨어지는 폭포를 이룬다. 그곳에서부터 강은 넓고 빠르게 흐르며 땅을 둘로 가른다. 잿빛 골짜기가 아즈샤라로 바뀌는 곳을 표시하고, 더 남쪽에서는 불모의 땅이 끝나고 듀로타가 시작되는 곳을 가른다. 하구에서 강은 고블린 항구 톱니항의 바로 북동쪽에서 마지막 폭포를 넘어 대해로 뛰어든다.\n\n강을 따라 다리들이 놓여 있는데, 하나는 아즈샤라와 잿빛 골짜기를, 또 하나는 듀로타와 불모의 땅을 잇는다. 그중 가장 서쪽 다리의 바로 북쪽에는 네 땅에 한꺼번에 닿는 물줄기가 한 곳 있다. 잿빛 골짜기와 아즈샤라, 듀로타, 불모의 땅이 만나는 유일한 곳이다.\n\n강은 여전히 기슭의 들판을 적시고, 흐르는 곳마다 흙을 푸르게 물들인다. 그러나 더 이상 마실 수는 없다.",
	["s:1440:splintertree post"] = "토막나무 주둔지의 목재에는 아직도 그것을 세운 도끼 자국이 남아 있다. 3차 대전쟁 때 오크가 처음 잿빛 골짜기로 밀고 들어왔을 때, 그롬마쉬 헬스크림과 그의 전쟁노래 부족이 길과 야영지를 위해 고대의 나무를 베어 이 전초기지를 세웠기 때문이다.\n\n나이트 엘프는 전쟁노래 부족이 그들의 숲에 한 짓을 결코 용서하지 않았고, 그 오랜 상처는 호드와 얼라이언스 사이의 불안한 휴전 아래 불편하게 남아 있다. 그래서 토막나무는 이 숲의 다른 어느 전초기지보다 보복을 많이 불러들이며, 근처 아스트라나르와의 습격이 양쪽에서 잦다.\n\n지금 남은 것은 정착지가 아니라 수비대이다. 오크와 타우렌이 정찰과 경계를 서며, 이제는 으레 오리라 여기게 된 습격자들을 찾아 숲의 경계를 지켜본다.",
	["s:1440:talondeep path"] = "돌발톱 토굴길은 잿빛 골짜기와 돌발톱 산맥을 잇는 구불구불한 굴로, 통로는 작은 막다른 길과 바위에 닳아 생긴 기이한 구멍들로 울퉁불퉁하다. 한쪽 끝은 미스트랄 호수 서쪽으로, 다른 쪽 끝은 칼바람 바위산 북서쪽으로 열려 있다. 그곳에 사는 것은 없다. 그저 산을 지나는 길일 뿐이다.",
	["s:1440:thistlefur village"] = "엉겅퀴 마을은 잿빛 골짜기 중서부, 아스트라나르 북쪽에 있다. 이곳은 타락하고 적대적으로 변해 근처를 지나는 자는 누구든 공격하는 퍼볼그, 엉겅퀴 부족의 보금자리이다. 사나운 전사 둘, 달 블러드클로와 로르기쉬 조울이 부족을 이끌며 다가오는 모든 이에게서 마을을 지킨다.",
	["s:1440:warsong labor camp"] = "잿빛 골짜기 남동쪽, 유성 호수 동쪽에서 전쟁노래 부족은 노동기지를 운영한다. 벌목꾼과 채집꾼들이 오크의 감시 아래 일하며 부족의 거점을 위한 목재를 벤다.\n\n이 기지는 전쟁노래 부족의 주력과 떨어져 있어, 경비병들은 고립된 채 증원을 바랄 수 없다.",
	["s:1440:warsong lumber camp"] = "전쟁노래부족 벌목기지에서는 잿빛 골짜기의 숲이 도끼 소리로 울린다. 전쟁노래 부족은 이곳에서 목재를 얻으려고 고대의 나무들을 벗겨 낸다. 기지는 전투 짐승의 우리와, 벌목을 지키기 위해 세운 요새인 카르가시아 요새를 중심으로 한다.\n\n목재에 대한 부족의 굶주림은 응답 없이 지나가지 않았다. 일리야나와 그녀의 자매들이 이곳 숲으로 나와 줄기를 갉아 먹는 벌목기에 자연의 마법으로 맞서고 있으며, 쌓인 통나무 사이의 땅은 얼라이언스와 호드의 싸움터가 되었다.\n\n그래도 기지는 여전히 제 역할을 한다. 목재 행렬이 이곳에서 토막나무 주둔지로 꾸준히 이어지며, 그곳의 성벽과 사람들은 전쟁노래부족 벌목기지가 보내는 것에 기대어 산다.",
	["s:1440:xavian"] = "사비안은 한때 나이트 엘프의 신전이 있던 자리에 솟아 있으며, 그 돌들은 이제 사티로스에게 넘어갔다. 잿빛 골짜기의 세 사티로스 거점 가운데 힘이 모이는 곳은 이곳이다. 왕자 레이즈와 겔타리스가 모두 이 폐허 안에 본거지를 두고 있으며, 사티로스가 의식을 위해 훔친 전쟁노래 기름을 쓰기 시작한 곳도 이곳이다.\n\n이곳의 이름은 먼 옛날 진아즈샤리에서 영원의 샘으로부터 끌어낸 차원문을 통해 불타는 군단의 길을 여는 데 힘을 보탠 자비우스에게서 왔다. 그 작업이 더디게 진행되는 것에 불만을 품은 살게라스는 자비우스를 최초의 사티로스로 뒤틀어 버렸다. 사비안은 아즈샤라와 충분히 가까워서, 그 이름이 우연처럼 보이지 않는다.\n\n드라이어드들이 사비안에 맞서 왔다. 그중 하나인 아닐리아는 사티로스가 차지한 세나리우스의 가지를 찾아 나섰다가, 끝내 헤쳐 나가지 못한 폐허 한가운데 땅바닥에 치명상을 입고 쓰러진 채 발견되었다.",
	["s:1440:zoram strand"] = "조람 해안을 따라 부서지는 파도 아래에는 한때 도시였던 것이 있다. 대분리로 세계가 찢어지기 전, 조람은 이곳에 나이트 엘프의 마을로 서 있었고, 바다가 솟아올라 부서진 세계의 제 몫을 차지할 때 조람도 함께 가라앉았다. 이제 물 위에 남은 것은 그 이름뿐이다.\n\n오늘날 해안을 걷는 것은 엘프가 아니라 나가이다. 그들은 해안을 자기 것으로 삼았고, 모래 위에 흩어진 잔해, 부서진 배와 해변에 떠밀려 온 바다 생물의 사체는 이 해안이 얼마나 완전히 그들의 손에 넘어갔는지 보여 준다. 근처 바위와 물에 잠긴 굴 사이에는 검은심연의 나락이 있는데, 조람이 바다로 가라앉았듯 땅속으로 가라앉아 있다.\n\n호드는 이곳 조람가르 전초기지에 작은 발판을 두고 있는데, 스스로 택했다기보다 떠밀려 온 것에 가깝다. 그리고 해안의 한 뼘 한 뼘을 다투는 성난꼬리 나가와 싸우느라 힘을 소진해 왔다. 바로 그 나가들이 탈렌을 덮쳤고, 전초기지는 여러 방향에서 적의 압박을 받게 되었다. 이곳은 거칠고 축축하며 다툼이 끊이지 않는 해안이다. 물에 잠긴 제국이 주인이라 주장했고, 지금은 그것을 삼킨 바다에서 태어난 존재들이 차지하고 있다.",
	["s:1440:zoramgar outpost"] = "조람가르 전초기지는 잿빛 골짜기의 조람 해안을 따라 자리한 호드의 항구로, 그 부두는 아래 바다로 뻗어 있다.",
	["s:1441:camp ethok"] = "에톡 야영지는 버섯구름 봉우리 북서쪽에 있는 갈라크 켄타우로스의 야영지이다. 이곳의 켄타우로스들은 고블린 위즐로 베어링샤이너를 태운 짐마차 행렬을 습격했지만, 그가 가장 아끼는 장치는 훔치지 못했다. 그것은 그의 사나운 애완 표범의 목에 안전하게 걸려 있었다.",
	["s:1441:darkcloud pinnacle"] = "먹구름 봉우리는 구름 승강장 동쪽의 작은 고원 세 개 위에 솟아 있으며, 그 꼭대기들은 허공에 걸린 밧줄 다리로 이어져 있다. 올라가는 길은 둘뿐이고, 둘 다 삼엄하게 지켜진다. 네 번째 고원을 가로지르는 자연 비탈과, 가시덩굴 구릉에서 건너오는 다리이다.\n\n그림토템 타우렌이 이 고지대를 차지하고 있으며, 아르나크 그림토템과 하브 파울마운틴이 그들을 이끈다. 지켜지는 다리 뒤에서 두 지도자는 정체를 알 수 없는 어떤 어둠의 세력과 은밀히 서신을 주고받는다. 그들 사이에 무엇이 오가는지는 공공연히 말해지지 않지만, 고원을 봉쇄하는 데 기울인 정성은 그 비밀이 얼마나 철저히 지켜지는지를 보여 준다.",
	["s:1441:freewind post"] = "높새바람 봉우리는 버섯구름 봉우리의 고원 높은 곳에 자리하며, 아래를 떠도는 켄타우로스의 손이 닿지 않는 곳에 세워졌다. 나무 승강기가 협곡 바닥에서 주민들을 실어 올리고, 이웃한 봉우리들 사이에는 밧줄 다리가 걸려 봉우리에서 봉우리로 올라가 마을에 이른다. 아래에서는 갈라크 켄타우로스가 전투 부대를 몰아붙이고, 하피들이 평원 위를 맴돌며 비명을 지르지만, 봉우리의 진짜 방어는 높이 그 자체이다.\n\n더 깊은 문제는 북서쪽, 그림토템 부족이 자기들만의 고지대를 차지한 먹구름 봉우리에서 왔다. 높새바람 봉우리는 공공연한 전쟁이 벌어지기 훨씬 전부터 그들을 경계하게 되었다. 타우렌이 실종되었고, 정체 모를 어두운 출신의 요원들이 그 봉우리를 드나드는 것이 목격되었으며, 살인의 책임이 그림토템에게 돌아갔다. 가장 큰 비난을 받은 것은 족장 아르나크 그림토템이었다. 높새바람 봉우리의 라코타 윈드송이 그의 구애를 거절하자 그는 그녀를 강제로 끌고 갔고, 그녀의 오빠가 그녀를 지키러 오자 그림토템은 그를 죽였다.",
	["s:1441:great lift"] = "구름 승강장은 타우렌이 만든 승강기로, 불모의 땅과 그 아래 버섯구름 봉우리 사이로 여행자들을 실어 나른다. 그리쉬 롱러너와 용사 문혼이 호드를 위해 그것을 지키고 있다.",
	["s:1441:highperch"] = "마루둥지는 버섯구름 봉우리 위로 솟아 있으며, 와이번과 그 둥지들의 보금자리이다. 바위산 사이에는 타우렌 파오카 스위프트마운틴이 오도 가도 못한 채, 와이번들 사이를 몰래 빠져나가 집으로 돌아가기를 바라고 있다.",
	["s:1441:ironstone camp"] = "강철바위 야영지는 소금 평원의 가장자리에 있다.",
	["s:1441:mirage raceway"] = "포직이라는 고블린과 피즐 브래스볼트라는 노움은 저마다 자기 종족이 더 영리한 기술자라고 믿었고, 둘 다 물러서지 않았다. 그래서 그들은 땜장이다운 방식으로 결판을 내기로 했다. 경주로를 만들고, 그 위를 달릴 로켓 자동차를 만든 것이다.\n\n이 경쟁은 두 사람을 훨씬 넘어 구경꾼들을 불러 모은다. 노움과 고블린의 자동차가 날마다 질주하는 동안 호드와 얼라이언스 모두 저마다 좋아하는 쪽을 응원하러 오고, 경주가 끝나면 각 팀은 새로운 우위를 찾아 엔진을 다시 만드느라 분주하다. 진짜 승부는 늘 같다. 어느 종족이 더 나은 기계를 만드는가. 그리고 그것은 결코 결판이 나지 않는다.",
	["s:1441:razorfen downs"] = "버섯구름 봉우리의 가시덤불 깊은 곳에는 가시와 뼈의 미로가 있다. 그 입구는 아가마간의 입을 본떠 만들었다고 하는데, 바깥 돔에 난 아치형 틈이 너무나 숨겨져 있어 이미 그 모양을 아는 이만 찾을 수 있다. 이곳은 가시멧돼지의 조상 대대로의 매장지이자 전통적인 수도인 가시덩굴 구릉으로, 가시덩굴 우리와 같은 거대한 덩굴로 빚어졌다. 그곳을 덮은 거대한 가시 돔의 대부분은 샬라 레이저플랭크가 빚어냈다.\n\n여러 세대 동안 구릉은 해골머리 부족의 대사제들이 돌보는 가시멧돼지 망자들의 장소로 서 있었다. 그러나 3차 대전쟁 이후, 리치 서리한 암네나르가 하수인들을 가시멧돼지에게 보내 그들의 성스러운 도시를 빼앗고 스컬지의 보루로 묶어 버렸다. 가시멧돼지들은 암네나르의 역병이 불모의 땅으로 더 퍼지기 전에 자기 것을 되찾으려 처절하게 싸웠고, 그 싸움 속에서 산 자들은 끌려 내려가 망자들과 함께 가시 속에 갇혔다.\n\n암네나르는 여전히 미로 안에 머물며 자기 뜻대로 굴복시킨 가시멧돼지들을 다스리고, 구릉에 대한 그의 장악은 흔들림이 없다.",
	["s:1441:roguefeather den"] = "버섯구름 봉우리 중남부의 작은 동굴에 하피 동굴의 하피들이 둥지를 틀었다. 그들은 다가오는 자에게 비명을 지르며, 동굴 안쪽에는 모아 둔 식량을 쌓아 두고 새끼를 지키듯 사납게 그 저장품을 지킨다.",
	["s:1441:rustmaul dig site"] = "녹슨망치 발굴현장은 소금 평원에 있으며, 참호들은 작업하다 만 채로 남아 있다. 탐험가 연맹은 오래된 유적을 발굴하러 이곳에 와서, 실리시드 둥지가 있는 동굴의 그늘 아래에서 땅을 파고 있었다.\n\n발굴은 끝나기 전에 멈추었다. 참호들은 텅 빈 채 열려 있고, 드워프들의 연장은 남겨진 자리에 버려져 있으며, 발굴지 아래 동굴은 여전히 그곳에 사는 실리시드의 보금자리로 남아 있다.",
	["s:1441:screeching canyon"] = "회오리 협곡은 버섯구름 봉우리 남부를 가르며, 그 벽에는 이곳에 들끓는 비명 하피들의 울음소리가 메아리친다. 협곡 안쪽에는 하피들의 거점인 하피 동굴이 있다.",
	["s:1441:shimmering flats"] = "소금 평원은 버섯구름 봉우리의 남동쪽 끝, 땅이 타나리스와의 경계까지 평평하고 헐벗게 이어지는 곳에 펼쳐져 있다. 이곳에는 아무것도 자라지 않는다. 땅은 단단히 구워진 소금이며, 바실리스크와 전갈, 거북, 독수리만이 산다. 한때 이곳은 호수 바닥이었다. 북쪽 평원에는 부서진 범선의 선체가 아직도 반쯤 묻혀 있다. 어떤 물과도 멀리 떨어져 좌초한 배는, 이곳이 소금과 갈라진 땅으로 말라붙기 전에 무엇이었는지 보여 주는 증거이다.\n\n그 평평함은 오랜 경쟁의 양쪽 끝에 선 고블린과 노움을 불러들였다. 그들은 이곳에 신기루 경주장을 세우고 서로보다 빠른 기계를 만들려고 경쟁했다. 그 장치들은 좀처럼 온전히 버티지 못했다. 엔진이 잘못된 곳마다 평원에 구덩이가 파였고, 실패한 경주차의 잔해는 소금 위에 흩어진 채 떨어진 자리에서 구워지고 있다.",
	["s:1441:south seas"] = "알려진 대륙들의 남쪽 바다는 대해의 넓은 구역으로 열린다. 트롤 제국의 옛 고향인 잔달라가 이 바다에서 솟아 있다. 본토의 세력들과 떨어져 자기 백성을 품고 있는 화산섬 케잔도 그 사이에 있다.",
	["s:1441:splithoof crag"] = "갈래발굽 바윗골은 먹구름 봉우리 동쪽, 버섯구름 봉우리의 북쪽 벽에 기대 서 있으며, 갈라크 켄타우로스의 보금자리이다. 그 중심에는 산허리의 동굴인 갈래발굽 소굴이 있는데, 갈라크 부족은 그곳에 고대의 화로와 그 성스러운 불꽃이 지키는 고대 유물, 갈라진 발굽을 보관하고 있다.",
	["s:1441:splithoof hold"] = "갈라크 켄타우로스는 갈래발굽 바윗골의 동굴에 갈래발굽 소굴을 두고 거점으로 삼았다. 그 안에는 고대의 화로 위에서 성스러운 불꽃이 타오르는데, 물속에서도 꺼지지 않는다고 한다.",
	["s:1441:tahonda ruins"] = "지금 소금 평원이 있는 곳에는 한때 타우렌 마을이 서 있었으나, 오래전에 폐허가 되어 모래에 삼켜졌다. 이제는 소금바위 바실리스크가 돌 사이에 둥지를 틀었고, 어떤 이들은 타우렌을 몰아낸 것이 바로 그들이라고 말한다.\n\n단서가 하나 남아 있다. 한 건물의 가죽 벽에 난 평행한 세 줄 찢김 자국 두 쌍이다. 바람이나 세월이 아니라 발톱의 흔적이다. 무언가가 분명한 목적을 가지고 그 마을을 찾아왔던 것이다.\n\n남은 이름은 없다. 타나리스로 가는 산길 근처에 폐허만 남아 있을 뿐이다.",
	["s:1441:weathered nook"] = "버섯구름 봉우리의 북쪽 벽에는 비바람 바위굴이라 알려진 작은 동굴이 숨어 있는데, 찾을 줄 모르면 그냥 지나치기 쉽다. 이곳에 돈 플레인스토커와 프레이트 클라우드시어가 보금자리를 마련하고, 아래 협곡의 바람과 먼지로부터 몸을 숨겼다.",
	["s:1441:weazels crater"] = "소금 평원 북쪽에는 한낮에도 빛을 삼킬 만큼 깊은 거대한 상처가 열려 있다. 그것이 어떻게 생겨났는지는 아무도 모르지만, 그 이름은 발견자든 만든 이든 위젤이라는 인물을 암시한다. 근처에 흩어진 잔해와 작은 구덩이들은 고블린이나 노움의 땜질이 잘못된 결과, 너무 멀리 밀어붙인 어떤 발명품을 떠올리게 한다.\n\n그 뒤로 소금바위 바실리스크가 구덩이를 자기들 것으로 삼았다.",
	["s:1441:whitereach post"] = "백사장 야영지는 버섯구름 봉우리의 에톡 야영지 근처 길가에 있는 작은 호드 야영지이다.",
	["s:1441:windbreak canyon"] = "갈기바람 협곡은 높새바람 봉우리와 소금 평원 사이에 있으며, 그 벽에는 둥지가 벌집처럼 박혀 있다. 바람뱀들이 이곳을 자기 것으로 삼고, 협곡에 이름을 준 바람을 타고 솟아오른다. 이곳의 길은 비바람 바위굴로 이어진다.",
	["s:1442:blackwolf river"] = "검은늑대 강은 돌발톱 산맥의 바위웅덩이 호수에서 칼바람 바위산을 지나 흐른다. 투자개발회사가 골짜기의 숲을 베어 낸 탓에 그 물은 독에 오염되어 더럽게 흐른다.",
	["s:1442:boulderslide cavern"] = "구릉바위 협곡 끝의 구릉바위 동굴에는 구릉바위 코볼트의 둥지가 있다. 그들은 대지의 마법이 깃든 희귀한 보라색 수정, 공명석을 캐며 그 광맥 하나하나를 목숨 걸고 지킨다.",
	["s:1442:boulderslide ravine"] = "구릉바위 협곡은 그물누비 고개를 따라 고요히 자리하며, 주변 땅을 어지럽히는 전쟁에도 물들지 않았다. 산양들이 비탈을 따라 조심스레 발을 옮기고, 절벽 폭풍새들이 머리 위를 맴돈다.\n\n협곡의 동굴 맞은편에는 버려진 동굴 하나가 서 있다. 통들은 아직 쌓여 있고, 투박한 횃불은 불 밝힐 이 하나 남지 않았는데도 아직 서 있다. 그 벽에는 타우렌의 솜씨로 보이는 양식의 부족 그림이 남아 있다.",
	["s:1442:camp aparaje"] = "아파라제 야영지는 돌발톱 산맥 동부의 타우렌 마을로, 그런디그 다크클라우드가 이끄는 그림토템 초소의 그림토템 세력에게 공격받았다. 마카바 플랫후프는 그 공격 전까지 딸 카야와 함께 그곳에 살았다.",
	["s:1442:charred vale"] = "잿더미 계곡은 한때 푸르렀다. 돌발톱 남서쪽의 이 골짜기에는 핏빛격노 하피들이 둥지를 틀었고, 나무정령들이 수호자로서 숲을 거닐었다.\n\n그러다 투자개발회사의 고블린들이 목재와 광석을 얻으려고 골짜기를 벗겨 내러 왔다. 나무정령들이 그들에 맞서 일어나 기계들을 몰아냈지만, 골짜기의 정령들은 진정되지 않았다. 발굴이 땅 아래의 무언가를 깨웠고, 숲이 서 있던 부서진 땅을 뚫고 불과 정령들이 솟구쳤다. 고블린을 물리친 나무정령들은 온전한 모습으로 돌아오지 못했다. 고블린의 무기가 그들에게 무엇을 남겼든 그것은 사라지지 않았고, 이제 그들은 골짜기의 수호자가 아니라 위험 가운데 하나로 꼽힌다.\n\n남은 것은 불꽃과 용암의 골짜기로, 한때 푸른 나무가 서 있던 자리에 검은 나무들이 잿더미 속에 서 있다. 해바위 야영지의 드루이드들이 한때 나무정령들이 하던 일을 이어받아, 골짜기가 산의 상처가 아니라 다시 숲이 되기를 바라며 불탄 땅에서 새싹을 틔우고 있다.",
	["s:1442:cragpool lake"] = "바위웅덩이 호수는 투자개발회사가 칼바람 바위산 위에 세운 거대한 목조 구조물 아래에 자리한다. 게렌조 렌치휘슬이 이곳에서 작업을 감시한다.\n\n호수 자체는 출입 금지이다. 그 고요한 물속에서 괴물처럼 자란 물고기, 바위아귀가 차지하고 있기 때문이다.",
	["s:1442:greatwood vale"] = "큰소나무 계곡은 돌발톱 산맥 기슭에 숲이 우거진 골짜기로, 그물누비 고개를 통해 닿을 수 있으며 남쪽에는 말라카진이 있다.\n\n골짜기의 고요는 그런디그 다크클라우드가 이끄는 그림토템 부족이 아파라제 야영지를 덮쳐 그곳의 거의 모든 이를 학살하면서 깨졌다. 마카바 플랫후프는 살아남았고, 그 대가로 골짜기의 그림토템을 추적해 처단해 달라고 호소했다.",
	["s:1442:grimtotem post"] = "그림토템 초소는 돌발톱 산맥에 있는 부족의 발판으로, 그들의 폭력배와 불량배, 마법사와 용병들이 주변 비탈을 순찰한다. 그런디그 다크클라우드가 이곳에서 그들을 지휘하며, 그림토템만의 목적을 위해 초소를 지키고 있다.",
	["s:1442:malakajin"] = "말라카진은 돌발톱 산맥, 그림토템 초소 남쪽에 자리한다. 소박한 마을로, 잡은 사냥감을 오가는 호드에게 팔아 생계를 꾸리는 트롤 사냥꾼들의 보금자리이며, 그림토템의 땅이 보이는 곳에 놓인 발판이다.",
	["s:1442:mirkfallon lake"] = "땅거미 호수는 돌발톱 산맥의 심장부에 자리한 거친 분지로, 와이번과 끈적이, 천둥도마뱀이 물과 기슭을 누빈다. 호수 한가운데에는 언덕 하나가 솟아 있고, 그 위의 칼바람 고지에는 이 지역에 남은 와이번들이 아직 둥지를 틀고 있다.",
	["s:1442:sishir canyon"] = "이 협곡은 돌발톱 산맥의 큰길에서 엘드레타르의 폐허로 이어지지만, 누구도 쉽게 지나가지 못한다. 시쉬르 협곡은 완전히 깊은이끼 거미의 차지로, 괴물 같은 무리의 알과 거미줄이 바위의 모든 턱과 틈을 메우고 있다. 깊은 곳에서는 그들 가운데 가장 거대한 베셀레스가 동족 사이에서 기다리고 있다.",
	["s:1442:stonetalon peak"] = "돌발톱 봉우리는 같은 이름을 지닌 산맥의 북서쪽 끝, 푸른 골짜기에 자리하며, 근처 갈퀴발톱굴의 드루이드들이 돌보고 있다. 이 산은 신성하게 여겨지며, 그 바위에는 마법이 짙게 흐른다.\n\n3차 대전쟁 동안 제이나 프라우드무어와 그녀의 원정대가 이곳에 와서 봉우리 아래 동굴 입구 근처에 기지를 세웠다. 스랄과 그의 호드는 예언자를 찾아 그 뒤를 따라왔다.\n\n그 뒤로 이곳은 나이트 엘프와 얼라이언스의 중심지가 되었고, 드루이드들이 골짜기를 지켜보고 있다.",
	["s:1442:sun rock retreat"] = "해바위 야영지는 돌발톱 산맥의 땅거미 호수 남쪽 봉우리들 사이에 숨어 있으며, 정령의 세계가 산 자의 세계에 바짝 맞닿은 곳이다. 호드가 이곳에 깃발을 올리기 훨씬 전부터, 타우렌은 정령의 세계로 건너가는 의식을 치르러 이 바위로 순례를 왔다. 태양 안셰가 한때 지금 야영지가 서 있는 산에 입을 맞추었다고 전해진다.\n\n이제 오크와 타우렌이 함께 해바위 야영지를 지키고 있다. 이 산맥에서 호드 세력이 가장 활발하게 모이는 곳이자 교역과 노동의 중심지로, 투자개발회사와 다른 악의적인 세력이 땅에서 뜯어 간 것을 고쳐 나가고 있다.",
	["s:1442:talon den"] = "돌발톱 봉우리 높은 곳에서 땅이 열려 갈퀴발톱굴이 된다. 땅거미 드라이어드와 그 이름을 함께 쓰는 수호자들의 보금자리인 지하굴로, 나이트 엘프 세나리온 관리인들이 지켜보고 있다.",
	["s:1442:talondeep path"] = "돌발톱 토굴길은 잿빛 골짜기와 돌발톱 산맥을 잇는 구불구불한 굴로, 통로는 작은 막다른 길과 바위에 닳아 생긴 기이한 구멍들로 울퉁불퉁하다. 한쪽 끝은 미스트랄 호수 서쪽으로, 다른 쪽 끝은 칼바람 바위산 북서쪽으로 열려 있다. 그곳에 사는 것은 없다. 그저 산을 지나는 길일 뿐이다.",
	["s:1442:webwinder path"] = "그물누비 고개는 말라카진과 땅거미 호수 사이, 양쪽으로 낮게 꺼진 땅을 지나 이어진다. 말라카진 서쪽에서 호드는 얼라이언스가 더 동쪽으로 밀고 오지 못하도록 길을 가로질러 방책을 세웠다.",
	["s:1442:windshear crag"] = "칼바람 바위산은 한때 돌발톱 산맥 사이의 골짜기에 빽빽하고 푸르게 우거진 원시림이었다. 지금은 그렇지 않다. 이곳에 서 있는 것은 그루터기와 더럽혀진 물, 그리고 삐걱거림을 멈추지 않는 기계들이다.\n\n그 폐허 뒤에는 이름 하나가 있다. 게렌조 렌치휘슬, 투자개발회사의 깃발 아래 벌목 원정대 전체를 맡은 문둥병 노움이다. 그는 바위산의 가장 오래된 나무도 톱밥으로 만들 수 있는 기계, 슈퍼 수확기 6000을 만들었고, 바위웅덩이 호수 위로 높이 세운 단 위에서 기계가 쓸어버린 모든 것의 주인으로서 자기 작품을 지켜본다. 이곳에 대한 그의 장악력은 오히려 그를 윗선이 버려도 되는 존재로 만들었다. 지하도시 기술자 조합의 이사 리들복스는 그의 죽음을 원하고, 고블린 지즈 피직스가 그 명령이 실행되는 것을 보려고 바위산에 숨어 기다리고 있다.\n\n바위산의 남동쪽 구석에서는 칼바람 코볼트가 칼바람 광산을 차지하고 연기철 광석을 찾아 굴을 파고 있다.",
	["s:1442:windshear mine"] = "칼바람 광산은 칼바람 바위산 안, 검은늑대 강의 끝에 있다. 투자개발회사는 한때 이곳에서 코볼트들에게 땅을 파게 하며 주석 광맥을 캤다.",
	["s:1443:bolgans hole"] = "겔키스 마을에서 볼간의 구덩이라 불리는 동굴은 부족의 가장 중요한 이들을 품고 있으며, 칸 샤카도 그중 하나이다.\n\n깊은 곳에는 테라드라스의 눈물인 푸른 수정이 자라는데, 겔키스 주술사들은 그 돌이 공주의 보호를 품고 있다고 믿으며 쌓아 둔다.",
	["s:1443:ethel rethor"] = "잊혀진 땅 북서쪽 해안 앞에서 바다는 에텔 레소르의 대부분을 삼켰다. 탑 하나만이 수면 위로 솟아 있으며, 좁은 다리로 해안과 이어져 굳게 닫힌 문에 닿는다. 나가들이 물에 잠긴 폐허를 자기 것으로 삼았다.",
	["s:1443:gelkis village"] = "겔키스 마을은 잊혀진 땅 남서쪽의 넓은 협곡을 빙 둘러 자리하며, 겔키스 부족의 본거지이다. 협곡의 절벽과 벼랑 사이에 걸린 다리들이 남쪽 산비탈에 파인 동굴, 볼간의 구덩이로 내려가며, 겔키스의 칸이 그곳에 머문다.\n\n마을은 잊혀진 땅의 남북 간 큰길에 바짝 붙어 있어, 길 자체가 그곳을 지나는 이들에게 위험이 되었다. 겔키스 부족은 처음 그들을 품어 준 협곡 너머로 퍼져, 페랄라스로 이어지는 길 동쪽의 호숫가를 따라 새 오두막들을 세웠다.",
	["s:1443:ghost walker post"] = "침묵의 초소는 잊혀진 땅 중부의 코도 무덤 곁에 서 있으며, 그곳의 망자들이 이곳의 모든 것을 결정한다. 타우렌 주술사들이 뼈들을 지키며 쓰러진 코도의 영혼이 다음 삶으로 편히 넘어가도록 돕고, 필요할 때면 이미 떠난 이들과 이야기를 나눈다. 거다 와일드메인이 그들을 이끌며, 겨우 최소한의 필수품만으로 이 노출된 초소를 지키고 있다.\n\n이 지역의 다른 곳에서 안전을 누리는 그늘수렵 마을과 달리, 침묵의 초소에는 그런 안전이 없다. 편안함이 아니라 전쟁을 위해 지은 전진 기지로, 여관도 쉴 곳도 없다. 이곳은 오직 하나의 목적을 위해 존재한다. 잊혀진 땅을 누비는 불타는 칼날 광신도와 켄타우로스 부족에 맞서 호드의 싸움을 이어 가는 것이다.",
	["s:1443:kodo graveyard"] = "잊혀진 땅의 코도들은 죽으러 이곳에 온다. 그 뼈들이 갈라진 땅 위에 하얗게 바랜 채 쌓여 있다. 그것을 건드리면 망자들은 가만히 있지 않는다. 코도의 망령들이 땅에서 일어나 자기 족속의 남은 것을 지킨다.",
	["s:1443:kolkar village"] = "잊혀진 땅 동쪽 끝의 이 마을은 콜카르 부족의 본거지로, 콜카르는 칼림도어 전역의 켄타우로스 부족 가운데 가장 번성한 부족이며 멀리 불모의 땅과 듀로타에까지 전초기지를 두고 있다. 경쟁 부족인 마그람이 끊임없이 그들을 압박한다. 두 부족 사이의 반목은 결코 쉬지 않기 때문이다.",
	["s:1443:kormeks hut"] = "잊혀진 땅 중북부에는 비바람에 닳은 오두막이 서 있다. 그 안에는 황혼의 망치단 일원인 윌로우가 살며, 그 교단의 일원답지 않게 따뜻한 손길로 이곳을 돌본다. 밖에서는 코도 뼈가 흩어진 우리 안에서 비블리 푸츠버클이 그 뼈들이 가져다줄 이익에 신이 나서 유해 사이를 춤추며 돌아다닌다.",
	["s:1443:magram village"] = "마그람 마을은 잊혀진 땅 남동쪽의 오염된 누런 웅덩이 사이에 흩어진 섬들 위에 솟아 있으며, 오두막들은 물 위에 걸친 투박한 다리로 이어져 있다. 이곳은 마그람 부족의 보금자리로, 이 척박한 땅의 패권을 두고 겔키스 부족과 전쟁에 갇혀 있는 켄타우로스 종족 가운데 하나이다.",
	["s:1443:mannoroc coven"] = "잊혀진 땅 곳곳에 부서진 채 널린 나이트 엘프의 폐허 가운데, 어떤 여행자도 가볍게 입에 올리지 않는 이름을 지닌 곳이 하나 있다. 만노로크 소굴은 공포의 구덩이 군주 만노로스에게서 이름을 얻었으며, 이곳의 땅은 그를 기억한다. 땅은 악마들이 오기 훨씬 전부터 죽어 있었지만, 지옥의 마법이 그것을 더욱 황폐하게 만들어, 이제는 공기마저 타락으로 짙게 드리워 들어서는 이 누구에게나 치명적인 장막이 내려앉는다.\n\n길을 연 것은 불타는 칼날 광신도들이었다. 그들은 세상에 여러 개의 차원문을 찢어 열고 그것을 통해 불타는 군단의 하수인들을 불러냈다. 지금 폐허를 배회하는 지옥불정령과 서큐버스, 지옥사냥개와 지옥수호병이다. 군주 아즈레소크가 이 악마들을 지휘하고, 오크 흑마법사 저그카르 그림로드는 그들 사이에서 소굴에 있는 불타는 칼날의 목소리 역할을 한다. 그들은 함께 칼림도어 중부 어디에서도 볼 수 없는 가장 거대한 악마 집결지를 세웠다. 광신도들의 계획이 경고 수준을 훨씬 넘어 성공했다는 증거이다.",
	["s:1443:nijels point"] = "나이젤의 야영지는 잊혀진 땅 북부 산맥에서 감시를 서고 있으며, 얼라이언스와 세나리온 의회가 지키는 전초기지이다.\n\n수호자 마란디스는 드라이어드 자매들과 함께 이곳에 와서, 테라드라스 공주를 쫓는 동안 이 전초기지를 본거지로 삼았다. 그들의 목적은 마라우돈 깊은 곳에서 자에타르의 시신을 되찾아 돌발톱 산맥으로 모셔 가는 것이었다.\n\n그와 동시에 스톰윈드 군은 이 지역을 장악한 켄타우로스 부족의 위협에 맞서 펜티개스트 대장 휘하의 나이젤의 야영지 경비대를 이곳에 주둔시켰다. 펜티개스트는 군인다운 경계심으로 겔키스와 마그람 사이의 경쟁을 지켜보았다. 그는 어느 부족이 이기든 대담해져 근처의 얼라이언스 거점을 공격하리라 확신했고, 그래서 한 부족을 다른 부족과 저울질하며 켄타우로스를 무찌를 방법을 알아내려 했다.",
	["s:1443:ranazjar isle"] = "라나즈자르 섬은 잊혀진 땅 북서쪽 해안 앞의 작고 바위투성이인 섬으로, 뱀 같은 나가의 보금자리이다. 돌 사이에는 에텔 레소르와 같은 고대 도시의 일부였던 나이트 엘프 폐허가 서 있으며, 이제는 그곳에 사는 나가들 위로 고요히 남아 있다.",
	["s:1443:sargeron"] = "이곳에 서 있던 도시는 한때 나이트 엘프의 이름을 지니고 있었으나, 고대의 전쟁이 세계를 찢어 놓은 뒤로 그 이름은 잊혔다. 남은 것은 폐허이며, 지금은 그곳에 사는 증오의 격노 사티로스가 악마 주인 살게라스를 기려 살게론이라 부른다.\n\n폐허에는 한때 엘룬의 성지 세 곳, 곧 그녀의 대성당과 신전과 성소가 있었다. 그 오래된 신앙의 유물들이 아직 돌 사이에 놓여 있다. 엘룬의 화로, 엘룬의 시녀, 엘룬의 잔, 그리고 고대 소용돌이 룬석이다.",
	["s:1443:sartheris strand"] = "잊혀진 땅이 바다와 만나는 해안은 그 뒤편의 땅과 다르다. 내륙은 잿빛으로 황량하지만, 살데리스 해안은 햇살이 가득하고 풀이 푸르다. 바다 거인들이 얕은 물을 헤치고, 나가들이 물속을 휘감으며, 마크루라들이 모래 위를 종종걸음 친다.\n\n에텔 레소르 아래 해변에는 작은 배 한 척이 박살 난 채 놓여 있다. 목재는 쪼개졌고, 태우고 있던 선원들은 사라졌다.",
	["s:1443:scrabblescrews camp"] = "잊혀진 땅의 코도 무덤 근처에는 작은 고블린 야영지가 서 있다. 이곳은 수완 좋은 고블린 스미드 스크래블스크류의 것으로, 그는 코도 행렬을 꾸려 이 땅이 허락하는 이익이라면 무엇이든 얻으려고 거대한 짐승들을 몰고 황무지를 건넌다.",
	["s:1443:shadowbreak ravine"] = "동트는 협곡은 쇼크토카르 남동쪽 산속에 숨어 있으며, 누구도 우연히 발견하기 어려운 잊혀진 땅의 주름이다. 거대한 버섯들이 바위 사이로 솟아 있고, 그 한가운데에는 거대한 사슬로 묶인 소환진이 있다. 협곡을 은신처로 삼은 불타는 칼날 광신도들이 만든 것이다.",
	["s:1443:shadowprey village"] = "그늘수렵 마을은 살데리스 해안이 잊혀진 땅의 남쪽 해안과 만나는 곳에 자리한 트롤의 어촌이다. 주민들은 바다에서 생계를 얻으며, 그들이 잡은 것이 더 내륙의 침묵의 초소를 먹여 살린다.",
	["s:1443:tethris aran"] = "잊혀진 땅 북부, 천둥도끼 요새 북쪽에는 나이트 엘프 폐허가 흩어져 있다. 대분리 때 파괴되었다고 여겨지는 거주지의 잔해이다. 다시 세워진 것은 아무것도 없다. 이제는 잊혀진 땅의 야생 생물들만이 부서진 돌 사이를 오간다.",
	["s:1443:thunder axe fortress"] = "천둥도끼 요새는 잊혀진 땅 북서쪽에 서 있으며, 불타는 칼날 교단에게 넘어갔다. 성채와 병영, 동굴과 감시탑으로 이루어진 성벽 뒤에서, 코호르 아래의 광신도들은 악마 나자르겐을 온전한 힘으로 소환하려 애쓰고 있다. 너무 일찍 불러내면 그가 파괴될 만큼 약할 것이기에 그들은 신중하다.\n\n요새에는 한때 불타는 칼날이 나가에게서 훔친 끔찍한 힘의 유물, 빛의 홀이 있었다. 은빛 여명회를 섬기는 아조어 알다모트가 그것을 되찾는 일에 나섰고, 도움을 받아 교단의 손에서 그것을 빼앗아 내는 데 성공했다.\n\n이 성벽 안에는 티라니스 말렘도 살았다. 그의 이름은 자기 종족 사이에서 경멸과 함께 불린다. 그는 동족을 배신하고 악마 마법 연구에 몸을 바쳤으며, 천둥도끼 요새를 그런 어두운 탐구를 위한 은신처로 삼았다.",
	["s:1443:valley of bones"] = "뼈의 골짜기는 잊혀진 땅 남쪽 끝의 바위산으로, 해골과 켄타우로스 강령술사, 그리고 학살당한 마그람 부족의 유령들이 출몰한다. 절벽 벽에는 기원을 알 수 없는 거대한 해골 한 쌍, 죽은 골리앗들이 기대어 있다.",
	["s:1443:valley of spears"] = "뾰족바위 골짜기는 잊혀진 땅 서부에 있으며, 켄타우로스 마라우딘 부족의 보금자리로, 걸어서는 남쪽과 동쪽의 좁은 산길을 통해서만 들어갈 수 있다. 그 남서쪽 끝에는 마라우돈의 입구가 있다. 켄타우로스들 사이에는 멜리자 브림버즐이 포로로 붙잡혀 있다.",
	["s:1444:camp mojache"] = "모자케 야영지는 빠른 개울이 갈기바람 호수로 흘러드는 곳에 자리한다. 이 땅을 지키는 타우렌은 두꺼운 가죽과 용맹한 용사들로 이름이 높으며, 그 용사들은 페랄라스의 위험으로부터 여행자들을 지킨다.",
	["s:1444:dire maul"] = "만 이천 년 전, 나이트 엘프 마법사들의 비밀 종파가 아즈샤라 여왕의 가장 귀한 비전의 비밀을 지키기 위해 엘드레탈라스를 세웠다. 그곳의 명가 가운데 셴드랄라라 불리는 비전술사들은 조용한 영화를 누렸고, 그중 하나인 밀리센트 세린은 풍요의 열매를 빚어냈다. 성장과 보호의 기운을 두른 이 덩굴 덕분에 도시 전체가 번성할 수 있었다.\n\n대분리 뒤 영원의 샘과 단절된 명가는 악마 이몰타르를 속박하고 그를 가둔 것에서 힘을 끌어냈다. 그 힘은 수천 년 동안 그들을 지탱했지만, 마침내 그를 붙잡아 두는 대가가 그가 주는 것보다 커졌다. 그들의 지도자 왕자 토르텔드린은 이에 자기 백성에게 등을 돌리는 것으로 답했다. 그는 나머지를 살리기에 충분한 힘을 풀어내려고 많은 동족을 학살했다. 살아남은 이들은 한때 자신들이 다스리던 폐허 속으로 더 깊이 물러났고, 도시의 나머지는 그곳에 깃들러 올 무엇에게든 내맡겨졌다.\n\n엘드레탈라스의 돌은 지금도 서 있으며, 이제는 아무도 기억하지 못하는 기술로 그 안에 비전의 힘이 묶여 있다. 살아남기 위해 자기 백성을 먹어 치운 도시의 모습을 간직한 채로.",
	["s:1444:dream bough"] = "비취비늘 호수 한가운데의 작은 섬에서 거대한 나무 한 그루가 솟아 있으며, 그 뿌리와 가지는 에메랄드의 꿈으로 들어가는 차원문 가운데 하나를 품고 있다. 녹색용군단이 그것을 지켜보며, 아래의 꿈에 손대려는 자로부터 그 문턱을 지킨다.",
	["s:1444:feathermoon stronghold"] = "페랄라스 서쪽 해안 앞 살도르 섬에는 바다 위에 세워진 요새가 서 있다. 이 요새를 세운 장군 샨드리스 페더문은 만 년 동안 파수꾼들 사이에서 티란데 위스퍼윈드의 오른팔로 그녀 곁을 지켜 왔다. 그녀는 요새에 자신의 이름을 붙였고, 요새는 지금도 나이트 엘프를 위해 칼림도어 해안의 이 구간을 지키고 있다.\n\n요새와 본토를 잇는 것은 바다뿐이다. 잊혀진 해안에서 섬의 부두까지 배가 오간다.",
	["s:1444:feral scar vale"] = "페랄라스 서부의 높은벌에는 거친흉터 골짜기가 있으며, 이곳에 이름을 준 거친흉터 설인들이 차지하고 있다.",
	["s:1444:forgotten coast"] = "잊혀진 해안은 땅이 장막의 바다와 만나는 페랄라스의 서쪽 끝 전체를 따라 이어진다. 이곳에서는 물의 정령이 파도에서 솟아오르고, 바다 거인들이 해안을 누빈다.\n\n이 해안에는 멀록 어촌 하나가 매달려 있다. 새들이 날아들어 올챙이를 채어 가는 일이 있었고, 마을은 인간과 놀의 습격을 차례로 겪었다. 가장 끔찍한 것은 골두니 오우거로, 그들은 여러 해 동안 이 마을을 노려 멀록들을 혈투의 전장 폐허로 끌고 가 가두었다. 그렇게 끌려간 멀록이 열 마리가 넘는데, 머를과 머글리라는 둘도 그중에 있다.",
	["s:1444:frayfeather highlands"] = "공작날개 고원은 공작날개 히포그리프의 땅으로, 그들은 그곳 높은 곳에 둥지를 틀고 이 땅에 이름을 주었다. 바위산 사이 곳곳의 둥지에 그들의 알이 숨겨져 있으며, 고원을 보금자리로 삼은 무리가 하늘을 맴돌며 그것을 지킨다.",
	["s:1444:gordunni outpost"] = "라리스 정자 북쪽의 산에는 골두니의 흔적이 새겨져 있다. 페랄라스의 다른 곳은 푸르지만, 이 전초기지는 오우거의 존재 아래 시들어 갈색으로 변했다.\n\n언덕에는 동굴이 둘 있다. 입구 근처의 작은 동굴과 뒤편의 거대한 흙더미로, 둘 다 이 황폐한 땅을 차지한 골두니가 지키고 있다.",
	["s:1444:grimtotem compound"] = "그림토템 주둔지는 혈투의 전장 동쪽에 그림토템 타우렌이 스스로 마련한 보금자리이다. 그 남쪽 구역에는 커다란 우리가 서 있는데, 사로잡힌 요정용들이 갇혀 있다. 북쪽 구역의 동쪽에는 놀들이 자기들만의 야영지를 차렸다.",
	["s:1444:high wilderness"] = "높은벌은 페랄라스 서부에 잊혀진 해안에서 베르단티스 강까지 펼쳐져 있다. 곰과 늑대, 히포그리프가 고대의 나무 사이를 누비고, 더 깊은 숲에는 나무정령이 서 있으며, 그 너머의 더 거친 땅은 설인과 오우거가 차지하고 있다.",
	["s:1444:isle of dread"] = "공포의 섬은 페랄라스 앞바다, 살도르 섬 남쪽에 있으며, 그 중앙 골짜기는 남동쪽의 단 하나의 길목을 제외한 사방이 험준한 절벽으로 막혀 있다. 그 숨겨진 분지에는 비전의 기운에 물든 짐승과 포식자 모두를 아우르는 키메로크가 살며, 군주 라크마에란이 그들을 다스린다. 그의 살은 생존보다 기묘한 목적으로 탐내어졌다. 고아지고 다시 빚어진 그것은 오백 파운드짜리 괴물 같은 새 요리가 되었고, 노움 마법사 나레인 수스팬시가 그것을 통째로 먹어 치웠다.\n\n섬 북쪽 끝에는 그곳에 알려진 어떤 것과도 다른, 깊고 기이하게 만들어진 동굴이 바위 속으로 파고들어 있다. 물 아래의 비밀 통로가 안쪽 방으로 이어지는데, 그 깊은 곳에 여군주 스잘라를 숨겨 두는 것 말고는 누구도 그 쓰임새를 찾지 못했다. 동굴과 그곳의 나가는 군주 샬자루가 지휘하며, 그의 존재는 자기 해안과 너무 가까운 나가를 경계한 페더문 요새의 이목을 끌었다.",
	["s:1444:jademir lake"] = "페랄라스 북부의 비취비늘 호수 한가운데에는 작은 섬, 꿈나무가 있다. 그곳에는 에메랄드의 꿈으로 들어가는 차원문이 서 있으며, 레슬라스와 여러 녹색용족이 그것을 지킨다. 감염된 녹색 새끼용들이 호수 북서쪽 기슭을 따라 머물고 있다.",
	["s:1444:lariss pavilion"] = "나이트 엘프의 석조 양식을 지닌 라리스 정자는 페랄라스의 모자케 야영지 북쪽에 서 있다. 그곳의 드라이어드들은 한때 평화로웠지만, 에메랄드의 악몽이 그들을 타락시켜 이제는 다가오는 자는 누구든 공격한다.\n\n정자 아래에는 숨겨진 내리막길이 있는데, 왕자 토르텔드린과 결별하고 그 길을 통해 혈투의 전장을 빠져나온 명가 아즈토르딘이 알고 있다. 그는 거의 아무것도 가지고 나오지 못했다. 그가 아래로 사라지기 전에 푸실린이라는 임프가 그의 주문서를 훔쳐 갔기 때문이다. 그 뒤로 그는 줄곧 그 통로에 머물고 있다.",
	["s:1444:lower wilds"] = "낮은벌은 페랄라스의 동쪽 끝을 채우고 있으며, 나무정령들이 나무 사이를 움직이고 타락한 드라이어드들이 기이하게 뒤틀린 힘을 지닌 채 걷는 곳이다.",
	["s:1444:oneiros"] = "페랄라스 북부의 비취비늘 호수 남쪽에는 오네이로스의 폐허가 있다.",
	["s:1444:rage scar hold"] = "무쇠설인 소굴은 페랄라스에 파인 동굴로, 이 지역에서 가장 사나운 설인들이 산다. 안에는 책과 기이한 문양들이 흩어져 있어, 비전 연구의 흔적이거나 어쩌면 그곳에서 최후를 맞은 불운한 마법사의 유품임을 짐작하게 한다.",
	["s:1444:ruins of isildien"] = "이실디엔 폐허는 만 년 전에 부서진 위대한 나이트 엘프 도시의 잔해이다. 이제 골두니 오우거가 무너진 열주 사이에 둥지를 틀고, 자신들보다 훨씬 오래된 손들이 세운 돌을 다스리고 있다.",
	["s:1444:ruins of ravenwind"] = "페랄라스 북부에는 까마귀바람의 부서진 돌들이 남아 있다. 혈투의 전장이 다른 곳에 세워졌듯, 먼 옛날 칼도레이의 명가가 세운 곳이다. 그 영광 가운데 지금 서 있는 것은 거의 없다. 북쪽샘 하피들이 폐허를 차지하고, 무너진 기둥과 빈 전당 사이에 둥지를 틀었다.",
	["s:1444:ruins of solarsal"] = "페더문 요새 남서쪽의 살도르 섬에는 솔라살의 오래된 돌들이 아직 나무 사이에 서 있다. 오래전에 야생에 버려진 나이트 엘프의 작품이다. 이제는 증오의 마루 나가가 폐허를 차지하고, 한때 엘프들이 거닐던 부서진 기둥 사이를 휘감으며 다닌다.",
	["s:1444:sardor isle"] = "살도르 섬은 페랄라스 앞바다에 솟은 작은 피난처로, 샨드리스 페더문 아래 나이트 엘프가 지키고 있다. 나가들이 해안으로 기어오르고, 늑대들이 남은 야생의 땅을 누비기에, 요새의 감시는 결코 쉬는 법이 없다.",
	["s:1444:shalzarus lair"] = "페더문 요새가 있는 섬의 남쪽, 공포의 섬 북쪽 끝에는 물길로 이어진 두 방을 품은 구불구불한 동굴이 있다. 증오의 마루 여마법사들과 뱀 경비병들이 그 안을 가득 메우고 있다. 깊은 곳에는 증오의 마루의 주인 샬자루가 산다.",
	["s:1444:thalanaar"] = "탈라나르는 고요히 서 있는 작은 전초기지로, 제 역할 말고는 여행자를 끌 만한 것이 거의 없다. 캐리시아 문헌터가 이곳에서 옛 부족의 방식대로 가죽과 무두질 일을 하는데, 누구든 이곳에 머물 몇 안 되는 이유 가운데 하나이다.",
	["s:1444:twin colossals"] = "쌍둥이 바위산은 페랄라스 서쪽 끝에 솟아 있다. 이 지역에서 가장 높은 곳을 이룰 만큼 높이 수직으로 솟은 두 산으로, 잊혀진 땅으로 가는 길이 그 사이의 틈을 꿰뚫고 지나간다.\n\n동쪽 봉우리 꼭대기에는 낚시를 할 수 있을 만큼 고요한 작고 깊은 연못이 있는데, 그레건 브루스퓨어를 그곳에서 만날 수 있다. 정상에서는 이 지역 전체가 발아래 펼쳐진다.",
	["s:1444:verdantis river"] = "베르단티스 강은 혈투의 전장 폐허 남동쪽, 페랄라스 중부를 굽이쳐 흐르며, 얽힌 숲 사이로 고요한 초록 실 한 가닥을 긋는다. 그 물에는 세상 어디에도 없는 페랄라스 아히가 산다.",
	["s:1444:wildwind lake"] = "갈기바람 호수는 페랄라스의 모자케 야영지 근처에 있으며, 주변의 황야 아래 고요히 잠겨 있다. 수면 아래에서 헤엄치는 것들과 근처 야영지 위에 드리운 고요함 말고는 이렇다 할 것이 없는 곳이다.",
	["s:1444:woodpaw den"] = "페랄라스 한가운데에는 덩굴발 놀의 소굴인 덩굴발일족 소굴이 있다. 이곳에서는 덩굴발 우두머리들이 동족을 다스리며, 외부인이 감히 시험하려 들지 않을 만큼 많은 수가 땅을 메우고 있다. 소굴 남쪽에는 암흑안개 폐허가 서 있다. 놀들의 소란 곁의 말 없는 이웃이다.",
	["s:1444:woodpaw hills"] = "덩굴발 언덕은 숲이 우거졌으며, 덩굴발 부족 놀의 보금자리이다. 그들의 땅에 대한 장악력은 흔들리고 있다. 가장 남동쪽 끝에서 땅이 갈라져 지금은 고통의 구덩이라 불리는 곳이 열렸고, 땅 밑에서 솟구친 떼거리들이 놀들을 그들 자신의 영역에서 몰아내고 있기 때문이다. 한때 덩굴발 우두머리들이 야영지에서 부족을 이끌었지만, 이제 그들이 지키는 곳은 덩굴발일족 소굴뿐이다.",
	["s:1444:writhing deep"] = "고통의 구덩이는 페랄라스 남동쪽에 있으며, 조크아쉬 벌집의 차지가 되었다. 그곳의 실리시드는 주변 땅을 독으로 물들여 근처 놀들을 광란에 빠뜨리고, 북쪽의 모자케 야영지로 몰아냈다.\n\n야영지의 전사들이 지상의 실리시드를 베어 냈지만, 알로 가득한 땅 밑 벌집의 심장부는 손도 대지 못했다. 렉사르는 다음 세대가 부화하는 것은 시간문제일 뿐이라고 경고한다.",
	["s:1445:alcaz island"] = "알카즈 섬은 먼지진흙 습지대 앞바다에서 솟아 있으며, 습지대의 잿빛 진흙 바로 옆에서 자랄 까닭이 없는 열대의 초록으로 뒤덮여 있다. 마치 더 오래되고 따뜻한 어떤 힘이 한때 이 땅을 차지하고 결코 놓아주지 않은 듯하다. 스트라샤즈 나가가 이곳을 차지하고 있으며, 전사와 세이렌들이 해안을 따라 빽빽하다.\n\n그러나 안퀴라즈와의 전쟁 동안 위빌 박사가 비행 기계를 타고 섬에 와서 부하들과 함께 언덕 꼭대기에 자리를 잡았고, 해안 한 구간을 기술 발명의 작업장으로 바꾸었다.",
	["s:1445:beezils wreck"] = "보급품을 싣고 남쪽으로 향하던 고블린 비행선 한 척이 타베사의 농장 동쪽, 먼지진흙 습지대의 가장 깊은 곳에 추락했다. 선체는 진흙 속에 부서져 누워 있고, 화물은 잔해 사이에 흩어져 있으며, 시포리움 추진기들은 떨어진 자리에 아직 그대로 놓여 있다.",
	["s:1445:bloodfen burrow"] = "먼지진흙 습지대 남서쪽의 한 동굴에는 유난히 많은 붉은늪지 랩터가 숨어 산다. 입구 밖에는 그 짐승들에게 갈가리 찢긴 어떤 거주지의 잔해가 놓여 있고, 그곳 사람들은 이제 늪의 진흙 속으로 사라졌다. 그 안 어딘가, 잔해 사이에는 코르텔로의 수수께끼 가운데 한 조각이 기다리고 있다.",
	["s:1445:bluefen"] = "푸른늪지는 먼지진흙 습지대 북부에 있으며, 낮은 땅에는 갈대와 고인 물이 가득하다. 거미와 악어, 랩터, 늪새들이 거침없이 늪지를 오가고, 테라모어 잠입자들이 갈대 사이로 보이지 않게 지나간다.",
	["s:1445:brackenwall village"] = "담쟁이 마을은 먼지진흙 습지대 북서쪽의 오두막과 오우거 흙더미 사이에 서 있으며, 호드에 충성을 맹세한 돌망치 오우거의 보금자리이다. 이곳이 처음부터 그들의 집이었던 것은 아니다. 돌망치 부족은 한때 남쪽에 마을을 두고 있었는데, 검은용군단이 그곳을 덮쳐 불태워 폐허로 만들었다. 렉사르의 뒤를 이어 지도자가 된 대군주 모크모로크는 생존자들을 이끌고 북쪽으로 와서 그 대신 담쟁이 마을을 세웠다.\n\n모크모로크는 제자리를 지키는 것 위에 자신의 통치를 세웠다. 오우거 드라즈질브가 공격자들이 오닉시아의 무리였음을 알아내 그에게 진실을 알렸을 때, 모크모로크는 움직이려 하지 않았다. 담쟁이 마을은 안전했고, 이곳에는 검은용이 살지 않았으며, 그것으로 그에게는 충분했다. 드라즈질브는 이 일을 그냥 덮어 두지 않을 것이며, 대군주를 무너뜨리고 돌망치 부족을 잃어버린 것으로 다시 이끌려면 무엇이 필요할지 조용히 저울질하고 있다.",
	["s:1445:darkmist cavern"] = "먼지진흙 습지대 북서쪽에는 작은 광산이 있는데, 오래전에 어둠 속에서 무시무시하게 커진 거미들에게 넘어갔다. 습지 사람들은 그들을 암흑안개 거미라 부르고, 동굴도 그에 따라 암흑안개라 부르지만, 그곳과 그곳을 차지한 생물 가운데 어느 이름이 먼저였는지는 아무도 말할 수 없다.\n\n광산 입구 밖에는 작은 집들의 폐허가 축축한 땅에 반쯤 가라앉은 채 서 있다. 오래전에 잊힌 어떤 거주지가 남긴 전부이다.",
	["s:1445:den of flame"] = "화염의 둥지는 돌망치 오우거가 소굴로 쌓아 올린 곳으로, 그 석조물에는 아직 그들의 솜씨가 남아 있다. 이곳은 돌망치일족 폐허 서쪽, 오닉시아가 차지한 습지대에 있다.\n\n이제 오우거들은 그곳에 없다. 검은용족이 둥지를 점령해 검은용군단의 둥지로 삼았다. 오래된 석조물과 안에 남겨진 돌망치의 깃발만이 그곳을 처음 지은 이들을 떠올리게 한다.",
	["s:1445:dragonmurk"] = "먼지진흙 습지대 남부에는 용의 늪이라 불리는 악취 나는 땅이 있으며, 검은용군단의 새끼용과 용족으로 가득하다. 근처에는 화염의 둥지와 돌망치일족 폐허가 있는데, 두 곳 모두 마찬가지로 검은용족에게 점령당했다.",
	["s:1445:dreadmurk shore"] = "테라모어 섬과 북부 전초기지 사이의 해안에는 수렁지느러미 멀록 부족이 빽빽하며, 그들은 해안선과 흩어진 섬들을 자기 것이라 주장한다. 바다거북과 다른 생물들이 그 주변의 물을 함께 쓴다.",
	["s:1445:dustwallow bay"] = "먼지진흙 만은 대해의 일부로, 테라모어 섬 서쪽에서 먼지진흙 습지대의 동쪽 해안으로 파고든다. 만 앞바다 성난파도 만의 작은 섬에서는 어부 냇 페이글이 홀로 물을 지켜보고 있다.",
	["s:1445:emberstrifes den"] = "악취 나는 용의 둥지로 넓은 동굴 하나가 열려 있는데, 검은 비룡 엠버스트라이프의 보금자리이다. 이곳에서 그는 어린 검은용족을 인내와 잔혹함의 시련으로 시험한다. 자격을 증명한 자만이 오닉시아의 둥지로 들어갈 수 있기 때문이다.",
	["s:1445:foothold citadel"] = "거점 요새는 테라모어 섬의 심장부에 서 있으며, 테라모어 경비대의 본부이다.\n\n스랄의 군대가 테라모어를 급습했을 때, 렉사르와 그의 동료들이 이끌고 들어간 이 요새에서 데일린 프라우드무어가 최후를 맞았다. 오크와 맺은 딸 제이나의 평화를 거역했던 대제독은 이 성벽 안에서 쓰러졌다.",
	["s:1445:lost point"] = "버려진 경비탑은 먼지진흙 습지대 서부에 테라모어가 세운 낡은 정찰탑으로, 더 이상 그것을 세운 이들을 위해 쓰이지 않는다. 이제 테라모어의 탈영병들이 그곳을 차지하고 있으며, 발로스 재큰이 그들을 이끈다. 그는 매우 중요한 인물의 납치에 헨델 이병이 연루되어 있다는 사실을 알고 있다.",
	["s:1445:north point tower"] = "북부 경비탑은 오가는 이가 많은 길 옆에서 먼지진흙 습지대 북부를 지켜보며, 상당한 규모의 테라모어 경비대가 지키고 있다. 탈영병들이 버려진 경비탑을 차지한 뒤로, 이 탑은 테라모어의 가장 먼 전초기지가 되었다.",
	["s:1445:onyxias lair"] = "오닉시아의 둥지로 들어가는 통로는 그 무리 어미의 쩍 벌린 턱을 닮았다. 그 너머의 길은 용암으로 둘러싸여 있고, 땅은 갈라져 아래에서 올라오는 불로 빛난다. 위의 바위 천장은 신음하며 흔들려 끊임없이 돌을 쏟아 내고, 열기를 붙잡아 둘 수 없는 곳에서는 벽마저 용암을 흘린다. 오닉시아는 먼지진흙 습지대 안의 음울한 늪, 용의 늪 깊은 아래에 이곳을 직접 깎아 만들었다.\n\n그녀는 동족과 다르다. 아버지가 무자비한 힘으로 다스리고, 오빠가 뒤틀린 괴물들을 빚어 제 뜻을 따르게 하는 반면, 오닉시아는 속삭임과 매력으로 일하며 필멸자들의 얽히고설킨 정치를 즐기고 그들을 조용히 자신의 목적에 굴복시킨다. 한동안 그녀는 카트라나 프레스터라는 훔친 이름을 쓰며, 그 모습으로 스톰윈드 궁정의 한복판에 스며들어 안에서부터 그것을 무너뜨리려 했다. 그 가면을 꿰뚫어 보고 그녀의 정체를 밝힌 이는 원수 윈저였다. 정체가 드러난 그녀는 도시를 떠나 늪 아래의 불타는 전당으로 돌아갔고, 지금도 그곳에서 그녀의 동족인 검은용군단의 호위를 받으며 머물고 있다.",
	["s:1445:quagmire"] = "먼지 수렁은 먼지진흙 습지대의 흠뻑 젖은 심장부로, 버려진 경비탑과 먼지진흙 만 사이에 이어지며, 북쪽으로는 담쟁이 마을, 남쪽으로는 용의 늪에 둘러싸여 있다.\n\n검은 물속에는 악어가 도사리고, 갈대 사이로는 수액괴물과 거미가 기어 다니며, 자신들을 동족이라 불러 줄 이들과 멀리 떨어진 그림토템 타우렌이 이곳에 자리를 잡고 있다. 머물기보다는 건너가는 편이 나은 곳이다.",
	["s:1445:sentry point"] = "감시초소는 테라모어에서 다리를 건너자마자 솟아 있으며, 아래 길을 감시하려고 요새가 세운 정찰탑이다. 탑은 무너지지 않은 채, 도시로 향하는 모든 이를 말없이 지켜보고 있다.",
	["s:1445:shady rest inn"] = "그늘 쉼터 여관은 한때 먼지진흙 습지대와 불모의 땅 남부 사이의 경계 근처에 서 있던, 인간이 지은 여행자 쉼터였다.\n\n여관은 아무 예고 없이 잿더미로 타 버렸다. 범인을 댈 수 있었을지도 모를 두 사람, 파발 리스와 콜드웰 중위가 있었지만, 둘 다 진실을 말하기 전에 살해당했고, 화재는 미결로 남았다.",
	["s:1445:stonemaul ruins"] = "돌망치 마을은 한때 먼지진흙 습지대에 서 있던 돌망치 부족 오우거의 보금자리였다. 고대 오크의 도끼 세라실을 손에 넣은 전쟁군주 코르갈이 부족을 장악해 잔혹함으로 다스리기 전까지는. 렉사르가 이곳에 와서 입장을 거부당하자 싸워서 들어간 곳이 바로 여기였다. 코르갈은 그가 죽음의 짐승들이 들끓는 골짜기, 시련의 길에서 살아남는다면 부족의 일원으로 받아 주겠다고 했다. 렉사르는 그것을 견디고 돌아와 돌망치의 일원이 되었다. 코르갈이 쿨 티라스에 맞선 호드의 전쟁에 부족을 내주기를 거부하자, 렉사르는 지도자 자리를 걸고 그에게 도전해 그를 죽였고, 직접 돌망치 부족을 이끌고 전쟁에 나섰다. 그 뒤 그는 모크모로크를 자기 대신 다스릴 자로 세우고 떠났다.\n\n모크모로크는 렉사르처럼 다스리지 않았다. 그는 백성을 섬기기보다 그들에게서 빼앗았고, 오닉시아의 무리가 마을에 내려와 그곳을 차지하자 생존자들을 안전한 곳으로 이끈 뒤, 옛 보금자리를 되찾으러 싸우기보다 용들에게서 멀리 떨어진 그곳에 머무는 데 만족했다.\n\n폐허는 이제 용의 늪 안에 서 있으며, 불갈기 용족이 들끓는다.",
	["s:1445:swamplight manor"] = "늪지기 오두막은 먼지진흙 습지대의 마녀 언덕에 있는 소박한 집으로, 늪눈이라 불리는 요리사 잘의 보금자리이다.\n\n바깥 정원에는 파헤쳐진 흙더미 하나가 잘의 요리로는 설명되지 않는 무언가를 숨기고 있다. 오크 첩자가 묻어 둔 보고서로, 엿보는 눈으로부터 비밀을 지키려고 흙 아래에 남겨 둔 것이다.",
	["s:1445:theramore isle"] = "3차 대전쟁이 끝난 뒤, 제이나 프라우드무어는 로데론의 생존자들을 이끌고 바다를 건너 칼림도어로 왔다. 그들은 먼지진흙 습지대 앞바다의 바위섬에 테라모어를 세웠다. 낯선 땅에서 얼라이언스의 남은 이들을 품기 위한 성벽 도시였다.\n\n도시는 대포탑이 박힌 네모난 성벽으로 둘러싸여 있으며, 성벽이 끊긴 곳은 항구뿐이고 그곳은 두 개의 정찰탑이 대신 지킨다. 한가운데에는 테라모어에서 가장 높은 건물인 제이나의 탑, 요새가 솟아 있다. 나무 바닥을 깐 여러 층이 구불구불한 계단으로 이어지고 공격에 대비한 보호 마법이 걸려 있으며, 제이나의 개인 거처와 서재, 도시의 작은 알현실이 그 안에 있다. 그 가까이에는 경비대 숙소인 거점 요새가 서 있는데, 병사들이 훈련용 허수아비를 상대로 연습하고, 신병들은 누가 다치는 순간 빛을 부를 준비가 된 사제들의 감시 아래 대련한다.\n\n습지는 척박한 흙과 쓸모없는 목재밖에 내주지 않으며, 테라모어의 선원들은 오크가 오그리마 위에서 베어 가는 떡갈나무가 먼지진흙이 내주는 어떤 것보다 훨씬 낫다고 투덜댄다. 그래도 인간과 오크는 생선과 듀로타의 남는 곡물을 맞바꾸고, 지금으로서는 도시의 범죄는 적으며 사람들은 대체로 평화롭게 지낸다.",
	["s:1445:tidefury cove"] = "성난파도 만은 테라모어 섬 남쪽, 먼지진흙 만의 끝에 있으며, 그 물에는 작은 섬들과 숨은 암초가 흩어져 있다. 배를 몰기에 위험한 바다이다. 두 척의 배가 얕은 물에 부서진 채 누워 있으며, 이제는 떠도는 마크루라의 차지가 되었다.\n\n작은 섬들 사이에는 어부 냇 페이글의 보금자리인 냇의 선착장이 있다.",
	["s:1445:witch hill"] = "늪지기 오두막은 마녀 언덕 한가운데에 서 있으며, 늪눈이라 불리는 잘의 보금자리이다. 수렁지느러미 멀록들이 근처 수렁에 야영지를 두고 있다.",
	["s:1445:wyrmbog"] = "먼지진흙 습지대의 용의 늪 남쪽에서 수렁은 짙어져 용의 둥지가 된다. 검은용들이 이곳을 보금자리로 삼고 있으며, 땅은 두 곳의 숨겨진 장소로 열린다. 엠버스트라이프의 굴 입구, 그리고 오닉시아 자신의 둥지이다.",
	["s:1446:abyssal sands"] = "이곳의 모래는 사방으로 뻗은 사막, 타나리스 안에 펼쳐져 있다.",
	["s:1446:broken pillar"] = "가젯잔 남쪽, 끝없는 사막 근처에는 무너진 기둥이라 불리는 작은 트롤 폐허 무리가 서 있다. 그곳에는 고블린 과학자 마르본 리벳시커가 야영지를 차리고, 무너진 돌 사이에서 자신만의 답을 찾고 있다.",
	["s:1446:caverns of time"] = "시간의 동굴은 타나리스 동쪽 모래 아래에 자리한 구불구불한 미로로, 위쪽 세상으로부터 봉인되어 있다. 이곳에서 청동용군단은 시간 그 자체의 갈래진 길을 지켜본다. 세상이 젊었을 때부터 이것은 티탄이 그들에게 맡긴 신성한 임무였다. 하찮은 손들의 간섭은 역사의 흐름을 풀어 버릴 수 있으니, 필멸자의 침입으로부터 동굴을 지키라는 것이다. 동굴 한가운데에는 거대한 모래시계가 서 있다.\n\n시간의 위상 노즈도르무는 이곳에서 자기 용군단과 함께 머물며, 희귀한 유물을 모으는 은밀한 취미를 즐긴다. 2차 대전쟁이 끝난 뒤, 마법사 크라서스는 한순간에 거리를 건너게 해 주는 장치인 영겁의 장미를 이용해 노즈도르무의 거처로 들어갔다. 노즈도르무는 그 침입이 수집하던 중의 자신을 방해했기에 불쾌해했고, 그 불쾌함을 분명히 드러냈다.",
	["s:1446:dunemaul compound"] = "모래망치 주둔지는 타나리스의 모래 위에 넓게 펼쳐진 모래망치 오우거의 흙더미 소굴로, 부족은 햇볕 아래 흙으로 지은 거처에 모여 산다.",
	["s:1446:eastmoon ruins"] = "타나리스의 모래지옥 협곡 서쪽, 돌 계단식 단과 금이 간 기둥들이 동쪽 달의 폐허를 표시한다. 오래전에 버려진 트롤 거주지의 남은 전부이다. 트롤들이 떠난 뒤 모래망치 오우거가 무너져 가는 석조물을 차지했고, 지금도 지키고 있다.",
	["s:1446:gadgetzan"] = "가젯잔은 타나리스 사막 북부에서 늘 검은 연기를 뒤집어쓴 채 솟아 있으며, 고블린 무역회사 가운데 가장 큰 스팀휘들 무역회사의 수도이다. 이곳에서는 고블린의 신조가 모든 것을 지배한다. 충성보다 이익이다. 호드와 얼라이언스 모두 공식적으로 이 도시를 중립 지대로 인정하며, 고블린 해결사들이 거리를 순찰하다가 교역 위에 세워진 이곳에 전쟁을 끌고 들어오는 어리석은 자는 누구든 곤죽이 되도록 두들겨 팬다. 누가 환영받는지를 정하는 것은 깃발이 아니라 지갑이다.\n\n그 중립이 모두에게 편했던 것은 아니다. 황야의 유랑단 도적들이 북동쪽의 해그늘 폐허와 샘솟는 벌판을 차지했다. 고블린들은 오래된 폐허에는 관심이 없었지만, 샘솟는 벌판은 이야기가 달랐다. 가젯잔 수도 회사가 사막의 이글거리는 태양 아래 그곳에 세우고 관리해 온 급수탑들은 도시를 살려 두는 액체 황금이었다. 고블린들은 땀 흘려 얻은 탑을 내줄 생각이 없었고, 그래서 세상 먼 곳에서 온 용병들이 가젯잔의 물을 빼앗으려는 도적들에 맞서 그것을 지키는 일에 끌려 들어왔다.",
	["s:1446:gaping chasm"] = "모래지옥 협곡은 하잘리 실리시드로 들끓으며, 그 벌집 단지가 타나리스 남동쪽의 바위 속에 벌집처럼 뚫려 있다.\n\n수석 측량사 피즐다우저는 한때 부하 스크림생크를 협곡 아래로 보내 측량하게 했다. 스크림생크는 끝내 나오지 못했다. 그는 벌집들 사이에서 죽었고, 나중에 그의 장비만이 수습되어 피즐다우저에게 돌아왔다. 피즐다우저는 자신이 그를 죽음으로 보냈다는 사실을 끝내 알지 못했다.",
	["s:1446:lands end beach"] = "끝자락 해안은 칼림도어의 남동쪽 모서리가 바다와 만나는 타나리스의 가장 남쪽 끝에 있다. 해안은 고요하며, 주로 그곳을 누비는 생물들로 눈에 띈다. 파도타기 바다거북과 모래톱 게들이 방해받지 않고 동쪽 모래사장을 따라 발을 옮긴다.",
	["s:1446:lost rigger cove"] = "세 방향이 산으로 가려진 해적단 소굴에는 타나리스 해안에 자리한 남해 해적단의 항구가 숨어 있으며, 그 조선소에서는 새 배를 짓느라 분주하다.",
	["s:1446:noonshade ruins"] = "해그늘 폐허는 가젯잔 동쪽에 있으며, 오래전에 사라진 트롤들이 남긴 닳은 돌이다. 이 폐허가 한때 어떤 쓰임새였는지, 그것을 세운 이들이 어떻게 되었는지, 사막의 모래는 더 이상 말해 주지 않는다.",
	["s:1446:noxious lair"] = "타나리스 남서쪽의 모래에는 한때 물이 있던 자리에 상처 하나가 나 있다. 실리시드가 오기 전 이 땅에는 강이든 호수든 넓고 얕은 무언가가 가로놓여 있었고, 켄티파르 떼는 그곳에서 찾은 것을 비워 버렸다. 그 때문에 타나리스 서부는 메말라 버렸다.\n\n지표는 아직도 잃어버린 것의 모양을 보여 준다. 땅은 가라앉고 움푹 꺼져, 마치 호숫가였던 시절을 기억하듯 운고로 분화구를 내려다본다. 여기저기 거대한 발톱들이 모래에서 곧게 솟아 꿈틀거리는데, 마치 묻힌 생물들이 공격하던 도중에 굳어 버린 듯하다. 발톱마다 그 주변의 흙은 실리시드의 점액으로 검고 축축하다. 한때 호수를 품었던 곳에 남은 유일한 습기이다.\n\n지표 아래의 맹독의 둥지는 켄티파르가 타나리스에 파 놓은 다른 벌집들과 다를 바 없다. 눅눅하고 따뜻하며, 섬뜩할 만큼 고요하고, 굴은 실리시드의 산으로 뒤덮여 있다.",
	["s:1446:sandsorrow watch"] = "슬픈모래 감시탑은 가젯잔 서쪽, 타나리스의 메마른 분지에 펼쳐져 있으며, 파라키 트롤과 그들이 자기 망자들 가운데서 일으킨 좀비들이 차지하고 있다.",
	["s:1446:south seas"] = "알려진 대륙들의 남쪽 바다는 대해의 넓은 구역으로 열리며, 그 이름을 주로 선원들만 아는 섬들을 지나 해류를 실어 나른다. 트롤 제국의 옛 고향인 잔달라가 이 바다에서 솟아 있다. 본토의 세력들과 떨어져 자기 백성을 품고 있는 화산섬 케잔도 그 사이에 있다.\n\n가시덤불 골짜기에 가까워질수록 바다는 암초와 숨은 만으로 험해진다. 선장이 바위 하나하나의 이름을 알거나 아니면 배를 잃는, 그런 바다이다. 이 구간에는 작은 섬들이 점점이 흩어져 있는데, 어떤 섬은 모래톱에 지나지 않고, 어떤 섬은 세운 이들이 오래전에 파도 아래로 사라진 폐허를 품고 있다.\n\n이 바다에 이름을 붙일 만한 까닭은 그 위에서 벌어진 어떤 한 전투라기보다, 바다가 삼켰다가 반쯤 다시 드러낸 것들에 있다. 가라앉은 신전, 물에 잠긴 해안, 썰물 때 맑은 물 너머로 언뜻 보이는 폐허들이다. 이곳은 가장자리와 틈새의 바다로, 가시덤불과 타나리스, 울둠의 경계를 따라 흐르며, 파도가 가져다주기로 한 것이면 무엇이든 자신이 가르는 해안으로 실어 나른다.",
	["s:1446:southbreak shore"] = "거친파도 해안은 타나리스 남쪽 끝을 따라 고요히 펼쳐진 평평한 해변으로, 생물이 거의 없다. 바다거북과 바다 거인들이 파도 속을 누빈다.",
	["s:1446:southmoon ruins"] = "서쪽 달의 폐허는 타나리스 남부에 있는 오래된 트롤 거주지의 잔해로, 그 돌들은 풍화되어 사막의 모래에 반쯤 묻혀 있다.",
	["s:1446:steamwheedle port"] = "스팀휘들 항구는 타나리스의 동쪽 해안에 자리하며, 서쪽으로는 모도시 가젯잔으로 가는 길이, 바다 쪽으로는 케잔을 향한 부두가 뻗어 있다. 이곳은 금만 좋다면 찾아오는 누구와도 거래하는 고블린들, 스팀휘들 무역회사의 것이다.\n\n항구의 주민 가운데에는 예키냐가 있는데, 그의 거래가 영혼의 약탈자 학카르의 귀환을 부추겼다.",
	["s:1446:thistleshrub valley"] = "덤불나무 골짜기에는 거대한 선인장이 빽빽한데, 이토록 척박한 사막이 살아 있는 것을 자라게 한다는 것이 기이하다. 한때 이곳에 무성하던 엉겅퀴 덤불은 최근 들어 드문드문해졌고, 이제는 그 사이에서 사막 꽃을 찾을 수 있지만 그마저 드물다.",
	["s:1446:uldum"] = "울둠은 칼림도어의 남쪽 해안에 있으며, 북쪽의 운고로 분화구, 동쪽의 타나리스, 북서쪽의 실리더스에 벽처럼 둘러싸여 있다. 티탄의 전승이 풍부한 곳으로, 그 산길은 어떤 필멸자의 눈도 들어가는 길을 찾지 못하도록 가려져 있다.",
	["s:1446:valley of the watchers"] = "감시자의 골짜기는 타나리스 남부를 지키며, 그곳에는 울둠에 맞서 뚫을 수 없는 거대한 문이 서 있다. 산악 거인인 모래파괴자들이 그 감시자로서 이곳을 누빈다.",
	["s:1446:waterspring field"] = "샘솟는 벌판이라는 이름은 그 위에 솟은 급수탑들에서 왔다. 급수탑은 땅속 깊은 곳의 저수층에서 물을 끌어 올린다. 가젯잔의 고블린들이 타나리스 사막에서의 작업에 쓸 물을 확보하려고 그것들을 세웠다.\n\n그 계획은 황야의 유랑단을 버텨 내지 못했다. 떠돌이 도적들이 벌판으로 몰려들어 그냥 차지해 버렸고, 그것을 세운 고블린들은 아랑곳하지 않고 탑들을 제 것으로 삼았다. 그들은 지금도 그곳에 눌러앉아 있으며, 그 전에 무엇을 피해 달아났든 이 땅에 꽤 만족한다. 그 전에 머물던 오우거 야영지에 대해서는 말하려 하지 않고, 그저 이곳이 낫다고만 한다.",
	["s:1446:wavestrider beach"] = "파도타기 해안은 타나리스의 동쪽 기슭을 따라, 스팀휘들 항구와 해적단 소굴 사이의 모래사장으로 이어진다. 이곳 해변에서는 사막 기어다니미들이 같은 해안을 함께 쓰는 강철턱 치악거북들과 나란히 종종걸음 친다.",
	["s:1446:zalashjis den"] = "잘라쉬지의 굴은 한때 이곳에 굴을 틀었던 누군가의 이름을 아직 지니고 있다. 전해지는 이야기 어디에도 잘라쉬지가 누구였는지, 그 뒤로 이곳이 어떻게 되었는지는 나오지 않는다. 잘라쉬지가 아직 살아 있는지, 이곳에서 죽었는지, 다른 곳에서 죽었는지 누구도 확실히 말할 수 없다.",
	["s:1446:zulfarrak"] = "줄파락은 한때 밀림의 도시였다. 타나리스가 아직 구루바시 제국 아래의 숲이던 시절이었다. 대분리가 고대 세계를 찢어 놓았을 때, 밀림은 불타 사막이 되었고, 이곳에 도시를 세웠던 파라키 트롤은 모래 한가운데 고립되었다. 그들은 버텨 냈고, 단단해져 모래폭풍 부족이 되었다. 트롤들 사이에서조차 무자비함과 어두운 신비주의로 이름난 부족이다.\n\n햇볕에 달구어진 성벽 안에서, 트롤의 전설은 채찍 술스라제를 이야기한다. 그 칼날이 닿는 적에게는 누구든 공포와 나약함을 심는다는 검이다. 오래전 그 검은 두 동강이 났고, 두 조각 모두 아직 도시 안 어딘가, 뜰과 신전 사이에 잃어버린 채 놓여 있다고 속삭여진다.\n\n줄파락의 심장부에는 성스러운 연못이 있고, 모래폭풍 부족은 그 고요한 물 아래에 자신들보다 훨씬 오래된 무언가를 잠들게 해 두었다고 한다. 깨어나면 도시와 그 안의 모든 것에 파멸을 불러올 반신이다.",
	["s:1447:bay of storms"] = "폭풍의 만은 아즈샤라의 동쪽 해안 앞에 있으며, 그 물은 그곳에 모이는 폭풍으로 여행자들에게 알려져 있다. 그 기슭을 따라 비늘수염 동굴, 헤타에라의 손아귀, 아크코란의 신전이 서 있다.",
	["s:1447:bears head"] = "곰마루라는 이름은 이 땅 곳곳에 흩어진 퍼볼그 마을에서 왔다. 더 북쪽의 나무구렁 요새와 우르솔란으로 가는 길목을 지켜보는 작은 전초기지들이다.\n\n마을들 위의 절벽에는 대마법사 자일렘의 탑이 서 있으며, 그는 그 벽 안에서 연구하고 일하는 여러 제자와 동료들과 함께 지낸다.",
	["s:1447:bitter reaches"] = "시련의 산마루는 아즈샤라 북동쪽에 있으며, 히포그리프와 수액괴물, 키메라가 가득하다. 북쪽 끝을 따라 산악 거인들이 더 작은 야생 동물들을 몰아내고 그 땅을 차지했다.",
	["s:1447:forlorn ridge"] = "쓸쓸한 마루는 아즈샤라 서부 위로 솟아 사방 수십 리의 땅을 굽어본다. 그 비탈에는 요새들이 짝을 이루어 서 있다. 얼라이언스와 호드가 서로 보이는 곳에 세운 것들로, 한 번도 벌어지지 않은 전투를 위해 지어져 텅 빈 채 서 있다.",
	["s:1447:haldarr encampment"] = "할다르 야영지는 아즈샤라 서부에 사티로스가 빽빽하게 모인 곳으로, 염소 다리를 한 타락한 마귀 무리의 모닥불이 섀도송 제단 북동쪽이자 옛 발로르모크 남서쪽에서 타오른다.",
	["s:1447:hetaeras clutch"] = "아즈샤라 앞바다 폭풍의 만 아래에는 헤타에라의 손아귀라는 신전이 있으며, 이제는 히드라의 보금자리가 되었다.",
	["s:1447:jagged reef"] = "톱니 산호초는 아즈샤라의 북쪽 해안으로, 모래사장이 튀어나온 바위와 작은 후미에 거듭 끊겨 있다. 수면 아래에는 바위와 얕은 곳이 숨어 있어 해안을 오가기가 위험하다. 멀록과 히드라, 마크루라가 이 해안을 차지하고, 얕은 물을 헤엄치거나 모래를 느릿느릿 걸으며 먹이를 찾는다.",
	["s:1447:lake mennar"] = "멘나르 호수의 물은 한가운데에서 고요하지만, 사방의 땅은 용족의 것이다. 그 경계를 넘어선 이는 호수 자체에는 위험이 없음을 알게 된다. 지켜지는 기슭 한가운데 자리한 고요와 휴식의 장소이다.\n\n이곳은 노스렌드를 제외하면 푸른용군단이 모습을 드러낸 세상의 몇 안 되는 곳 가운데 하나이다. 이에 견줄 만한 곳은 여명의 설원의 마즈소릴뿐이다. 이 물가 근처에서는 어린 하늘빛 새끼용을 흔히 볼 수 있다.",
	["s:1447:legash encampment"] = "레가쉬 사티로스는 아즈샤라 북부, 우르솔란 동쪽에 야영지를 두고 있다.\n\n대마법사 자일렘은 한때 이곳에서 마법서 한 권을 발견했고, 그 발견은 지옥의 기운에 물든 생물들의 별다를 것 없는 이 야영지에 이목을 끌었다.",
	["s:1447:ravencrest monument"] = "아즈샤라 남쪽 끝의 절벽에는 거상의 잔해가 남아 있지만, 이제는 그 말에 걸맞은 것이 거의 남아 있지 않다. 부서진 다리만이 바다 위에 박힌 채 아직 서 있고, 거대한 형상의 나머지는 주변 바위 위에 흩어져 있거나 아래의 파도 속으로 미끄러져 들어갔다.\n\n이제 폐허는 악의비늘 나가의 차지이다. 바다로는 이곳에 닿을 수 없다. 이곳을 찾으려는 이는 땅으로 와서 엘다라스 폐허 너머로 뻗은 다리를 건너, 한때 틀림없이 보기에 장엄했을 무언가의 쓰러진 다리 아래에 서야 한다.",
	["s:1447:rethress sanctum"] = "레스리스 성소는 레이븐크레스트 기념비 남서쪽, 버려진 착륙장 사이에 부서진 채 서 있다. 이제는 아무도 그곳을 돌보지 않는다. 멀록과 마크루라만이 무너진 돌 사이를 떠돌 뿐, 그곳을 찾는 것은 그들뿐이다.",
	["s:1447:ruined reaches"] = "아즈샤라의 남쪽 해안은 그 폐허를 숨김없이 드러낸다. 절벽과 해변은 후미로 갈라지고, 물은 어떤 선원도 세고 싶지 않을 만큼 많은 선체를 붙잡은 얕은 곳을 숨기고 있다. 난파선들이 세운 이들이 사라진 더 오래되고 기이한 폐허와 나란히 모래에 반쯤 묻혀 있다. 멀록과 히드라, 마크루라가 해안에 출몰하며, 이 해안을 아는 이들조차 조심스럽게 발을 옮긴다.\n\n서쪽 해안의 해변 위 언덕에는 노움의 건물 한 채가 서 있는데, 내륙에서 올라가는 가파른 길로만 닿을 수 있다. 블리모와 주비 가젯스프링이 이곳에 보금자리를 마련하고 장사를 한다. 위층의 개인 거처에는 세 번째 침대가 놓여 있다. 그것이 누구의 것인지, 누가 거기서 자기는 하는지, 아무도 모른다.",
	["s:1447:ruins of eldarath"] = "세계가 부서지기 전, 엘다라스는 명가의 위대한 거점 가운데 하나로 솟아 있었다. 가장 강력한 마법사들이 룬과 석판을 돌에 새겨 공공장소에 세워 두어, 지나가는 누구든 비전에 대한 그들의 통찰을 곱씹을 수 있게 한 비전 학문의 도시였다.\n\n도시는 조용히 무너지지 않았다. 고대의 전쟁 동안 칼도레이 저항군은 이곳에서 불타는 군단에 맞서 버티었다. 대분리가 세계를 찢어 놓았을 때 엘다라스는 그것을 견디지 못했다. 도시 대부분이 무너져 내려 아래 폭풍의 만의 물속으로 가라앉았다.\n\n남은 것은 동쪽 절벽에 매달린 부서진 탑들의 무리로, 한때 그곳을 고향이라 부르던 나이트 엘프들이 오래전부터 멀리해 온 곳이다. 이제 나가가 폐허를 차지했고, 전쟁군주 크렐리안이 진말로의 신전에서 남은 것을 다스린다. 잔해 사이에는 옛 명가의 룬 석판들이 아직 서 있으며, 그 비전의 지혜는 그 뒤로 흐른 세월에도 손상되지 않았다.",
	["s:1447:scalebeards cave"] = "폭풍의 만의 아주 작은 섬에 있는 동굴은 희귀한 늙은 거북, 비늘수염의 이름을 지니고 있다. 이곳은 그의 집이지만 좀처럼 쉬는 곳은 아니다. 그는 대해 먼 곳에서 사냥하기를 좋아해 굴을 비워 두기 때문이다.",
	["s:1447:shadowsong shrine"] = "아즈샤라 서부의 폐허로 뒤덮인 언덕, 섀도송 제단에는 왜 그 이름을 지니게 되었는지 분명한 기록이 남아 있지 않다. 그 이름은 고대의 전쟁에서 저항군을 이끈 자로드 섀도송, 그리고 하이잘 산에서 배신한 일리단 스톰레이지를 가둔 감시관으로 기억되는 그의 누이 마이에브의 이름과 같다. 둘 중 누가 이 언덕과 무슨 관련이 있는지는 아무도 말할 수 없다.\n\n말할 수 있는 것은 그곳을 걷는 것들이다. 명가의 유령들이 돌 사이에 머물며, 가까이 다가오는 살아 있는 것이라면 무엇이든 굶주린 듯 노린다.",
	["s:1447:shattered strand"] = "조각난 해안은 아즈샤라 폭풍의 만의 북쪽을 따라 이어지며, 히드라와 바다 거인, 마크루라, 멀록이 빽빽하게 저마다 모래사장 한 구간씩을 차지하고 있다. 발톱과 촉수가 들끓는데도 아크코란의 신전과 엘다라의 탑이 해안에서 솟아 있다.\n\n고블린들도 이 해안에 말뚝을 박고, 이빨과 파도 한가운데서 해변 부동산에 투기를 하고 있다.",
	["s:1447:southfury river"] = "분노의 강은 하이잘 산 높은 곳에서 발원해, 산정 호수에서 쏟아져 저지대로 우레처럼 떨어지는 폭포를 이룬다. 그곳에서부터 강은 넓고 빠르게 흐르며 땅을 둘로 가른다. 잿빛 골짜기가 아즈샤라로 바뀌는 곳을 표시하고, 더 남쪽에서는 불모의 땅이 끝나고 듀로타가 시작되는 곳을 가른다. 하구에서 강은 고블린 항구 톱니항의 바로 북동쪽에서 마지막 폭포를 넘어 대해로 뛰어든다.\n\n강을 따라 다리들이 놓여 있는데, 하나는 아즈샤라와 잿빛 골짜기를, 또 하나는 듀로타와 불모의 땅을 잇는다.\n\n강은 여전히 기슭의 들판을 적시고, 흐르는 곳마다 흙을 푸르게 물들인다.",
	["s:1447:southridge beach"] = "남녘마루 해안은 폭풍의 만 남쪽 가장자리를 따라 이어지며, 그 모래 위에는 한때 위대했던 도시 엘다라스의 폐허가 흩어져 있다. 이제 나가가 해안을 차지하고, 마크루라와 히드라, 멀록, 그리고 이따금 깊은 물에서 올라오는 바다 거인과 그곳을 함께 쓴다.",
	["s:1447:storm cliffs"] = "폭풍 절벽은 아즈샤라에 솟아 있으며, 바위 사이에 사는 악의비늘 나가가 차지하고 있다. 절벽의 동쪽 끝에는 레이븐크레스트 기념비가 서 있다. 나가가 차지한 바위를 굽어보는 외로운 표지이다.",
	["s:1447:talrendis point"] = "탈렌드리스 초소는 아즈샤라 남서쪽에 서 있으며, 두 개의 경비탑이 잿빛 골짜기와의 경계를 지켜보고, 달샘 하나가 아직 남쪽 땅을 적신다.\n\n이 초소는 숲 가장자리에서 감시를 서던 작은 나이트 엘프 야영지에서 시작되었다.",
	["s:1447:temple of arkkoran"] = "아크코란의 신전은 한때 엘룬 숭배에 바쳐진 곳으로, 그 돌들은 아즈샤라 북동쪽 해안에 세워졌다. 그 신성함은 오래전에 사라졌다. 이제 바다 거인 아크코록이 그 꼭대기에 살며, 가까이 오는 자는 누구든 덮치는 멀록과 마크루라가 그를 지킨다. 주변 해안인 조각난 해안도 더 안전한 길을 내주지 않는다. 아크코록 못지않게 사나운 히드라와 바다 거인들이 그곳을 지키고 있다.",
	["s:1447:temple of zin malor"] = "진말로의 신전은 엘다라스 폐허 사이에 서 있으며, 그 돌들은 근처 아크코란의 신전, 그리고 훗날 다르나서스에 세워진 달의 신전을 닮은 모습으로 다듬어졌다. 이 신전은 나이트 엘프가 비전 마법에 눈을 돌리기 전 시절, 엘룬에 대한 헌신으로 지어졌다.\n\n그 안에는 한때 진말로의 수정이 놓여 있었다. 명가에게 전하려던 메시지를 담은 선물이었다. 그들에게는 애초에 비전 마법이 진정으로 필요하지 않다는 메시지였다. 수정은 이제 사라졌다. 오래전에 누군가가 가져갔다.\n\n그 뒤로 신전은 악의비늘 부족 나가의 손에 떨어졌다. 이제 전쟁군주 크렐리안이 그곳을 다스리며, 한때 여신 숭배를 위해 남겨 두었던 영예로운 자리를 자기 것으로 삼았다.",
	["s:1447:thalassian base camp"] = "레가쉬 야영지들 위의 언덕은 블러드 엘프의 것으로, 그 비탈은 마법사 림토리 아래의 작은 요새화된 초소들로 나뉘어 있다. 그녀는 호드와 거래를 맺었다. 원정대를 지킬 금과 무기를 받는 대신 원정대가 발굴하는 것이면 무엇이든 한몫을 나누겠다고 약속한 것이다. 그 거래는 지켜지지 않았다. 림토리는 자금을 받고 아무것도 돌려주지 않았으며, 배신의 소문은 퍼지고 퍼져 이제 그녀와 추종자들에게 그만한 복수가 돌아가야 한다는 말까지 나온다.\n\n림토리 자신은 좀처럼 야영지에 있지 않다. 그녀는 직접 고른 호위를 거느리고 아즈샤라를 탐험하는 데 몰두하고, 그녀가 없는 동안 마법학자 호크헬름이 언덕을 지킨다. 두 사람이 진정으로 노리는 것은 금이 아니다. 야영지의 한 마루에는 악마를 세상으로 불러낼 수 있는 칼도레이 소환의 서가 놓여 있으며, 그것이 그곳에 있다는 사실은 원정대의 정체를 드러낸다. 보물 사냥이 아니라, 보물 사냥의 옷을 입은 더 어두운 무언가이다.",
	["s:1447:tower of eldara"] = "엘다라의 탑은 폭풍의 만 위, 땅의 가장 북동쪽 끝에 서 있으며, 그 모래 해안은 멀록과 마크루라, 히드라가 순찰한다. 탑은 한때 이 해안 곳곳에 퍼져 있던 나이트 엘프 문명의 것이었지만, 지금은 닫힌 채 버려져 있다.",
	["s:1447:ursolan"] = "우르솔란은 퍼볼그 종족이 숭배하는 곰의 반신 우르솔에게서 이름을 얻었다. 이제 이곳은 나무구렁 퍼볼그의 넓은 거주지로, 남쪽으로 요새를 지나 곰마루까지 이어져 있다.",
	["s:1447:valormok"] = "발로르모크는 아즈샤라 북서쪽, 할다르 야영지 북쪽에 있는 호드 전초기지이다. 그곳에 주둔한 전사들은 힘든 시절을 견디면서도 희망을 놓지 않는다.\n\n그 희망은 안에서부터 배신당했다. 벨그롬 락모올은 블러드 엘프인 마법사 림토리를 오크 전사 무리와 함께 보내 이 지역의 부와 강력한 유물을 찾게 했다. 림토리는 찾던 것을 찾아냈지만, 그 발견을 나누는 대신 자신을 호위한 전사들에게 등을 돌려 그들을 죽이고 전리품을 독차지했다. 야영지를 이끄는 아그토르 블러드피스트는 그 학살을 그냥 넘기지 않을 것이다. 그는 쓰러진 이들과 락모올의 상처 입은 자존심을 위해 복수하고, 근처 그녀의 야영지에서 마법사 림토리를 죽일 전사들을 찾고 있다.",
	["s:1448:bloodvenom falls"] = "피멍울 폭포는 악령의 숲 높은 곳에서 굴러떨어지며, 그 물은 근원에서부터 더럽혀져 있다. 이곳에서 피멍울 강이 시작되어 오염을 아래로 실어 나르다가, 병든 성난굽이 강이 되어 어둠의 해안으로 흘러든다.",
	["s:1448:bloodvenom post"] = "피멍울 초소는 피멍울 강이 악령의 숲을 가르는 곳, 어둠의 해안 위 높은 절벽에 서 있다. 그 건축 양식과 그곳을 지키는 타우렌은 이곳이 타우렌이 세운 곳임을 보여 준다. 아래 해안을 지켜보는 호드의 작은 발판이다.\n\n악령의 숲을 지나는 돌길에서 강의 남쪽 기슭을 따라 서쪽으로 이어지는 어두운 오솔길을 따라가면, 언덕 비탈을 돌아 초소에 이른다.",
	["s:1448:bloodvenom river"] = "피멍울 강은 악령의 숲을 검게 흐르며, 그 타락은 지역을 넘어 퍼져 어둠의 해안에서 성난굽이 강으로 다시 모습을 드러낸다. 유독한 수액괴물들이 강둑을 기어 다니고, 근처의 야생 동물들은 독을 품게 되었다. 누구도 그 물을 마시지 않고, 누구도 그 물에서 헤엄치지 않는다.",
	["s:1448:deadwood village"] = "마른가지 퍼볼그는 악령의 숲 남부에 굵은 통나무 벽을 둘러 마을을 세우고, 그 안에 더 튼튼한 건물들을 지었다. 타락한 숲 곳곳의 동족처럼, 그들도 악령의 숲의 오염에 굴복해 적대적이고 뒤틀린 존재가 되었다.",
	["s:1448:emerald sanctuary"] = "에메랄드 성소는 악령의 숲 남동쪽에 서 있는 에메랄드 의회 드루이드들의 야영지이다. 그들은 이곳에서 자에데나르를 지켜보며, 그곳에서 퍼져 나오는 악마의 타락이 땅을 더 삼키기 전에 꺼 버리려 애쓴다.",
	["s:1448:felpaw village"] = "악령발 마을은 악령의 숲 북쪽 끝, 나무구렁 요새 입구 근처에 서 있다. 이곳은 타락으로 동족과 등을 돌린 퍼볼그, 마른가지 부족의 것이며, 그들의 오염은 여전히 그들이 차지한 땅에 흔적을 남기고 있다.",
	["s:1448:irontree cavern"] = "동굴 깊은 곳에는 뒤틀린숲의 뒤틀린 나무가 뿌리를 내려, 살아 있는 수호자 대신 어둠을 누비는 파쇄자와 이끼 가죽벗기미를 낳았다.",
	["s:1448:irontree woods"] = "강철나무 숲은 한때 악령의 숲 북부의 평화로운 숲이었다. 불타는 군단의 타락이 그것을 다른 무언가로 뒤틀기 전까지는. 이곳에는 나이트 엘프의 위대한 고대정령 셋, 하스타트, 스토마, 바르트루스라는 살아 있는 나무들이 살았다. 타락은 그들도 가만두지 않았다. 셋 모두 선 자리에서 돌로 굳었고, 지금도 자신들을 죽인 역병 한가운데서 죽은 채 숲에 묻혀 있다.\n\n그러나 무언가는 죽은 채로 있기를 거부했다. 숲의 심장부에 부은 달샘 물이 묘목 하나를 틔웠다. 보살핌을 받으며 자란 묘목은 꽃을 피웠고, 태어난 땅으로 돌아가 돌로 굳은 망자들 사이에 뿌리를 내린 채, 그들을 대신할 고대정령으로 설 날을 기다리고 있다.",
	["s:1448:jadefire glen"] = "악령의 숲 남부의 타락한 숲에서, 비취불꽃 숲은 사티로스 야영지를 품고 있다. 악마 같은 이 생물들은 오염된 분지를 자기 것으로 삼아 그 썩음 속에서 번성하며, 주변 나무들 사이로 타락을 더 퍼뜨린다.",
	["s:1448:jadefire run"] = "악령의 숲 북부에는 이 지역에서 가장 강력한 사티로스의 보금자리, 비취불꽃 비탈이 있다. 가까이 가려는 이는 조심해야 한다. 그 건물들은 필멸자가 아닌 악마의 양식을 따르고 있다.",
	["s:1448:jaedenar"] = "자에데나르는 한때 나이트 엘프의 것이었던 땅에서 솟아 있으며, 그 돌들은 지금 그것을 차지한 타락보다 오래되었다. 그 폐허 아래에는 한때 신성했던 드루이드의 지하굴 두 곳이 있으며, 어둠의 의회가 자신들의 지배를 세운 것은 바로 이 더럽혀진 토대 위였다. 그들은 책략가 킬제덴을 숭배하며 이곳의 이름을 지었다.\n\n3차 대전쟁 이후, 폐허는 군주 베인할로우와 그가 이끄는 어둠의 의회의 손에 넘어갔다. 오크와 포세이큰 흑마법사들이 그 전당을 채웠고, 그들은 혼자 오지 않았다. 서큐버스와 지옥사냥개, 지옥수호병, 사티로스가 그들 사이를 오갔다. 그 심장부에는 아제로스에 있는 의회의 권력 중심인 어둠의 요새가 서 있고, 그 곁에는 킬제덴의 이름으로 세운 책략가의 사원이 있다.",
	["s:1448:morlosaran"] = "모를로스아란은 한때 대분리가 세계를 찢어 놓기 전에 세워진 거대한 나이트 엘프 거주지였다. 이제 그곳은 악령의 숲 남쪽 끝에 폐허로 누워 있다. 아메스아란, 바샬아란, 오르딜아란, 테드리스아란처럼 한때 번성했던 도시들 가운데 하나로, 이제는 모두 돌과, 오래전에 잃어버린 황금시대의 기억일 뿐이다.",
	["s:1448:ruins of constellas"] = "이곳의 부서진 기둥들은 한때 하이잘 산 근처의 나이트 엘프 거주지에 속해 있었다. 그 한가운데에는 아직 달샘이 있지만, 더 이상 맑은 빛을 품고 있지 않다. 지옥의 타락이 그 물에 스며들었고, 이제 사티로스 자바스라스가 자바릭을 대신해 그것을 돌보며, 독을 뿌리려고 가꾸는 정원처럼 타락을 기르고 있다. 폐허 더 깊은 곳에서는 불의 벽이 그에게 가는 길을 막고 있다.\n\n드루이드 동족들은 악마들을 그냥 두지 않았다. 그들은 이곳에 뿌리내린 지옥의 기운으로부터 이곳을 되찾으려고 악마들을 공격하고 있다.",
	["s:1448:shadow hold"] = "악령의 숲 서부, 자에데나르 아래에는 한때 나이트 엘프의 지하굴이었던 미로가 있다. 어둠의 의회가 오래전에 그곳을 차지했고, 이제는 흑마법사들과 그들의 악마 사역마들이 그 굴을 누빈다. 사티로스 왕자 자발리스와 공포의 군주 베인할로우가 모두 그 안에 산다.\n\n성기사 트레이 라이트포지와 나이트 엘프 아르코나린 스타셰이드는 어둠의 의회가 벌이는 일의 흔적을 쫓아 악령의 숲으로 들어갔다. 광신도들은 두 사람을 모두 붙잡아 어둠의 요새 안에 가두었다. 트레이는 그곳에서 고문을 받다 죽었고, 그의 영혼은 포획자들에게 뒤틀려 타락했다. 아르코나린은 아직 깊은 곳에 갇힌 채 고문자들의 감시를 받으며, 아직 오지 않은 구조를 기다리고 있다.",
	["s:1448:shatter scar vale"] = "불벼락 골짜기는 3차 대전쟁 때 불타는 군단이 악령의 숲을 휩쓸면서 지옥불정령들이 떨어진 곳이다. 그들이 남긴 구덩이는 아직도 연기를 피우며 땅에 상처를 남기고 있고, 악마들이 여전히 그 사이를 떠돈다.",
	["s:1448:shrine of the deceiver"] = "책략가의 사원은 악령의 숲 자에데나르에 있는 타락한 지하굴로, 불타는 군단의 군주인 책략가 킬제덴에게서 이름을 얻었다. 어둠의 의회 흑마법사들이 그 깊은 곳을 채우고 있어, 준비되지 않은 이에게는 위험한 곳이다.",
	["s:1448:talonbranch glade"] = "갈퀴가지 숲은 악령의 숲 북부, 나무구렁 요새 남쪽에 자리하며, 달의 숲과 여명의 설원으로 이어지는 길을 따라 있다.",
	["s:1448:timbermaw hold"] = "악령의 숲 북동쪽의 나무구렁 요새는 퍼볼그 나무구렁 부족의 수도이다. 그 굴은 달의 숲과 여명의 설원으로 통하는 길을 열어 준다.\n\n불타는 군단의 타락이 칼림도어의 성스러운 숲으로 스며들었을 때, 퍼볼그들은 그 영향 아래 떨어져 광기로 뒤틀렸다. 오직 나무구렁 부족만이 그 어둠을 피했다. 그들은 요새 안에 몸을 숨겼고, 그들이 사랑하던 숲은 곪아 가는 뒤틀린 모습으로 변해 갔다. 악마들의 우두머리가 쓰러지고 한참이 지나서도 숲에 남은 오염은 사라지지 않았다.\n\n나무구렁 요새의 퍼볼그들은 모든 이방인을 경계한다. 타락한 동족으로 오인받아 보자마자 공격당할까 두렵기 때문이다. 그러나 그들은 홀로 버틸 수 없음을 알고 있으며, 그들의 신뢰를 얻은 이들은 나무구렁 부족이 무엇보다 우정을 소중히 여긴다는 것을 알게 된다. 무엇보다 그들이 바라는 것은 오직 타락한 형제들의 고통을 끝내고, 악령의 숲이라는 상처를 치료할 방법을 찾는 것이다.",
	["s:1449:fire plume ridge"] = "불기둥 마루는 운고로 분화구의 심장부에 솟은 그을린 바위산으로, 용암이 비탈을 타고 흘러내리고 불의 정령들이 열기 속에서 꿈틀댄다. 분화구 바닥 아래로는 얕은 용암 줄기가 흐르며 운고로 곳곳에서 쉭쉭대는 증기 웅덩이와 간헐천을 먹여 살리고, 그래서 분지 전체가 산의 불로 숨을 쉬는 듯하다.\n\n꼭대기의 동굴 안에는 이 마루에 출몰하는 불의 정령 가운데 가장 강한, 산의 타오르는 심장의 주인 화염질주자가 산다. 이곳에서 깜빡이며 춤추는 불의 영혼들은 수 세기 동안 타오르다 잉걸불로 사그라들고, 다시 불붙기를 끝없이 되풀이해 왔다고 말한다.\n\n이 마루를 찾는 모든 이가 그것을 정복하는 것은 아니다. 링고라는 방랑자가 그 비탈을 탐험하러 왔다가 길을 잃었고, 열기에 지쳐 쓰러졌다. 그는 끝내 빠져나오지 못한 채, 지금도 남쪽 동굴에서 찾을 수 있다.",
	["s:1449:fungal rock"] = "버섯 바위굴은 운고로 분화구의 북동쪽 벽에 열린 동굴로, 그 어둠 속에서 자라는 유령버섯 사이에 고릴라들이 산다. 바깥에는 폭포 아래에 작은 웅덩이가 고여 있고, 그곳에 카르나 렘트레블의 기계 유인원 에이미 01이 서 있다.",
	["s:1449:golakka hot springs"] = "골락카 간헐천에서는 끊임없이 증기가 피어오른다. 운고로 분화구의 화산 심장이 분화구 서쪽의 웅덩이와 간헐천으로 열기를 흘려보내는 곳이다. 그 증기와 불에서 태어난 격노의 정령들이 기슭을 서성이며, 간헐천을 끓게 하는 바로 그 힘에 이끌려 땅에서 나왔다.\n\n크래클은 한때 이 간헐천과 근처 불기둥 마루의 불을 잇는 것이 무엇인지 추적하러 이곳에 왔지만, 그의 탐색은 그를 다른 곳으로 데려갔다.",
	["s:1449:ironstone plateau"] = "운고로의 초록을 뚫고 북동쪽 벽을 따라 헐벗은 바위가 드러나 있다. 강철바위 고원은 분화구의 다른 곳에 비해 고요하며, 포식자가 거의 없다. 어린 테러닥스들이 이곳에 둥지를 틀며, 고원의 고요함은 이곳을 운고로의 쉴 새 없는 생장과 구별 짓는다.",
	["s:1449:lakkari tar pits"] = "마샬의 야영지 북쪽의 검은 호수들은 운고로의 초록 한가운데 걸쭉하고 악취를 풍기며 놓여 있다. 수면 위로는 수백 개의 뼈가 튀어나와 있다. 단단한 땅이라 믿고 발을 디뎠다가 그렇지 않음을 알게 된 짐승들의 유해이다. 청소부들이 가장자리를 서성이며 타르가 시작한 일을 끝내기를 기다리고, 타르 짐승들이 구덩이 자체에서 솟아올랐다.",
	["s:1449:marshals refuge"] = "마샬의 야영지는 운고로 분화구 북쪽 끝에 자리하며, 윌리든 마샬과 홀아니 마샬이 이끈 마샬 원정대가 세웠다. 분화구로 들어선 그들의 모험은 거기서 마주친 것에 대비되어 있지 않았다. 운고로의 짐승들은 너무나 사나웠고, 원정대의 야영지들은 하나씩 짓밟혔다. 남은 일행은 더 높은 곳으로 달아나 이곳 분화구 가장자리로 피신했다.\n\n야영지는 그 퇴각이 남긴 것이다. 얻어 낸 것이 아니라 겨우 지켜 낸 발판이다.",
	["s:1449:marshlands"] = "늪지대는 운고로 분화구 남동쪽에 펼쳐진 고인 물과 무성한 풀의 낮은 땅으로, 다른 길은 모두 위험하기에 타나리스에서 분화구로 처음 내려오는 이들 대부분을 맞이한다. 랩터들이 갈대 사이를 떼 지어 누비는데, 그중 일부는 이빨에 독을 품고 있다.\n\n이곳에서는 푸른 마력 수정을 찾을 수 있으며, 그 존재는 늪지 자체에 스며들어, 축축한 땅을 누비며 사냥하는 랩터들에게까지 스며들어 흔적을 남겼다.\n\n물에서 솟은 둔덕 위에서는 토르와 패스파인더가 감시를 서고 있다. 그는 분화구의 다른 곳에서 카누를 타고 이곳까지 왔다.",
	["s:1449:slithering scar"] = "갈래굽이 구렁은 운고로 분화구 남부에 펼쳐져 있으며, 고리시 종파의 벌집이다.\n\n벌집에는 한때 여왕이 있었는데, 그 안의 고리시 실리시드 수정을 건드리면 소환되었다.",
	["s:1449:terror run"] = "갈래굽이 구렁 서쪽의 공포의 터에서는 운고로 분화구의 다른 어디와도 다르게 붉은 수정이 땅에서 자라난다. 이곳의 짐승들은 그 힘을 빨아들였고, 그것이 그들의 모습에 드러난다.",
	["s:1450:lake eluneara"] = "수정처럼 맑은 물이 달의 숲의 심장부를 채우고, 나무 아래 유리처럼 고요하다. 그 수면 아래에는 수 세기 전에 패배했으나 결코 이 깊은 곳에서 완전히 사라지지 않은 미친 반신 오멘이 누워 있다. 호수는 그를 붙잡아 두고 있다. 잔잔한 물 아래의 조용한 무게이다.",
	["s:1450:nighthaven"] = "엘룬아라 호숫가에는 나이트헤이븐이 서 있다. 나이트 엘프의 석조물과 달샘이 있는 마을로, 세나리온 의회 드루이드들의 보금자리이다. 고요하고 외딴 곳으로, 대부분의 이방인에게 닫혀 있으며, 주민들은 드루이드의 길과 야생을 돌보는 일에 몸을 바친다.\n\n나이트헤이븐은 일 년에 단 한 번 문을 연다. 달의 축제가 열려 엘룬의 힘을 기리며 호수 위로 불꽃놀이가 터질 때, 평소라면 결코 환영받지 못할 이방인들을 맞이한다.\n\n그러나 이 마을은 어떤 축제보다 어두운 밤도 겪었다. 수호자 레물로스가 타락해 마을에 등을 돌린 악몽의 용 에라니쿠스와 맞선 곳이 바로 이곳이었다. 악몽의 생물들이 나이트헤이븐을 덮쳐 마을을 완전히 무너뜨리려 했고, 마침내 티란데 위스퍼윈드가 와서 엘룬의 빛을 불러내려 용을 사로잡은 타락을 정화했다. 달샘들은 지금도 그 빛으로 타오른다.",
	["s:1450:shrine of remulos"] = "달의 숲 서부에는 그곳을 지키는 수호자를 기려 세운 레물로스의 제단이 서 있다. 그 안에는 나이트 엘프 타자리가 살며, 바다표범 변신을 배우려는 젊은 드루이드들을 이끈다.",
	["s:1450:stormrage barrow dens"] = "달의 숲의 고요한 잔디 아래에는 지하굴들이 있다. 많은 나이트 엘프 드루이드가 결코 진정으로 떠나지 않는 땅속으로, 그들의 몸은 쉬고 영혼은 에메랄드의 꿈을 떠돈다.\n\n말퓨리온 스톰레이지가 한때 잠든 곳이 바로 이곳이며, 그 때문에 지하굴은 그의 이름을 지니고 있다. 3차 대전쟁 때 티콘드리우스와 그의 공포의 군주들이 왔을 때, 그들은 누워 있는 말퓨리온을 공격해 그의 굴을 거의 찢어 놓았다. 그를 깨운 이는 티란데 위스퍼윈드였다. 그녀는 아키몬드와 불타는 군단에 맞서도록 그를 세상으로 다시 불러냈다.\n\n그 뒤 세나리온 의회가 두 번째 세계수를 키우는 일을 논의하자, 말퓨리온은 명상하러 지하굴로 돌아왔다. 훗날 그를 찾아온 티란데는 그의 몸이 잠든 듯 멈춰 있고 깨울 수 없는 것을 발견했다. 의회는 그를 옮기지 않는 편이 현명하다고 판단했다. 만약 그의 영혼이 아직 꿈속을 떠돌며 돌아올 길을 찾고 있다면, 떠나온 그 자리에서 몸을 찾아야 할 것이기 때문이다. 그래서 그는 세나리온 의회와 엘룬의 자매단의 보살핌 속에 그곳에 남았고, 그의 몸은 그의 이름을 지닌 굴에 고요히 누워 있다.",
	["s:1450:timbermaw hold"] = "나무구렁 요새는 악령의 숲 북동쪽에 서 있으며, 그곳에서 굴 하나가 달의 숲과 여명의 설원으로 뚫려 있다. 이곳은 퍼볼그 나무구렁 부족의 수도이다.\n\n불타는 군단의 타락이 칼림도어의 성스러운 숲으로 스며들었을 때, 퍼볼그들은 그 영향 아래 떨어졌다. 오직 나무구렁 부족만이 그 어둠을 피했다. 그들은 요새 안에 몸을 숨긴 채, 그들이 사랑하던 숲이 곪아 가는 뒤틀린 모습으로 변해 가는 것을 속수무책으로 지켜보았다. 그 타락의 근원이 파괴된 뒤에도 숲에 남은 오염은 사라지지 않았다.\n\n이제 나무구렁 부족은 모든 이방인을 경계한다. 타락한 동족으로 오인받아 보자마자 공격당할까 두렵기 때문이다. 그러나 그들은 홀로 버틸 수 없음을 알고 있으며, 그들의 신뢰를 얻은 이들은 나무구렁 부족이 무엇보다 우정을 소중히 여긴다는 것을 알게 된다. 그들의 주술 전통은 이어지고 있으며, 가죽으로 방어구를 만드는 기술과 오래된 치유의 지식이 풍부하다. 무엇보다 부족은 타락한 동족의 고통을 끝내, 태고의 숲이 잃어버린 노랫소리와 웃음소리로 언젠가 다시 울려 퍼지기를 간절히 바란다.",
	["s:1451:bones of grakkarond"] = "실리더스 중부에는 흐르는 모래의 전쟁 때 그곳에서 쓰러진 용 그락카론드의 거대한 뼈가 놓여 있다.",
	["s:1451:bronzebeard encampment"] = "브론즈비어드 야영지는 실리더스 남부, 스카라베 성벽 동쪽에 서 있다.",
	["s:1451:cenarion hold"] = "세나리온 요새는 흐르는 모래의 전쟁 이후, 세나리온 의회가 고대 나이트 엘프 거주지 위에 세워 실리더스에 솟아났다. 이곳은 크기로는 달의 숲에만 견줄 수 있는 칼림도어의 거대한 드루이드 거점 가운데 하나이며, 그 목적은 단 하나이다. 실리시드 떼에 맞서 전선을 지키고, 모래 아래 묻힌 것, 곧 갇혀 있는 고대 신 쑨을 지켜보며 그 군대가 다시 일어서지 못하게 하는 것이다.\n\n살기에는 혹독하고 늘 싸움에 시달리는 곳이다. 실리시드는 끊임없이 성벽을 압박하고, 주변 지역은 점점 더 적대적으로 변해 간다. 그래도 요새의 상인들은 운고로 분화구에서 먼 길을 올라오는 누구와든 거래하려고 좌판을 열어 둔다. 다른 어디와도 그토록 멀리 떨어진 곳에서는 교역이 귀하고, 동전 한 닢 한 닢이 소중하기 때문이다.\n\n그곳으로 가는 길은 운고로에서 북서쪽으로 이끼 더미를 지나 굽이치며, 지그재그로 꺾이는 가파른 절벽을 올라간 뒤 실리더스의 타는 듯한 황무지로 열린다.",
	["s:1451:crystal vale"] = "실리더스 북서쪽 끝 구석에는 수정 골짜기가 있다. 대지와 바람의 정령들에게 넘어간 골짜기이다. 그 바위 아래에는 토륨이 두텁게 흐르지만, 땅은 무엇보다 그곳에서 꿈틀대는 오래되고 불안한 정령들의 것이다. 대영주 데미트리안이 골짜기 안에 야영지를 두고 있다.\n\n바로 이곳에서 바람추적자 썬더란을 불러내 그의 분노를 품은 칼날에 다시 묶을 수 있다. 폭풍과 의지를 다루는 그 작업은 감히 시도하는 이가 드물고, 끝까지 해내는 이는 더욱 드물다.",
	["s:1451:hiveashi"] = "하이브아쉬는 실리더스 북부에 있으며, 그 실리시드 무리는 경계 너머로 퍼져 벌레무리 기둥에까지 들끓는다.",
	["s:1451:hiveregal"] = "실리더스 남부에서는 하이브레갈의 흙더미들이 모래 위로 솟아 있다. 실리시드의 보금자리로, 먼지 한가운데 굴과 키틴질 껍데기가 가득하다.",
	["s:1451:hivezora"] = "하이브조라는 실리더스 서부의 모래 속에 파고든 실리시드 둥지이다.",
	["s:1451:ortells hideout"] = "실리더스 남동쪽에는 비탈로 열린 작은 동굴이 있는데, 오르텔이라는 은둔자의 보금자리이다.",
	["s:1451:ravaged twilight camp"] = "실리더스 북서쪽 수정 골짜기에는 대영주 데미트리안이 차지한 황혼의 망치단 야영지가 서 있다.\n\n데미트리안은 이곳에 머물며 교단을 위해 이 땅을 지키고 있다.",
	["s:1451:scarab dais"] = "스카라베 징은 실리더스 남부, 안퀴라즈 밖 스카라베 성벽 북서쪽의 스카라베 제단에 서 있다.",
	["s:1451:scarab wall"] = "스카라베 성벽은 실리더스의 남쪽 끝을 따라 이어지며, 사막과 그 너머 폐허가 된 도시 안퀴라즈를 갈라놓고 있다. 이 성벽은 흐르는 모래의 전쟁이 끝날 무렵 모래 자체에서 솟아올랐으며, 그 사암 덩어리는 적어도 백 피트 높이로 하늘을 향해 솟아 있다. 돌이 더 오를 수 없는 그 위로는, 청동용군단이 몇 배나 더 높은 마법의 장벽을 엮어 올렸다.\n\n이것을 만든 나이트 엘프와 청동용들은 그것을 이라나에실, 그림자를 막는 방패라 이름 지었다. 그 이름은 그것이 무엇을 위한 것인지 분명히 말해 준다. 쑨과 그 실리시드 무리는 안퀴라즈 안에 봉인되어 있었고, 성벽은 그 공포와 나머지 세상 사이를 가로막고 서 있었다.",
	["s:1451:southwind village"] = "마파람 마을은 한때 실리더스의 나이트 엘프 전초기지였다. 이곳은 흐르는 모래의 전쟁을 견디지 못했다.\n\n퀴라지가 떼 지어 무수히 일어났을 때, 판드랄 스테그헬름의 아들 발스탄 스테그헬름이 나이트 엘프 군대의 한 부대를 이끌고 마을을 지켰다. 그의 병사들은 선 자리에서 학살당했고, 발스탄 자신은 장군 라작스에게 산 채로 붙잡혔다. 그가 지키러 온 마을은 그의 등 뒤에서 갈가리 찢겼다.\n\n퀴라지가 남기고 간 곳은 비어 있지 않았다. 학살 속에 쓰러진 드루이드와 파수꾼의 영혼들이 잔해 사이에 머물며, 목적 없이 떠돌고, 죽은 자리에 묶인 채 앰버문의 망령을 따른다. 마파람 마을은 고요한 폐허가 아니라 유령이 출몰하는 땅으로 서 있으며, 그곳의 망자들은 아직 그곳과의 일을 끝내지 못했다.",
	["s:1451:staghelm point"] = "실리더스 북동쪽의 한 봉우리에는 한때 나이트 엘프의 탑이 서 있었다. 이곳에서 영원한 감시자 랄로샨이 자리를 지키고 있으며, 그 위 하늘에는 노즈도르무 혈족의 청동 비룡 하나가 맴돈다. 탑에서 길을 따라 내려가면 황혼의 터가 있는데, 황혼의 광신도들이 숨어 있는 동굴로 그 입구에는 작은 야영지가 있다. 감시자가 맞서야 하는 위협이다.",
	["s:1451:swarming pillar"] = "벌레무리 기둥은 세나리온 요새 남쪽에 솟아 있으며, 실리시드의 굴이 속속들이 뚫린 봉우리로 그 비탈은 한시도 가만있지 않는다. 작은 실리시드 떼가 밤낮없이 바위 주위를 맴도는데, 이 살아 있는 구름이 기둥에 이름을 주었다. 그 기슭의 모래 아래에는 벌집의 방 하나가 있으며, 실리더스의 땅을 벌집처럼 뚫어 놓은 수많은 둥지 가운데 가장 크다.",
	["s:1451:twilight base camp"] = "황혼의 망치단 주둔지는 황혼의 망치단이 실리더스의 황무지 곳곳에 세운 네 야영지 가운데 하나로, 그 황폐한 땅의 먼지와 폐허 한가운데서 고대 신의 도래를 섬기는 이들의 발판이다.",
	["s:1451:twilight outpost"] = "황혼의 전초기지는 실리더스의 남서쪽 끝 구석, 스카라베 성벽 근처이자 브론즈비어드 야영지 서쪽에 서 있다. 이곳은 황혼의 망치단이 차지하고 있다.",
	["s:1451:twilight post"] = "황혼의 초소는 실리더스 북서쪽, 세나리온 요새 서쪽이자 황혼의 망치단 주둔지 북서쪽에 서 있으며, 그 황폐하고 흙먼지 날리는 땅에서 황혼의 망치단이 차지한 발판이다.",
	["s:1451:twilights run"] = "황혼의 터는 실리더스 북부, 스테그헬름 거점 기슭의 바위 속에 숨어 있다. 그 동굴 입구는 너머의 어둠을 무엇이 채우고 있는지 전혀 드러내지 않는다. 방마다 황혼의 망치단에게 넘어갔고, 그들은 산속의 이 빈 곳을 깊숙이, 보이지 않게 자기 것으로 삼았으며, 그 위의 바위는 사막의 바람이 쓸고 지나간다.",
	["s:1451:valors rest"] = "용사의 안식처는 실리더스 끝자락의 작은 야영지로, 운고로 분화구 북서쪽 구석에서 올라오는 길로 닿는다. 모래 땅으로 올라오는 여행자가 처음 밟는 땅이다.\n\n세나리온 의회의 일원들이 야영지를 돌보며, 섬뜩할 만큼 낯익은 벌레 떼와 그 땅을 함께 쓴다. 얼라이언스와 호드 모두 지나가는 길에 이곳에서 몸을 쉬고, 그 가장자리에는 무덤들이 고요히 서 있다.",
	["s:1452:banthallow barrow den"] = "여명의 설원의 별똥별 마을 뒤편에는 반탈로우 지하굴이 있다. 마을이 소중히 여기는 축복받은 유물들을 품은 굴의 미로이다.",
	["s:1452:darkwhisper gorge"] = "검은속삭임 협곡은 여명의 설원 남부에 있다.\n\n3차 대전쟁 때 불타는 군단의 군대가 하이잘 산에서 부서지고 아키몬드가 쓰러졌을 때, 살아남은 악마들은 세상에서 사라지지 않았다. 그들은 검은속삭임 협곡으로 달아나 그곳에 숨었다. 세상을 거의 무너뜨릴 뻔했던 군세의 잔당이 어둠 속에서 곪아 가도록 남겨진 것이다.",
	["s:1452:dun mandarr"] = "던 만다르는 여명의 설원 남동쪽의 얼음 동굴 근처에 있으며, 그 이름은 드워프의 손길을 드러낸다. 이제는 사나운 달빛야수들이 야영지를 점령했고, 그곳을 세운 이가 누구였든 남은 것은 거의 없다.",
	["s:1452:everlook"] = "눈망루 마을은 여명의 설원의 교역로가 교차하는 곳에 서 있는 스팀휘들 무역회사의 고블린 거점으로, 건물들 사이에 실험실이 자리 잡고 있다.\n\n은빛 여명회는 무역회사의 현지 통치 앞에서 자신들의 이익을 대변하도록 그레고르 그레이스톤을 이곳에 보냈다.",
	["s:1452:frostfire hot springs"] = "여명의 설원의 서쪽 끝에는 줄지어 늘어선 웅덩이에서 김이 피어오르는데, 주변의 얼어붙은 땅에 어울리지 않을 만큼 물이 따뜻하다. 이 온천이 왜 눈과 얼음 아래에서 뜨겁게 타오르는지 설명한 이는 없다. 근처에 야영하는 도노바 스노든은 검은속삭임 협곡에서 북쪽으로 스며 나오는 어떤 악마의 오염이 이곳까지 흘러와 바위를 데우는 것은 아닐까 궁금해한다.\n\n나무구렁 요새에 가장 가까운 웅덩이는 한 번도 눈사태일족의 손아귀에서 벗어난 적이 없다. 그들은 지금도 그곳을 차지하고 있으며, 그 퍼볼그들은 자기들이 차지한 온기를 나눌 생각이 없다.",
	["s:1452:frostsaber rock"] = "눈호랑이 바위 꼭대기에는 눈호랑이와 그들을 타려는 이들 사이의 유대를 지키는 리번 프로스트윈드가 서 있다. 그는 자격을 얻은 얼라이언스의 벗들에게, 아래의 얼음 바위를 누비는 거대한 흰 고양이를 길들이고 타는 법을 가르친다.",
	["s:1452:frostwhisper gorge"] = "서리속삭임 골짜기는 여명의 설원 남부를 가르며, 그 바닥과 능선은 나이트 엘프 폐허로 조각나 있다. 이 오래된 돌 사이에 서리망치 거인과 거대한 보존자들이 산다.",
	["s:1452:hidden grove"] = "숨겨진 숲은 여명의 설원의 분화구 안에 움푹 자리하며, 사방이 깎아지른 절벽으로 막혀 있다. 남동쪽 능선에 파인 동굴 하나만이 통로가 되어 주고, 위쪽 높은 곳에서 뛰어내리는 것은 감히 시도할 이가 드문 길이다.\n\n한때 이 분지에는 흰 토끼보다 무서운 것이 없었고, 토끼들은 그 안식처에서 방해받지 않고 번성했다. 그 뒤로 사정이 달라졌다. 이제 숲은 들어오는 자에게 적대적인 달빛야수들이 차지했고, 그들의 존재는 절벽이 그러했던 것만큼 확실하게 이곳을 봉해 버렸다.",
	["s:1452:ice thistle hills"] = "얼음엉겅퀴 언덕은 눈망루 마을 남동쪽에 솟아 있으며, 언덕 비탈을 따라 올라가는 동굴에 굴을 틀고 주변 비탈을 누비는 얼음엉겅퀴 설인의 보금자리이다. 그들의 두꺼운 털과 창백한 뿔은 추위를 무릅쓰고 그것을 얻으러 오는 이들에게 귀하게 여겨진다.\n\n탁 트인 비탈에는 얼음송이가 자라고, 동굴 안의 바위에는 토륨 광맥이 흐른다. 무엇보다 귀한 것은 동굴 바로 입구에 이따금 핀다는 검은 연꽃으로, 설인들의 땅 한가운데서 연약하고 기이하게 피어난다.",
	["s:1452:lake keltheril"] = "켈테릴 호수의 얼어붙은 물은 여명의 설원의 심장부에 고요히 놓여 있으며, 같은 이름을 지닌 폐허가 그 주위를 둘러싸고 있다. 폐허는 옛 명가의 작품이며, 그곳에 살던 이들은 전당이 무너졌을 때 떠나지 않았다. 그들의 영혼은 고통 속에 여전히 머물며, 얼음과 부서진 돌 위를 떠돈다.",
	["s:1452:mazthoril"] = "여명의 설원의 얼음 깊숙한 곳, 켈테릴 호수 근처에서 마즈소릴 동굴이 땅 아래로 열려 있다. 차갑고 광대하며 마법이 짙게 서린 곳이다. 이곳에는 말리고스에게 충성을 맹세한 푸른용 무리가 살고, 그들의 여족장이 홀로 감시를 이어 간다.\n\n할레는 세상이 참모습이라 부를 만한 모습을 좀처럼 드러내지 않으며, 동굴 가장 높은 곳에 선 하이 엘프의 모습으로만 나타난다. 그곳은 저 아래 바닥에 새겨진 이동의 룬을 통해서만 닿을 수 있다. 그녀의 족속이 아닌 자 가운데 그녀의 얼굴을 본 이는 거의 없다.\n\n그녀는 자신의 은둔에 걸맞은 호위를 주위에 두었다. 강력한 비룡 넷이 오직 그녀에게만 답한다. 주문아귀는 여명의 설원 저지대의 삼분의 일을 쉼 없이 천천히 돌고, 마나발톱과 예언자는 잠긴 문 앞의 보초처럼 동굴 뒤편의 룬 위를 지키고 서 있다.",
	["s:1452:moon horror den"] = "눈망루 마을 성문에서 북동쪽으로 조금 걸어가면, 땅이 솟아 공포의 달빛 동굴이라 불리는 작은 동굴로 이어진다. 사나운 광포한 올빼미야수의 보금자리이다. 동굴과 남쪽의 눈사태일족 마을은 가까워 보이지만 그 사이에 산이 가로막고 있어 곧장 잇는 길이 없고, 고지대를 빙 돌아가는 먼 길뿐이다.",
	["s:1452:owl wing thicket"] = "올빼미날개 숲의 동굴들은 여명의 설원 남부를 가르며, 광포해지고 달빛에 물들어 미쳐 버린 올빼미야수들의 보금자리이다. 고대의 엘룬의 수호자들이 이곳에서 달빛야수가 처음 세상에 나온 이야기를 전한다고 하며, 그 이야기는 란샬라가 간직하고 있다.",
	["s:1452:ruins of keltheril"] = "켈테릴의 폐허는 그 이름을 지닌 호수의 가장자리에 부서진 채 놓여 있으며, 위대한 나이트 엘프 도시가 남긴 전부이다. 이 도시는 세계 자체가 찢겨 나간 대분리 때 무너졌고, 다시는 일어서지 못했다.\n\n지금 그곳에 머무는 것은 안식하지 못하는 슬픔이다. 켈테릴이 무너질 때 죽은 명가는 떠나지 못했다. 그들의 영혼은 북쪽 폐허의 무너진 기둥 사이에 남아 고통받으며, 잃어버린 것을 놓지 못한다. 동쪽 구역에는 하이 엘프 유령들이 출몰하는데, 그중에는 배신당한 순찰자들과 대마법사 하나가 있다.\n\n진말로라는 수정이 이곳의 몰락과 얽혀 있으며, 이곳에서 여러 세대의 엘프를 삼킨 파멸과 이어져 있다. 그 이야기는 켈테릴 자체의 것, 무너진 돌과 여전히 그 사이를 걷는 유령들의 것이다.",
	["s:1452:starfall village"] = "별똥별 마을은 여명의 설원을 지나는 길을 따라 서 있으며, 그 추운 땅에서 얼라이언스가 발판을 둔 유일한 곳이다. 나이트 엘프 산장 한 채와 작은 집 한 채가 마을을 이루고, 근처에는 이름의 유래가 된 무덤 언덕처럼 땅속에 가라앉은 반탈로우 지하굴이 있다.",
	["s:1452:timbermaw hold"] = "나무구렁 요새는 악령의 숲 북부의 굴, 달의 숲과 여명의 설원으로 열린 통로에 자리하며, 퍼볼그 나무구렁 부족의 마지막 거점이다.\n\n불타는 군단의 타락이 칼림도어의 성스러운 숲으로 스며들었을 때, 그 땅의 퍼볼그들은 그 아래 떨어져 야만적이고 잔혹한 무언가로 뒤틀렸다. 오직 나무구렁 부족만이 그 운명을 피했다. 그들은 굴을 지켰고, 그들이 사랑하던 숲은 그들 주변에서 곪아 가는 뒤틀린 모습으로 변해 갔다. 타락의 근원이 파괴된 뒤에도 숲의 오염은 걷히지 않았다.\n\n나무구렁 부족은 여전히 모든 이방인을 경계한다. 타락한 동족으로 오인받아 결백을 증명하기도 전에 베일까 두렵기 때문이다. 그러나 그들은 홀로 버틸 수 없음을 알고 있으며, 신뢰를 얻은 이들에게는 너그럽다. 그들은 옛 주술의 길을 지키고, 간직한 치유의 지식을 아낌없이 나눈다. 그들이 가장 바라는 것은 타락한 형제들의 고통이 끝나는 것, 그리고 악령의 숲이 입은 상처가 치유되는 것이다.",
	["s:1452:timbermaw post"] = "나무구렁 야영지는 더 이상 어울리지 않는 이름을 지니고 있다. 이 야영지는 한때 나무구렁 부족의 것이었지만, 이제는 타락한 눈사태일족 퍼볼그가 완전히 차지하고 있다. 얼음불꽃 온천 남동쪽이자 켈테릴 호수 서쪽이다.",
	["s:1452:winterfall village"] = "눈사태일족 마을은 눈망루 마을 근처, 여명의 설원의 동쪽 비탈을 타고 올라가 있으며, 그곳 퍼볼그들은 오래전에 타락했다. 꼭대기에는 작은 동굴이 있는데, 그곳에서 마을을 다스리는 대족장 눈사태의 본거지이다.",
	["s:1453:champions hall"] = "스톰윈드의 구시가지 남쪽에는 용사의 전당이 서 있다. 얼라이언스의 장교들이 머무는 곳으로, 그들의 지위에 걸맞게 옛 도시 안에서도 따로 떨어져 있다.",
	["s:1453:deeprun tram"] = "마그니 브론즈비어드 왕이 깊은굴 지하철을 만든 것은 편의를 위해서가 아니었다. 2차 대전쟁이 끝나고 스톰윈드가 폐허에서 스스로를 재건하려 애쓰던 시절, 마그니는 아이언포지의 원조가 인간 동맹에게 너무 느리게 닿는 것에 조바심을 냈고, 다시 전쟁이 벌어진다면 드워프 병사들이 그들에게 얼마나 느리게 닿을지 불안해했다. 그는 아제로스에서 가장 존경받는 기술자인 땜장이왕 겔빈 멕카토크에게 이 문제를 맡겼다. 멕카토크의 답은 땅 밑으로 뚫어 두 수도를 곧장 잇는 철도였다.\n\n건설자들은 굴이 지나갈 길 아래에서 지하 호수를 만났지만, 그것을 돌아가지 않았다. 지하철은 지금도 그 호수를 지나며, 밀폐된 선로는 물 옆이 아니라 물 아래를 지난다.\n\n노움들이 날마다 지하철을 돌보며, 세 칸짜리 객차 두 편성이 아이언포지와 스톰윈드 사이를 빠르고 매끄럽게 달리게 한다. 지하 승강장을 건너는 누구에게나 무료이다.",
	["s:1453:valley of heroes"] = "옅은 빛깔의 돌다리가 스톰윈드 남문 앞의 해자 위로 모든 여행자를 건네, 영광만큼이나 슬픔을 위해 세운 석상들이 늘어선 푸른 골짜기로 이끈다.\n\n2차 대전쟁 이후 스톰윈드가 폐허에서 재건되었을 때, 도시는 얼라이언스 원정대를 이끌고 어둠의 문을 지나 저편에서 그것을 봉인한 이들을 기렸다. 길 왼편에는 쿠르드란 와일드해머와 대마법사 카드가가, 오른편에는 군사령관 다나스 트롤베인과 순찰대장 알레리아 윈드러너가 서 있고, 길이 갈라져 도시로 들어가는 길 끝에는 그들 모두를 이끈 장군 투랄리온이 서 있다. 다섯 가운데 누구도 돌아오지 않았다.\n\n여러 해 뒤, 알레리아와 투랄리온의 아들 아라토르가 백은의 손 기사의 어깨에 올라탄 채 골짜기의 한 의식에 왔다. 그는 기억조차 없는 얼굴, 어머니의 석상을 올려다보았다. 그곳에서 그녀의 무언가가 그에게 닿았는지, 소년은 미소 지으며 석상을 향해 손을 뻗었다. 그는 자라는 동안 거듭 그곳을 찾아와 그녀의 얼굴 앞에 서서, 그녀를 기억하지 못해도 그녀가 자신을 사랑했음을 알게 되었다.",
	["s:1454:hall of legends"] = "전설의 전당은 오그리마의 힘의 골짜기에 서 있으며, 호드의 장교들이 회의를 여는 병영이다.\n\n그 한가운데에는 아제로스의 지도가 펼쳐진 탁자가 있다.",
	["s:1454:ragefire chasm"] = "오그리마 아래로 땅이 열려 불타는 협곡이 드러나며, 그 굴은 용암과 연기로 숨이 막힌다. 이곳 깊은 곳에서 트로그들이 기어오르기 시작했는데, 호드는 그 부족을 성난불길 트로그라 부르게 되었다. 타우렌 예언자 마가타는 그들을 위쪽 도시에서 돌려세울 수 있으리라 기대하며 그들과 화친을 시도했다. 그녀가 마주한 것은 적의뿐이었다. 이 생물들이 외교에 아무 관심이 없으며, 그대로 두면 호드를 완전히 집어삼킬 수도 있다는 것이 분명해졌다.\n\n더 나쁜 것은, 음모가 오그리마 안까지 뻗쳐 있었다는 것이다. 불타는 칼날의 우두머리로서 진짜 충성을 숨기고 있던 니루 파이어블레이드는 스랄의 충성스러운 추종자들을 협곡 아래로 꾀어내, 그곳에 숨은 어둠의 광신도 무리에게 바쳤다. 그들을 없애는 동시에 광신도들을 믿을 수 있는지 시험하기 위해서였다. 스랄은 그 배신에 대해 드러내는 것보다 더 많이 알고 있지만, 광신도 지도자들은 여전히 자기 것으로 삼은 동굴을 차지하고 있다.",
	["s:1455:deeprun tram"] = "마그니 브론즈비어드 왕이 깊은굴 지하철을 만든 것은 편의를 위해서가 아니었다. 2차 대전쟁이 끝나고 스톰윈드가 폐허에서 스스로를 재건하려 애쓰던 시절, 마그니는 아이언포지의 원조가 인간 동맹에게 너무 느리게 닿는 것에 조바심을 냈고, 다시 전쟁이 벌어진다면 드워프 병사들이 그들에게 얼마나 느리게 닿을지 불안해했다. 그는 아제로스에서 가장 존경받는 기술자인 땜장이왕 겔빈 멕카토크에게 이 문제를 맡겼다. 멕카토크의 답은 땅 밑으로 뚫어 두 수도를 곧장 잇는 철도였다.\n\n건설자들은 굴이 지나갈 길 아래에서 지하 호수를 만났지만, 그것을 돌아가지 않았다. 지하철은 지금도 그 호수를 지나며, 밀폐된 선로는 물 옆이 아니라 물 아래를 지난다.\n\n노움들이 날마다 지하철을 돌보며, 세 칸짜리 객차 두 편성이 아이언포지와 스톰윈드 사이를 빠르고 매끄럽게 달리게 한다. 지하 승강장을 건너는 누구에게나 무료이다.",
	["s:1455:gates of ironforge"] = "아이언포지 성문은 던 모로의 거대한 비탈길이 산과 만나는 곳에 솟아 있으며, 여행자가 닿기 한참 전부터 설원 너머 수십 리 밖에서도 보인다. 성문은 탁 트인 드워프의 땅과 아이언포지 본성 사이의 문턱으로 서 있다.\n\n문을 지나면 대왕 모디무스 앤빌마를 기려 세운 거대한 석상의 시선 아래 서게 된다. 석상은 입구 바로 안쪽에서 감시하도록 세워져, 누구도 먼저 그의 눈 아래를 지나지 않고서는 도시에 들어갈 수 없다.",
	["s:1456:elder rise"] = "장로의 봉우리는 중앙 고원 동쪽에 서 있으며, 밧줄 다리로 높은 봉우리와 가운데 봉우리로 이어진다. 이곳에는 세나리온 의회의 보금자리가 있어 타우렌 드루이드와 사제들이 모이며, 대드루이드 하물 룬토템이 머문다. 장로 회의도 이곳에서 통치를 한다.\n\n두 다리 사이에는 그림토템 부족의 지도자 마가타 그림토템이 차지한 오두막이 서 있다.",
	["s:1456:hunter rise"] = "썬더 블러프의 남쪽 봉우리는 싸우는 이들과 사냥하는 이들의 것이다. 이곳에는 타우렌이 전사와 사냥꾼을 훈련시키는 사냥꾼의 전당이 있고, 덫사냥꾼과 추적자, 무두장이들이 저마다의 기술에 전념한다. 밧줄 다리가 봉우리를 위아래의 길로 이어, 고원의 나머지와 하나로 묶는다.",
	["s:1456:pools of vision"] = "정기의 봉우리 꼭대기 아래로 굴 하나가 열려, 예언의 웅덩이라 알려진 고요하고 검은 물로 이어진다. 포세이큰은 타우렌의 땅 깊숙한 이곳에 발판을 두고 마법사와 사제들의 거점으로 삼고 있으며, 포세이큰 파멸단의 사절이 웅덩이 사이에서 전투에 나설 신병을 찾고 있다.",
	["s:1456:spirit rise"] = "정기의 봉우리는 중앙 고원 북서쪽에 서 있으며, 타우렌의 주술 연구에 바쳐진 곳이다. 이곳은 스카이체이서 부족이 이끈다. 고원의 표면 아래에는 숨은 증기로 데워진 예언의 웅덩이가 있다. 밧줄 다리가 아래쪽 봉우리와 가운데 봉우리로 내려가 높은 곳들을 하나로 묶는다.",
	["s:1457:cenarion enclave"] = "세나리온 자치령은 다르나서스 북서쪽에 있는 둥근 숲으로, 이곳의 떡갈나무와 물푸레나무는 도시의 다른 곳에 있는 돌 전당보다 높이 솟아 있다. 이곳의 나무마다 룬이 새겨져 있는데, 깎아 낸 것이 아니라 살아 있는 껍질에서 자라난 것이다. 숲의 모임 장소들 역시 나무와 돌을 함께 다듬어 이루어져, 지었다기보다 길러 낸 듯하다.\n\n달의 신전이 도시 사제들의 본거지이듯, 이곳은 언제나 도시 드루이드들의 본거지였다. 대드루이드 판드랄 스테그헬름이 자치령의 가지에서 그들을 이끌며, 숲 한가운데 서 있는 가장 큰 살아 있는 건물이 그의 거처이다.\n\n숲은 여전히 그 아래 모이는 이들을 섬긴다. 드루이드들은 옛 방식을 배우러 이곳에 오고, 사냥꾼들은 가장 동쪽의 나무에서 훈련하며, 거대한 자치령 나무 발치에서는 다르나서스의 기수들을 태우고 황야를 누비는 나이트세이버를 타는 법을 배울 수 있다. 땅 아래, 가장 서쪽의 가지 속에 숨겨진 곳에는 은밀한 도적 조합이 거처를 두고 있으며, 이미 어디를 봐야 하는지 아는 이들만 그곳을 안다.",
	["s:1457:craftsmens terrace"] = "장인의 정원은 다르나서스 북쪽에 있으며, 전쟁이나 예배가 아니라 교역에 바쳐진 곳이다. 이곳에는 도시의 장인들이 가게를 두고 있고, 지친 여행자들은 다르나서스의 여관 가운데 한 곳에서 쉴 수 있다. 은빛 여명회의 대사관도 이곳에 서 있다. 엘프의 도시 안에 자리를 허락받은 이방의 존재이다.\n\n정원은 남쪽으로 전사의 정원과, 서쪽으로 세나리온 자치령과 맞닿아 있다.",
	["s:1457:temple gardens"] = "다르나서스의 심장부에는 신전 정원이 있다. 물과 산책로, 작은 섬들이 넓게 펼쳐진 곳으로, 바로 남쪽에 솟은 거대한 달의 신전에서 이름을 얻었다. 다리들이 사방으로 뻗어 북쪽의 세나리온 자치령, 동쪽의 장인의 정원과 전사의 정원, 상인의 정원, 그리고 남쪽의 달의 신전을 이어, 도시를 지나는 모든 길이 이곳에 모이는 듯하다.\n\n가장 큰 섬에는 도시의 은행이 있고, 정원 서쪽 끝의 차원문은 세계수 밑동의 루테란 마을로 내려가는 길을 열어 준다. 그래서 물과 돌의 이 고요한 중심은 다르나서스와 그 너머 세상 사이의 문턱이기도 하다.",
	["s:1457:tradesmens terrace"] = "상인의 정원은 다르나서스 남쪽에 자리하며, 가게 주인들이 좌판을 두고 상인들이 모여 흥정하는 곳으로, 도시 전체 상업의 중심이다. 북쪽으로는 전사의 정원으로 열려 있고, 서쪽으로는 길이 달의 신전과 신전 정원으로 이어진다.\n\n그 건물들은 나이트 엘프의 방식대로 나무를 길러 만든 것으로, 가볍고 우아하다.",
	["s:1457:warriors terrace"] = "전사의 정원에는 다르나서스의 동문이 있으며, 도시는 이곳에서 텔드랏실의 황야로 열린다. 이곳은 파수꾼들의 터전이며, 도시를 위해 무기를 들려는 나이트 엘프는 누구든 이 정원에 와서 사격장과 대련장에서 전쟁에 나설 만한 실력이 될 때까지 수련한다.\n\n나이트세이버를 탄 기수들이 성문을 따라 감시를 서고, 정원은 숲에서 길을 따라 올라올지 모를 어떤 폭력에도 맞서는 도시의 방패로 서 있다.\n\n정원은 북쪽으로 장인의 정원, 남쪽으로 상인의 정원, 서쪽으로 신전 정원과 맞닿아 있어, 이곳에서 수련하는 전사는 도시의 장인과 상인, 사제 모두의 부름이 닿는 곳에 서 있다.",
	["s:1458:ruins of lordaeron"] = "묻힌 도시 위로 로데론의 궁전은 여전히 서 있다. 전당은 하늘을 향해 뚫려 있고 정원은 폐허가 되었다. 얼라이언스의 위대한 왕국이 죽은 곳이 바로 이곳이며, 그 유령들은 이곳을 끝내 떠나지 못했다.\n\n그것을 끝낸 이는 아서스 메네실이었다. 왕자는 자기 백성에게 겨눈 군대를 이끌고 고향으로 돌아왔고, 그가 무엇이 되었는지 누구도 깨닫기 전에 종소리와 환호 속에 이 성문을 지나 환영받았다. 그는 왕좌의 방에서 기다리던 아버지 테레나스 왕을 찾아내 그 자리에서 죽였다. 시신을 굽어보며 그가 한 말은 지금도 그 방에 머무는 이에게 메아리친다. 왕국은 무너질 것이고, 그 잿더미에서 세상을 뒤흔들 새로운 질서가 일어나리라고. 헛된 호언이 아니었다. 며칠 만에 도시와 백성은 학살당했고, 로데론은 스컬지의 것이 되었다.\n\n지금도 안뜰을 걸으면 돌이 기억하는 것을 들을 수 있다고 한다. 속삭이는 목소리, 환영하는 종소리, 결코 완전히 사라지지 않는 왕좌의 방의 웅얼거림. 장막 너머를 볼 수 있는 이들은 로데론의 시민들이 자기 왕국이 사라진 줄도 모른 채 아직 그곳을 걷고 있다고 말한다.",
	["z:1411"] = "듀로타는 바위산과 협곡이 이어지는 갈라진 붉은 땅으로, 메마르고 뜨거우며 물도 푸른 것도 드물다. 오크들은 이곳에서 드레노어를 떠올리게 하는 거친 아름다움을 발견한다. 하이잘 산의 전투가 끝난 뒤 스랄은 바로 이곳으로 동족을 이끌어 새 고향을 세웠고, 살해당한 아버지 듀로탄의 이름을 따서 이 땅의 이름을 지었다. 본래 이 땅은 서슬갈기 가시멧돼지의 것이었으나 호드가 그들을 몰아냈다.\n\n그 평화는 오래가지 못했다. 2차 대전쟁의 영웅이자 오크에게 결코 호의적이지 않았던 대제독 데일린 프라우드무어가 호드가 뿌리내리기 전에 짓밟겠다며 얼라이언스의 대함대를 이끌고 듀로타로 쳐들어왔다. 그의 딸 제이나는 다른 길을 택했다. 테라모어에서 그녀는 아버지에게 등을 돌리고 스랄의 편에서 싸웠으며, 데일린은 두 사람이 화해하기도 전에 전투에서 목숨을 잃었다. 스랄은 그녀의 신의에 감사하며 제이나의 병사들이 무사히 테라모어로 물러나도록 허락했다.\n\n검은창 트롤은 스스로 원해서가 아니라 추방자로서 듀로타의 해안에 왔다. 동족인 주술사 잘라제인에게 배신당한 그들은 메아리 섬의 보금자리에서 쫓겨나 본토 해안에 어촌인 센진 마을을 세웠고, 잘라제인이 빼앗아 간 것을 끝내 되찾지 못했다.",
	["z:1412"] = "수백 년 동안 타우렌에게는 자신들의 땅이 없었다. 켄타우로스 약탈자들에게 쫓겨 칼림도어 곳곳을 떠돌았고, 부족들은 흩어져 떠도는 야영지 신세가 되었다. 스랄과 오크들이 이 해안에 상륙했을 때, 케른 블러드후프는 그들에게서 명예롭고 강인한 동류의 영혼을 보았다. 오크들의 호위와 힘을 등에 업은 케른은 사방이 산으로 둘러싸인 아늑한 골짜기로 동족을 이끌었고, 그곳에서 블러드후프 부족은 초원에서 켄타우로스를 몰아내고 마침내 그 땅을 차지했다.\n\n케른은 평원 위로 솟은 고원 위에 썬더 블러프를 세웠다. 그곳은 모든 부족의 타우렌에게 열린 안식처였고, 시간이 흘러 흩어져 있던 부족들은 그의 통치 아래 하나로 뭉쳤다.\n\n목초지는 여전히 푸르고, 고원들은 지금도 블러드후프 마을 위로 긴 그림자를 드리운다. 성년이 된 타우렌은 누구나 조상들이 그러했듯 거친 평원으로 나아가 위대한 사냥에서 스스로를 증명해야 한다.",
	["z:1413"] = "이곳의 흙먼지가 처음부터 흙먼지였던 것은 아니다. 한때 이곳은 칼도레이가 가꾸던 숲이었고, 그들은 이곳에 텐랄로어 전초기지를 세웠다. 고대의 전쟁 때 반신 로고쉬가 이곳에서 불타는 군단에 맞섰다고 전해진다. 대분리가 그 모든 것을 끝냈고, 푸른 골짜기는 지금처럼 햇볕에 그을린 평원이 되었다.\n\n여러 세대 동안 타우렌은 이 평원을 떠돌며 코도와 천둥도마뱀을 사냥하고 대지 어머니의 지혜를 구했지만, 재미 삼아 그들을 사냥하는 켄타우로스에게 늘 쫓겨 다녔다. 그들은 맞서 싸웠으나 결코 전쟁이 좋아서 싸운 것은 아니었다. 켄타우로스가 몰려오면 목숨을 헛되이 버리기보다 천막을 걷고 떠나는 쪽을 택했다. 평화의 한 해, 전쟁의 한 해. 그것이 타우렌의 삶이었다. 스랄의 오크와 검은창 트롤이 상륙하여 블러드후프 타우렌과 함께 켄타우로스에 맞서 진군하기 전까지는. 하이잘 산에서 군단이 패퇴한 뒤, 스랄은 불모의 땅 동부를 차지하고 서슬갈기 가시멧돼지를 몰아낸 다음 그 땅을 듀로타라 이름 짓고 오그리마를 수도로 세웠다.\n\n이 땅에는 더 오래된 슬픔도 서려 있다. 데소린이라는 사내가 사랑하는 알루라나가 다른 이의 품에 안긴 것을 보았고, 그의 절규가 모래 속에서 도끼 킬메임을 뽑아 올렸다고 한다. 그가 그녀를 죽이는 데 쓴 바로 그 도끼였다.",
	["z:1414"] = "대분리가 세계를 부순 뒤, 남은 나이트 엘프들은 의도적으로 세상과 발길을 끊었다. 인간들 사이에서 칼림도어는 전설로만 남았다. 부서져 파도 아래로 가라앉았다는 땅, 위치도 모습도 알 수 없는 땅이었다.\n\n하지만 완전히 잊힌 것은 아니었다. 그 후로도 나이트 엘프들은 쿠엘도레이를 찾아왔고, 그 덕분에 쿠엘탈라스의 하이 엘프들만은 그 전설이 사실임을 알고 있었다.\n\n3차 대전쟁이 닥쳤을 때에도 인간 대부분은 칼림도어의 존재를 믿지 않았고, 테레나스 왕의 궁정에 파견된 키린 토의 대사조차 의심하는 이들 가운데 있었다. 메디브의 경고에 귀를 기울여 서쪽으로 배를 띄운 이는 소수뿐이었는데, 스랄의 새로운 호드가 그중 하나였고 제이나 프라우드무어의 원정대가 그 뒤를 따랐다. 그들이 발견한 것은 전설이 아니라 온전한 하나의 대륙이었다. 북쪽에는 얼음이, 남쪽에는 사막이 펼쳐져 있었고, 그 사이의 숲은 여전히 나이트 엘프들이 지키고 있었다.",
	["z:1415"] = "동부 왕국이 처음부터 여러 땅으로 나뉘어 있던 것은 아니다. 한때 이곳은 하나의 대륙이었으나, 대분리가 세계를 찢어 놓으면서 지금은 아제로스, 카즈 모단, 로데론이라 불리는 부서진 조각들만 남았다. 쿠엘탈라스는 그 마지막 조각난 땅의 북쪽에 매달려 있는데, 지금도 그곳이 독립된 땅인지 아니면 다른 땅의 한 귀퉁이일 뿐인지 분명하지 않다.\n\n이 조각들을 가로질러 카즈 모단의 산맥과 붉은마루 산맥이 대륙의 심장부를 관통하는 등뼈처럼 솟아 있고, 그 주위로 오래된 종족들이 살아가고 있다. 깊은 전당의 드워프와 노움, 여러 왕국의 인간, 숲의 하이 엘프와 블러드 엘프, 그리고 이제는 로데론의 백성이 살던 곳에서 되살아난 포세이큰까지. 오크, 고블린, 드레나이, 나가, 오우거도 이 땅에 발을 들였지만, 이 땅에서 태어난 종족은 아니다.\n\n그 첫 번째 붕괴의 상처는 여전히 이곳의 진실로 남아 있다. 이곳의 모든 국경, 한 왕국과 다음 왕국 사이의 모든 해협과 물에 잠긴 땅은 동부 왕국이 한때 하나였고 이제는 더 이상 하나가 아님을 기억하고 있다.",
	["z:1416"] = "이 봉우리들에는 비가 좀처럼 그치지 않고, 그 위의 하늘은 언제나 잿빛이다. 한때 이 산맥은 북부 대부분을 다스리던 도시국가 알터랙의 왕관이었고, 달라란도 품고 있었다. 이제 둘 다 사라졌으며, 남은 것을 보면 왜 이곳을 오르려는 이가 그토록 적은지 알 수 있다.\n\n2차 대전쟁이 끝났을 때, 로데론 연합은 알터랙의 영주들이 호드와 몰래 내통했다는 사실을 알고 배신자들을 그들의 본거지에서 치기 위해 이 산맥으로 군대를 보냈다. 도시는 함락되었고 백성은 흩어지거나 투옥되었으며, 그 혈통은 끝내 왕좌를 되찾지 못했다. 몰락한 가문의 후대 왕자인 알리덴 페레놀드는 도적 두목으로 일어나 추방자와 복수심에 불타는 자들을 비밀결사로 불러 모았다. 이 무법자 집단은 지금도 스트란브래드를 장악하고 이 비탈 곳곳을 누비며 그의 가문이 잃은 것을 되찾으려 한다.\n\n오늘날 알터랙 성의 폐허는 산사태 오우거의 차지가 되었고, 오우거가 차지하지 못한 곳의 대부분은 비밀결사가 쥐고 있다.",
	["z:1417"] = "소라딘 왕은 이곳에서 그의 백성이 번영하리라는 꿈을 꾸고 이 메마른 땅에 왔으며, 통일된 아라소르의 첫 수도인 스트롬을 세웠다. 메마른 땅은 그에게 가시 울타리 역할을 해 주어 아마니의 숲 트롤이 매복할 곳을 주지 않았고, 그는 거기에 더해 두 번째 성벽까지 쌓았다. 천 년 동안 스트롬은 제국의 심장부에 서 있었으나, 귀족 가문들은 더 비옥한 땅을 찾아 하나둘 떠나갔고 소라딘의 마지막 후손들도 스톰윈드를 세우러 떠났다. 남은 곳은 스트롬가드가 되었고, 그 뒤로 줄곧 트롤베인 가문이 다스렸다.\n\n그 후 스트롬가드는 오우거와 비밀결사에게 짓밟혀 함락되었고, 생존자들은 요새에서 쫓겨나 지금은 임시 주둔지라 부르는 협곡으로 물러났다. 가까이에는 해머폴이 있다. 한때 인간이 오크 포로를 가두던 수용소였으나, 지금은 오크들이 직접 차지하고 오그림 둠해머의 이름을 따 새로 이름을 붙였다.\n\n소라딘의 거대한 성벽은 무너져 휑한 폐허가 되었고, 그의 요새는 부서진 채 여전히 분쟁의 땅으로 남아 있다. 오우거와 비밀결사, 그리고 그곳을 되찾으려는 왕국의 마지막 병사들이 지금도 그곳을 두고 싸운다.",
	["z:1418"] = "황야의 땅은 메마른 흙과 흩어진 바위, 굽이진 협곡으로 이루어진 갈라진 사막이며, 사방이 산으로 막혀 있다. 코요테와 퓨마, 대머리수리 말고는 이곳에서 살아남는 것이 거의 없다.\n\n북쪽 끝에는 고대 대지인이 만든 울다만의 폐허가 있다. 울다만이 발굴되었을 때 그곳은 드워프의 고귀한 기원에 대한 첫 단서를 내놓았고, 아이언포지의 탐사꾼들이 티탄의 유물을 찾아 폐허로 몰려들었다. 그러나 수천 년의 잠에서 깨어난 돌무덤 트로그가 탐험가들을 학살했고, 지금은 빼앗은 도시를 사납게 지키고 있다. 울다만 바로 남쪽에는 거대한 검은무쇠 요새가 서 있는데, 그곳의 드워프들은 먼지목도리 부족 오우거, 그리고 동쪽의 검은용 무리 사이에 둥지를 튼 비룡들과 전쟁을 벌이고 있다.\n\n훗날 이곳에는 카즈 모단에서 유일한 호드 전초기지인 카르가스가 세워졌다. 변절한 검은바위 동족을 감시하기 위해 오크들이 세운 곳이다. 대족장 스랄은 직접 카르가스 원정대를 보내 렌드 블랙핸드를 추적하게 했다.",
	["z:1419"] = "저주받은 땅이라는 이름은 과장이 아니다. 발밑의 붉은 진흙은 한때 검은늪이라 불리던 어두운 늪지의 황갈색 흙이었다. 오크 호드가 이곳에서 어둠의 문을 찢어 열고 아제로스로 쏟아져 들어오기 전까지는. 그날 새어 나온 마법이 흙을 붉게 태우고 영영 죽여 버렸다. 이제 이곳에는 억센 사막 덤불과, 그만큼 억센 사막의 생물들, 곧 바실리스크와 전갈과 하이에나 말고는 아무것도 자라지 않는다.\n\n대마법사 카드가와 키린 토는 무너진 관문을 감시하고 다시는 아무것도 그곳을 통과하지 못하도록 네더가드 요새를 세웠다. 평화는 두 해 동안 이어졌으나, 드레노어의 호드가 어둠의 문을 다시 열고 요새를 포위했다. 넬쥴의 의식이 드레노어를 찢어발기기 시작하자, 카드가와 마법사들은 굴단의 해골을 사용해 저편에서 어둠의 문의 돌 틀을 산산조각 냈고, 두 세계를 잇는 다리를 영원히 끊어 버렸다.\n\n오늘날에도 네더가드의 마법사와 성기사들은 죽은 어둠의 문을 음울하게 지키고 있다. 그들은 누구도 믿지 않고 어떤 실수도 용납하지 않는, 엄격하고 무뚝뚝한 공동체이다. 동쪽 바다에서 몰려온 폭풍우조차 구워진 땅 위를 쓸고 흘러가 버려 아무 도움이 되지 않는 이 땅에서, 그곳은 유일한 피난처이다.",
	["z:1420"] = "티리스팔 숲의 하늘은 수년째 병든 초록빛으로 드리워 있고, 나무들은 역병이 남겨 준 생명에 간신히 매달려 있다. 한때 이곳은 테레나스 왕의 치세 아래 평화로운 농장들이었고, 여러 세대가 방앗간과 호박밭 사이에서 조용히 살았다. 그 삶은 아서스 메네실이 로데론을 유린하고 시골 전역에 역병을 퍼뜨려 백성을 죽이고 리치 왕의 노예로 되살리면서 끝났다. 죽은 이가 너무 많아 제대로 묻어 주지 못한 곳에는 지금도 거대한 공동묘지가 남아 있다. 몇 달 뒤 발니르 농장 근처에서 실바나스 윈드러너는 밴시들을 이끌고 아서스에게 반기를 들어 그 죽음의 기사에게 독화살을 박아 넣었으나, 켈투자드의 해골 병사들에게 밀려났다.\n\n그 폐허에서 실바나스의 자유 의지를 지닌 망자들, 곧 포세이큰이 태어나 이 땅을 자신들의 것으로 삼았다. 그들의 적은 결코 이 땅을 떠나지 않았다. 북쪽의 옛 붉은십자군 수도원은 인간이 아닌 모든 것을 불태우고 사냥하는 광신자, 붉은십자군이 장악하고 있다.",
	["z:1421"] = "은빛소나무 숲, 간단히 은빛소나무라고도 불리는 이곳은 로데론의 험준한 서부 해안을 따라 펼쳐진 광활하고 오래된 숲이다. 땅은 제법 평평한 곳부터 구릉진 곳까지 다양하며, 더 높은 산들 사이에 포근히 자리하고 있다. 숲은 섬뜩할 만큼 고요하며, 이따금 나무 사이로 울려 퍼지는 기이한 울부짖음만이 그 정적을 깬다. 이끼 낀 바위 턱이 차가운 바람에 떨고, 나무들은 모두 병들었거나 죽어 가고 있다. 허물어진 농가와 버려진 광산이 곳곳에 흩어져 있으며, 이제는 숲의 더 어두운 존재들이 그곳에 깃들어 산다.\n\n이 숲은 유령이 출몰하는 거친 곳으로, 은빛 껍질의 키 큰 소나무들이 풀이 덮인 둔덕 위로 우뚝 솟아 있는 것이 특징이다. 이곳이 푸르고 생기 넘치던 시절에는 얼라이언스가 은빛소나무 숲을 지켰다. 이제 이곳은 유령 같은 안개에 휩싸여 있다. 포세이큰이 숲 북부를 장악하고 비열한 썩은가죽 놀과 끊임없이 충돌한다. 남은 인간들은 숲 남부를 지키고 있지만, 절박한 처지에 병력도 얇게 흩어져 있다. 달라란은 이 사람들을 지키고 언데드 역병과 늑대인간의 저주를 연구하기 위해 은빛소나무 숲으로 자주 원정대를 보낸다. 늑대인간의 저주란 달이 뜨면 희생자를 피에 굶주린 늑대인간 괴물로 변하게 하는 수수께끼의 병이다.\n\n숲의 남쪽은 길니아스와 힐스브래드 구릉지에 닿아 있고, 북쪽에는 티리스팔 숲이 있다. 로다미어 호수는 은빛소나무 숲의 동쪽 경계를 이룬다.\n\n이 땅은 포세이큰의 영토이지만, 달라란의 마법사들과, 폐허가 된 들판과 농가 일부를 차지한 스컬지의 하수인들이 그 소유권을 다투고 있다. 썩은가죽 놀은 수수께끼의 펜리스 섬을 거점으로 삼아, 감히 그들의 일에 다가오는 자는 누구든 사납게 공격한다. 남서쪽에는 장작나무 마을이 있는데, 그곳 주민들은 대마법사 아루갈의 저주에 걸려 밤이면 피에 굶주린 늑대인간으로 변한다. 아루갈은 근처 그림자송곳니 성채의 어두운 탑에 머물고 있다.\n\n은빛소나무 숲에서는 전투가 잦다. 사우스쇼어의 얼라이언스 병력이 이 버려진 숲으로 와서 공동묘지를 공격하거나 그림자송곳니 성채로 들어가기 때문이다. 이곳은 포세이큰 본토의 끝자락이자, 언데드 역병의 영향이 초목에서 드러나는 가장 남쪽 지점이다.",
	["z:1422"] = "한때 이곳은 로데론 북부에서 가장 아름다운 농토였다. 숲이 우거지고 푸르렀으며, 안돌할에서 왕국의 곡창을 채웠고 하스글렌의 영주관에서 다스려졌다. 바로 그 풍요가 이 땅을 파멸시킨 무기가 되었다.\n\n리치 왕의 계획에 따라 저주받은 교단은 그의 역병 기운을 휴대용 가마솥에 담아 남쪽으로 옮겼고, 충성스러운 교단 신도들의 마을에 숨겨 두었으며, 가장 큰 네 개는 안돌할의 들판에 직접 설치했다. 곡물 자체가 오염되었고, 그 곡물은 아무도 의심하지 않은 짐마차에 실려 로데론 전역으로 퍼져 나갔다. 자기 손으로 구운 빵을 먹은 사람들은 병들어 죽었고, 리치 왕의 노예로 되살아났다. 숲은 끝내 회복되지 못했다. 소나무들은 병든 안개 아래 잿빛으로 서서 갈색 바늘잎을 매달고 있으며, 줄기는 종양 같은 혹으로 부풀어 있다.\n\n남아 있는 질서는 왕국이 무너진 뒤 간신히 건져 낸 것이다. 붉은십자군은 하스글렌의 마르덴홀드 요새를 점령하고, 그곳에서 나머지 땅을 장악한 언데드를 향해 출격했다. 그 모든 혼란 속에서 평화를 지키는 곳은 단 하나, 빛의 인도자 우서에게 봉헌된 우서 경의 무덤뿐이다. 역병이 한 번도 닿지 않은 땅이다.",
	["z:1423"] = "이곳의 땅은 한때 농토였고, 로데론의 제2의 도시 스트라솔름 주변으로 동쪽 숲의 마을들이 흩어져 있었다. 그중 남은 것은 하나도 없다. 이제 흙은 갈색으로 병들었고, 나무들은 버섯처럼 부풀었으며, 공기는 주황빛 안개로 자욱하다.\n\n아서스 왕자가 이미 마을 사람들을 앗아 간 역병의 근원을 쫓아 온 곳이 바로 스트라솔름이었다. 백은의 손의 수장 우서 경은 그가 도시를 정화하는 것을 거부했다. 아서스는 그의 지휘권을 박탈하고 그 자리에서 백은의 손을 해산한 뒤, 스트라솔름 주민들이 스컬지로 되살아나게 두느니 자기 손으로 그들을 칼로 베었다. 그는 거기서 멈추지 않았다. 공포의 군주 말가니스를 쫓아 북쪽으로 갔다가 죽음의 기사가 되어 돌아왔고, 자신의 아버지를 죽여 로데론 왕국을 끝장냈다.\n\n알렉산드로스 모그레인은 백은의 손의 잔존 세력으로 십자군을 일으켜 폐허를 되찾고자 했다. 그는 티르의 손 수도원과 스트라솔름의 절반을 점령했지만, 그가 죽자 그의 기사단은 은빛 여명회와 붉은십자군으로 갈라졌다. 붉은십자군은 지금도 이 들판을 장악한 채 스컬지와 끝없는 전쟁을 벌이고 있으며, 다른 누구도 반기지 않는다.",
	["z:1424"] = "힐스브래드의 흙은 비옥하고 언덕은 푸르다. 여행자들은 역병이 오기 전 로데론 전체가 이런 모습이었다고 말한다. 그것은 이 땅의 위안인 동시에 잔인함이기도 하다. 이 땅은 다른 모든 곳에서 잃어버린 것을 기억하고 있지만, 이곳을 지키는 사람들은 나머지 땅을 파멸시킨 바로 그 전쟁을 여전히 치르고 있기 때문이다.\n\n2차 대전쟁 초기, 오크 약탈자들이 해안 마을들을 습격했고, 오그림 둠해머는 줄진을 감옥에서 풀어 주기 위해 직접 던홀드 요새로 진격했다. 수십 년 뒤 이 언덕을 지나간 이는 스랄이었다. 그는 흩어진 오크 부족들을 규합한 뒤 밤에 사우스쇼어로 숨어들어 배를 훔쳤고, 새로운 호드를 태우고 바다 건너 칼림도어로 떠났다.\n\n오크들이 시작한 일을 포세이큰이 이어 가고 있다. 그들은 타렌 밀농장을 가장 남쪽의 거점으로 삼아, 얼라이언스를 위해 굳건히 버티는 사우스쇼어와 힐스브래드 농장의 인간들을 공격하는 전진 기지로 만들었다.\n\n이제 농토 곳곳에는 소나무 숲이 흩어져 있고, 길은 여전히 목초지를 가로질러 북쪽의 음울한 포세이큰 정착지로 이어진다. 마치 이 땅 자체가 어느 편이 자신을 차지할지 아직도 기다리고 있는 듯하다.",
	["z:1425"] = "세 망치의 전쟁이 끝난 뒤, 와일드해머 드워프는 그림 바톨의 굴을 버리고 북쪽으로 와서 맹금의 봉우리에 땅 위의 보금자리를 지었다. 그들은 돌과 대장간을 등지고 하늘과 날개를 향했으며, 이 지역의 야생 그리핀과 워낙 깊은 유대를 맺어 그 인연을 기리고자 도시 안에 거대한 그리핀 석상을 세우기까지 했다. 이미 이 땅을 차지하고 있던 숲 트롤, 한때 위대했던 아마니 제국의 잔당은 드워프를 조상의 땅에 무단으로 눌러앉은 자들로 여기고 틈만 나면 그리핀 둥지를 습격했다.\n\n2차 대전쟁 때 호드가 휩쓸고 지나가자, 그때까지 그런 침략자가 존재하는지조차 몰랐던 영주 쿠르드란 와일드해머와 그의 기수들은 폭풍의 기운이 서린 망치를 들고 하늘에서 오크 행렬을 덮쳐 쉴 새 없이 몰아붙였다. 오그림 둠해머는 얼라이언스의 병력을 동부 내륙지로 끌어들여 쿠엘탈라스를 아무 저항 없이 치고자 했지만, 안두인 로서는 그 계획을 꿰뚫어 보고 직접 쿠르드란의 곁으로 달려갔다. 두 사람은 함께 침략자들을 무찌르고 알터랙 산맥까지 몰아냈다. 그 일로 쿠르드란은 자기 백성이 얼라이언스를 돕겠다고 맹세했다.",
	["z:1426"] = "던 모로에는 눈이 깊게 쌓여 있으며, 사방이 카즈 모단의 산맥으로 둘러싸여 있고, 그 고갯길은 언제나 드워프 병사들이 지키고 있다. 이 산맥이 다른 누구의 것이 되기 전에는 서리갈기 얼음 트롤의 땅이었다. 그들은 먼 옛날 드라카리 제국에서 떨어져 나와 이 지역에 정착했다.\n\n그 사정은 최초의 노움들이 울다만에서 기어 나와 추위와 트롤 모두에게서 살아남는 데 지혜를 쏟으며 봉우리 깊숙이 요새화된 거처를 파면서 달라졌다. 오백 년 뒤 드워프들도 지평선 너머로 보았던 같은 산맥에 이끌려 울다만에서 올라왔고, 가장 높은 봉우리 아래에 아이언포지를 세웠다. 노움들이 이미 근처에 자리 잡고 있는 것을 본 두 종족은 한 번도 깨진 적 없는 우정을 맺었다. 드워프는 힘을 보태 놈리건을 세웠고, 노움은 기계의 비밀을 나누었다. 두 종족의 군대는 함께 서리갈기 트롤을 무찌르고 살아남은 자들을 언덕으로 몰아내어, 이 땅에 대한 트롤의 지배를 영원히 끝냈다.\n\n이제 놈리건은 사라져 폐허가 되었고, 그 백성은 피난처를 찾아 아이언포지로 몰려들었다.",
	["z:1427"] = "한때 이곳은 붉은마루 산맥의 일부인 푸른 땅이었다. 이백삼십여 년 전, 대지 자체가 찢겨 나가기 전까지는.\n\n세 망치의 전쟁 때 검은무쇠 드워프의 마법사 영주 타우릿산은 적을 무너뜨릴 무기를 찾았다. 그는 가장 신임하는 일곱 드워프와 함께 세계의 밑바닥으로 손을 뻗어, 잠들어 있어야 했던 힘을 불러냈다. 응답한 것은 하인이 아니라 주인이었다. 바로 고대의 불의 군주 라그나로스였다. 그가 깨어나면서 검은바위 산이 땅에서 솟구쳤고, 수십 리에 걸친 땅이 검게 그을렸으며, 검은무쇠 드워프의 수도 타우릿산은 그 아래에서 잔해로 짓뭉개졌다. 남쪽의 그을린 평원은 불타는 평원으로, 북쪽의 이 황폐한 골짜기는 이글거리는 협곡으로 알려지게 되었다.\n\n그 파멸 이후 모든 검은무쇠 드워프가 부족에 충성을 지킨 것은 아니었다. 그중 일부는 떨어져 나와 스스로를 토륨 형제단이라 칭했고, 옛 동족이 골짜기 바닥에 파 들어간 거대한 발굴지를 내려다보는 곳에 토륨 조합 거점을 세워 위에서 검은무쇠 드워프의 작업을 지켜보고 있다.",
	["z:1428"] = "불타는 평원의 하늘은 검은바위 산의 간헐적인 분화로 밝혀져 한 번도 붉은빛을 잃은 적이 없고, 땅은 결코 식지 않는다. 어둠의 문이 열리기 이백 년 전, 검은무쇠 드워프는 아이언포지에서 추방당해 이곳으로 왔다. 그들의 마법사 영주 타우릿산은 정령 하수인을 소환해 브론즈비어드와 와일드해머 부족을 상대로 세 망치의 전쟁에서 승리하려 했다. 응답한 것은 하수인이 아니라, 한때 티탄에게 추방당했던 불의 군주 라그나로스였다. 그의 강림은 주변 산들을 녹이고 폭발의 중심에 화산을 솟게 했으며, 그를 소환한 드워프들을 파멸시켰다. 그 새 봉우리 북쪽은 이글거리는 협곡이 되었고, 남쪽은 불타는 평원이 되어 그 이후로 줄곧 상처를 안고 있다.\n\n1차 대전쟁 때 오크들은 화산의 비탈에 정착했고, 2차 대전쟁 내내 검은바위 첨탑을 요새로 삼았다. 이후 검은바위 오크들이 돌아와 지금도 그곳에 머물며, 스랄의 휴전 이전의 잔혹한 옛 방식을 따르고 있다. 네파리안이 이끄는 검은용들이 첨탑의 위층을 차지하고 있으며, 라그나로스는 여전히 그 모든 것 아래 어딘가에서 분노를 곱씹고 있다고 한다.",
	["z:1429"] = "1차 대전쟁 때 오크들이 쳐들어오자 수천의 병력이 엘윈 숲을 지나 스톰윈드를 에워쌌고, 바다를 제외한 모든 곳과 도시를 단절시켰다. 기사 대장 안두인 로서는 스톰윈드 기사단을 이끌고 숲을 가로질러 돌격해, 오크의 후방 부대를 기습하여 흩어 놓았다. 그 덕분에 도시는 시간을 벌었지만 충분하지는 않았다. 대족장 블랙핸드는 곧 호드와 왕 사이에 남은 마지막 마을인 골드샤이어와 문브룩을 점령했고, 스톰윈드 성은 약탈당했다. 로서는 생존자들을 이끌고 바다를 건너 로데론으로 떠났고, 도시의 폐허는 한동안 폭풍불꽃 부족의 차지가 되었다. 지금도 이 지역 곳곳에는 부서져 썩어 가는 오크 투석기가 흩어져 있다. 그 점령의 흔적으로 남은 것은 그것뿐이다.\n\n도시 동쪽의 노스샤이어 포도밭은 한때 스톰윈드 농부들의 자랑이었다. 석공 조합은 폐허가 된 수도를 재건하는 데 여러 해를 바쳤지만 대가를 받지 못했고, 귀족들은 빚을 갚는 대신 조합을 해산해 버렸다. 조합장 에드윈 밴클리프의 분노는 폭동으로 번져 티핀 엘러리안 린 왕비의 목숨을 앗아 갔고, 데피아스 단을 낳았다. 데피아스 단은 노스샤이어에서 농부들을 몰아내고 그 들판을 점령했다.",
	["z:1430"] = "죽음의 고개는 아제로스 중부의 산맥을 가로지르며 그늘숲과 슬픔의 늪을 잇는다. 이십여 년 전만 해도 이곳은 붉은마루 산맥의 일부로 여겨졌다.\n\n한때 어둠의 마법사 메디브의 권좌였던 카라잔의 상아탑이 이 험준한 지역의 한가운데에 서서 사악한 마법을 땅으로 흘려보내고 있다. 나무들은 잎 하나 없이 돌처럼 굳었고, 협곡 사이로 끔찍한 바람이 울부짖는다. 오우거와 악마, 언데드, 그리고 소수의 인간 유랑민이 이곳 안쪽을 떠돈다. 그리고 어떤 새로운 세력이 상아탑을 차지했으며 오우거와 악마들이 그 지배 아래 있다는 소문이 은밀히 돈다.",
	["z:1431"] = "그늘숲에는 부자연스러운 밤이 장막처럼 드리워 있으며, 그것은 한 번도 걷힌 적이 없다. 한때 엘윈 숲의 아름다운 한 자락이었던 이곳은 이제 저주받아 죽어 가는 땅이다. 검은 안개 아래에서 나무들은 뒤틀려 자랐고, 죽은 자들은 무덤에서 일어났으며, 엘룬의 낫이 일으킨 힘에 이끌린 늑대인간들이 어둠과 함께 슬금슬금 스며들었다. 죽음의 고개에서 밀려드는 오우거들은 그 비참함을 더욱 깊게 할 뿐이었다.\n\n스톰윈드의 보호는 오래전에 이곳에서 아무 의미가 없어졌고, 남은 사람들은 그 보호 없이 땅을 지키는 법을 익혔다. 그들의 민병대인 밤의 감시단은 길을 순찰하며, 그림자 속에서 움직이는 모든 것으로부터 다크샤이어를 지킨다. 해골 전사와 구울, 사나운 늑대인간, 그리고 데피아스 단원들까지.\n\n숲의 심장부에는 오래전에 죽은 화산의 분화구가 있으며, 그곳은 주변의 어둠보다 한결 부드러운 황혼에 감싸여 있다. 그 안에는 에메랄드의 꿈을 향해 뿌리를 뻗은 거대한 나무 가운데 하나가 서 있고, 잠든 드루이드들의 영향이 근처에서 자라는 모든 것에 물들어 있다. 그 너머로는 버려진 농가들과, 어둠이 내린 뒤로 해마다 채워져 온 까마귀 언덕 묘지의 넓은 무덤들이 펼쳐져 있다.",
	["z:1432"] = "모단 호수의 물은 잿빛 바위에 포근히 안겨 돌다지 댐에 가두어져 있다. 아제로스의 그 어떤 건축물도 따라온 적이 없는 드워프 공학의 걸작이다. 사방으로 산이 깎아지른 듯 솟아 있고 소나무와 자작나무가 드문드문 자라며, 호수는 마치 한 번도 흔들린 적 없는 것처럼 고요하고 잔잔하다.\n\n이 호수는 한때 전쟁터였다. 2차 대전쟁 때 호드의 오크들이 이 지역으로 몰려들어 이곳에서 얼라이언스에 맞서 최후의 저항을 벌였다. 아이언포지는 버텨 냈다. 그 드워프들은 오크를 몰아내고 모단 호수를 되찾았지만, 그 전쟁의 잔해는 끝내 다 치워지지 않았다. 부서진 투석기와 산산조각 난 대형 쇠뇌가 지금도 호수 바닥과 섬들 곳곳에 반쯤 가라앉은 채 흩어져 있다. 이 고요한 물이 한때 살육의 현장이었다는 증거로 남은 것은 그것뿐이다.",
	["z:1433"] = "붉은마루 산맥은 엘윈 숲의 동쪽, 그늘숲의 북동쪽, 불타는 평원의 남쪽에 자리하고 있다.\n\n세차게 흐르는 강과 우뚝 솟은 느릅나무, 점점 높아지는 지형이 어우러진 목가적인 이 지역은 스톰윈드의 보호를 받고 있지만, 2차 대전쟁 이후로는 명목상 독립된 땅이다. 이곳은 여전히 아제로스에 몇 남지 않은 평화로운 지역 가운데 하나로, 주민들은 평온하고 만족스럽게 살며 스톰윈드에 목재와 생선, 곡물을 공급한다. 그러나 평화가 완전하지는 않다. 불타는 평원에서 온 검은바위 오크 무리가 돌망루 요새를 차지하고 있는데, 지금까지는 자기들끼리만 지내고 있다. 서부 몰락지대의 참상에 비하면 붉은마루는 아직 버티고 있는 셈이다.\n\n영원의 호수 북쪽 기슭에는 레이크샤이어 마을이 있는데, 주변 언덕에서 내려온 놀과 검은바위 오크에게 포위당해 있다. 그 남쪽에는 붉은마루 삼거리라 불리는 갈림길이 있어 레이크샤이어를 엘윈과 그늘숲으로 잇고, 호수마루 오솔길을 통해 돌망루 요새로도 이어진다. 그 길에는 새끼용과 놀, 멀록, 야수들이 도사리고 있다.\n\n호수의 수면은 충분히 잔잔해 보이지만 그 아래에는 멀록이 숨어 있고, 깊은 곳에 바다 괴물이 산다는 소문도 끊이지 않는다.",
	["z:1434"] = "가시덤불 골짜기는 그늘숲 남쪽에 펼쳐진 광활한 밀림이다. 정글 트롤이 이 찌는 듯한 열대 우림을 순찰하고 나가가 해안을 따라 사냥하며, 목을 조르는 가시덤불 덩굴과 야수들 탓에 여행은 위험하기 그지없다.\n\n이 골짜기는 한때 구루바시 제국의 심장부였고, 그 거대한 도시들이 지역 곳곳에 서 있었다. 제국이 무너진 뒤 그 도시들은 폐허로 허물어졌지만, 트롤들은 지금도 그 사이에서 살고 있다. 북동쪽의 줄구룹은 한때 구루바시의 수도였다.\n\n무법항은 원래 인간들이 세운 작은 항구 마을이었으나 트롤들에게 짓밟혔다. 이후 스팀휘들 무역회사의 고블린들이 만에서 트롤을 몰아내고 그곳을 차지했으며, 동부 왕국에서의 활동 중심지로 키워 냈다.\n\n북쪽에는 쿠르젠 대령의 원정대가 세운 주둔지가 있다. 그곳에서 대령의 정신은 오우거 마법사 마이조스에게 사로잡혔다. 마이조스는 정신의 눈이라는 유물로 쿠르젠의 의지를 꺾어 그의 부하들을 지휘했다. 쿠르젠의 병사 일부는 사로잡힌 지휘관에게 반기를 들고 서쪽으로 달아나, 그에게 맞서 반란군 야영지를 세웠다.",
	["z:1435"] = "늪의 검은 물 아래에는 이곳에 슬픔이라는 이름을 붙인 그 슬픔보다도 오래된 신전이 잠겨 있다. 구루바시 제국이 무너지자 아탈라이라 불리는 변절한 트롤 무리가 늪지대로 달아나 아탈학카르 신전을 세웠고, 그곳에서 그들의 어둠의 로아인 영혼의 약탈자 학카르를 세상으로 다시 불러내기 위해 끔찍한 의식을 행했다. 그들의 마법은 신전 주변의 식물과 짐승을 뒤틀었고, 결국 그 타락은 눈에 띄지 않을 수 없게 되었다. 꿈의 여왕 이세라는 교단의 야망을 알아채고 자신의 힘으로 그들에 맞섰으며, 학카르가 돌아오기 전에 신전을 가장 큰 늪 아래로 가라앉혔다. 그러나 그녀는 트롤들이 자신들의 신을 영원히 포기하리라 믿지 않았다. 그녀는 배우자 에라니쿠스와 녹색용 무리를 보내 폐허를 영원히 감시하게 하여, 다시는 그곳이 그러한 악을 세상에 풀어놓는 데 쓰이지 않도록 했다. 녹색용족은 지금도 그녀의 명령에 따라 이 늪지를 순찰하며, 가라앉은 사원은 파괴되지 않은 채 감시를 받으며 물 아래 봉인되어 있다.",
	["z:1436"] = "이제 서부 몰락지대의 들판 위로는 바람이 막힘없이 불어 간다. 그것을 막아 줄 높은 것이 하나도 남아 있지 않기 때문이다. 한때 이곳은 스톰윈드의 곡창 지대로서 여러 세대에 걸쳐 젊은 왕국을 먹여 살렸다.\n\n2차 대전쟁 후 스톰윈드를 재건한 석공 조합이 대가를 받지 못하고 경비대마저 그들의 항의에 등을 돌리자, 조합장 에드윈 밴클리프는 바리안 왕의 심판을 받느니 부하들을 이끌고 시골로 숨어들었다. 그곳에서 그들은 데피아스 단이 되었고, 밴클리프는 문브룩의 헛간 아래에서 오래된 광산 갱도를 발견했다. 바다에서 스톰윈드를 불태울 무기를 몰래 만들 수 있을 만큼 깊은 곳이었다. 그는 농부들을 몰아내고, 강발톱 놀을 고용해 땅을 지키게 했으며, 부하들에게 들판을 불태우고 땅에 소금을 뿌려 다시는 아무것도 자라지 못하게 했다.\n\n금고가 바닥난 스톰윈드는 서부 몰락지대가 알아서 살아가도록 내버려 두었다. 오직 그리안 스타우트맨틀만이 나섰고, 아무 군대도 오지 않자 감시의 언덕에서 민병대를 일으켰다.\n\n그가 소금을 뿌린 들판은 그 일로 서부 몰락지대를 용서하지 않았다. 한때 밀이 어깨 높이까지 자라던 곳에서 풀은 여전히 누렇고 가늘게 자란다.",
	["z:1437"] = "댐 아래에는 차갑고 잿빛인 늪지가 펼쳐져 있다. 강과 연못 위로 안개가 깔려 있고, 세 방향은 산에 막혀 있으며 서쪽으로는 바다가 트여 있다. 곳곳에 흩어진 돌무더기는 한때 이 땅을 지키던 드워프 요새들의 잔해이다. 이제는 멀록과 야수, 변절한 오크들이 대신 이곳을 차지하고 있으며, 메네실 항구만이 이곳에서 얼라이언스의 유일한 진정한 거점이다.\n\n그 항구가 처음부터 얼라이언스의 땅이었던 것은 아니다. 2차 대전쟁이 시작되었을 때, 오그림 둠해머는 바라딘 만의 작은 섬에서 침공 함대를 건조했다. 그의 배들이 지상 방어선을 거치지 않고 로데론 해안을 칠 수 있도록 하기 위해서였다. 그 대가는 저습지가 치렀다. 오크와 용들이 이 땅에서 마구 먹어 치웠고, 사냥감은 줄어들었다. 전쟁이 끝난 뒤 항구는 재건되어 테레나스 메네실 2세를 기려 메네실 항구라는 새 이름을 얻었다.\n\n그림 바톨의 몰락은 그 뒤에 찾아왔다. 그곳에서 용아귀 부족을 섬기도록 노예가 되었던 붉은용군단은 풀려나자마자 포획자들에게 등을 돌렸고, 부족은 무너져 생존자들은 황야로 흩어졌다. 알렉스트라자는 그 산을 봉인해 두는 것이 자신의 용군단이 짊어질 짐이라 여겼고, 그 이후로 붉은용족이 그곳을 지키고 있다.",
	["z:1438"] = "말퓨리온 스톰레이지가 에메랄드의 꿈 속으로 사라지자, 대드루이드 판드랄 스테그헬름이 그를 대신해 세나리온 의회를 이끌게 되었고, 고대정령 의회를 설득해 이제 새로운 세계수를 키워 나이트 엘프가 잃어버린 불멸을 되찾을 때가 왔다고 했다. 그들은 장막의 바다에 대지의 왕관 텔드랏실을 키웠고, 그 가지 위에 다르나서스를 세웠다. 그러나 최초의 세계수를 축복했던 노즈도르무는 이 나무를 축복하길 거부하며 그 소망을 오만이라 일컬었고, 나이트 엘프가 바라던 불멸은 끝내 찾아오지 않았다.\n\n시간이 흐르며 텔드랏실 위의 땅에는 불길한 기운이 드리웠다. 숲의 퍼볼그와 그렐은 미쳐 버렸고, 나무들 사이로 사티로스가 나타났으며, 한때 나무 주변의 바다를 헤엄치던 거대한 거북과 탈곡상어들은 달아나 어둠의 해안 기슭에 올라와 죽었다. 이 타락의 근원은 여전히 수수께끼로 남아 있고, 말퓨리온은 그것을 찾아 나서기 위해 꿈에서 돌아오지 않았다.",
	["z:1439"] = "이 해안에는 잿빛 안개가 드리우지 않는 날이 드물고, 나이트 엘프들은 오래전부터 그것을 경고로 여겨 왔다. 비와 바위 때문에 이 땅은 살기 좋은 곳이 아니며, 교역소인 아우버다인 너머로 정착하려던 시도는 모두 수포로 돌아갔다.\n\n만 년 전, 이곳에는 아트리쿠스 나라신이 다스리는 쌍둥이 도시 아메스아란과 바샬아란이 서 있었다. 고대의 전쟁이 세계를 부수고 대분리가 닥쳐오자, 아트리쿠스는 백성을 구하겠다고 맹세했다. 그는 약속의 문구는 지켰지만 그 정신은 저버렸다. 그는 영원한 생명이라 속이며 백성의 영혼을 영혼석에 가두었으나, 실은 그들을 빨아들여 자신의 힘을 채웠다. 도시들은 폐허가 되었고, 지금 그 돌무더기 사이를 걷는 것들은 온전히 안식을 얻지 못했다.\n\n3차 대전쟁이 끝난 뒤, 판드랄 스테그헬름은 세나리온 의회의 드루이드들을 어둠의 해안으로 이끌고 와 이 해안에 새로운 세계수 텔드랏실을 심었다.",
	["z:1440"] = "잿빛 골짜기는 오래된 나무와 오래된 마법이 가득한 태고의 숲이며, 이 숲을 둘러싼 다툼은 한 번도 멈춘 적이 없다.\n\n전쟁노래 부족의 오크들이 처음 이곳에 온 것은 벌목꾼으로서였다. 닐록 그리디핑거가 이끄는 고블린들은 이 지역의 퍼볼그들이 그들을 몰아낼 때까지 나무를 마구 베어 냈고, 그롬마쉬 헬스크림은 고블린의 도움을 잃지 않으려고 퍼볼그와 파수꾼을 차례로 무찔렀다. 세나리우스가 베어진 숲을 되살리려 직접 찾아왔지만, 그 대가는 그의 목숨이었다. 불타는 군단의 지배자들이 그의 믿음을 함정으로 바꾸었고, 그롬마쉬가 그를 쓰러뜨렸다.\n\n군단이 총력을 기울여 잿빛 골짜기로 진군하자 더 끔찍한 일이 뒤따랐다. 아키몬드의 지옥불정령들이 불타며 하늘에서 떨어졌고, 언데드와 악마들이 동쪽에서 휩쓸려 와 분열된 나이트 엘프, 오크, 인간의 군대를 가리지 않고 짓밟은 뒤 하이잘 산으로 밀고 나아갔다. 티란데 위스퍼윈드가 에메랄드의 꿈에서 말퓨리온을 깨웠을 때, 그가 기억하던 숲은 지옥의 불길과 숨 막히는 역병에 삼켜져 있었다.\n\n그 오랜 다툼은 끝나지 않았다. 나이트 엘프들은 여전히 아스트라나르와 흩어진 은신처들을 지키고 있고, 호드는 전쟁노래 부족의 야영지를 남쪽과 동쪽 깊숙이 밀어붙이며 나무를 베고 파수꾼을 밀어내고 있다. 어느 쪽도 이 숲을 둘러싼 싸움을 끝낸 적이 없다.",
	["z:1441"] = "협곡은 깊고 메마르게 뻗어 있고, 그 바닥은 우뚝 솟은 고원들 사이로 사라지다가 동쪽에서 넓은 하늘 아래 펼쳐진 거대한 소금밭, 소금 평원으로 열린다. 높새바람 봉우리나 먹구름 봉우리 주변 고지대에서 바라보는 일출은 이토록 황량한 땅 위에서 장관을 이룬다. 드루이드 쿠엔틴은 울창한 밀림인 이웃 페랄라스와 바로 맞닿아 있는 이곳의 혹독한 건조함이 자연스러운 것이 아니라, 이 땅에 걸린 어떤 기묘한 마법의 흔적이 아닐까 궁금해했다.\n\n높은 고원들은 타우렌의 땅이며, 높새바람 봉우리는 그 사이에 자리한 그들의 거점이다. 그들이 이 땅을 아무 도전 없이 지켜 온 것은 아니었다. 이 지역의 켄타우로스가 그들을 압박했고, 더 나쁘게도 그림토템 부족의 동족마저 그들에게 등을 돌려, 높새바람 봉우리의 타우렌은 고지대를 두고 부족끼리 싸워야 했다. 그들은 호드의 도움을 받고서야 켄타우로스와 그림토템을 물리칠 수 있었다.",
	["z:1442"] = "돌발톱 봉우리는 그 어떤 종족의 것이 되기 전부터 언제나 정령들의 것이었다. 나이트 엘프는 그 꼭대기에 지하굴과 숲을 두고 자연과 교감하며, 타우렌 또한 이곳을 신성하게 여긴다. 불멸의 예언자가 한때 이곳에서 대지 어머니가 짜는 운명의 실타래를 지켜보았기 때문이다. 전설에 따르면 이 산맥에 처음 정착한 타우렌은 불타는 토템을 들고 가장 높은 바위산까지 올라가 안셰에게 모닥불을 바치며 바위에 달라붙은 어둠을 불살랐다고 한다.\n\n산의 더 낮은 곳에는 엘룬이 오래전 치유의 은총을 내린 샘이 있다. 훗날 하피들이 근처 봉우리를 차지하고 그곳에 둥지를 튼 와이번을 사로잡았으며 샘물을 더럽혔다. 스랄은 케른 블러드후프와 그의 타우렌과 함께 그들에 맞섰고, 켄타우로스 무리를 무찔러 정화의 문양을 얻어 하피들이 오염시킨 것을 깨끗이 했다. 풀려난 와이번들이 그들을 봉우리 꼭대기까지 태워 주었다.\n\n남쪽에서는 그 오랜 대지와의 평화가 사라졌다. 투자개발회사는 칼바람 바위산을 헐벗게 만들었다. 나무를 베고, 공기를 그을음으로 채우고, 물을 기름과 오물로 더럽혔고, 마침내 산의 정령들이 멀리 오그리마의 주술사들까지 들을 만큼 크게 울부짖었다.",
	["z:1443"] = "바위 어머니 테라제인의 딸 테라드라스는 한때 비옥한 초원 아래에서 잠들어 있었다. 대지 어머니 자신이 그 아래에 산다고 믿은 타우렌 주술사들은 수십 년 동안 그녀를 불렀고, 마침내 무언가가 응답했다. 대지 어머니가 아니라, 잠에서 깨어나 분노한 테라드라스였다. 그녀는 약해진 몸을 되살리려 땅을 집어삼켰고, 초원은 한순간에 죽어 버렸다. 타우렌은 남은 땅을 잊혀진 땅이라 불렀다.\n\n숲의 군주 세나리우스의 아들 자에타르가 그녀를 속박하러 왔지만 오히려 그녀를 사랑하게 되었고, 그녀도 그를 사랑했다. 둘의 결합에서 켄타우로스가 태어났는데, 그들이 처음으로 한 일은 자신들의 아버지를 살해한 것이었다. 그들은 빠르게 번식해 타우렌을 그 땅에서 몰아냈고, 두 종족 사이의 수백 년에 걸친 전쟁이 시작되었다.\n\n테라드라스는 지금도 서쪽 협곡 아래의 마라우돈에 머물고 있으며, 켄타우로스는 바로 그곳에서 자기 종족이 태어났다고 여긴다.",
	["z:1444"] = "페랄라스는 이웃한 땅들 사이에서 기이하게 솟아 있다. 주변의 황무지가 오직 흙먼지만을 약속하는 곳에, 태고의 나무들이 우거진 열대 우림이 펼쳐져 있다. 그 초록 곳곳에는 뿌리와 덩굴에 반쯤 삼켜진 엘프들의 폐허가 흩어져 있으며, 그중 가장 거대한 것은 땅에 묻힌 도시 혈투의 전장이다.\n\n이제 페랄라스는 골두니 오우거의 차지이며, 그들은 이 땅을 부숴 가며 자기 것으로 만들었다. 그들은 숲을 통째로 쓰러뜨렸고, 그들의 오염은 병처럼 땅 위에 내려앉았다. 혈투의 전장 성벽 너머에서 그들의 약탈대는 남쪽 숲 곳곳의 마을을 불태우고 여행자를 살해한다. 황야에 퍼져 가는 이 타락의 뿌리는 그 아래 폐허로 이어진다.\n\n그림토템 타우렌도 여전히 이 지역 곳곳에 흩어져 살고 있으며, 그 부족이 저지른 일을 기억하는 이들에게 쫓기고 있다.",
	["z:1445"] = "이곳에서는 모기가 멎는 날이 없고, 진흙도 마찬가지다. 나무들이 물 위로 잎을 너무 빽빽하게 엮어 햇빛은 조각나 내려오며, 바다와 늪이 만나는 짠물 여울에는 악어와 멀록이 도사리고 있다. 남쪽에는 검은용들이 워낙 많이 모여들어 사람들은 그곳을 그저 용의 둥지라 부른다.\n\n이 황무지에 처음으로 진정한 보금자리를 마련한 이는 제이나 프라우드무어였다. 그녀는 하이잘 산 전투가 끝난 뒤 백성을 이끌고 이곳에 와 바위섬 위에 테라모어를 세웠다. 그녀의 도시 성벽은 빛나지만, 그것은 동시에 그녀를 가두고 있다. 불모의 땅으로 향하는 길목의 흩어진 검문소 너머로 늪지는 여전히 거칠고, 그녀의 수비대는 아무도 설명하지 못하는 조용한 탈영으로 점점 줄어들고 있다.\n\n호드와 얼라이언스 사이의 평화가 결정적으로 깨진 곳도 바로 이곳이었다. 대제독 데일린 프라우드무어는 쿨 티라스 함대를 이끌고 늪지에서 호드에 맞섰고, 뒤이은 교전은 그의 죽음으로 끝나 휴전을 공공연한 적대로 굳혀 버렸다.\n\n담쟁이 마을은 돌망치 오우거가 호드에게 문을 열어 준 곳에 서 있다. 그 너머로 불모의 땅으로 가는 길은 텅 빈 채 허물어져 가고 있으며, 언제나 이 땅의 주인이었던 랩터와 거미 말고는 아무도 그 길을 지켜보지 않는다.",
	["z:1446"] = "한때 밀림이 있던 자리를 모래가 채우고 있다. 세계가 부서지기 전 타나리스는 푸른 땅이었고, 구루바시 제국의 영토였다. 대분리가 땅을 찢어 놓자 밀림은 죽었고, 남은 것은 모래 언덕과 바위로 구워졌다. 물이 빠지면서 한 트롤 부족이 이곳에 고립되었고, 이어진 긴 세월 동안 그들의 몸과 삶의 방식은 사막에 맞게 휘어져 더 이상 예전의 트롤이 아니게 되었다. 그들은 모래 트롤, 곧 모래폭풍 부족이 되었다. 자신들을 가둔 땅이 빚어낸 종족이다.\n\n스팀휘들 무역회사의 고블린들은 교역을 위해 이 황무지를 골랐고, 가젯잔과 스팀휘들 항구를 세웠다. 칼림도어에서 그들이 정착할 수 있는 곳 가운데 이 사막이 가라앉은 고향과 가장 닮았기 때문이다. 스팀휘들 항구의 부두는 저 너머의 섬들을 향해 뻗어 있지만, 고블린들은 배를 자기들끼리만 쓰며 다른 종족을 바다 건너로 태워 주려 하지 않는다.\n\n모래 언덕과 남쪽 산맥 아래로는 대부분 지도에 없는 굴이 수십 리에 걸쳐 이어지며, 그 아래로 내려간 이들이 늘 돌아와 무엇을 보았는지 이야기해 주는 것은 아니다.",
	["z:1447"] = "아즈샤라는 만 년 동안 가을에 머물러 있다. 나무들은 절벽 위에서 주황과 붉은빛으로 타오르고, 그 절벽은 아직도 한 도시가 잠겨 있는 산호초로 떨어진다. 아즈샤라는 한때 나이트 엘프가 세운 가장 위대한 대도시였으나, 고대의 전쟁이 닥치자 그 대부분이 바다 속으로 가라앉았다. 부서진 건물 몇 채만이 아직 절벽에 매달린 채 물 아래 자신의 폐허를 내려다보고 있다.\n\n한참 뒤, 일리단 스톰레이지가 나가와 멀구르, 사티로스를 거느리고 하이잘 산에서 북쪽으로 달아날 때, 그는 아즈샤라의 해안을 휩쓸며 나이트 엘프의 항구들을 파괴해 아무도 그를 따라 살게라스의 무덤으로 오지 못하게 했다. 마이에브 섀도송과 그녀의 감시자들이 그 뒤를 쫓아, 그가 지나간 자리에 남긴 광기 어린 괴물들을 처치했다.",
	["z:1448"] = "악령의 숲의 나무들은 자란다기보다 곪아 간다. 껍질에서는 병든 진물이 흘러내리고, 잎은 검게 말려 늘어져 있으며, 그 아래의 짐승들은 흙 속의 타락 때문에 뒤틀리고 굶주린 모습으로 태어난다.\n\n이 부패는 자연의 우연이 아니었다. 불타는 군단이 하이잘 산으로 밀고 나아갈 때, 아키몬드는 산을 지키는 나이트 엘프를 약화시키기 위해 숲을 망가뜨리라 명령했고, 공포의 군주 티콘드리우스가 끔찍한 힘을 지닌 흑마법사의 유물인 굴단의 해골로 그 명령을 수행했다. 땅은 안에서부터 죽어 가는 것으로 응답했다. 고대정령들은 썩어 난폭해졌고, 짐승들은 변이했으며, 대지 자체가 독에 물들었다.\n\n일리단 스톰레이지가 남은 생을 결정지은 선택을 한 곳도 바로 이곳이었다. 해골의 힘으로 그것이 일으킨 타락에 맞설 수 있다는 말을 들은 일리단은 홀로 악령의 숲으로 들어가 티콘드리우스를 베고 그 유물을 차지했다. 그는 그 뒤에도 유물을 내놓지 않았다. 마법에 대한 갈망이 신중함보다 강했던 것이다. 군단의 힘을 사용한 대가로, 그는 친형 말퓨리온에게 추방당했다.",
	["z:1449"] = "운고로 분화구는 세 사막 사이에 벽처럼 막힌 채 칼림도어 남부에 움푹 들어앉은 초록빛 상처이며, 이곳에서 세상은 황량해야 한다는 것을 잊는다. 기억보다도 오래된 공룡들이 밀림을 누비는데, 그중 일부는 살아 있는 어떤 것도 이르러서는 안 될 크기로 자랐고, 대지와 불의 정령들이 그들 사이를 아무렇지 않게 걸어 다닌다. 그 위의 능선에는 아무도 설명한 적 없는 수정탑들이 서 있다.\n\n흐르는 모래의 전쟁 때 나이트 엘프들은 이 분화구를 지나 타나리스 사막 끝자락까지 밀려났고, 바로 그곳에서 퀴라지의 진격이 꺾였다. 운고로 자체의 무언가가 침략자들이 이 땅을 차지하도록 허락하지 않았지만, 그것이 무엇인지는 아무도 말하지 않았다.\n\n윌리든 마샬과 홀아니 마샬이 이끈 원정대가 한때 이곳에 거점을 마련하려 했지만, 분화구의 야만성은 그들이 대비한 것 이상이었다. 야영지는 짓밟혔고, 생존자들은 더 높은 곳으로 달아나 지금은 마샬의 야영지라 불리는 곳에서 최후의 저항을 벌였다.",
	["z:1450"] = "달의 숲은 산으로 둘러싸인 고리 안에 포근히 안긴 숨겨진 골짜기로, 이곳의 숲은 한 번도 타락을 겪은 적이 없다. 그 중심에는 여신의 이름을 딴 엘룬아라 호수가 있고, 호숫가의 나이트헤이븐 마을에서는 타우렌과 나이트 엘프가 다툼 없이 함께 거닌다. 그들은 자연에 대한 공통된 경외로 묶여 있으며, 달의 숲 수호자들은 그 유대가 깨지는 것을 결코 용납하지 않는다.\n\n고대의 전쟁 시절, 나이트 엘프가 군단 앞에서 파멸의 벼랑 끝에 섰을 때 말퓨리온 스톰레이지가 찾아온 곳이 바로 이 골짜기였다. 말퓨리온은 자기 동족이 홀로는 이길 수 없음을 알았고, 티란데 위스퍼윈드와 동생 일리단을 이끌고 달의 숲의 성스러운 고요 속으로 들어가 세나리우스에게 도움을 간청했다. 반신은 응답했고, 대분리가 세계를 새로 빚은 뒤 숲의 수호자들과 이곳에 몸을 피했던 드라이어드들은 세상으로 나아갔다. 세나리우스 자신은 결코 떠나지 않았고, 달의 숲은 드루이드 신앙의 가장 신성한 땅이 되었다.\n\n셀 수 없이 많은 둔덕 아래에는 옛 드루이드들의 성소가 잠들어 있고, 엘룬아라 호수 아래에는 한때 엘룬의 사랑을 받았던 반신 오멘이 편치 않은 잠에 빠져 있다.",
	["z:1451"] = "이 사막은 칼림도어의 남서쪽 끝자락에 자리한 부서진 바위와 모래의 황무지로, 운고로에서 뻗어 나온 넓은 길을 따라 닿을 수 있다. 그 지하에는 아퀴르 제국의 잔재인 안퀴라즈가 있다. 나이트 엘프는 무언가 끔찍한 것이 깨어나지 못하도록 그 중앙 사원을 봉인했다. 실리더스 곳곳에 흩어진 폐허와 지금 모래 속에 벌집처럼 뚫린 실리시드 둥지들은 그 봉인이 버티지 못했다는 충분한 증거이다.\n\n오래전 퀴라지는 흐르는 모래의 전쟁이 끝난 뒤 스카라베 성벽 뒤로 쫓겨나 그곳에 갇혔다. 그들의 하수인인 실리시드는 풀려난 채 남았고, 수 세기에 걸쳐 번식하며 칼림도어 남부 전역으로 퍼져 나갔다. 마침내 나이트 엘프는 그 위협이 더 이상 지켜보기만 할 수 없을 만큼 커졌다고 판단했고, 대신 안퀴라즈 성문을 다시 열어 성벽이 미루어 두었을 뿐인 일을 끝내기로 했다.\n\n세나리온 의회는 세나리온 요새에서 감시를 계속하며 실리시드 무리를 추적하고, 그것이 어느 한 종족이 홀로 맞서기에는 너무 큰 위험인지 가늠하고 있다.",
	["z:1452"] = "여명의 설원에는 눈이 끊임없이 덮여 있으며, 악마들이 남쪽 지역을 휩쓴 곳에서조차 그 아름다움은 흐트러지지 않았다. 한때 이곳은 말리고스의 배우자 할레를 비롯한 많은 푸른용군단의 보금자리였다.\n\n만 년 전 명가는 엘다라스의 한 신전에서 진말로의 수정을 훔친 뒤 이곳에 켈테릴이라는 도시를 세웠다. 그들은 수정의 힘을 시험해 보고 싶은 유혹을 이기지 못했고, 수정이 산산이 부서지자 그로부터 풀려난 저주가 그들을 집어삼켰다. 수정이 시작한 일을 대분리가 마무리했고, 켈테릴은 폐허가 되었다. 그곳의 망자들은 결코 떠나지 않았다. 훗날 수정의 파편을 찾아 쿠엘탈라스에서 하이 엘프들이 왔지만, 같은 광기가 그들도 사로잡았다. 이제 그들의 유령은 자신들이 연구하러 왔던 망자들과 나란히 폐허를 떠돈다.\n\n골짜기의 중심인 눈망루 마을은 고블린들이 차지하고 있고, 나이트 엘프들도 여전히 이곳에서 나름의 감시를 이어 가며 그 둘보다 오래된 고향을 지키고 있다.",
	["z:1453"] = "오크 호드가 불태운 뒤, 스톰윈드는 젊은 바리안 왕의 치세 아래 석공 조합의 손으로 하얀 돌의 도시로 다시 일어섰다. 그러나 전쟁 빚으로 왕실 금고가 바닥나고 귀족들이 조합에 품삯을 주지 않자, 조합장 에드윈 밴클리프의 항의에 돌아온 것은 조합의 해산이었다. 폭동이 뒤따랐고, 그 혼란 속에서 티핀 린 왕비가 목숨을 잃었다. 바리안의 분노는 석공들을 서부 몰락지대로 내쫓았고, 그들은 그곳에서 데피아스 단이 되었다. 그동안 왕좌 뒤에서는 카트라나 프레스터라는 고문이 자신의 목적을 위해 은밀히 왕과 조합을 이간질했다.\n\n그 후 바리안 왕은 수상한 정황 속에 실종되었고, 프레스터 부인의 권유에 따라 왕국의 질서를 지키기 위해 왕관은 그의 어린 아들 안두인 왕자에게 넘어갔다. 대영주 볼바르 폴드라곤이 스톰윈드의 섭정이자 군 사령관으로 봉직하고, 프레스터 부인은 왕국의 자원을 어떻게 쓸지 그에게 조언한다. 성 안에서 그녀를 의심하거나 그녀에게 맞서는 이는 아무도 없다.",
	["z:1454"] = "오그리마는 하이잘 산 전투 이후, 대족장 스랄이 동족을 이끌고 칼림도어의 황량한 해안에 왔던 시절에 세워졌다. 그는 아버지를 기려 그 땅을 듀로타라 불렀고, 그곳에 세운 도시는 자신을 길러 준 벗이자 스승인 오그림 둠해머를 기려 오그리마라 이름 지었다. 도시는 빠르게 세워졌지만 허술하지 않았다. 튼튼한 성벽과 거대한 성문, 높은 탑을 갖추었고, 뒤편의 산을 깎아 요새의 일부로 삼아 대지가 도시를 지키도록 했다.\n\n도시를 세운 호드는 한때 세상을 불태우며 휩쓸었던 그 호드가 아니었다. 악마의 저주가 풀리자 스랄의 백성은 정복이 아닌 생존을 향해 돌아섰고, 오그리마는 오크만큼이나 다른 이들의 손으로 세워졌다. 고블린과 타우렌, 검은창 트롤이 그들과 함께 일했고, 모크나탈의 렉사르도 일손을 보탰다. 켄타우로스와 하피, 천둥도마뱀, 코볼트, 가시멧돼지가 모두 첫 몇 해 동안 이 젊은 도시를 시험했지만, 도시는 버텨 냈다. 그리고 오크뿐 아니라 트롤과 타우렌, 시간이 흘러서는 새로 호드에 받아들여진 포세이큰의 보금자리가 되었다.\n\n이곳에서는 바람조차 친구가 아니다. 칼날 같은 바람이 골짜기를 휩쓸며, 허술하게 지은 건물의 지붕쯤은 뜯어낼 만큼 거세게 분다.",
	["z:1455"] = "아이언포지는 드워프의 수도로, 드워프의 조상 대대로의 고향인 던 모로 북부 아이언포지 산 깊숙이 새겨져 있으며, 아제로스에서 가장 오래된 도시 가운데 하나이다. 이곳은 카즈 모단의 수도이며, 브론즈비어드 부족의 마그니 브론즈비어드 왕이 다스린다.\n\n장인과 탐험가, 광부와 전사의 거대한 지하 도시인 아이언포지는 그 산업과 얼라이언스 교역의 중심지로 이름이 높으며, 요새이자 수도로서 드워프의 힘과 강인함을 보여 주는 증거이다. 도시는 동심원 모양의 고리들로 이루어져 있고, 지하 깊이 내려갈수록 층이 작아지며, 그 모두가 중앙에 있는 도시 이름의 유래인 대용광로에서 뻗어 나간다. 좁은 통로와 바위벽을 파서 만든 상점, 동굴 같은 방들이 가득하다. 이곳은 북적이고 시끌벅적하며 공업 도시의 느낌이 나지만 아늑하기도 하다. 여관과 상점의 화로에서는 불길이 으르렁거리고, 드워프들의 웃음소리와 흥겨운 소란이 끊이지 않는다. 스톰윈드나 다르나서스와 달리 이 도시는 드워프들이 직접 땅속에 파낸 거대한 동굴이며, 천장과 바닥 모두 단단한 바위로 되어 있다.",
	["z:1456"] = "썬더 블러프는 멀고어의 초원 위, 바람이 휘몰아치는 네 개의 고원 위에 솟아 있으며, 타우렌이 만든 밧줄과 나무 승강기나 고원 사이에 걸린 긴 다리로만 오갈 수 있다. 봉우리마다 천막과 긴 집, 채색된 토템이 얹혀 있다. 여러 세대 동안 타우렌은 칼림도어 곳곳을 누비는 켄타우로스에게 쉼 없이 시달리며 떠도는 유목민으로 살았다. 그 유랑을 끝낸 이는 블러드후프 부족의 족장 케른 블러드후프였다. 3차 대전쟁 때 대족장 스랄과 그의 새로운 호드가 멀고어에 왔을 때, 그들의 힘은 케른의 힘과 하나가 되었고, 그들은 함께 켄타우로스를 무찔러 마침내 타우렌에게 초원을 안겨 주었다. 케른은 고원 위에 흩어진 모든 부족에게 열린 안식처를 세웠고, 시간이 흘러 그 부족들은 한 민족으로서 그의 통치를 따르게 되었다. 앞으로 나아갈 길에 대해서는 때때로 의견이 갈렸지만, 그들을 이끄는 그의 지혜에 대해서는 결코 이견이 없었다.\n\n고원들은 그 솟은 봉우리와 다리에, 그리고 한 족장의 지붕 아래 모인 부족들의 천막에 지금도 그 건국의 무게를 짊어지고 있다.",
	["z:1457"] = "나이트 엘프는 3차 대전쟁 이후, 그들의 오랜 불멸이 사라졌을 때 다르나서스를 세웠다. 많은 이들이 갑작스레 찾아온 노화와 나약함의 무게를 견디지 못했다. 슬픔에 잠긴 드루이드 몇몇은 영원한 세계와의 유대를 되찾기 위해 새로운 세계수를 심기로 결심했다. 말퓨리온 스톰레이지가 실종되자, 판드랄 스테그헬름이 대드루이드의 자리를 이어받아 그 일을 이끌었다. 그들이 키운 나무 텔드랏실은 해안에서 솟아올라 그 꼭대기가 구름을 뚫었고, 나이트 엘프는 그 가지 사이에 동족이 살아남았음을 증명하는 도시를 세웠다.\n\n다르나서스는 인간과 드워프의 비좁고 성벽에 둘러싸인 도시들과 달리 하늘을 향해 열려 있다. 도시는 넓은 호수를 둘러싸고 세워졌으며, 호숫가는 우아한 다리로 이어져 있고, 길에는 낙엽이 양탄자처럼 깔려 있다. 달의 신전은 대여사제 티란데 위스퍼윈드와 엘룬의 자매단의 본거지로서 나무들 위로 솟아 있고, 그 곁에는 파수꾼들이 감시를 서는 열주가 늘어선 정의의 전당이 있다. 도시는 처음 세워진 목적 그대로 남아 있다. 평온한 안식처이자, 필멸과 함께 사는 법을 배워 가는 한 종족의 기념비로서.",
	["z:1458"] = "포세이큰이 차지하기 훨씬 전부터 언더시티에는 이름과 쓰임새가 있었다. 로데론 궁전 저 아래로는 왕실 망자들의 오래된 납골당과 지하 감옥, 하수도가 뻗어 있었다. 그곳은 오직 죄수와 시체를 위한 곳이었지만, 로데론에서 가장 가난한 사람들은 어떻게든 그 어둠 속으로 몰려들었고, 그들을 몰아내려는 경비병들의 소탕은 한 번도 효과를 거두지 못했다.\n\n리치 왕이 자신의 피조물에 대한 장악력을 잃자, 실바나스 윈드러너는 정신을 유지한 언데드들과 함께 스컬지에서 떨어져 나와, 자신을 이렇게 만든 타락한 왕자 아서스에게 칼끝을 돌렸다. 그녀는 폐허가 된 왕국에서 그를 함정으로 꾀어냈지만, 그는 켈투자드의 도움으로 빠져나가 북쪽으로 달아나 스스로 리치 왕이 되었다. 싸움터의 주인으로 남은 실바나스와 그녀의 추종자들은 스스로를 포세이큰이라 부르며 폐허가 된 수도 아래의 납골당을 차지했고, 스컬지가 짓기 시작한 요새를 완성했다.\n\n지금 서 있는 것은 방어를 위해 지은 미로이다. 모든 길을 따라 독성 오물의 강이 흐르고, 공기는 산 자가 숨쉬기도 힘들 만큼 짙은 독기로 가득하다. 포세이큰에게 그곳은 여전히 자신들을 사냥하는 세상 속의 피난처이다.",
	["z:947"] = "만 년 전, 영원의 샘이 지닌 힘에 도취된 칼림도어의 명가는 타락한 티탄 살게라스의 부름에 응하여 불타는 군단을 위한 문을 열어젖혔다. 말퓨리온 스톰레이지와 칼도레이 저항군은 용의 영혼으로 그 문을 부수고 살게라스를 뒤틀린 황천으로 몰아냈지만, 샘의 붕괴는 세계 그 자체를 부숴 놓았다. 고대 칼림도어는 불길과 홍수 속에 가라앉았다. 잔해 위로 폐허가 된 네 개의 대륙이 솟아올랐고, 물에 잠긴 대지의 심장부는 대해가 되었으며, 샘이 있던 자리에는 혼돈의 소용돌이가 휘몰아치게 되었다.",
})
